def append_jsonl(path: Path, row: Mapping[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(row, ensure_ascii=False, sort_keys=True) + "\n")


def _stable_int_seed(*parts: Any) -> int:
    text = "::".join(str(part) for part in parts)
    return int(hashlib.sha256(text.encode("utf-8")).hexdigest()[:16], 16)


def _safe_sigmoid_float(value: float) -> float:
    value = max(-60.0, min(60.0, float(value)))
    return 1.0 / (1.0 + math.exp(-value))


def opposite_binary_label(label: str | None) -> str | None:
    normalized = normalize_binary_label(label)
    if normalized == "Yes":
        return "No"
    if normalized == "No":
        return "Yes"
    return None


def first_normalized_label(row: Mapping[str, Any], fields: Sequence[str]) -> str | None:
    for field in fields:
        label = normalize_binary_label(row.get(field))
        if label is not None:
            return label
    return None


def branch_disagreement_alternative_answer(row: Mapping[str, Any], current: str | None) -> str | None:
    current_label = normalize_binary_label(current)
    if current_label is None:
        return None
    branch_fields = (
        "full_branch_answer",
        "non_target_branch_answer",
        "text_branch_answer",
        "target_branch_answer",
    )
    counter = Counter(
        label
        for label in (normalize_binary_label(row.get(field)) for field in branch_fields)
        if label is not None and label != current_label
    )
    if counter:
        return counter.most_common(1)[0][0]
    return opposite_binary_label(current_label)


def _branch_support_for_answer(row: Mapping[str, Any], answer: str | None) -> tuple[float | None, int]:
    """Estimate branch-view support for an answer without using references."""
    label = normalize_binary_label(answer)
    if label is None:
        return None, 0
    support = 0.0
    count = 0

    branches = row.get("branches")
    if isinstance(branches, Mapping):
        for branch in branches.values():
            if not isinstance(branch, Mapping):
                continue
            branch_answer = normalize_binary_label(branch.get("answer"))
            if branch_answer is None:
                continue
            count += 1
            if branch_answer != label:
                continue
            confidence_key = "confidence_on_yes" if label == "Yes" else "confidence_on_no"
            confidence = _finite_float_or_none(branch.get(confidence_key))
            margin = _finite_float_or_none(branch.get("margin"))
            if confidence is not None:
                support += max(0.0, float(confidence))
            elif margin is not None:
                support += max(0.0, abs(float(margin)))
            else:
                support += 1.0

    field_pairs = (
        ("full_branch_answer", "soft_conflict_full_margin"),
        ("target_branch_answer", "target_branch_margin"),
        ("non_target_branch_answer", "non_target_branch_margin"),
        ("text_branch_answer", "text_branch_margin"),
    )
    for answer_field, margin_field in field_pairs:
        branch_answer = normalize_binary_label(row.get(answer_field))
        if branch_answer is None:
            continue
        count += 1
        if branch_answer != label:
            continue
        margin = _finite_float_or_none(row.get(margin_field))
        support += max(0.0, abs(float(margin))) if margin is not None else 1.0

    if count <= 0:
        return None, 0
    return float(support), int(count)


def soft_conflict_budget_from_row(
    row: Mapping[str, Any],
    *,
    tau: float,
    strong_floor: float = 0.75,
    weak_floor: float = 0.35,
    current_answer: str | None = None,
    candidate_answer: str | None = None,
) -> dict[str, Any]:
    state = safe_text(row.get("conflict_state"))
    if state == "no_target_prior_conflict":
        return {
            "budget": 0.0,
            "mode_applied": True,
            "budget_reason": "identity_no_target_prior_conflict",
            "soft_conflict_score": _finite_float_or_none(row.get("soft_conflict_score")),
            "soft_conflict_cur_support": _finite_float_or_none(row.get("soft_conflict_cur_support")),
            "soft_conflict_alt_support": _finite_float_or_none(row.get("soft_conflict_alt_support")),
            "soft_conflict_margin": None,
        }

    cur_support = _finite_float_or_none(row.get("soft_conflict_cur_support"))
    alt_support = _finite_float_or_none(row.get("soft_conflict_alt_support"))
    score = _finite_float_or_none(row.get("soft_conflict_score"))
    if cur_support is not None and alt_support is not None:
        margin = float(alt_support) - float(cur_support)
        budget = _safe_sigmoid_float(margin / max(1.0e-6, float(tau)))
        return {
            "budget": max(0.0, min(1.0, float(budget))),
            "mode_applied": True,
            "budget_reason": "soft_support_margin",
            "soft_conflict_score": score,
            "soft_conflict_cur_support": cur_support,
            "soft_conflict_alt_support": alt_support,
            "soft_conflict_margin": margin,
        }
    if state == "soft_runtime_branch_conflict" and score is not None:
        margin = float(score or 0.0)
        budget = _safe_sigmoid_float(margin / max(1.0e-6, float(tau)))
        return {
            "budget": max(0.0, min(1.0, float(budget))),
            "mode_applied": True,
            "budget_reason": "soft_score_margin",
            "soft_conflict_score": score,
            "soft_conflict_cur_support": cur_support,
            "soft_conflict_alt_support": alt_support,
            "soft_conflict_margin": margin,
        }

    current = normalize_binary_label(current_answer) or first_normalized_label(
        row,
        (
            "current_answer_y0",
            "baseline_prediction",
            "baseline_answer",
            "base_protocol_answer",
            "mad_protocol_baseline_answer",
        ),
    )
    candidate = normalize_binary_label(candidate_answer) or first_normalized_label(
        row, ("candidate_answer_y", "target_answer")
    )
    if candidate is None or candidate == current:
        candidate = branch_disagreement_alternative_answer(row, current)
    cur_branch_support, cur_branch_count = _branch_support_for_answer(row, current)
    alt_branch_support, alt_branch_count = _branch_support_for_answer(row, candidate)
    if cur_branch_support is not None and alt_branch_support is not None:
        margin = float(alt_branch_support) - float(cur_branch_support)
        budget = _safe_sigmoid_float(margin / max(1.0e-6, float(tau)))
        strength = safe_text(row.get("conflict_strength"))
        if state == "target_vs_mad_baseline_conflict" and strength == "strong":
            budget = max(float(budget), max(0.0, min(1.0, float(strong_floor))))
        elif state == "target_vs_mad_baseline_conflict" and strength == "weak":
            budget = max(float(budget), max(0.0, min(1.0, float(weak_floor))))
        return {
            "budget": max(0.0, min(1.0, float(budget))),
            "mode_applied": True,
            "budget_reason": "branch_support_margin",
            "soft_conflict_score": score,
            "soft_conflict_cur_support": cur_branch_support,
            "soft_conflict_alt_support": alt_branch_support,
            "soft_conflict_margin": margin,
            "soft_conflict_cur_branch_count": cur_branch_count,
            "soft_conflict_alt_branch_count": alt_branch_count,
        }

    strength = safe_text(row.get("conflict_strength"))
    fallback_budget = 0.0
    fallback_reason = "identity_unrecognized_nonconflict"
    if state == "target_vs_mad_baseline_conflict":
        fallback_budget = (
            max(0.0, min(1.0, float(strong_floor)))
            if strength == "strong"
            else max(0.0, min(1.0, float(weak_floor)))
        )
        fallback_reason = f"fallback_{strength or 'unknown'}_target_prior_conflict"
    elif state == "soft_runtime_branch_conflict":
        fallback_budget = 0.5
        fallback_reason = "fallback_soft_runtime_branch_conflict"
    return {
        "budget": max(0.0, min(1.0, float(fallback_budget))),
        "mode_applied": fallback_budget > 0.0,
        "budget_reason": fallback_reason,
        "soft_conflict_score": score,
        "soft_conflict_cur_support": cur_support,
        "soft_conflict_alt_support": alt_support,
        "soft_conflict_margin": None,
    }


def candidate_reliability_from_carrier_rows(
    carrier_rows: Sequence[Mapping[str, Any]],
    *,
    tau: float,
) -> dict[str, Any]:
    """Runtime candidate trust from the same carriers used by evidence construction.

    This treats the candidate answer as a contrast hypothesis, not as a label.
    A candidate-directed update is trusted only when target evidence, cross-modal
    evidence, and branch-consistency signals do not disagree with that contrast.
    """

    margin_tau = max(1.0e-6, float(tau))

    def mean_key(key: str) -> float | None:
        return finite_mean(item.get(key) for item in carrier_rows)

    def prob(candidate_value: float | None, current_value: float | None) -> float | None:
        if candidate_value is None or current_value is None:
            return None
        return _safe_sigmoid_float((float(candidate_value) - float(current_value)) / margin_tau)

    target_prob = prob(
        mean_key("evidence_validation_branch_target_candidate_support"),
        mean_key("evidence_validation_branch_target_current_support"),
    )
    cross_prob = prob(
        mean_key("evidence_validation_branch_cross_candidate_support"),
        mean_key("evidence_validation_branch_cross_current_support"),
    )
    full_prob = prob(
        mean_key("evidence_validation_branch_full_candidate_support"),
        mean_key("evidence_validation_branch_full_current_support"),
    )
    candidate_branch_trust = mean_key("evidence_validation_continuous_candidate_branch_trust")
    current_branch_trust = mean_key("evidence_validation_continuous_current_branch_trust")
    branch_trust_prob = None
    if candidate_branch_trust is not None and current_branch_trust is not None:
        denom = max(1.0e-12, float(candidate_branch_trust) + float(current_branch_trust))
        branch_trust_prob = max(0.0, min(1.0, float(candidate_branch_trust) / denom))

    target_like_terms = [
        value for value in (target_prob, branch_trust_prob) if value is not None
    ]
    if target_like_terms:
        target_like = min(float(value) for value in target_like_terms)
        target_like_source = "min_target_branch_and_continuous_trust"
    elif target_prob is not None:
        target_like = float(target_prob)
        target_like_source = "target_branch_only"
    elif branch_trust_prob is not None:
        target_like = float(branch_trust_prob)
        target_like_source = "continuous_branch_trust_only"
    else:
        target_like = 0.5
        target_like_source = "uninformative_fallback"

    cross_like = float(cross_prob) if cross_prob is not None else 1.0
    reliability = target_like * math.sqrt(max(0.0, min(1.0, cross_like)))
    reliability = max(0.0, min(1.0, float(reliability)))
    return {
        "candidate_reliability": reliability,
        "candidate_reliability_reason": target_like_source,
        "candidate_reliability_target_prob": target_prob,
        "candidate_reliability_cross_prob": cross_prob,
        "candidate_reliability_full_prob": full_prob,
        "candidate_reliability_branch_trust_prob": branch_trust_prob,
        "candidate_reliability_candidate_branch_trust": candidate_branch_trust,
        "candidate_reliability_current_branch_trust": current_branch_trust,
        "candidate_reliability_target_like": target_like,
        "candidate_reliability_cross_like": cross_like,
    }


def candidate_reliable_conflict_budget(
    base_payload: Mapping[str, Any],
    reliability_payload: Mapping[str, Any],
    *,
    weak_floor: float,
) -> dict[str, Any]:
    base_budget = max(0.0, min(1.0, float(base_payload.get("budget") or 0.0)))
    reliability = max(
        0.0,
        min(1.0, float(reliability_payload.get("candidate_reliability") or 0.0)),
    )
    ambiguous_floor = max(0.0, min(1.0, float(weak_floor)))
    candidate_factor = max(ambiguous_floor, reliability) if base_budget > 0.0 else 0.0
    payload = dict(base_payload)
    payload.update(
        {
            "budget": max(0.0, min(1.0, base_budget * candidate_factor)),
            "base_budget": base_budget,
            "candidate_factor": candidate_factor,
            "candidate_floor": ambiguous_floor,
            "candidate_reliability_mode": "target_cross_branch_consensus",
            **dict(reliability_payload),
        }
    )
    payload["budget_reason"] = (
        f"{safe_text(base_payload.get('budget_reason'))}"
        f"+candidate_reliable_factor"
    )
    payload["mode_applied"] = bool(base_payload.get("mode_applied")) and payload["budget"] > 0.0
    return payload


def _target_trust_gate_from_path_certificate(
    token_payload: Mapping[str, Any],
    *,
    mode: str,
    floor: float,
    tau: float,
    candidate_reliability: float | None,
    target_prob: float | None,
) -> dict[str, Any]:
    """Continuous target-modality trust gate from token/head/path certificate.

    This is intentionally not an oracle or a sample router. It only rescales the
    residual update when the same token/head paths used for editing do not
    support a clean target-evidence-backed correction.
    """

    mode_key = safe_text(mode) or "none"
    floor_value = max(0.0, min(1.0, float(floor)))
    tau_value = max(1.0e-6, float(tau))
    if mode_key == "none":
        return {
            "mode": mode_key,
            "scale": 1.0,
            "raw": 1.0,
            "floor": floor_value,
            "path_balance": None,
            "source_path": None,
            "evidence_path": None,
            "candidate_reliability": candidate_reliability,
            "target_prob": target_prob,
            "available": False,
        }

    source_path = _finite_float_or_none(token_payload.get("oelpr_source_path_weight_mean"))
    evidence_path = _finite_float_or_none(token_payload.get("oelpr_evidence_path_weight_mean"))
    if source_path is None:
        source_path = _finite_float_or_none(token_payload.get("source_mass_mean_selected_heads"))
    if evidence_path is None:
        evidence_path = _finite_float_or_none(token_payload.get("evidence_mass_mean_selected_heads"))

    path_balance: float | None = None
    if source_path is not None and evidence_path is not None:
        # Empirically, reliable corrections in the conflict set require a real
        # suppressible source/prior path; unreliable target-only answers often
        # have strong evidence-path activity but weak source conflict.
        path_balance = _safe_sigmoid_float((float(source_path) - float(evidence_path)) / tau_value)

    rel = max(0.0, min(1.0, float(candidate_reliability))) if candidate_reliability is not None else None
    tgt = max(0.0, min(1.0, float(target_prob))) if target_prob is not None else None

    if mode_key == "path_balance":
        raw = path_balance
    elif mode_key == "candidate_reliability":
        raw = rel
    elif mode_key == "target_prob":
        raw = tgt
    elif mode_key == "target_prob_path_balance":
        raw = (tgt if tgt is not None else 1.0) * (path_balance if path_balance is not None else 1.0)
    elif mode_key == "candidate_reliability_path_balance":
        raw = (rel if rel is not None else 1.0) * (path_balance if path_balance is not None else 1.0)
    else:
        raise ValueError(f"unknown oelpr_target_trust_gate_mode: {mode}")

    if raw is None or not math.isfinite(float(raw)):
        raw = 1.0
    raw = max(0.0, min(1.0, float(raw)))
    scale = floor_value + (1.0 - floor_value) * raw
    return {
        "mode": mode_key,
        "scale": float(scale),
        "raw": float(raw),
        "floor": floor_value,
        "path_balance": path_balance,
        "source_path": source_path,
        "evidence_path": evidence_path,
        "candidate_reliability": rel,
        "target_prob": tgt,
        "available": raw is not None,
    }


def _normalize_float_weights(weights: Sequence[float]) -> torch.Tensor:
    tensor = torch.tensor([max(0.0, float(x)) for x in weights], dtype=torch.float32)
    if tensor.numel() <= 0:
        return tensor
    total = float(tensor.sum().item())
    if total <= 1.0e-12:
        return torch.full_like(tensor, 1.0 / float(tensor.numel()))
    return tensor / total


def _renorm_like(vec: torch.Tensor, ref: torch.Tensor) -> torch.Tensor:
    vec = vec.detach().float().cpu()
    ref = ref.detach().float().cpu()
    vec_norm = vec.norm().clamp_min(1.0e-6)
    ref_norm = ref.norm().clamp_min(1.0e-6)
    return (vec / vec_norm) * ref_norm


def _expert_item_score(item: Mapping[str, Any]) -> float:
    for key in ("selection_score", "attention_score", "weight", "fused_score", "query_attention_score"):
        value = item.get(key)
        if value is None:
            continue
        try:
            return max(0.0, float(value))
        except (TypeError, ValueError):
            continue
    return 0.0


def _target_pool_positions_from_evidence(record: Mapping[str, Any]) -> list[int]:
    for key in (
        "target_token_positions",
        "audio_token_positions",
        "vision_token_positions",
        "union_omni_token_indices",
    ):
        values = record.get(key)
        if values:
            return sorted({int(x) for x in values})
    for start_key, count_key in (
        ("target_token_start", "target_token_count"),
        ("audio_token_start", "audio_token_count"),
        ("video_token_start", "video_token_count"),
    ):
        start = record.get(start_key)
        count = record.get(count_key)
        if start is None or count is None:
            continue
        start_i = int(start)
        count_i = int(count)
        if count_i > 0:
            return [start_i + idx for idx in range(count_i)]
    return []


def expert_positions_and_weights(
    record: Mapping[str, Any] | None,
    *,
    sample_id: str,
    mode: str,
    top_k: int,
) -> dict[str, Any]:
    random_control = str(mode) in {"random_topk_control", "random_topk_or_pool_control"}
    allow_pool_fallback = str(mode) in {"expert_topk_or_pool", "random_topk_or_pool_control"}
    if record is None:
        return {
            "positions": [],
            "weights": [],
            "source": "missing_record",
            "strict_topk_count": 0,
            "pool_count": 0,
        }
    score_by_token: dict[int, float] = {}
    for item in list(record.get("selected_topk_query_attended_tokens") or [])[: max(0, int(top_k))]:
        token_idx = item.get("token_index")
        if token_idx is None:
            continue
        token_idx = int(token_idx)
        score = _expert_item_score(item)
        prev = score_by_token.get(token_idx)
        if prev is None or score > prev:
            score_by_token[token_idx] = float(score)
    if score_by_token:
        positions = sorted(score_by_token)
        weights = [float(score_by_token[pos]) for pos in positions]
        if random_control:
            pool = [pos for pos in _target_pool_positions_from_evidence(record) if pos not in set(positions)]
            if len(pool) < len(positions):
                return {
                    "positions": [],
                    "weights": [],
                    "source": "empty_random_control_pool",
                    "strict_topk_count": len(positions),
                    "pool_count": len(_target_pool_positions_from_evidence(record)),
                }
            rng = torch.Generator(device="cpu")
            rng.manual_seed(_stable_int_seed(sample_id, "expert_evidence_random_topk_control"))
            perm = torch.randperm(len(pool), generator=rng).tolist()
            positions = sorted(pool[int(idx)] for idx in perm[: len(positions)])
            return {
                "positions": positions,
                "weights": weights,
                "source": "random_control_from_expert_topk",
                "strict_topk_count": len(weights),
                "pool_count": len(_target_pool_positions_from_evidence(record)),
            }
        return {
            "positions": positions,
            "weights": weights,
            "source": "expert_topk",
            "strict_topk_count": len(positions),
            "pool_count": len(_target_pool_positions_from_evidence(record)),
        }
    if not allow_pool_fallback:
        return {
            "positions": [],
            "weights": [],
            "source": "empty_expert_topk",
            "strict_topk_count": 0,
            "pool_count": len(_target_pool_positions_from_evidence(record)),
        }
    pool = _target_pool_positions_from_evidence(record)
    if not pool:
        return {
            "positions": [],
            "weights": [],
            "source": "empty_token_pool",
            "strict_topk_count": 0,
            "pool_count": 0,
        }
    # Deterministic sparse pool fallback: keeps the same runtime inputs, but avoids
    # turning hundreds of modality tokens into an overly broad carrier.
    k = min(max(1, int(top_k)), len(pool))
    rng = torch.Generator(device="cpu")
    seed_tag = "expert_evidence_random_pool_control" if random_control else "expert_evidence_pool_fallback"
    rng.manual_seed(_stable_int_seed(sample_id, seed_tag))
    perm = torch.randperm(len(pool), generator=rng).tolist()
    positions = sorted(pool[int(idx)] for idx in perm[:k])
    return {
        "positions": positions,
        "weights": [1.0 for _ in positions],
        "source": "random_control_from_token_pool" if random_control else "target_token_pool_fallback",
        "strict_topk_count": 0,
        "pool_count": len(pool),
    }


@torch.no_grad()
def capture_position_states_by_layer(
    adapter: QwenOmniAdapter,
    *,
    row: Mapping[str, Any],
    layers: Sequence[int],
    positions: Sequence[int],
    budget: Mapping[str, float],
) -> dict[int, torch.Tensor]:
    unique_layers = sorted({int(x) for x in layers})
    unique_positions = sorted({int(x) for x in positions})
    if not unique_layers or not unique_positions:
        return {}
    pos_tensor = torch.tensor(unique_positions, dtype=torch.long)
    inputs = prepare_branch_inputs(adapter, row=dict(row), branch="full", budget=dict(budget))
    thinker = adapter._model.thinker
    captured: dict[int, torch.Tensor] = {}
    hooks = []

    def make_hook(layer_id: int):
        def hook_fn(_module, _inp, output):
            hidden = output[0] if isinstance(output, (tuple, list)) else output
            if not isinstance(hidden, torch.Tensor):
                return None
            pos_dev = pos_tensor.to(device=hidden.device)
            captured[int(layer_id)] = hidden[0, pos_dev, :].detach().float().cpu()
            return None

        return hook_fn

    try:
        for layer in unique_layers:
            hooks.append(thinker.model.layers[int(layer)].register_forward_hook(make_hook(int(layer))))
        _ = thinker(**inputs, use_cache=False, output_attentions=False, return_dict=True)
    finally:
        for hook in hooks:
            hook.remove()
    return captured


def weighted_state_direction(
    states: torch.Tensor,
    weights: Sequence[float],
    *,
    text_anchor: torch.Tensor,
    legacy_reference: torch.Tensor,
) -> torch.Tensor | None:
    if not isinstance(states, torch.Tensor) or states.numel() <= 0 or states.dim() != 2:
        return None
    weight_tensor = _normalize_float_weights(weights)
    if weight_tensor.numel() != int(states.shape[0]):
        return None
    proto = (states.detach().float().cpu() * weight_tensor.unsqueeze(1)).sum(dim=0)
    direction = proto - text_anchor.detach().float().cpu()
    if float(direction.norm().item()) <= 1.0e-12:
        return None
    return _renorm_like(direction, legacy_reference)


