def finite_mean(values: Iterable[Any]) -> float | None:
    clean: list[float] = []
    for value in values:
        try:
            number = float(value)
        except (TypeError, ValueError):
            continue
        if math.isfinite(number):
            clean.append(number)
    return float(sum(clean) / len(clean)) if clean else None


def first_nonempty(values: Iterable[Any]) -> str | None:
    for value in values:
        text = safe_text(value)
        if text:
            return text
    return None


def parse_layer_groups(raw_groups: Sequence[str] | None, layers: Sequence[int]) -> list[list[int]]:
    if not raw_groups:
        return [[int(layer)] for layer in sorted({int(layer) for layer in layers})]
    groups: list[list[int]] = []
    for raw in raw_groups:
        parts = str(raw).replace("+", ",").split(",")
        group = sorted({int(part.strip()) for part in parts if part.strip()})
        if not group:
            continue
        groups.append(group)
    if not groups:
        raise ValueError("--layer-groups was provided but no valid layer group was parsed")
    return groups


def parse_layer_group_weights(
    raw_weights: Sequence[str] | None,
    layer_groups: Sequence[Sequence[int]],
) -> list[dict[int, float]]:
    groups = [[int(layer) for layer in group] for group in layer_groups]
    if not raw_weights:
        return [{layer: 1.0 / float(len(group)) for layer in group} for group in groups]
    if len(raw_weights) != len(groups):
        raise ValueError(
            "--layer-group-weights must be omitted or have the same number of entries as --layer-groups; "
            f"got {len(raw_weights)} weights for {len(groups)} groups."
        )
    parsed: list[dict[int, float]] = []
    for raw, group in zip(raw_weights, groups, strict=True):
        group_set = set(group)
        text = str(raw).strip()
        if not text:
            parsed.append({layer: 1.0 / float(len(group)) for layer in group})
            continue
        weights: dict[int, float] = {}
        parts = [part.strip() for part in text.replace("+", ",").split(",") if part.strip()]
        if all(":" not in part for part in parts):
            if len(parts) != len(group):
                raise ValueError(f"Positional weights for group {group} need {len(group)} values, got {parts}")
            weights = {layer: float(weight) for layer, weight in zip(group, parts, strict=True)}
        else:
            for part in parts:
                if ":" not in part:
                    raise ValueError(f"Mixed named and positional layer weights are not supported: {raw}")
                layer_text, weight_text = part.split(":", 1)
                layer = int(layer_text.strip())
                if layer not in group_set:
                    raise ValueError(f"Layer weight {layer} is not in layer group {group}")
                weights[layer] = float(weight_text.strip())
            missing = [layer for layer in group if layer not in weights]
            if missing:
                raise ValueError(f"Missing weights for layer(s) {missing} in group {group}")
        total = sum(float(value) for value in weights.values())
        if total <= 0.0:
            raise ValueError(f"Layer group weights must sum to a positive value: {raw}")
        parsed.append({layer: float(weights[layer]) / total for layer in group})
    return parsed


def parse_layer_weight_map(raw: str | None) -> dict[int, float] | None:
    if raw is None or not str(raw).strip():
        return None
    text = str(raw).strip()
    parts = [part.strip() for part in text.replace("+", ",").split(",") if part.strip()]
    if not parts:
        return None
    weights: dict[int, float] = {}
    if all(":" not in part for part in parts):
        value = 1.0 / float(len(parts))
        for part in parts:
            weights[int(part)] = value
    else:
        for part in parts:
            if ":" not in part:
                raise ValueError(f"Mixed named and positional layer weights are not supported: {raw}")
            layer_text, weight_text = part.split(":", 1)
            weights[int(layer_text.strip())] = float(weight_text.strip())
    total = sum(float(value) for value in weights.values())
    if total <= 0.0:
        raise ValueError(f"Layer intervention weights must sum to a positive value: {raw}")
    return {layer: float(weight) / total for layer, weight in weights.items()}


def parse_layer_list(raw: str | None) -> list[int]:
    if raw is None or not str(raw).strip():
        return []
    parts = [part.strip() for part in str(raw).replace("+", ",").split(",") if part.strip()]
    return sorted({int(part) for part in parts})


def _finite_float(value: Any, default: float = 0.0) -> float:
    try:
        out = float(value)
    except (TypeError, ValueError):
        return float(default)
    if not math.isfinite(out):
        return float(default)
    return out


def project_update_to_halfspaces(
    update: torch.Tensor,
    constraints: Sequence[tuple[str, torch.Tensor, float]],
    *,
    eps: float = 1.0e-7,
) -> dict[str, Any]:
    """Project an update to linear halfspaces g^T delta >= b.

    The feasible-update operator has only two constraints in practice, so an
    active-set enumeration is exact and avoids introducing an optimizer or any
    benchmark-dependent heuristic.
    """
    x = update.float()
    valid: list[tuple[str, torch.Tensor, float]] = []
    for name, direction, lower_bound in constraints:
        g_raw = direction.to(device=x.device, dtype=torch.float32)
        norm = torch.norm(g_raw)
        if float(norm.item()) <= 1.0e-12:
            continue
        valid.append((str(name), g_raw / norm.clamp_min(1.0e-12), float(lower_bound)))

    def values(candidate: torch.Tensor) -> dict[str, float]:
        return {
            name: float(torch.dot(g, candidate).item())
            for name, g, _bound in valid
        }

    def satisfied(candidate: torch.Tensor) -> bool:
        return all(float(torch.dot(g, candidate).item()) >= bound - eps for _name, g, bound in valid)

    raw_values = values(x)
    if not valid or satisfied(x):
        return {
            "update": x,
            "changed": False,
            "active_constraints": [],
            "constraint_values_before": raw_values,
            "constraint_values_after": raw_values,
            "projection_l2": 0.0,
            "feasible": True,
        }

    candidates: list[tuple[float, torch.Tensor, list[str]]] = []
    n_constraints = len(valid)
    for mask in range(1, 1 << n_constraints):
        active = [idx for idx in range(n_constraints) if mask & (1 << idx)]
        names = [valid[idx][0] for idx in active]
        basis = torch.stack([valid[idx][1] for idx in active], dim=1)  # [d, k]
        lower = torch.tensor(
            [valid[idx][2] for idx in active],
            device=x.device,
            dtype=torch.float32,
        )
        current = basis.T @ x
        gram = basis.T @ basis
        coeff = torch.linalg.pinv(gram) @ (lower - current)
        candidate = x + basis @ coeff
        if satisfied(candidate):
            distance = float(torch.norm(candidate - x).item())
            candidates.append((distance, candidate, names))

    if not candidates:
        # Deterministic fallback for numerically degenerate cases. With two
        # halfspaces this should rarely be used; it still avoids leaving the
        # evidence constraint violated when the active-set solve is singular.
        candidate = x
        active_names: list[str] = []
        for _ in range(4):
            for name, g, bound in valid:
                value = torch.dot(g, candidate)
                violation = float((bound - value).item())
                if violation > eps:
                    candidate = candidate + violation * g
                    if name not in active_names:
                        active_names.append(name)
        return {
            "update": candidate,
            "changed": True,
            "active_constraints": active_names,
            "constraint_values_before": raw_values,
            "constraint_values_after": values(candidate),
            "projection_l2": float(torch.norm(candidate - x).item()),
            "feasible": satisfied(candidate),
        }

    _distance, best, active_names = min(candidates, key=lambda item: item[0])
    return {
        "update": best,
        "changed": True,
        "active_constraints": active_names,
        "constraint_values_before": raw_values,
        "constraint_values_after": values(best),
        "projection_l2": float(torch.norm(best - x).item()),
        "feasible": True,
    }


def feasible_update_projection(
    *,
    base: torch.Tensor,
    raw_update: torch.Tensor,
    evidence_direction: torch.Tensor,
    prior_direction: torch.Tensor,
    beta_for_layer: float,
    evidence_damage_tolerance: float,
    prior_reduction_floor_ratio: float,
    prior_reduction_floor_abs: float,
) -> dict[str, Any]:
    e_dir = unit(evidence_direction).to(device=base.device, dtype=torch.float32)
    p_dir = unit(prior_direction).to(device=base.device, dtype=torch.float32)
    prior_projection = torch.dot(base.float(), p_dir)
    prior_sign = 1.0 if float(prior_projection.item()) >= 0.0 else -1.0
    signed_prior_dir = prior_sign * p_dir
    current_prior_magnitude = abs(float(prior_projection.item()))
    nominal_reduction = max(0.0, float(beta_for_layer) * current_prior_magnitude)
    prior_floor = max(
        0.0,
        float(prior_reduction_floor_abs),
        max(0.0, float(prior_reduction_floor_ratio)) * nominal_reduction,
    )
    prior_floor = min(current_prior_magnitude, prior_floor)
    evidence_lower = -max(0.0, float(evidence_damage_tolerance))

    constraints = [
        ("evidence_preservation", e_dir, evidence_lower),
        ("prior_nonincrease", -signed_prior_dir, prior_floor),
    ]
    projected = project_update_to_halfspaces(raw_update.float(), constraints)
    prior_floor_relaxed = False
    if not bool(projected.get("feasible")) and prior_floor > 0.0:
        prior_floor_relaxed = True
        constraints = [
            ("evidence_preservation", e_dir, evidence_lower),
            ("prior_nonincrease", -signed_prior_dir, 0.0),
        ]
        projected = project_update_to_halfspaces(raw_update.float(), constraints)

    constrained_update = projected["update"].to(device=base.device, dtype=torch.float32)
    raw_evidence_projection = float(torch.dot(raw_update.float(), e_dir).item())
    constrained_evidence_projection = float(torch.dot(constrained_update, e_dir).item())
    raw_prior_reduction = float(torch.dot(-raw_update.float(), signed_prior_dir).item())
    constrained_prior_reduction = float(torch.dot(-constrained_update, signed_prior_dir).item())
    return {
        "update": constrained_update,
        "changed": bool(projected.get("changed")),
        "feasible": bool(projected.get("feasible")),
        "active_constraints": list(projected.get("active_constraints") or []),
        "projection_l2": float(projected.get("projection_l2") or 0.0),
        "constraint_values_before": projected.get("constraint_values_before") or {},
        "constraint_values_after": projected.get("constraint_values_after") or {},
        "evidence_damage_tolerance": max(0.0, float(evidence_damage_tolerance)),
        "evidence_lower_bound": evidence_lower,
        "prior_reduction_floor": float(prior_floor),
        "prior_reduction_floor_ratio": max(0.0, float(prior_reduction_floor_ratio)),
        "prior_reduction_floor_abs": max(0.0, float(prior_reduction_floor_abs)),
        "prior_floor_relaxed": bool(prior_floor_relaxed),
        "current_prior_magnitude": current_prior_magnitude,
        "nominal_prior_reduction": nominal_reduction,
        "raw_update_evidence_projection": raw_evidence_projection,
        "constrained_update_evidence_projection": constrained_evidence_projection,
        "raw_update_prior_reduction": raw_prior_reduction,
        "constrained_update_prior_reduction": constrained_prior_reduction,
        "raw_update_l2": float(raw_update.float().norm().item()),
        "constrained_update_l2": float(constrained_update.norm().item()),
    }


def beta_to_suppression_mu(beta: float) -> float:
    """Map legacy projection shrink beta to quadratic suppression strength.

    For unit prior direction p and lambda=0, the soft-minimal objective
    min 1/2||delta||^2 + mu/2(<h+delta,p>)^2 yields
    delta = -(mu/(1+mu)) <h,p> p. This mapping makes that shrink fraction
    equal to the legacy beta whenever beta < 1.
    """
    shrink = max(0.0, min(0.999, float(beta)))
    return float(shrink / max(1.0e-6, 1.0 - shrink))


def soft_minimal_suppression_delta(
    *,
    base: torch.Tensor,
    prior_direction: torch.Tensor,
    evidence_direction: torch.Tensor,
    beta: float,
    evidence_lambda: float,
) -> dict[str, Any]:
    """Closed-form finite-lambda evidence-preserving conflict suppression.

    It solves, within span{prior,evidence}:
        min_delta 1/2||delta||^2
          + mu/2 (<h + delta, p>)^2
          + lam/2 (<delta, e>)^2
    where p/e are unit directions and mu is calibrated from the legacy beta.
    The operator does not assume p and e are separable; lambda controls how
    strongly target-evidence projection changes are penalized.
    """
    h = base.float()
    p = unit(prior_direction).to(device=h.device, dtype=torch.float32)
    e = unit(evidence_direction).to(device=h.device, dtype=torch.float32)
    mu = beta_to_suppression_mu(beta)
    lam = max(0.0, float(evidence_lambda))
    prior_projection = torch.dot(h, p)
    cos_pe = torch.dot(p, e)
    if mu <= 1.0e-12:
        delta = torch.zeros_like(h)
        return {
            "delta": delta,
            "mu": float(mu),
            "lambda": float(lam),
            "cos_prior_evidence": float(cos_pe.item()),
            "prior_projection_before": float(prior_projection.item()),
            "raw_projection_delta_l2": 0.0,
            "soft_delta_l2": 0.0,
            "delta_evidence_projection": 0.0,
            "delta_prior_projection": 0.0,
            "solver_degenerate": False,
        }

    matrix = torch.stack(
        [
            torch.stack([torch.tensor(1.0 + mu, device=h.device), mu * cos_pe]),
            torch.stack([lam * cos_pe, torch.tensor(1.0 + lam, device=h.device)]),
        ]
    ).to(dtype=torch.float32)
    rhs = torch.tensor([1.0, 0.0], device=h.device, dtype=torch.float32)
    solver_degenerate = False
    try:
        coeff = torch.linalg.solve(matrix, rhs)
    except RuntimeError:
        solver_degenerate = True
        coeff = torch.linalg.pinv(matrix) @ rhs
    inverse_prior = coeff[0] * p + coeff[1] * e
    delta = -mu * prior_projection * inverse_prior
    raw_projection_delta = -max(0.0, float(beta)) * prior_projection * p
    return {
        "delta": delta,
        "mu": float(mu),
        "lambda": float(lam),
        "cos_prior_evidence": float(cos_pe.item()),
        "prior_projection_before": float(prior_projection.item()),
        "raw_projection_delta_l2": float(raw_projection_delta.norm().item()),
        "soft_delta_l2": float(delta.norm().item()),
        "delta_evidence_projection": float(torch.dot(delta, e).item()),
        "delta_prior_projection": float(torch.dot(delta, p).item()),
        "solver_degenerate": bool(solver_degenerate),
    }


def up_r_projection_delta(
    *,
    base: torch.Tensor,
    prior_direction: torch.Tensor,
    evidence_direction: torch.Tensor,
    beta: float,
) -> dict[str, Any]:
    """Rank-1 U/P/R rewrite of the legacy projection shrinkage.

    HulluEdit decomposes a hidden state into evidence, anti-prior, and residual
    subspaces. In the current-mainline limiting case, U is the unit evidence
    carrier and P is the already selected prior carrier. Shrinking h_P by
    s_P = 1 - beta is exactly delta = -beta * Proj_P(h).
    """
    h = base.float()
    p = unit(prior_direction).to(device=h.device, dtype=torch.float32)
    u = unit(evidence_direction).to(device=h.device, dtype=torch.float32)
    beta_value = float(beta)
    h_p = torch.dot(h, p) * p
    h_u = torch.dot(h, u) * u
    h_r = h - h_u - h_p
    shrink_p = 1.0 - beta_value
    delta = (shrink_p - 1.0) * h_p
    updated = h + delta
    legacy_delta = -beta_value * h_p
    lambda_p = beta_value / max(1.0e-6, 1.0 - beta_value) if beta_value < 1.0 else None
    return {
        "delta": delta,
        "legacy_delta": legacy_delta,
        "equivalence_error_l2": float((delta - legacy_delta).norm().item()),
        "u_p_abs_cos": abs(float(torch.dot(u, p).item())),
        "u_component_l2": float(h_u.norm().item()),
        "p_component_l2": float(h_p.norm().item()),
        "r_component_l2": float(h_r.norm().item()),
        "p_shrink": float(shrink_p),
        "lambda_p_equiv": lambda_p,
        "prior_projection_before": float(torch.dot(h, p).item()),
        "prior_projection_after": float(torch.dot(updated, p).item()),
        "evidence_projection_before": float(torch.dot(h, u).item()),
        "evidence_projection_after": float(torch.dot(updated, u).item()),
    }


def signed_path_closed_form_delta(
    *,
    base: torch.Tensor,
    evidence_basis: torch.Tensor,
    prior_basis: torch.Tensor,
    beta_scale: float,
    kappa: float,
    lambda_prior: float,
    lambda_n_max: float,
    lambda_p_max: float,
    vcr_floor: float,
    pcr_ceiling: float,
    pcr_threshold: float,
    blend_tau: float,
    norm_preserve: bool,
    norm_beta: float,
    trust_mode: str = "hulluedit",
) -> dict[str, Any]:
    """HulluEdit-style closed-form edit on our signed cross-modal path U/P."""
    h = base.float()
    eps = 1.0e-6
    trust_key = safe_text(trust_mode) or "hulluedit"
    if trust_key not in {"hulluedit", "coverage"}:
        raise ValueError(f"unsupported signed_path_closed_form trust_mode: {trust_mode}")

    def basis_component(basis_payload: torch.Tensor) -> tuple[torch.Tensor, bool, int]:
        basis = torch.as_tensor(basis_payload).detach().float().to(device=h.device)
        if basis.ndim != 2 or int(basis.shape[0]) != int(h.numel()) or int(basis.shape[1]) <= 0:
            return torch.zeros_like(h), False, 0
        return basis @ (basis.T @ h), True, int(basis.shape[1])

    h_u, u_available, rank_u = basis_component(evidence_basis)
    h_p, p_available, rank_p = basis_component(prior_basis)
    if not u_available and not p_available:
        return {
            "delta": torch.zeros_like(h),
            "available": False,
            "reason": "empty_signed_path_basis",
            "trust_mode": trust_key,
            "lambda_n": 0.0,
            "lambda_p": 0.0,
            "gate": 0.0,
            "vcr": 0.0,
            "pcr": 0.0,
            "rank_evidence": rank_u,
            "rank_prior": rank_p,
        }

    h_r = h - h_u - h_p
    h_norm_sq = torch.dot(h, h) + eps
    vcr_raw = torch.dot(h_u, h_u) / h_norm_sq
    pcr_raw = torch.dot(h_p, h_p) / h_norm_sq
    vcr = torch.clamp(vcr_raw, min=float(vcr_floor), max=1.0)
    pcr = torch.clamp(pcr_raw, min=0.0, max=float(pcr_ceiling))
    beta_value = max(0.0, float(beta_scale))
    if beta_value <= 1.0e-12:
        lambda_n = torch.zeros((), device=h.device, dtype=h.dtype)
        lambda_p = torch.zeros((), device=h.device, dtype=h.dtype)
    else:
        if trust_key == "coverage":
            carrier_coverage = torch.sqrt(vcr_raw.clamp(0.0, 1.0))
            lambda_n = beta_value * float(kappa) * carrier_coverage / (1.0 - carrier_coverage + eps)
        else:
            lambda_n = beta_value * float(kappa) * (1.0 - vcr) / (vcr + eps)
        if bool(p_available) and float(pcr.detach().cpu().item()) >= float(pcr_threshold):
            lambda_p = beta_value * float(lambda_prior) * pcr / (1.0 - pcr + eps)
        else:
            lambda_p = torch.zeros((), device=h.device, dtype=h.dtype)
    lambda_n = torch.clamp(lambda_n, min=0.0, max=float(lambda_n_max))
    lambda_p = torch.clamp(lambda_p, min=0.0, max=float(lambda_p_max))

    h_closed = h_u + h_p / (1.0 + lambda_n + lambda_p) + h_r / (1.0 + lambda_n)
    norm_scale = torch.ones((), device=h.device, dtype=h.dtype)
    if bool(norm_preserve):
        h_closed_norm = torch.sqrt(torch.dot(h_closed, h_closed) + eps)
        h_orig_norm = torch.sqrt(torch.dot(h, h) + eps)
        norm_scale = (h_orig_norm / h_closed_norm).pow(float(norm_beta))
        h_closed = h_closed * norm_scale

    tau = max(0.0, min(1.0, float(blend_tau)))
    h_edited = (1.0 - tau) * h + tau * h_closed
    delta = h_edited - h
    gate = lambda_n / (1.0 + lambda_n)
    return {
        "delta": delta,
        "available": True,
        "reason": "ok",
        "trust_mode": trust_key,
        "lambda_n": float(lambda_n.detach().cpu().item()),
        "lambda_p": float(lambda_p.detach().cpu().item()),
        "gate": float(gate.detach().cpu().item()),
        "vcr": float(vcr_raw.detach().cpu().item()),
        "pcr": float(pcr_raw.detach().cpu().item()),
        "vcr_clipped": float(vcr.detach().cpu().item()),
        "pcr_clipped": float(pcr.detach().cpu().item()),
        "blend_tau": float(tau),
        "norm_scale": float(norm_scale.detach().cpu().item()),
        "rank_evidence": rank_u,
        "rank_prior": rank_p,
        "u_component_l2": float(h_u.norm().detach().cpu().item()),
        "p_component_l2": float(h_p.norm().detach().cpu().item()),
        "r_component_l2": float(h_r.norm().detach().cpu().item()),
        "delta_l2": float(delta.norm().detach().cpu().item()),
    }


def _max_normalize(values: Mapping[int, float]) -> dict[int, float]:
    max_value = max((abs(float(value)) for value in values.values()), default=0.0)
    if max_value <= 1.0e-12:
        return {int(key): 0.0 for key in values}
    return {int(key): max(0.0, float(value)) / max_value for key, value in values.items()}


def adaptive_layer_group_weights(
    group: Sequence[int],
    base_weights: Mapping[int, float],
    carriers: Mapping[int, Mapping[str, Any]],
    *,
    mode: str,
) -> dict[int, float]:
    group_layers = [int(layer) for layer in group]
    if str(mode) == "none" or len(group_layers) <= 1:
        return {layer: float(base_weights[int(layer)]) for layer in group_layers}
    if str(mode) != "conflict_bottleneck":
        raise ValueError(f"Unsupported adaptive-layer-weights mode: {mode}")

    prior_projection = {
        layer: abs(_finite_float(carriers[layer].get("prior_projection_before")))
        for layer in group_layers
    }
    prior_residual = {
        layer: _finite_float(carriers[layer].get("u_p_perp_norm"))
        for layer in group_layers
    }
    evidence_gap = {
        layer: max(0.0, _finite_float(carriers[layer].get("evidence_transfer_gap")))
        for layer in group_layers
    }
    prior_projection_n = _max_normalize(prior_projection)
    prior_residual_n = _max_normalize(prior_residual)
    evidence_gap_n = _max_normalize(evidence_gap)

    # Decision-near layers are a prior, not a hard rule. The row-specific
    # conflict statistics can still move mass away from L26 when needed.
    layer_bias_default = 0.45
    layer_bias = {
        20: 0.35,
        22: 0.55,
        24: 0.82,
        26: 1.00,
        27: 0.62,
    }
    raw_scores: dict[int, float] = {}
    for layer in group_layers:
        clean_cos = abs(_finite_float(carriers[layer].get("cos_e_clean_p_perp")))
        raw_cos = abs(_finite_float(carriers[layer].get("cos_e_p_perp")))
        entanglement_penalty = min(0.95, max(clean_cos, raw_cos))
        disentangled_safety = 1.0 - entanglement_penalty
        conflict_score = (
            0.46 * prior_projection_n[layer]
            + 0.34 * evidence_gap_n[layer]
            + 0.20 * prior_residual_n[layer]
        )
        raw_scores[layer] = (
            max(0.05, layer_bias.get(layer, layer_bias_default))
            * max(0.05, conflict_score)
            * (0.50 + 0.50 * max(0.0, disentangled_safety))
        )

    score_sum = sum(raw_scores.values())
    if score_sum <= 1.0e-12:
        adaptive = {layer: 1.0 / len(group_layers) for layer in group_layers}
    else:
        adaptive = {layer: raw_scores[layer] / score_sum for layer in group_layers}

    base_sum = sum(max(0.0, float(base_weights[int(layer)])) for layer in group_layers)
    if base_sum <= 1.0e-12:
        base = {layer: 1.0 / len(group_layers) for layer in group_layers}
    else:
        base = {layer: max(0.0, float(base_weights[int(layer)])) / base_sum for layer in group_layers}

    blended = {
        layer: 0.65 * adaptive[layer] + 0.35 * base[layer]
        for layer in group_layers
    }
    total = sum(blended.values())
    if total <= 1.0e-12:
        return {layer: 1.0 / len(group_layers) for layer in group_layers}
    return {layer: blended[layer] / total for layer in group_layers}


def adaptive_intervention_layer_weights(
    group: Sequence[int],
    base_weights: Mapping[int, float] | None,
    carriers: Mapping[int, Mapping[str, Any]],
    *,
    mode: str,
    kind: str,
) -> dict[int, float] | None:
    if str(mode) == "none":
        return None
    group_layers = [int(layer) for layer in group]
    if base_weights is None:
        base = {layer: 1.0 / float(len(group_layers)) for layer in group_layers}
    else:
        base = {layer: max(0.0, float(base_weights.get(layer, 0.0))) for layer in group_layers}
    candidates = [layer for layer in group_layers if base.get(layer, 0.0) > 1.0e-12]
    if not candidates:
        return None
    if len(candidates) == 1:
        return {candidates[0]: 1.0}

    if kind == "evidence":
        if str(mode) != "evidence_lift":
            raise ValueError(f"Unsupported adaptive evidence intervention mode: {mode}")
        evidence_gap = {
            layer: max(0.0, _finite_float(carriers[layer].get("evidence_transfer_gap")))
            for layer in candidates
        }
        clean_gap = {
            layer: max(0.0, _finite_float(carriers[layer].get("clean_target_full_evidence_gap")))
            for layer in candidates
        }
        evidence_advantage = {
            layer: max(0.0, _finite_float(carriers[layer].get("clean_target_evidence_advantage")))
            for layer in candidates
        }
        target_full_clean_norm = {
            layer: max(0.0, _finite_float(carriers[layer].get("target_full_gap_clean_norm")))
            for layer in candidates
        }
        evidence_gap_n = _max_normalize(evidence_gap)
        clean_gap_n = _max_normalize(clean_gap)
        evidence_advantage_n = _max_normalize(evidence_advantage)
        target_full_clean_norm_n = _max_normalize(target_full_clean_norm)
        layer_bias_default = 0.40
        # Evidence is less fused in earlier answer-path layers; this is a soft prior.
        layer_bias = {
            8: 0.75,
            10: 0.90,
            12: 1.00,
            14: 0.95,
            16: 0.86,
            18: 0.76,
            20: 0.64,
            22: 0.45,
        }
        raw_scores: dict[int, float] = {}
        for layer in candidates:
            raw_entangle = abs(_finite_float(carriers[layer].get("cos_e_p_raw")))
            entanglement_safety = 1.0 - min(0.95, raw_entangle)
            evidence_score = (
                0.40 * evidence_gap_n[layer]
                + 0.25 * clean_gap_n[layer]
                + 0.20 * evidence_advantage_n[layer]
                + 0.15 * target_full_clean_norm_n[layer]
            )
            raw_scores[layer] = (
                max(0.05, layer_bias.get(layer, layer_bias_default))
                * max(0.05, evidence_score)
                * (0.70 + 0.30 * max(0.0, entanglement_safety))
            )
    elif kind == "prior":
        if str(mode) != "conflict_bottleneck":
            raise ValueError(f"Unsupported adaptive prior intervention mode: {mode}")
        prior_projection = {
            layer: abs(_finite_float(carriers[layer].get("prior_projection_before")))
            for layer in candidates
        }
        prior_residual = {
            layer: _finite_float(carriers[layer].get("u_p_perp_norm"))
            for layer in candidates
        }
        evidence_gap = {
            layer: max(0.0, _finite_float(carriers[layer].get("evidence_transfer_gap")))
            for layer in candidates
        }
        prior_projection_n = _max_normalize(prior_projection)
        prior_residual_n = _max_normalize(prior_residual)
        evidence_gap_n = _max_normalize(evidence_gap)
        layer_bias_default = 0.45
        # Late layers are closer to answer arbitration; this is a soft prior.
        layer_bias = {
            20: 0.35,
            22: 0.55,
            24: 0.82,
            26: 1.00,
            27: 0.62,
        }
        raw_scores = {}
        for layer in candidates:
            clean_cos = abs(_finite_float(carriers[layer].get("cos_e_clean_p_perp")))
            raw_cos = abs(_finite_float(carriers[layer].get("cos_e_p_perp")))
            entanglement_penalty = min(0.95, max(clean_cos, raw_cos))
            disentangled_safety = 1.0 - entanglement_penalty
            conflict_score = (
                0.46 * prior_projection_n[layer]
                + 0.34 * evidence_gap_n[layer]
                + 0.20 * prior_residual_n[layer]
            )
            raw_scores[layer] = (
                max(0.05, layer_bias.get(layer, layer_bias_default))
                * max(0.05, conflict_score)
                * (0.50 + 0.50 * max(0.0, disentangled_safety))
            )
    else:
        raise ValueError(f"Unsupported intervention layer weight kind: {kind}")

    score_sum = sum(raw_scores.values())
    if score_sum <= 1.0e-12:
        adaptive = {layer: 1.0 / len(candidates) for layer in candidates}
    else:
        adaptive = {layer: raw_scores[layer] / score_sum for layer in candidates}
    base_sum = sum(base[layer] for layer in candidates)
    if base_sum <= 1.0e-12:
        base_n = {layer: 1.0 / len(candidates) for layer in candidates}
    else:
        base_n = {layer: base[layer] / base_sum for layer in candidates}
    # Keep a weak base prior so adaptive weights cannot collapse to one noisy layer.
    blend_adaptive = 0.75 if kind == "evidence" else 0.65
    blended = {
        layer: blend_adaptive * adaptive[layer] + (1.0 - blend_adaptive) * base_n[layer]
        for layer in candidates
    }
    total = sum(blended.values())
    if total <= 1.0e-12:
        return {layer: 1.0 / len(candidates) for layer in candidates}
    return {layer: blended[layer] / total for layer in candidates}


def adaptive_evidence_alpha_gate(
    group: Sequence[int],
    evidence_weights: Mapping[int, float] | None,
    carriers: Mapping[int, Mapping[str, Any]],
    *,
    mode: str,
    max_cos_prior: float,
    max_cos_fusion: float,
    max_advantage: float,
    min_gap: float,
) -> dict[str, Any]:
    if str(mode) == "none":
        return {
            "scale": 1.0,
            "accepted": True,
            "reason": "disabled",
            "layers": [int(layer) for layer in group],
        }
    if str(mode) != "clean_deficient_gate":
        raise ValueError(f"Unsupported adaptive evidence alpha mode: {mode}")
    if evidence_weights is None:
        active_layers = [int(layer) for layer in group]
    else:
        active_layers = [
            int(layer)
            for layer in group
            if float(evidence_weights.get(int(layer), 0.0)) > 1.0e-12
        ]
    active_layers = [layer for layer in active_layers if layer in carriers]
    if not active_layers:
        return {
            "scale": 0.0,
            "accepted": False,
            "reason": "no_active_evidence_layers",
            "layers": [],
        }

    mean_abs_cos_prior = finite_mean(
        abs(_finite_float(carriers[layer].get("cos_e_p_raw"))) for layer in active_layers
    )
    mean_abs_cos_fusion = finite_mean(
        abs(_finite_float(carriers[layer].get("cos_raw_prior_fusion_residual"))) for layer in active_layers
    )
    mean_clean_advantage = finite_mean(
        _finite_float(carriers[layer].get("clean_target_evidence_advantage")) for layer in active_layers
    )
    mean_clean_gap = finite_mean(
        max(0.0, _finite_float(carriers[layer].get("clean_target_full_evidence_gap")))
        for layer in active_layers
    )
    clean = (
        mean_abs_cos_prior is not None
        and mean_abs_cos_fusion is not None
        and float(mean_abs_cos_prior) <= float(max_cos_prior)
        and float(mean_abs_cos_fusion) <= float(max_cos_fusion)
    )
    deficient = (
        mean_clean_advantage is not None
        and mean_clean_gap is not None
        and float(mean_clean_advantage) <= float(max_advantage)
        and float(mean_clean_gap) >= float(min_gap)
    )
    accepted = bool(clean and deficient)
    failed = []
    if not clean:
        failed.append("not_clean")
    if not deficient:
        failed.append("not_deficient")
    return {
        "scale": 1.0 if accepted else 0.0,
        "accepted": accepted,
        "reason": "accepted" if accepted else "+".join(failed),
        "layers": active_layers,
        "mean_abs_cos_prior": mean_abs_cos_prior,
        "mean_abs_cos_fusion": mean_abs_cos_fusion,
        "mean_clean_target_evidence_advantage": mean_clean_advantage,
        "mean_clean_target_full_evidence_gap": mean_clean_gap,
        "max_cos_prior": float(max_cos_prior),
        "max_cos_fusion": float(max_cos_fusion),
        "max_advantage": float(max_advantage),
        "min_gap": float(min_gap),
    }


def layer_group_weight_label(layer_group: Sequence[int], weights: Mapping[int, float]) -> str:
    parts = []
    for layer in [int(layer) for layer in layer_group]:
        weight = float(weights[int(layer)])
        parts.append(f"{layer}:{weight:.4g}")
    return "+".join(parts)


def infer_thinker_text_layer_count(model_path: str | Path) -> int | None:
    config_path = Path(model_path) / "config.json"
    if not config_path.exists():
        return None
    with config_path.open("r", encoding="utf-8") as handle:
        config = json.load(handle)
    candidates = [
        config.get("thinker_config", {}).get("text_config", {}).get("num_hidden_layers"),
        config.get("text_config", {}).get("num_hidden_layers"),
        config.get("num_hidden_layers"),
    ]
    for value in candidates:
        try:
            count = int(value)
        except (TypeError, ValueError):
            continue
        if count > 0:
            return count
    return None


def validate_model_layers(layers: Sequence[int], model_path: str | Path) -> int | None:
    layer_count = infer_thinker_text_layer_count(model_path)
    if layer_count is None:
        return None
    invalid = [int(layer) for layer in layers if int(layer) < 0 or int(layer) >= layer_count]
    if invalid:
        valid_range = f"0..{layer_count - 1}"
        raise ValueError(
            f"Invalid thinker text layer(s) {invalid} for model {model_path}; "
            f"valid layer index range is {valid_range}."
        )
    return layer_count


def layer_group_label(layer_group: Sequence[int]) -> int | str:
    group = [int(layer) for layer in layer_group]
    if len(group) == 1:
        return int(group[0])
    return "+".join(str(layer) for layer in group)


def layer_group_text(layer_group: Sequence[int]) -> str:
    return str(layer_group_label(layer_group))


def answer_correct(answer: Any, reference: Any) -> bool | None:
    if safe_text(reference) == AXIS_OTHER_REFERENCE:
        return False if normalize_binary_label(answer) is not None else None
    a = normalize_binary_label(answer)
    r = normalize_binary_label(reference)
    if not a or not r:
        return None
    return a == r


def _label_token_id(adapter: QwenOmniAdapter, label: Any) -> int | None:
    text = safe_text(label)
    if not text:
        return None
    tokenizer = adapter._processor.tokenizer
    for surface in (text, f" {text}"):
        token_ids = tokenizer.encode(surface, add_special_tokens=False)
        if len(token_ids) == 1:
            return int(token_ids[0])
    return None


def row_answer_axis_token_ids(
    adapter: QwenOmniAdapter,
    row: Mapping[str, Any],
    *,
    default_yes_id: int,
    default_no_id: int,
) -> tuple[int, int, dict[str, Any]]:
    if not bool(row.get("answer_axis_enabled")):
        return int(default_yes_id), int(default_no_id), {"answer_axis_enabled": False}
    yes_label = safe_text(row.get("answer_axis_yes_label"))
    no_label = safe_text(row.get("answer_axis_no_label"))
    yes_id = _label_token_id(adapter, row.get("answer_axis_yes_token") or yes_label)
    no_id = _label_token_id(adapter, row.get("answer_axis_no_token") or no_label)
    if yes_id is None or no_id is None or yes_id == no_id:
        raise ValueError(
            "invalid row-local answer axis for "
            f"sample={row.get('sample_id')}: yes={yes_label!r}/{yes_id}, no={no_label!r}/{no_id}"
        )
    return int(yes_id), int(no_id), {
        "answer_axis_enabled": True,
        "answer_axis_yes_label": yes_label,
        "answer_axis_no_label": no_label,
        "answer_axis_yes_token_id": int(yes_id),
        "answer_axis_no_token_id": int(no_id),
        "answer_axis_reference_label": safe_text(row.get("answer_axis_reference_label")),
        "answer_axis_reference_outside": bool(row.get("answer_axis_reference_outside")),
    }


def literal_answer_axis_from_frozen_head(
    adapter: QwenOmniAdapter,
    *,
    current_answer: str | None,
    candidate_answer: str | None,
    yes_id: int,
    no_id: int,
) -> tuple[torch.Tensor, dict[str, Any]]:
    """Return the strict literal W_h-W_c axis, oriented from current c to candidate h.

    This intentionally refuses multi-token or aliased answer surfaces.  A first-token
    approximation would not be the literal answer-vector control requested by G1.
    """

    current = normalize_binary_label(current_answer)
    candidate = normalize_binary_label(candidate_answer)
    if current is None or candidate is None or current == candidate:
        raise ValueError(
            "literal_answer_axis requires distinct normalized current/candidate answers; "
            f"got current={current_answer!r}, candidate={candidate_answer!r}"
        )
    tokenizer = adapter._processor.tokenizer
    token_ids_by_label: dict[str, int] = {}
    for label, expected_id in (("Yes", int(yes_id)), ("No", int(no_id))):
        encoded = tokenizer.encode(label, add_special_tokens=False)
        if len(encoded) != 1:
            raise ValueError(
                "literal_answer_axis is undefined because the Qwen tokenizer does not "
                f"encode {label!r} as exactly one token: token_ids={encoded}"
            )
        token_id = int(encoded[0])
        if token_id != int(expected_id):
            raise ValueError(
                "literal_answer_axis token identity disagrees with the active answer axis: "
                f"label={label!r}, strict_token_id={token_id}, active_token_id={expected_id}"
            )
        token_ids_by_label[label] = token_id

    lm_head = adapter._model.thinker.lm_head
    weight = getattr(lm_head, "weight", None)
    if not isinstance(weight, torch.Tensor) or weight.ndim != 2:
        raise ValueError("literal_answer_axis requires a 2-D frozen thinker language-head weight")
    h_id = token_ids_by_label[candidate]
    c_id = token_ids_by_label[current]
    axis = (weight[h_id] - weight[c_id]).detach().float().cpu()
    if axis.ndim != 1 or axis.numel() != int(weight.shape[1]):
        raise ValueError(
            "literal_answer_axis cannot enter the thinker hidden dimension: "
            f"axis_shape={tuple(axis.shape)}, lm_head_shape={tuple(weight.shape)}"
        )
    axis_norm = float(axis.norm().item())
    if not math.isfinite(axis_norm) or axis_norm <= 1.0e-12:
        raise ValueError(
            "literal_answer_axis is degenerate for the active current/candidate tokens: "
            f"current={current!r}/{c_id}, candidate={candidate!r}/{h_id}, norm={axis_norm}"
        )
    return axis / axis_norm, {
        "mode": "literal_answer_axis",
        "current_answer_c": current,
        "candidate_answer_h": candidate,
        "current_token_id_c": c_id,
        "candidate_token_id_h": h_id,
        "axis_raw_l2": axis_norm,
        "axis_hidden_dim": int(axis.numel()),
        "axis_orientation": "W_h_minus_W_c",
    }


def axis_label_for_binary(row: Mapping[str, Any], answer: Any) -> str | None:
    label = normalize_binary_label(answer)
    if label == "Yes":
        return safe_text(row.get("answer_axis_yes_label")) or "Yes"
    if label == "No":
        return safe_text(row.get("answer_axis_no_label")) or "No"
    return None


def axis_reference_for_runtime(row: Mapping[str, Any]) -> str | None:
    reference = normalize_binary_label(row.get("reference_answer"))
    if reference is not None:
        return reference
    if bool(row.get("answer_axis_reference_outside")):
        return AXIS_OTHER_REFERENCE
    return None


def axis_original_correct(row: Mapping[str, Any], binary_answer: Any) -> bool | None:
    predicted = axis_label_for_binary(row, binary_answer)
    reference = safe_text(row.get("answer_axis_reference_label"))
    if predicted is None:
        return None
    if not reference:
        return None
    return predicted == reference


def target_branch_for(row: Mapping[str, Any]) -> str:
    modality = safe_text(row.get("target_modality")).lower()
    if modality == "audio":
        return "audio_only"
    if modality == "visual":
        return "visual_only"
    raise ValueError(f"Unsupported target_modality={modality!r} for sample={row.get('sample_id')}")


def non_target_branch_for(row: Mapping[str, Any]) -> str:
    return "visual_only" if target_branch_for(row) == "audio_only" else "audio_only"


def yes_no_payload(logits: torch.Tensor) -> dict[str, Any]:
    values = logits.detach().float().cpu().reshape(-1)
    yes_logit = float(values[0].item())
    no_logit = float(values[1].item())
    probs = torch.softmax(values, dim=0)
    margin = yes_logit - no_logit
    return {
        "yes_logit": yes_logit,
        "no_logit": no_logit,
        "yes_prob": float(probs[0].item()),
        "no_prob": float(probs[1].item()),
        "margin_yes_minus_no": margin,
        "prediction": pred_from_margin(margin),
    }


def _mask_positions(mask: torch.Tensor) -> torch.Tensor:
    return torch.nonzero(mask.detach().cpu().bool(), as_tuple=False).flatten().long()


def _resolve_token_group_positions(
    *,
    label_masks: Mapping[str, torch.Tensor],
    group: str,
    target_modality: str,
) -> torch.Tensor:
    target = safe_text(target_modality).lower()
    key = safe_text(group).lower()
    if key == "auto_target":
        key = "audio" if target == "audio" else "video"
    elif key in {"auto_target_non_target", "auto_target_plus_non_target"}:
        key = "audio_video"
    elif key == "auto_non_target":
        key = "video" if target == "audio" else "audio"
    mapping = {
        "audio": "A",
        "video": "V",
        "visual": "V",
        "vision": "V",
        "language": "L",
        "audio_video": "VA",
        "audio_visual": "VA",
        "language_audio": "LA",
        "language_video": "LV",
    }
    if key == "language_non_target":
        base = label_masks["L"].detach().cpu().bool()
        non_target = "V" if target == "audio" else "A"
        return _mask_positions(base | label_masks[non_target].detach().cpu().bool())
    mask_key = mapping.get(key)
    if mask_key is None or mask_key not in label_masks:
        raise ValueError(f"unsupported token group {group!r} for target_modality={target_modality!r}")
    return _mask_positions(label_masks[mask_key])


def _resolve_causallens_system_positions(
    *,
    input_ids: torch.Tensor,
    attention_mask: torch.Tensor,
    special_ids: Mapping[str, int | None],
) -> torch.Tensor:
    """Approximate CausalLens H_sys tokens as valid non-media tokens before media.

    The common AVCD language mask intentionally keeps post-media question text.
    CausalLens, however, gates with the system-prompt pathway H_sys and then
    forms T=H_sys+H_text. For Qwen-Omni prompts, the closest label-free proxy is
    the valid non-media prefix before the first audio/video token.
    """
    masks = build_token_group_masks(
        input_ids=input_ids.detach().cpu(),
        attention_mask=attention_mask.detach().cpu(),
        special_ids=dict(special_ids),
    )
    valid = masks["valid"].detach().cpu().bool()
    media = masks["media"].detach().cpu().bool()
    seq_len = int(valid.numel())
    if seq_len <= 0 or int(media.sum().item()) <= 0:
        return torch.empty(0, dtype=torch.long)
    first_media = int(torch.nonzero(media, as_tuple=False).flatten().min().item())
    positions = torch.arange(seq_len, dtype=torch.long)
    system = valid & ~media & (positions < first_media)
    return _mask_positions(system)


def _select_patch_heads(
    *,
    source_mass: torch.Tensor,
    evidence_mass: torch.Tensor,
    mode: str,
    max_heads: int,
    min_source_margin: float,
    min_source_mass: float,
    seed: int,
    answer_current_over_candidate: torch.Tensor | None = None,
    min_answer_contribution: float = 0.0,
) -> torch.Tensor:
    # source_mass/evidence_mass: [num_heads]
    num_heads = int(source_mass.numel())
    if num_heads <= 0:
        return torch.empty(0, dtype=torch.long)
    max_count = min(max(0, int(max_heads)), num_heads)
    if max_count <= 0:
        return torch.empty(0, dtype=torch.long)
    mode = safe_text(mode).lower()
    if mode == "all":
        return torch.arange(num_heads, dtype=torch.long)
    margin = source_mass.float() - evidence_mass.float()
    eligible = torch.arange(num_heads, dtype=torch.long)
    eligible = eligible[source_mass.float() >= float(min_source_mass)]
    if mode == "source_over_evidence":
        eligible = eligible[margin[eligible] >= float(min_source_margin)]
        if eligible.numel() <= 0:
            return torch.empty(0, dtype=torch.long)
        scores = margin[eligible]
    elif mode == "low_source_over_evidence":
        if eligible.numel() <= 0:
            return torch.empty(0, dtype=torch.long)
        scores = margin[eligible]
    elif mode == "answer_contribution":
        if answer_current_over_candidate is None:
            return torch.empty(0, dtype=torch.long)
        answer_scores = answer_current_over_candidate.detach().float().cpu()
        if answer_scores.numel() != num_heads:
            raise ValueError(
                "answer_current_over_candidate must have one score per head "
                f"({answer_scores.numel()} != {num_heads})"
            )
        if float(min_source_margin) > 0.0:
            eligible = eligible[margin[eligible] >= float(min_source_margin)]
        eligible = eligible[answer_scores[eligible] >= float(min_answer_contribution)]
        if eligible.numel() <= 0:
            return torch.empty(0, dtype=torch.long)
        scores = answer_scores[eligible]
    elif mode == "source_answer_contribution":
        if answer_current_over_candidate is None:
            return torch.empty(0, dtype=torch.long)
        answer_scores = answer_current_over_candidate.detach().float().cpu()
        if answer_scores.numel() != num_heads:
            raise ValueError(
                "answer_current_over_candidate must have one score per head "
                f"({answer_scores.numel()} != {num_heads})"
            )
        margin_floor = max(0.0, float(min_source_margin))
        eligible = eligible[margin[eligible] > margin_floor]
        eligible = eligible[answer_scores[eligible] >= float(min_answer_contribution)]
        if eligible.numel() <= 0:
            return torch.empty(0, dtype=torch.long)
        scores = answer_scores[eligible]
    elif mode in {"source_mass_topk", "random_control"}:
        if eligible.numel() <= 0:
            return torch.empty(0, dtype=torch.long)
        scores = source_mass[eligible].float()
    else:
        raise ValueError(f"unsupported head selection mode: {mode}")
    k = min(max_count, int(eligible.numel()))
    if mode == "random_control":
        generator = torch.Generator(device="cpu")
        generator.manual_seed(int(seed))
        perm = torch.randperm(int(eligible.numel()), generator=generator)
        return eligible[perm[:k]].sort().values
    order = torch.argsort(scores, descending=(mode != "low_source_over_evidence"))
    return eligible[order[:k]].sort().values


def _causallens_raw_evidence_sensitivity(
    row: torch.Tensor,
    evidence_gate: torch.Tensor,
    eps: float = 1.0e-12,
) -> tuple[torch.Tensor, torch.Tensor]:
    """CausalLens sensitivity on raw evidence attention weights.

    CausalLens defines s=Var(A_evidence)/(Mean(A_evidence)+eps) over the
    evidence-token attention slice. We deliberately do not renormalize the
    evidence slice; otherwise low-mass but locally sharp heads are over-rated.
    """
    gate = evidence_gate.float().clamp(0.0, 1.0)
    values = row.float() * gate
    count = gate.sum(dim=-1).clamp_min(1.0)
    mean = values.sum(dim=-1) / count
    var = ((values - mean.unsqueeze(-1)).square() * gate).sum(dim=-1) / count
    sensitivity = var / mean.clamp_min(eps)
    sensitivity_hat = sensitivity / sensitivity.mean(dim=1, keepdim=True).clamp_min(eps)
    return sensitivity, sensitivity_hat


def _select_evidence_support_heads(
    *,
    source_mass: torch.Tensor,
    evidence_mass: torch.Tensor,
    max_heads: int,
    exclude_heads: torch.Tensor,
    answer_candidate_over_current: torch.Tensor | None = None,
    min_answer_contribution: float = 0.0,
) -> torch.Tensor:
    num_heads = int(evidence_mass.numel())
    max_count = min(max(0, int(max_heads)), num_heads)
    if num_heads <= 0 or max_count <= 0:
        return torch.empty(0, dtype=torch.long)
    margin = evidence_mass.detach().float().cpu() - source_mass.detach().float().cpu()
    eligible = torch.arange(num_heads, dtype=torch.long)
    if exclude_heads.numel() > 0:
        keep = torch.ones(num_heads, dtype=torch.bool)
        keep[exclude_heads.detach().cpu().long()] = False
        eligible = eligible[keep[eligible]]
    eligible = eligible[margin[eligible] > 0.0]
    if eligible.numel() <= 0:
        return torch.empty(0, dtype=torch.long)
    k = min(max_count, int(eligible.numel()))
    scores = margin[eligible]
    if answer_candidate_over_current is not None:
        answer_scores = answer_candidate_over_current.detach().float().cpu()
        if answer_scores.numel() != num_heads:
            raise ValueError(
                "answer_candidate_over_current must have one score per head "
                f"({answer_scores.numel()} != {num_heads})"
            )
        answer_eligible = eligible[answer_scores[eligible] >= float(min_answer_contribution)]
        if answer_eligible.numel() > 0:
            eligible = answer_eligible
            scores = answer_scores[eligible]
            k = min(max_count, int(eligible.numel()))
    order = torch.argsort(scores, descending=True)
    return eligible[order[:k]].sort().values


def _select_carrier_trace_heads_by_score(
    *,
    mass: torch.Tensor,
    max_heads: int,
    answer_scores: torch.Tensor | None = None,
    sensitivity_scores: torch.Tensor | None = None,
    min_answer_contribution: float = 0.0,
) -> tuple[torch.Tensor, dict[str, Any]]:
    """Select carrier heads from a continuous localization score.

    The score follows the same evidence-localization logic used by recent
    head-level hallucination work: token mass localizes the carrier, answer-axis
    effect keeps the carrier on the intended answer direction, and causal
    sensitivity breaks ties among localized heads.
    """
    mass_cpu = mass.detach().float().cpu().reshape(-1)
    num_heads = int(mass_cpu.numel())
    max_count = min(max(0, int(max_heads)), num_heads)
    if num_heads <= 0 or max_count <= 0:
        return torch.empty(0, dtype=torch.long), {
            "carrier_trace_score_available": False,
            "carrier_trace_score_reason": "empty_heads",
        }

    score = mass_cpu.clamp_min(0.0)
    answer_weight = None
    if answer_scores is not None:
        answer_cpu = answer_scores.detach().float().cpu().reshape(-1)
        if int(answer_cpu.numel()) != num_heads:
            raise ValueError(
                "answer_scores must have one score per head "
                f"({int(answer_cpu.numel())} != {num_heads})"
            )
        answer_weight = torch.clamp(2.0 * torch.sigmoid(answer_cpu / 0.10) - 1.0, min=0.0, max=1.0)
        score = score * answer_weight
        if float(min_answer_contribution) > 0.0:
            score = torch.where(
                answer_cpu >= float(min_answer_contribution),
                score,
                torch.zeros_like(score),
            )

    sensitivity_weight = None
    if sensitivity_scores is not None:
        sensitivity_cpu = sensitivity_scores.detach().float().cpu().reshape(-1)
        if int(sensitivity_cpu.numel()) != num_heads:
            raise ValueError(
                "sensitivity_scores must have one score per head "
                f"({int(sensitivity_cpu.numel())} != {num_heads})"
            )
        sensitivity_weight = sensitivity_cpu.clamp(0.0, 1.0)
        score = score * sensitivity_weight

    positive = torch.nonzero(score > 0.0, as_tuple=False).flatten()
    positive_head_count = int(positive.numel())
    elbow_threshold = 0.0
    thresholded = positive
    if positive_head_count > 0:
        positive_scores = score[positive].float()
        if int(positive_scores.numel()) <= 2:
            elbow_threshold = float(positive_scores.min().item())
        else:
            y = torch.sort(positive_scores).values.to(dtype=torch.float64)
            x = torch.arange(int(y.numel()), dtype=torch.float64)
            start = torch.stack([x[0], y[0]])
            end = torch.stack([x[-1], y[-1]])
            line = end - start
            line_len = torch.linalg.norm(line)
            if float(line_len.item()) <= 1.0e-12:
                elbow_threshold = float(y[0].item())
            else:
                unit = line / line_len.clamp_min(1.0e-12)
                points = torch.stack([x, y], dim=1)
                vecs = points - start.view(1, 2)
                proj = (vecs @ unit).view(-1, 1) * unit.view(1, 2)
                dist = torch.linalg.norm(vecs - proj, dim=1)
                elbow_threshold = float(y[int(torch.argmax(dist).item())].item())
        thresholded = positive[score[positive] >= float(elbow_threshold)]
        if int(thresholded.numel()) <= 0:
            thresholded = positive[torch.argmax(score[positive]).view(1)]
    eligible = thresholded
    if int(eligible.numel()) <= 0:
        return torch.empty(0, dtype=torch.long), {
            "carrier_trace_score_available": False,
            "carrier_trace_score_reason": "zero_positive_score",
            "carrier_trace_score_mean": float(score.mean().item()),
            "carrier_trace_score_max": float(score.max().item()),
            "carrier_trace_positive_head_count": positive_head_count,
            "carrier_trace_elbow_threshold": float(elbow_threshold),
            "carrier_trace_thresholded_head_count": int(thresholded.numel()),
            "carrier_trace_answer_weight_mean": (
                float(answer_weight.mean().item()) if answer_weight is not None else None
            ),
            "carrier_trace_sensitivity_weight_mean": (
                float(sensitivity_weight.mean().item()) if sensitivity_weight is not None else None
            ),
        }

    k = min(max_count, int(eligible.numel()))
    order = torch.argsort(score[eligible], descending=True)
    heads = eligible[order[:k]].sort().values
    selected_score = score[heads]
    return heads, {
        "carrier_trace_score_available": True,
        "carrier_trace_score_reason": "ok",
        "carrier_trace_score_mean": float(score.mean().item()),
        "carrier_trace_score_max": float(score.max().item()),
        "carrier_trace_positive_head_count": positive_head_count,
        "carrier_trace_elbow_threshold": float(elbow_threshold),
        "carrier_trace_thresholded_head_count": int(thresholded.numel()),
        "carrier_trace_selected_score_mean": float(selected_score.mean().item()),
        "carrier_trace_selected_score_min": float(selected_score.min().item()),
        "carrier_trace_selected_score_max": float(selected_score.max().item()),
        "carrier_trace_answer_weight_mean": (
            float(answer_weight.mean().item()) if answer_weight is not None else None
        ),
        "carrier_trace_selected_answer_weight_mean": (
            float(answer_weight[heads].mean().item()) if answer_weight is not None and int(heads.numel()) > 0 else None
        ),
        "carrier_trace_sensitivity_weight_mean": (
            float(sensitivity_weight.mean().item()) if sensitivity_weight is not None else None
        ),
        "carrier_trace_selected_sensitivity_weight_mean": (
            float(sensitivity_weight[heads].mean().item())
            if sensitivity_weight is not None and int(heads.numel()) > 0
            else None
        ),
    }


def _allpath_head_scaled_output(
    *,
    original_head_output: torch.Tensor,
    hallu_heads: torch.Tensor,
    good_heads: torch.Tensor,
    beta_for_layer: float,
    alpha_for_layer: float,
    alpha_mode: str,
) -> dict[str, Any]:
    """AllPath-style per-head output scaling adapted to Omni evidence carriers."""
    head_output = original_head_output.float()
    num_heads = int(head_output.shape[1])
    hallu_cpu = hallu_heads.detach().cpu().long()
    good_cpu = good_heads.detach().cpu().long()
    if hallu_cpu.numel() > 0 and good_cpu.numel() > 0:
        hallu_set = set(int(x) for x in hallu_cpu.tolist())
        good_set = set(int(x) for x in good_cpu.tolist())
        overlap = hallu_set & good_set
        hallu_cpu = torch.tensor(sorted(hallu_set - overlap), dtype=torch.long)
        good_cpu = torch.tensor(sorted(good_set - overlap), dtype=torch.long)
    de_scale = max(0.0, 1.0 - max(0.0, float(beta_for_layer)))
    in_scale = 1.0
    if safe_text(alpha_mode) == "evidence_value_boost":
        in_scale = 1.0 + max(0.0, float(alpha_for_layer))
    scale = torch.ones(
        1,
        num_heads,
        1,
        1,
        device=head_output.device,
        dtype=torch.float32,
    )
    if hallu_cpu.numel() > 0:
        scale[:, hallu_cpu.to(device=head_output.device), :, :] = float(de_scale)
    if good_cpu.numel() > 0:
        scale[:, good_cpu.to(device=head_output.device), :, :] = float(in_scale)
    patched = head_output * scale
    changed = sorted(set(int(x) for x in hallu_cpu.tolist()) | set(int(x) for x in good_cpu.tolist()))
    if changed:
        changed_tensor = torch.tensor(changed, dtype=torch.long, device=head_output.device)
        delta = patched[:, changed_tensor, :, :] - head_output[:, changed_tensor, :, :]
    else:
        delta = torch.zeros_like(head_output[:, :0, :, :])
    return {
        "patched_head_output": patched,
        "delta": delta,
        "allpath_hallu_head_count": int(hallu_cpu.numel()),
        "allpath_good_head_count": int(good_cpu.numel()),
        "allpath_changed_head_count": int(len(changed)),
        "allpath_de_scale": float(de_scale),
        "allpath_in_scale": float(in_scale),
        "allpath_hallu_heads": [int(x) for x in hallu_cpu.tolist()],
        "allpath_good_heads": [int(x) for x in good_cpu.tolist()],
        "head_transport_delta_l2": float(delta.norm().detach().cpu().item()),
        "head_transport_prior_delta_l2": float(
            (head_output[:, hallu_cpu.to(device=head_output.device), :, :] - patched[:, hallu_cpu.to(device=head_output.device), :, :]).norm().detach().cpu().item()
            if hallu_cpu.numel() > 0
            else 0.0
        ),
        "head_transport_transport_delta_l2": float(
            (patched[:, good_cpu.to(device=head_output.device), :, :] - head_output[:, good_cpu.to(device=head_output.device), :, :]).norm().detach().cpu().item()
            if good_cpu.numel() > 0
            else 0.0
        ),
        "head_transport_compensation_delta_l2": 0.0,
        "head_transport_alpha_ratio": float(max(0.0, float(alpha_for_layer))),
    }


def _allpath_token_scaled_output(
    *,
    original_head_output: torch.Tensor,
    hallu_heads: torch.Tensor,
    good_heads: torch.Tensor,
    source_contribution: torch.Tensor,
    evidence_contribution_good: torch.Tensor,
    beta_for_layer: float,
    alpha_for_layer: float,
    alpha_mode: str,
) -> dict[str, Any]:
    """AllPath/SPIN-style scaling localized to token value contributions.

    AllPath scales hallucination/good heads after decomposing the attention path.
    SPIN localizes the relevant heads by modality attention. Here we keep both
    ideas but avoid whole-head or whole-hidden edits: hallucination heads lose
    only their source-token value contribution, while evidence heads gain only
    their evidence-token value contribution.
    """
    patched = original_head_output.float().clone()
    hallu_cpu = hallu_heads.detach().cpu().long()
    good_cpu = good_heads.detach().cpu().long()
    if hallu_cpu.numel() > 0 and good_cpu.numel() > 0:
        hallu_set = set(int(x) for x in hallu_cpu.tolist())
        good_set = set(int(x) for x in good_cpu.tolist())
        overlap = hallu_set & good_set
        hallu_cpu = torch.tensor(sorted(hallu_set - overlap), dtype=torch.long)
        good_cpu = torch.tensor(sorted(good_set - overlap), dtype=torch.long)
    prior_delta_l2 = 0.0
    evidence_delta_l2 = 0.0
    beta_value = max(0.0, float(beta_for_layer))
    alpha_value = max(0.0, float(alpha_for_layer)) if safe_text(alpha_mode) == "evidence_value_boost" else 0.0
    if hallu_cpu.numel() > 0:
        hallu_dev = hallu_cpu.to(device=patched.device)
        source_delta = -beta_value * source_contribution.float().to(device=patched.device)
        patched[:, hallu_dev, :, :] = patched[:, hallu_dev, :, :] + source_delta
        prior_delta_l2 = float(source_delta.norm().detach().cpu().item())
    if good_cpu.numel() > 0 and alpha_value > 0.0:
        good_dev = good_cpu.to(device=patched.device)
        evidence_delta = alpha_value * evidence_contribution_good.float().to(device=patched.device)
        patched[:, good_dev, :, :] = patched[:, good_dev, :, :] + evidence_delta
        evidence_delta_l2 = float(evidence_delta.norm().detach().cpu().item())
    changed = sorted(set(int(x) for x in hallu_cpu.tolist()) | set(int(x) for x in good_cpu.tolist()))
    if changed:
        changed_tensor = torch.tensor(changed, dtype=torch.long, device=patched.device)
        delta = patched[:, changed_tensor, :, :] - original_head_output.float()[:, changed_tensor, :, :]
    else:
        delta = torch.zeros_like(patched[:, :0, :, :])
    return {
        "patched_head_output": patched,
        "delta": delta,
        "allpath_hallu_head_count": int(hallu_cpu.numel()),
        "allpath_good_head_count": int(good_cpu.numel()),
        "allpath_changed_head_count": int(len(changed)),
        "allpath_de_scale": float(max(0.0, 1.0 - beta_value)),
        "allpath_in_scale": float(1.0 + alpha_value),
        "allpath_hallu_heads": [int(x) for x in hallu_cpu.tolist()],
        "allpath_good_heads": [int(x) for x in good_cpu.tolist()],
        "head_transport_delta_l2": float(delta.norm().detach().cpu().item()),
        "head_transport_prior_delta_l2": prior_delta_l2,
        "head_transport_transport_delta_l2": evidence_delta_l2,
        "head_transport_compensation_delta_l2": 0.0,
        "head_transport_alpha_ratio": float(alpha_value),
    }


def _carrier_weighted_allpath_token_scaled_output(
    *,
    original_head_output: torch.Tensor,
    hallu_heads: torch.Tensor,
    good_heads: torch.Tensor,
    source_contribution: torch.Tensor,
    evidence_contribution_good: torch.Tensor,
    evidence_contribution_selected: torch.Tensor | None = None,
    source_prior_alignment: torch.Tensor,
    evidence_carrier_alignment: torch.Tensor,
    beta_for_layer: float,
    alpha_for_layer: float,
    alpha_mode: str,
    source_current_over_candidate: torch.Tensor | None = None,
    evidence_candidate_over_current: torch.Tensor | None = None,
    current_protection_weight: float | None = None,
    protect_current: bool = False,
) -> dict[str, Any]:
    """Carrier-constrained AllPath token scaling.

    This keeps the empirically strong AllPath/SPIN token-path edit, but the
    path strength is no longer a uniform head-level scale. Each source/evidence
    token value path receives a mean-preserving weight from its alignment to the
    current prior/evidence carrier and its answer-path contribution.
    """
    patched = original_head_output.float().clone()
    hallu_cpu = hallu_heads.detach().cpu().long()
    good_cpu = good_heads.detach().cpu().long()
    if hallu_cpu.numel() > 0 and good_cpu.numel() > 0:
        hallu_set = set(int(x) for x in hallu_cpu.tolist())
        good_set = set(int(x) for x in good_cpu.tolist())
        overlap = hallu_set & good_set
        hallu_cpu = torch.tensor(sorted(hallu_set - overlap), dtype=torch.long)
        good_cpu = torch.tensor(sorted(good_set - overlap), dtype=torch.long)

    beta_value = max(0.0, float(beta_for_layer))
    alpha_value = max(0.0, float(alpha_for_layer)) if safe_text(alpha_mode) == "evidence_value_boost" else 0.0
    answer_temperature = 0.001
    eps = 1.0e-12
    current_protection_value = max(0.0, min(1.0, float(current_protection_weight or 0.0)))

    def normalized_weight(
        values: torch.Tensor | None,
        *,
        count: int,
        device: torch.device,
        use_sigmoid: bool = False,
    ) -> torch.Tensor:
        if values is None or count <= 0:
            return torch.ones(count, device=device, dtype=torch.float32)
        weight = values.detach().float().to(device=device)
        if int(weight.numel()) != count:
            raise ValueError(f"carrier-weighted AllPath expected {count} weights, got {int(weight.numel())}")
        if use_sigmoid:
            weight = torch.sigmoid(weight / answer_temperature)
        else:
            weight = weight.clamp_min(0.0)
        mean = weight.mean().clamp_min(eps)
        if not bool(torch.isfinite(mean).detach().cpu().item()) or float(mean.detach().cpu().item()) <= eps:
            return torch.ones(count, device=device, dtype=torch.float32)
        # Mean-preserving normalization keeps the best AllPath strength while
        # making the per-path allocation carrier/answer aware.
        return (weight / mean).clamp(0.0, 2.0)

    prior_delta_l2 = 0.0
    evidence_delta_l2 = 0.0
    source_path_weight = torch.empty(0, device=patched.device, dtype=torch.float32)
    evidence_path_weight = torch.empty(0, device=patched.device, dtype=torch.float32)
    source_align_weight = torch.empty(0, device=patched.device, dtype=torch.float32)
    evidence_align_weight = torch.empty(0, device=patched.device, dtype=torch.float32)
    source_answer_weight = torch.empty(0, device=patched.device, dtype=torch.float32)
    evidence_answer_weight = torch.empty(0, device=patched.device, dtype=torch.float32)
    source_protection_weight = torch.empty(0, device=patched.device, dtype=torch.float32)

    if hallu_cpu.numel() > 0:
        hallu_count = int(hallu_cpu.numel())
        hallu_dev = hallu_cpu.to(device=patched.device)
        source_align_weight = normalized_weight(
            source_prior_alignment,
            count=hallu_count,
            device=patched.device,
            use_sigmoid=False,
        )
        source_answer_weight = normalized_weight(
            source_current_over_candidate,
            count=hallu_count,
            device=patched.device,
            use_sigmoid=True,
        )
        source_path_weight = (source_align_weight * source_answer_weight)
        source_path_weight = source_path_weight / source_path_weight.mean().clamp_min(eps)
        source_path_weight = source_path_weight.clamp(0.0, 2.0).view(1, hallu_count, 1, 1)
        if protect_current and current_protection_value > 0.0:
            if evidence_contribution_selected is not None and evidence_contribution_selected.numel() > 0:
                selected_source_norm = source_contribution.detach().float().pow(2).sum(dim=(0, 2, 3)).sqrt()
                selected_evidence_norm = evidence_contribution_selected.detach().float().pow(2).sum(dim=(0, 2, 3)).sqrt()
                source_to_evidence_ratio = selected_source_norm / (selected_evidence_norm + eps)
                source_to_evidence_ratio = source_to_evidence_ratio.to(device=patched.device)
                source_protection_weight = torch.sigmoid((source_to_evidence_ratio - 0.45) / 0.08)
                source_protection_weight = (
                    1.0 - current_protection_value * (1.0 - source_protection_weight)
                ).clamp(0.2, 1.0)
                source_path_weight = source_path_weight * source_protection_weight.view(1, hallu_count, 1, 1)
        source_delta = (
            -beta_value
            * source_path_weight
            * source_contribution.float().to(device=patched.device)
        )
        patched[:, hallu_dev, :, :] = patched[:, hallu_dev, :, :] + source_delta
        prior_delta_l2 = float(source_delta.norm().detach().cpu().item())

    if good_cpu.numel() > 0 and alpha_value > 0.0:
        good_count = int(good_cpu.numel())
        good_dev = good_cpu.to(device=patched.device)
        evidence_align_weight = normalized_weight(
            evidence_carrier_alignment,
            count=good_count,
            device=patched.device,
            use_sigmoid=False,
        )
        evidence_answer_weight = normalized_weight(
            evidence_candidate_over_current,
            count=good_count,
            device=patched.device,
            use_sigmoid=True,
        )
        evidence_path_weight = evidence_align_weight * evidence_answer_weight
        evidence_path_weight = evidence_path_weight / evidence_path_weight.mean().clamp_min(eps)
        evidence_path_weight = evidence_path_weight.clamp(0.0, 2.0).view(1, good_count, 1, 1)
        evidence_delta = (
            alpha_value
            * evidence_path_weight
            * evidence_contribution_good.float().to(device=patched.device)
        )
        patched[:, good_dev, :, :] = patched[:, good_dev, :, :] + evidence_delta
        evidence_delta_l2 = float(evidence_delta.norm().detach().cpu().item())

    changed = sorted(set(int(x) for x in hallu_cpu.tolist()) | set(int(x) for x in good_cpu.tolist()))
    if changed:
        changed_tensor = torch.tensor(changed, dtype=torch.long, device=patched.device)
        delta = patched[:, changed_tensor, :, :] - original_head_output.float()[:, changed_tensor, :, :]
    else:
        delta = torch.zeros_like(patched[:, :0, :, :])

    def mean_or_none(values: torch.Tensor) -> float | None:
        if values.numel() <= 0:
            return None
        return float(values.detach().float().mean().cpu().item())

    return {
        "patched_head_output": patched,
        "delta": delta,
        "allpath_hallu_head_count": int(hallu_cpu.numel()),
        "allpath_good_head_count": int(good_cpu.numel()),
        "allpath_changed_head_count": int(len(changed)),
        "allpath_de_scale": float(max(0.0, 1.0 - beta_value)),
        "allpath_in_scale": float(1.0 + alpha_value),
        "allpath_hallu_heads": [int(x) for x in hallu_cpu.tolist()],
        "allpath_good_heads": [int(x) for x in good_cpu.tolist()],
        "carrier_weighted_allpath_source_prior_alignment_mean": mean_or_none(
            source_prior_alignment.detach().float()
        ),
        "carrier_weighted_allpath_evidence_alignment_mean": mean_or_none(
            evidence_carrier_alignment.detach().float()
        ),
        "carrier_weighted_allpath_source_align_weight_mean": mean_or_none(source_align_weight),
        "carrier_weighted_allpath_evidence_align_weight_mean": mean_or_none(evidence_align_weight),
        "carrier_weighted_allpath_source_answer_weight_mean": mean_or_none(source_answer_weight),
        "carrier_weighted_allpath_evidence_answer_weight_mean": mean_or_none(evidence_answer_weight),
        "carrier_weighted_allpath_source_path_weight_mean": mean_or_none(source_path_weight),
        "carrier_weighted_allpath_evidence_path_weight_mean": mean_or_none(evidence_path_weight),
        "carrier_weighted_allpath_source_protection_weight_mean": mean_or_none(source_protection_weight),
        "carrier_weighted_allpath_current_protection_weight_mean": float(current_protection_value),
        "head_transport_delta_l2": float(delta.norm().detach().cpu().item()),
        "head_transport_prior_delta_l2": prior_delta_l2,
        "head_transport_transport_delta_l2": evidence_delta_l2,
        "head_transport_compensation_delta_l2": 0.0,
        "head_transport_alpha_ratio": float(alpha_value),
    }


def _continuous_carrier_refinement_output(
    *,
    original_head_output: torch.Tensor,
    source_contribution: torch.Tensor,
    evidence_contribution: torch.Tensor,
    source_mass: torch.Tensor,
    evidence_mass: torch.Tensor,
    beta_for_layer: float,
    alpha_for_layer: float,
    alpha_mode: str,
    source_current_over_candidate: torch.Tensor | None = None,
    evidence_candidate_over_current: torch.Tensor | None = None,
) -> dict[str, Any]:
    """Continuous token/head/path refinement without hard head selection.

    A source-dominant head receives mostly source-prior suppression; an
    evidence-dominant head receives mostly evidence reinforcement. The same
    carrier-competition coefficient controls both terms, so this is a single
    path update rather than a stack of head selection plus token scaling.
    """
    head_output = original_head_output.float()
    source = source_contribution.float().to(device=head_output.device)
    evidence = evidence_contribution.float().to(device=head_output.device)
    num_heads = int(head_output.shape[1])
    if int(source.shape[1]) != num_heads or int(evidence.shape[1]) != num_heads:
        raise ValueError(
            "continuous carrier refinement expects source/evidence contributions "
            f"for all heads, got source={tuple(source.shape)} evidence={tuple(evidence.shape)} "
            f"head_output={tuple(head_output.shape)}"
        )
    src_mass = source_mass.detach().float().to(device=head_output.device)
    evi_mass = evidence_mass.detach().float().to(device=head_output.device)
    if int(src_mass.numel()) != num_heads or int(evi_mass.numel()) != num_heads:
        raise ValueError(
            "continuous carrier refinement expects one mass score per head "
            f"({int(src_mass.numel())}, {int(evi_mass.numel())}) != {num_heads}"
        )

    beta_value = max(0.0, float(beta_for_layer))
    alpha_value = max(0.0, float(alpha_for_layer)) if safe_text(alpha_mode) == "evidence_value_boost" else 0.0
    temperature = 0.02
    answer_temperature = 0.001
    score = (src_mass - evi_mass) / temperature
    prior_weight = torch.sigmoid(score).view(1, num_heads, 1, 1)
    evidence_weight = 1.0 - prior_weight
    source_answer_weight = torch.ones_like(prior_weight)
    evidence_answer_weight = torch.ones_like(evidence_weight)
    source_answer_scores = None
    evidence_answer_scores = None
    if source_current_over_candidate is not None:
        source_answer_scores = source_current_over_candidate.detach().float().to(device=head_output.device)
        if int(source_answer_scores.numel()) != num_heads:
            raise ValueError(
                "source_current_over_candidate must have one score per head "
                f"({int(source_answer_scores.numel())} != {num_heads})"
            )
        source_answer_weight = torch.sigmoid(source_answer_scores / answer_temperature).view(
            1,
            num_heads,
            1,
            1,
        )
    if evidence_candidate_over_current is not None:
        evidence_answer_scores = evidence_candidate_over_current.detach().float().to(device=head_output.device)
        if int(evidence_answer_scores.numel()) != num_heads:
            raise ValueError(
                "evidence_candidate_over_current must have one score per head "
                f"({int(evidence_answer_scores.numel())} != {num_heads})"
            )
        evidence_answer_weight = torch.sigmoid(evidence_answer_scores / answer_temperature).view(
            1,
            num_heads,
            1,
            1,
        )

    prior_delta = -beta_value * prior_weight * source_answer_weight * source
    evidence_delta = alpha_value * evidence_weight * evidence_answer_weight * evidence
    delta = prior_delta + evidence_delta
    patched = head_output + delta

    with torch.no_grad():
        source_norm = source.norm(dim=-1, keepdim=True)
        evidence_norm = evidence.norm(dim=-1, keepdim=True)
        cos = torch.abs(
            (source * evidence).sum(dim=-1, keepdim=True)
            / (source_norm * evidence_norm).clamp_min(1.0e-12)
        )
        valid_source = source_norm > 1.0e-12
        valid_evidence = evidence_norm > 1.0e-12
        prior_heads = torch.nonzero((prior_weight[0, :, 0, 0] > 0.5).detach().cpu(), as_tuple=False).flatten()
        evidence_heads = torch.nonzero((evidence_weight[0, :, 0, 0] >= 0.5).detach().cpu(), as_tuple=False).flatten()

    return {
        "patched_head_output": patched,
        "delta": delta,
        "continuous_carrier_temperature": float(temperature),
        "continuous_carrier_answer_temperature": float(answer_temperature),
        "continuous_carrier_score_mean": float(score.mean().detach().cpu().item()),
        "continuous_carrier_score_min": float(score.min().detach().cpu().item()),
        "continuous_carrier_score_max": float(score.max().detach().cpu().item()),
        "continuous_carrier_prior_weight_mean": float(prior_weight.mean().detach().cpu().item()),
        "continuous_carrier_prior_weight_min": float(prior_weight.min().detach().cpu().item()),
        "continuous_carrier_prior_weight_max": float(prior_weight.max().detach().cpu().item()),
        "continuous_carrier_evidence_weight_mean": float(evidence_weight.mean().detach().cpu().item()),
        "continuous_carrier_evidence_weight_min": float(evidence_weight.min().detach().cpu().item()),
        "continuous_carrier_evidence_weight_max": float(evidence_weight.max().detach().cpu().item()),
        "continuous_carrier_prior_dominant_head_count": int(prior_heads.numel()),
        "continuous_carrier_evidence_dominant_head_count": int(evidence_heads.numel()),
        "continuous_carrier_prior_dominant_heads": [int(x) for x in prior_heads.tolist()],
        "continuous_carrier_evidence_dominant_heads": [int(x) for x in evidence_heads.tolist()],
        "continuous_carrier_answer_consistency": bool(
            source_answer_scores is not None or evidence_answer_scores is not None
        ),
        "continuous_carrier_source_answer_weight_mean": float(
            source_answer_weight.mean().detach().cpu().item()
        ),
        "continuous_carrier_source_answer_weight_min": float(
            source_answer_weight.min().detach().cpu().item()
        ),
        "continuous_carrier_source_answer_weight_max": float(
            source_answer_weight.max().detach().cpu().item()
        ),
        "continuous_carrier_evidence_answer_weight_mean": float(
            evidence_answer_weight.mean().detach().cpu().item()
        ),
        "continuous_carrier_evidence_answer_weight_min": float(
            evidence_answer_weight.min().detach().cpu().item()
        ),
        "continuous_carrier_evidence_answer_weight_max": float(
            evidence_answer_weight.max().detach().cpu().item()
        ),
        "continuous_carrier_source_current_over_candidate_mean": (
            float(source_answer_scores.mean().detach().cpu().item())
            if source_answer_scores is not None
            else None
        ),
        "continuous_carrier_evidence_candidate_over_current_mean": (
            float(evidence_answer_scores.mean().detach().cpu().item())
            if evidence_answer_scores is not None
            else None
        ),
        "continuous_carrier_source_component_l2": float(source.norm().detach().cpu().item()),
        "continuous_carrier_evidence_component_l2": float(evidence.norm().detach().cpu().item()),
        "head_transport_delta_l2": float(delta.norm().detach().cpu().item()),
        "head_transport_prior_delta_l2": float(prior_delta.norm().detach().cpu().item()),
        "head_transport_transport_delta_l2": float(evidence_delta.norm().detach().cpu().item()),
        "head_transport_compensation_delta_l2": 0.0,
        "head_transport_alpha_ratio": float(alpha_value),
        "head_transport_u_p_abs_cos": float(cos.mean().detach().cpu().item()),
        "head_transport_valid_prior_ratio": float(valid_source.float().mean().detach().cpu().item()),
        "head_transport_valid_evidence_ratio": float(valid_evidence.float().mean().detach().cpu().item()),
    }


def _oelpr_constrained_path_refinement_output(
    *,
    original_head_output: torch.Tensor,
    source_contribution: torch.Tensor,
    evidence_contribution: torch.Tensor,
    source_mass: torch.Tensor,
    evidence_mass: torch.Tensor,
    beta_for_layer: float,
    alpha_for_layer: float,
    alpha_mode: str,
    source_current_over_candidate: torch.Tensor | None = None,
    evidence_candidate_over_current: torch.Tensor | None = None,
    current_protection_weight: float | None = None,
    counterfactual_path_mode: str = "none",
    source_target_shortcut_excess: torch.Tensor | None = None,
    evidence_counter_support: torch.Tensor | None = None,
    counterfactual_target_answer: str | None = None,
    counterfactual_counter_answer: str | None = None,
    latent_anchor_mode: str = "none",
    latent_anchor_margin: float | None = None,
    source_latent_anchor_effect: torch.Tensor | None = None,
    evidence_latent_anchor_effect: torch.Tensor | None = None,
    latent_anchor_answer: str | None = None,
    latent_anchor_counter_answer: str | None = None,
    latent_anchor_confidence_gate: str = "none",
    latent_anchor_gate_threshold: float = 3.70,
    latent_anchor_gate_tau: float = 0.25,
    latent_anchor_apply_update_gate: bool = True,
    full_context_margin: float | None = None,
    source_full_context_effect: torch.Tensor | None = None,
    evidence_full_context_effect: torch.Tensor | None = None,
    full_context_answer: str | None = None,
    full_context_counter_answer: str | None = None,
    candidate_view_support: float | None = None,
    current_view_support: float | None = None,
    view_competition_mode: bool = False,
    path_update_geometry: str = "additive",
    anchor_nullspace_axis: torch.Tensor | None = None,
    attention_causal_mode: str = "none",
    path_score_mode: str = "factorized",
    source_attention_causal_effect: torch.Tensor | None = None,
    evidence_attention_causal_effect: torch.Tensor | None = None,
) -> dict[str, Any]:
    """Omni evidence-localized path refinement with current-preservation.

    This is the paper-facing path operator: every head is updated by a single
    continuous objective combining source/evidence carrier competition,
    answer-path consistency, and a target-current preservation penalty. The
    preservation term is not a sample-level gate; it only attenuates source
    suppression on paths that still support the runtime current answer.
    """
    head_output = original_head_output.float()
    source = source_contribution.float().to(device=head_output.device)
    evidence = evidence_contribution.float().to(device=head_output.device)
    num_heads = int(head_output.shape[1])
    if int(source.shape[1]) != num_heads or int(evidence.shape[1]) != num_heads:
        raise ValueError(
            "O-ELPR constrained path refinement expects source/evidence contributions "
            f"for all heads, got source={tuple(source.shape)} evidence={tuple(evidence.shape)} "
            f"head_output={tuple(head_output.shape)}"
        )

    src_mass = source_mass.detach().float().to(device=head_output.device).clamp_min(0.0)
    evi_mass = evidence_mass.detach().float().to(device=head_output.device).clamp_min(0.0)
    if int(src_mass.numel()) != num_heads or int(evi_mass.numel()) != num_heads:
        raise ValueError(
            "O-ELPR constrained path refinement expects one mass score per head "
            f"({int(src_mass.numel())}, {int(evi_mass.numel())}) != {num_heads}"
        )

    eps = 1.0e-12
    beta_value = max(0.0, float(beta_for_layer))
    alpha_value = max(0.0, float(alpha_for_layer)) if safe_text(alpha_mode) == "evidence_value_boost" else 0.0
    mass_temperature = 0.02
    answer_temperature = 0.001
    protection_value = max(0.0, min(1.0, float(current_protection_weight or 0.0)))
    cf_mode = safe_text(counterfactual_path_mode) or "none"
    if cf_mode not in {"none", "diagnose", "apply"}:
        raise ValueError(f"unknown counterfactual_path_mode: {counterfactual_path_mode}")
    anchor_mode = safe_text(latent_anchor_mode) or "none"
    if anchor_mode not in {"none", "diagnose", "constrain"}:
        raise ValueError(f"unknown latent_anchor_mode: {latent_anchor_mode}")
    anchor_gate_key = safe_text(latent_anchor_confidence_gate) or "none"
    if anchor_gate_key not in {"none", "soft_margin", "hard_margin"}:
        raise ValueError(f"unknown latent_anchor_confidence_gate: {latent_anchor_confidence_gate}")
    attention_causal_key = safe_text(attention_causal_mode) or "none"
    if attention_causal_key not in {"none", "uniform_path_contrast", "uniform_path_boost"}:
        raise ValueError(f"unknown attention_causal_mode: {attention_causal_mode}")
    path_score_key = safe_text(path_score_mode) or "factorized"
    if path_score_key not in {
        "factorized",
        "unified_sensitivity",
        "unified_sensitivity_posterior",
        "evidence_flow_calibrated",
    }:
        raise ValueError(f"unknown path_score_mode: {path_score_mode}")
    update_geometry = safe_text(path_update_geometry) or "additive"
    if update_geometry not in {"additive", "angular", "anchor_nullspace"}:
        raise ValueError(f"unknown path_update_geometry: {path_update_geometry}")

    source_answer_scores = None
    evidence_answer_scores = None
    if source_current_over_candidate is None:
        source_answer_weight = torch.ones(num_heads, device=head_output.device, dtype=torch.float32)
    else:
        source_answer_scores = source_current_over_candidate.detach().float().to(device=head_output.device)
        if int(source_answer_scores.numel()) != num_heads:
            raise ValueError(
                "source_current_over_candidate must have one score per head "
                f"({int(source_answer_scores.numel())} != {num_heads})"
            )
        source_answer_weight = torch.sigmoid(source_answer_scores / answer_temperature)
    if evidence_candidate_over_current is None:
        evidence_answer_weight = torch.ones(num_heads, device=head_output.device, dtype=torch.float32)
    else:
        evidence_answer_scores = evidence_candidate_over_current.detach().float().to(device=head_output.device)
        if int(evidence_answer_scores.numel()) != num_heads:
            raise ValueError(
                "evidence_candidate_over_current must have one score per head "
                f"({int(evidence_answer_scores.numel())} != {num_heads})"
            )
        evidence_answer_weight = torch.sigmoid(evidence_answer_scores / answer_temperature)

    source_suppression_answer_weight = source_answer_weight
    cf_source_scores = None
    cf_source_weight = None
    cf_evidence_scores = None
    cf_evidence_weight = None
    if source_target_shortcut_excess is not None and cf_mode != "none":
        cf_source_scores = source_target_shortcut_excess.detach().float().to(device=head_output.device)
        if int(cf_source_scores.numel()) != num_heads:
            raise ValueError(
                "source_target_shortcut_excess must have one score per head "
                f"({int(cf_source_scores.numel())} != {num_heads})"
            )
        cf_source_weight = torch.sigmoid(cf_source_scores / answer_temperature)
        if cf_mode == "apply":
            source_suppression_answer_weight = torch.maximum(
                source_suppression_answer_weight,
                cf_source_weight,
            )
    if evidence_counter_support is not None and cf_mode != "none":
        cf_evidence_scores = evidence_counter_support.detach().float().to(device=head_output.device)
        if int(cf_evidence_scores.numel()) != num_heads:
            raise ValueError(
                "evidence_counter_support must have one score per head "
                f"({int(cf_evidence_scores.numel())} != {num_heads})"
            )
        cf_evidence_weight = torch.sigmoid(cf_evidence_scores / answer_temperature)
        if cf_mode == "apply":
            evidence_answer_weight = torch.maximum(evidence_answer_weight, cf_evidence_weight)

    anchor_margin_value = None
    anchor_confidence = None
    source_anchor_scores = None
    evidence_anchor_scores = None
    source_anchor_harm_weight = None
    evidence_anchor_harm_weight = None
    source_anchor_constraint_scale = torch.ones(num_heads, device=head_output.device, dtype=torch.float32)
    evidence_anchor_constraint_scale = torch.ones(num_heads, device=head_output.device, dtype=torch.float32)
    latent_anchor_update_gate = torch.tensor(1.0, device=head_output.device, dtype=torch.float32)
    if anchor_mode != "none" and latent_anchor_margin is not None:
        anchor_margin_value = abs(float(latent_anchor_margin))
        # Self-logit margins are regular logits, not tiny value-path contributions.
        anchor_confidence = torch.tanh(
            torch.tensor(anchor_margin_value, device=head_output.device, dtype=torch.float32)
        )
        if anchor_gate_key == "hard_margin":
            latent_anchor_update_gate = torch.tensor(
                1.0 if anchor_margin_value >= float(latent_anchor_gate_threshold) else 0.0,
                device=head_output.device,
                dtype=torch.float32,
            )
        elif anchor_gate_key == "soft_margin":
            latent_anchor_update_gate = torch.sigmoid(
                (
                    torch.tensor(anchor_margin_value, device=head_output.device, dtype=torch.float32)
                    - float(latent_anchor_gate_threshold)
                )
                / max(1.0e-6, float(latent_anchor_gate_tau))
            ).clamp(0.0, 1.0)
        if source_latent_anchor_effect is not None:
            source_anchor_scores = source_latent_anchor_effect.detach().float().to(device=head_output.device)
            if int(source_anchor_scores.numel()) != num_heads:
                raise ValueError(
                    "source_latent_anchor_effect must have one score per head "
                    f"({int(source_anchor_scores.numel())} != {num_heads})"
                )
            # Suppressing a source path that already supports the early self-logit anchor is harmful.
            source_anchor_harm_weight = torch.sigmoid(source_anchor_scores / answer_temperature)
            if anchor_mode == "constrain":
                source_anchor_constraint_scale = (
                    1.0 - anchor_confidence * source_anchor_harm_weight
                ).clamp(0.25, 1.0)
        if evidence_latent_anchor_effect is not None:
            evidence_anchor_scores = evidence_latent_anchor_effect.detach().float().to(device=head_output.device)
            if int(evidence_anchor_scores.numel()) != num_heads:
                raise ValueError(
                    "evidence_latent_anchor_effect must have one score per head "
                    f"({int(evidence_anchor_scores.numel())} != {num_heads})"
                )
            # Reinforcing an evidence path that points away from the early anchor is harmful.
            evidence_anchor_harm_weight = torch.sigmoid(-evidence_anchor_scores / answer_temperature)
            if anchor_mode == "constrain":
                evidence_anchor_constraint_scale = (
                    1.0 - anchor_confidence * evidence_anchor_harm_weight
                ).clamp(0.25, 1.0)

    full_context_margin_value = None
    full_context_confidence = None
    source_full_context_scores = None
    evidence_full_context_scores = None
    source_full_context_preserve_weight = None
    evidence_full_context_support_weight = None
    evidence_full_context_harm_weight = None
    source_full_context_scale = torch.ones(num_heads, device=head_output.device, dtype=torch.float32)
    evidence_full_context_scale = torch.ones(num_heads, device=head_output.device, dtype=torch.float32)
    evidence_full_context_reinforcement = torch.ones(
        num_heads, device=head_output.device, dtype=torch.float32
    )
    if anchor_mode == "constrain" and full_context_margin is not None:
        full_context_margin_value = abs(float(full_context_margin))
        full_context_confidence = torch.tanh(
            torch.tensor(full_context_margin_value, device=head_output.device, dtype=torch.float32)
        )
        if source_full_context_effect is not None:
            source_full_context_scores = source_full_context_effect.detach().float().to(
                device=head_output.device
            )
            if int(source_full_context_scores.numel()) != num_heads:
                raise ValueError(
                    "source_full_context_effect must have one score per head "
                    f"({int(source_full_context_scores.numel())} != {num_heads})"
                )
            source_full_context_preserve_weight = torch.sigmoid(
                source_full_context_scores / answer_temperature
            )
            source_full_context_scale = (
                1.0 - full_context_confidence * source_full_context_preserve_weight
            ).clamp(0.25, 1.0)
        if evidence_full_context_effect is not None:
            evidence_full_context_scores = evidence_full_context_effect.detach().float().to(
                device=head_output.device
            )
            if int(evidence_full_context_scores.numel()) != num_heads:
                raise ValueError(
                    "evidence_full_context_effect must have one score per head "
                    f"({int(evidence_full_context_scores.numel())} != {num_heads})"
                )
            evidence_full_context_support_weight = torch.sigmoid(
                evidence_full_context_scores / answer_temperature
            )
            evidence_full_context_harm_weight = torch.sigmoid(
                -evidence_full_context_scores / answer_temperature
            )
            evidence_full_context_scale = (
                1.0 - full_context_confidence * evidence_full_context_harm_weight
            ).clamp(0.25, 1.0)
            evidence_full_context_reinforcement = (
                1.0 + 0.50 * full_context_confidence * evidence_full_context_support_weight
            ).clamp(1.0, 1.50)

    source_attention_causal_scores = None
    evidence_attention_causal_scores = None
    source_attention_causal_scale = torch.ones(num_heads, device=head_output.device, dtype=torch.float32)
    evidence_attention_causal_scale = torch.ones(num_heads, device=head_output.device, dtype=torch.float32)
    if attention_causal_key in {"uniform_path_contrast", "uniform_path_boost"}:
        if source_attention_causal_effect is not None:
            source_attention_causal_scores = source_attention_causal_effect.detach().float().to(
                device=head_output.device
            )
            if int(source_attention_causal_scores.numel()) != num_heads:
                raise ValueError(
                    "source_attention_causal_effect must have one score per head "
                    f"({int(source_attention_causal_scores.numel())} != {num_heads})"
                )
            source_attention_causal_raw = (
                2.0 * torch.sigmoid(source_attention_causal_scores / answer_temperature)
            )
            if attention_causal_key == "uniform_path_boost":
                source_attention_causal_scale = torch.maximum(
                    torch.ones_like(source_attention_causal_raw),
                    source_attention_causal_raw,
                ).clamp(1.0, 1.75)
            else:
                source_attention_causal_scale = source_attention_causal_raw.clamp(0.25, 1.75)
                source_attention_causal_scale = (
                    source_attention_causal_scale
                    / source_attention_causal_scale.mean().clamp_min(eps)
                ).clamp(0.25, 1.75)
        if evidence_attention_causal_effect is not None:
            evidence_attention_causal_scores = evidence_attention_causal_effect.detach().float().to(
                device=head_output.device
            )
            if int(evidence_attention_causal_scores.numel()) != num_heads:
                raise ValueError(
                    "evidence_attention_causal_effect must have one score per head "
                    f"({int(evidence_attention_causal_scores.numel())} != {num_heads})"
                )
            evidence_attention_causal_raw = (
                2.0 * torch.sigmoid(evidence_attention_causal_scores / answer_temperature)
            )
            if attention_causal_key == "uniform_path_boost":
                evidence_attention_causal_scale = torch.maximum(
                    torch.ones_like(evidence_attention_causal_raw),
                    evidence_attention_causal_raw,
                ).clamp(1.0, 1.75)
            else:
                evidence_attention_causal_scale = evidence_attention_causal_raw.clamp(0.25, 1.75)
                evidence_attention_causal_scale = (
                    evidence_attention_causal_scale
                    / evidence_attention_causal_scale.mean().clamp_min(eps)
                ).clamp(0.25, 1.75)

    candidate_view_support_value = _finite_float_or_none(candidate_view_support)
    current_view_support_value = _finite_float_or_none(current_view_support)
    view_candidate_deficit = torch.tensor(0.0, device=head_output.device, dtype=torch.float32)
    view_current_advantage = torch.tensor(0.0, device=head_output.device, dtype=torch.float32)
    view_candidate_advantage = torch.tensor(0.0, device=head_output.device, dtype=torch.float32)
    view_source_scale = torch.ones(num_heads, device=head_output.device, dtype=torch.float32)
    view_evidence_scale = torch.ones(num_heads, device=head_output.device, dtype=torch.float32)
    view_constraint_key = "none"
    if candidate_view_support_value is not None:
        candidate_support_tensor = torch.tensor(
            max(0.0, min(1.0, float(candidate_view_support_value))),
            device=head_output.device,
            dtype=torch.float32,
        )
        current_support_tensor = None
        if current_view_support_value is not None:
            current_support_tensor = torch.tensor(
                max(0.0, min(1.0, float(current_view_support_value))),
                device=head_output.device,
                dtype=torch.float32,
            )
        if bool(view_competition_mode) and current_support_tensor is not None:
            view_constraint_key = "candidate_current_competition"
            view_current_advantage = (current_support_tensor - candidate_support_tensor).clamp(0.0, 1.0)
            view_candidate_advantage = (candidate_support_tensor - current_support_tensor).clamp(0.0, 1.0)
            view_evidence_scale = ((1.0 - view_current_advantage) ** 2).clamp(
                0.02, 1.0
            ).expand(num_heads)
            view_source_scale = (
                (1.0 - current_support_tensor * view_current_advantage) ** 2
            ).clamp(0.02, 1.0).expand(num_heads)
        else:
            view_constraint_key = "candidate_deficit"
            # 0.5 is the neutral sigmoid support. Only evidence-free candidate axes
            # shrink the update; any branch-level positive support leaves the path intact.
            view_candidate_deficit = ((0.5 - candidate_support_tensor) * 2.0).clamp(0.0, 1.0)
            view_evidence_scale = (1.0 - view_candidate_deficit).clamp(0.10, 1.0).expand(num_heads)
            if current_support_tensor is not None:
                view_source_scale = (
                    1.0 - current_support_tensor * view_candidate_deficit
                ).clamp(0.10, 1.0).expand(num_heads)

    def positive_max_normalized(scores: torch.Tensor | None) -> torch.Tensor:
        if scores is None:
            return torch.zeros(num_heads, device=head_output.device, dtype=torch.float32)
        pos = scores.detach().float().to(device=head_output.device).clamp_min(0.0)
        return pos / pos.max().clamp_min(eps)

    # Carrier competition is mass-based in the legacy path. The unified path
    # instead treats mass, answer-axis output sensitivity, and uniform-attention
    # causal effect as one competition before any preservation constraint.
    carrier_score = (src_mass - evi_mass) / mass_temperature
    source_carrier_weight = torch.sigmoid(carrier_score)
    evidence_carrier_weight = 1.0 - source_carrier_weight
    source_answer_sensitivity = positive_max_normalized(source_answer_scores)
    evidence_answer_sensitivity = positive_max_normalized(evidence_answer_scores)
    source_causal_sensitivity = positive_max_normalized(source_attention_causal_scores)
    evidence_causal_sensitivity = positive_max_normalized(evidence_attention_causal_scores)
    source_unified_sensitivity = torch.maximum(source_answer_sensitivity, source_causal_sensitivity)
    evidence_unified_sensitivity = torch.maximum(evidence_answer_sensitivity, evidence_causal_sensitivity)
    unified_activity = torch.maximum(source_unified_sensitivity, evidence_unified_sensitivity)
    source_mass_fraction = torch.full((num_heads,), 0.5, device=head_output.device, dtype=torch.float32)
    evidence_mass_fraction = torch.full((num_heads,), 0.5, device=head_output.device, dtype=torch.float32)
    mass_sum = src_mass + evi_mass
    mass_valid = mass_sum > eps
    source_mass_fraction = torch.where(mass_valid, src_mass / mass_sum.clamp_min(eps), source_mass_fraction)
    evidence_mass_fraction = torch.where(mass_valid, evi_mass / mass_sum.clamp_min(eps), evidence_mass_fraction)
    sensitivity_sum = source_unified_sensitivity + evidence_unified_sensitivity
    sensitivity_valid = sensitivity_sum > eps
    source_flow_fraction = torch.where(
        sensitivity_valid,
        source_unified_sensitivity / sensitivity_sum.clamp_min(eps),
        torch.full_like(source_unified_sensitivity, 0.5),
    )
    evidence_flow_fraction = torch.where(
        sensitivity_valid,
        evidence_unified_sensitivity / sensitivity_sum.clamp_min(eps),
        torch.full_like(evidence_unified_sensitivity, 0.5),
    )
    source_flow_alignment = torch.sqrt((source_mass_fraction * source_flow_fraction).clamp_min(0.0))
    evidence_flow_alignment = torch.sqrt((evidence_mass_fraction * evidence_flow_fraction).clamp_min(0.0))
    flow_alignment_sum = source_flow_alignment + evidence_flow_alignment
    evidence_flow_edit_permission = torch.where(
        flow_alignment_sum > eps,
        evidence_flow_alignment / flow_alignment_sum.clamp_min(eps),
        torch.full_like(evidence_flow_alignment, 0.5),
    ).clamp(0.0, 1.0)
    if path_score_key in {"unified_sensitivity", "unified_sensitivity_posterior"}:
        source_logit = torch.log(source_mass_fraction.clamp_min(eps)) + source_unified_sensitivity
        evidence_logit = torch.log(evidence_mass_fraction.clamp_min(eps)) + evidence_unified_sensitivity
        path_posterior = torch.softmax(torch.stack((source_logit, evidence_logit), dim=0), dim=0)
        posterior_activity = (
            unified_activity
            if path_score_key == "unified_sensitivity"
            else torch.ones_like(unified_activity)
        )
        source_carrier_weight = path_posterior[0] * posterior_activity
        evidence_carrier_weight = path_posterior[1] * posterior_activity
        carrier_score = source_logit - evidence_logit

    source_current_preservation = (protection_value * source_answer_weight).clamp(0.0, 1.0)
    source_suppression_scale = (1.0 - source_current_preservation).clamp(0.10, 1.0)
    evidence_reinforcement_scale = (
        1.0 + protection_value * evidence_answer_weight * (1.0 - source_answer_weight)
    ).clamp(1.0, 1.50)
    if path_score_key in {"unified_sensitivity", "unified_sensitivity_posterior"}:
        source_path_base = source_carrier_weight * source_suppression_scale
        evidence_path_base = evidence_carrier_weight
    else:
        source_path_base = (
            source_carrier_weight
            * source_suppression_answer_weight
            * source_suppression_scale
            * source_attention_causal_scale
        )
        evidence_path_base = (
            evidence_carrier_weight
            * evidence_answer_weight
            * evidence_reinforcement_scale
            * evidence_attention_causal_scale
        )
    if path_score_key == "evidence_flow_calibrated":
        source_path_base = source_path_base * evidence_flow_edit_permission
        evidence_path_base = evidence_path_base * evidence_flow_edit_permission

    latent_anchor_path_gate = (
        latent_anchor_update_gate
        if bool(latent_anchor_apply_update_gate)
        else torch.tensor(1.0, device=head_output.device, dtype=torch.float32)
    )
    source_path_weight = (
        source_path_base
        * source_anchor_constraint_scale
        * source_full_context_scale
        * view_source_scale
        * latent_anchor_path_gate
    ).view(1, num_heads, 1, 1)
    evidence_path_weight = (
        evidence_path_base
        * evidence_anchor_constraint_scale
        * evidence_full_context_scale
        * evidence_full_context_reinforcement
        * view_evidence_scale
        * latent_anchor_path_gate
    ).view(1, num_heads, 1, 1)

    prior_delta = -beta_value * source_path_weight * source
    evidence_delta = alpha_value * evidence_path_weight * evidence
    additive_delta = prior_delta + evidence_delta
    angular_valid = torch.zeros(num_heads, device=head_output.device, dtype=torch.bool)
    angular_active = torch.zeros(num_heads, device=head_output.device, dtype=torch.bool)
    angular_target_angle = torch.zeros(num_heads, device=head_output.device, dtype=torch.float32)
    angular_plane_norm = torch.zeros(num_heads, device=head_output.device, dtype=torch.float32)
    nullspace_valid = torch.zeros(num_heads, device=head_output.device, dtype=torch.bool)
    nullspace_removed = torch.zeros_like(additive_delta)
    if update_geometry == "anchor_nullspace":
        if anchor_nullspace_axis is None:
            delta = additive_delta
        else:
            anchor_axis = anchor_nullspace_axis.detach().float().to(device=head_output.device)
            if tuple(anchor_axis.shape) != tuple(head_output.shape):
                raise ValueError(
                    "anchor_nullspace_axis must match head_output shape "
                    f"{tuple(anchor_axis.shape)} != {tuple(head_output.shape)}"
                )
            anchor_norm = anchor_axis.norm(dim=-1, keepdim=True)
            nullspace_valid = (anchor_norm[:, :, 0, 0] > eps)
            anchor_dir = anchor_axis / anchor_norm.clamp_min(eps)
            nullspace_removed = (additive_delta * anchor_dir).sum(dim=-1, keepdim=True) * anchor_dir
            delta = torch.where(
                nullspace_valid[:, :, None, None],
                additive_delta - nullspace_removed,
                additive_delta,
            )
    elif update_geometry == "angular":
        source_vec = source[:, :, 0, :]
        evidence_vec = evidence[:, :, 0, :]
        head_vec = head_output[:, :, 0, :]
        source_norm_vec = source_vec.norm(dim=-1, keepdim=True)
        b1 = source_vec / source_norm_vec.clamp_min(eps)
        evidence_orth = evidence_vec - (evidence_vec * b1).sum(dim=-1, keepdim=True) * b1
        evidence_orth_norm = evidence_orth.norm(dim=-1, keepdim=True)
        b2 = evidence_orth / evidence_orth_norm.clamp_min(eps)
        angular_valid = ((source_norm_vec[:, :, 0] > eps) & (evidence_orth_norm[:, :, 0] > eps))
        source_axis = (beta_value * source_path_weight[0, :, 0, 0]).clamp(0.0, 0.95)
        evidence_axis = (alpha_value * evidence_path_weight[0, :, 0, 0]).clamp(0.0, 0.95)
        target_b1_coeff = (1.0 - source_axis).clamp(0.0, 1.0)
        target_b2_coeff = evidence_axis
        target_norm = (target_b1_coeff.pow(2) + target_b2_coeff.pow(2)).sqrt().clamp_min(eps)
        target_vec = (
            (target_b1_coeff / target_norm).view(1, num_heads, 1) * b1
            + (target_b2_coeff / target_norm).view(1, num_heads, 1) * b2
        )
        projection_b1 = (head_vec * b1).sum(dim=-1, keepdim=True)
        projection_b2 = (head_vec * b2).sum(dim=-1, keepdim=True)
        plane_projection = projection_b1 * b1 + projection_b2 * b2
        plane_norm = plane_projection.norm(dim=-1, keepdim=True)
        angular_plane_norm = plane_norm[:, :, 0].detach()
        angular_active = angular_valid & (projection_b1[:, :, 0] > 0.0)
        angular_delta = plane_norm * target_vec - plane_projection
        delta = torch.where(
            angular_active[:, :, None, None],
            angular_delta.unsqueeze(2),
            torch.zeros_like(head_output),
        )
        angular_target_angle = torch.atan2(
            target_b2_coeff.detach(),
            target_b1_coeff.detach().clamp_min(eps),
        )
    else:
        delta = additive_delta
    patched = head_output + delta

    with torch.no_grad():
        source_norm = source.norm(dim=-1, keepdim=True)
        evidence_norm = evidence.norm(dim=-1, keepdim=True)
        cos = torch.abs(
            (source * evidence).sum(dim=-1, keepdim=True)
            / (source_norm * evidence_norm).clamp_min(eps)
        )
        valid_source = source_norm > eps
        valid_evidence = evidence_norm > eps
        prior_heads = torch.nonzero((source_path_weight[0, :, 0, 0] > 0.5).detach().cpu(), as_tuple=False).flatten()
        evidence_heads = torch.nonzero(
            (evidence_path_weight[0, :, 0, 0] >= source_path_weight[0, :, 0, 0]).detach().cpu(),
            as_tuple=False,
        ).flatten()

    def mean_value(values: torch.Tensor) -> float:
        return float(values.detach().float().mean().cpu().item())

    def min_value(values: torch.Tensor) -> float:
        return float(values.detach().float().min().cpu().item())

    def max_value(values: torch.Tensor) -> float:
        return float(values.detach().float().max().cpu().item())

    return {
        "patched_head_output": patched,
        "delta": delta,
        "oelpr_mass_temperature": float(mass_temperature),
        "oelpr_answer_temperature": float(answer_temperature),
        "oelpr_current_protection_weight": float(protection_value),
        "oelpr_path_score_mode": path_score_key,
        "oelpr_unified_source_sensitivity_mean": mean_value(source_unified_sensitivity),
        "oelpr_unified_source_sensitivity_max": max_value(source_unified_sensitivity),
        "oelpr_unified_evidence_sensitivity_mean": mean_value(evidence_unified_sensitivity),
        "oelpr_unified_evidence_sensitivity_max": max_value(evidence_unified_sensitivity),
        "oelpr_unified_activity_mean": mean_value(unified_activity),
        "oelpr_unified_activity_max": max_value(unified_activity),
        "oelpr_source_mass_fraction_mean": mean_value(source_mass_fraction),
        "oelpr_evidence_mass_fraction_mean": mean_value(evidence_mass_fraction),
        "oelpr_flow_source_fraction_mean": mean_value(source_flow_fraction),
        "oelpr_flow_evidence_fraction_mean": mean_value(evidence_flow_fraction),
        "oelpr_flow_source_alignment_mean": mean_value(source_flow_alignment),
        "oelpr_flow_source_alignment_max": max_value(source_flow_alignment),
        "oelpr_flow_evidence_alignment_mean": mean_value(evidence_flow_alignment),
        "oelpr_flow_evidence_alignment_max": max_value(evidence_flow_alignment),
        "oelpr_flow_evidence_edit_permission_mean": mean_value(evidence_flow_edit_permission),
        "oelpr_flow_evidence_edit_permission_min": min_value(evidence_flow_edit_permission),
        "oelpr_flow_evidence_edit_permission_max": max_value(evidence_flow_edit_permission),
        "oelpr_path_update_geometry": update_geometry,
        "oelpr_angular_valid_head_ratio": float(
            angular_valid.float().mean().detach().cpu().item()
        ),
        "oelpr_angular_active_head_ratio": float(
            angular_active.float().mean().detach().cpu().item()
        ),
        "oelpr_angular_target_angle_mean_deg": float(
            (angular_target_angle * (180.0 / math.pi)).mean().detach().cpu().item()
        ),
        "oelpr_angular_target_angle_max_deg": float(
            (angular_target_angle * (180.0 / math.pi)).max().detach().cpu().item()
        ),
        "oelpr_angular_plane_norm_mean": float(
            angular_plane_norm.mean().detach().cpu().item()
        ),
        "oelpr_anchor_nullspace_valid_head_ratio": float(
            nullspace_valid.float().mean().detach().cpu().item()
        ),
        "oelpr_anchor_nullspace_removed_l2": float(
            nullspace_removed.norm().detach().cpu().item()
        ),
        "oelpr_anchor_nullspace_removed_ratio": float(
            (
                nullspace_removed.norm()
                / additive_delta.norm().clamp_min(eps)
            ).detach().cpu().item()
        ),
        "oelpr_carrier_score_mean": mean_value(carrier_score),
        "oelpr_carrier_score_min": min_value(carrier_score),
        "oelpr_carrier_score_max": max_value(carrier_score),
        "oelpr_source_carrier_weight_mean": mean_value(source_carrier_weight),
        "oelpr_source_carrier_weight_min": min_value(source_carrier_weight),
        "oelpr_source_carrier_weight_max": max_value(source_carrier_weight),
        "oelpr_evidence_carrier_weight_mean": mean_value(evidence_carrier_weight),
        "oelpr_evidence_carrier_weight_min": min_value(evidence_carrier_weight),
        "oelpr_evidence_carrier_weight_max": max_value(evidence_carrier_weight),
        "oelpr_source_answer_weight_mean": mean_value(source_answer_weight),
        "oelpr_source_answer_weight_min": min_value(source_answer_weight),
        "oelpr_source_answer_weight_max": max_value(source_answer_weight),
        "oelpr_source_suppression_answer_weight_mean": mean_value(source_suppression_answer_weight),
        "oelpr_source_suppression_answer_weight_min": min_value(source_suppression_answer_weight),
        "oelpr_source_suppression_answer_weight_max": max_value(source_suppression_answer_weight),
        "oelpr_evidence_answer_weight_mean": mean_value(evidence_answer_weight),
        "oelpr_evidence_answer_weight_min": min_value(evidence_answer_weight),
        "oelpr_evidence_answer_weight_max": max_value(evidence_answer_weight),
        "oelpr_counterfactual_path_mode": cf_mode,
        "oelpr_counterfactual_path_applied": bool(cf_mode == "apply"),
        "oelpr_counterfactual_target_answer": normalize_binary_label(counterfactual_target_answer),
        "oelpr_counterfactual_counter_answer": normalize_binary_label(counterfactual_counter_answer),
        "oelpr_cf_source_target_shortcut_mean": (
            float(cf_source_scores.mean().detach().cpu().item())
            if cf_source_scores is not None
            else None
        ),
        "oelpr_cf_source_target_shortcut_min": (
            float(cf_source_scores.min().detach().cpu().item())
            if cf_source_scores is not None
            else None
        ),
        "oelpr_cf_source_target_shortcut_max": (
            float(cf_source_scores.max().detach().cpu().item())
            if cf_source_scores is not None
            else None
        ),
        "oelpr_cf_source_target_weight_mean": (
            float(cf_source_weight.mean().detach().cpu().item())
            if cf_source_weight is not None
            else None
        ),
        "oelpr_cf_source_target_weight_min": (
            float(cf_source_weight.min().detach().cpu().item())
            if cf_source_weight is not None
            else None
        ),
        "oelpr_cf_source_target_weight_max": (
            float(cf_source_weight.max().detach().cpu().item())
            if cf_source_weight is not None
            else None
        ),
        "oelpr_cf_evidence_counter_support_mean": (
            float(cf_evidence_scores.mean().detach().cpu().item())
            if cf_evidence_scores is not None
            else None
        ),
        "oelpr_cf_evidence_counter_support_min": (
            float(cf_evidence_scores.min().detach().cpu().item())
            if cf_evidence_scores is not None
            else None
        ),
        "oelpr_cf_evidence_counter_support_max": (
            float(cf_evidence_scores.max().detach().cpu().item())
            if cf_evidence_scores is not None
            else None
        ),
        "oelpr_cf_evidence_counter_weight_mean": (
            float(cf_evidence_weight.mean().detach().cpu().item())
            if cf_evidence_weight is not None
            else None
        ),
        "oelpr_cf_evidence_counter_weight_min": (
            float(cf_evidence_weight.min().detach().cpu().item())
            if cf_evidence_weight is not None
            else None
        ),
        "oelpr_cf_evidence_counter_weight_max": (
            float(cf_evidence_weight.max().detach().cpu().item())
            if cf_evidence_weight is not None
            else None
        ),
        "oelpr_cf_available": bool(cf_source_scores is not None or cf_evidence_scores is not None),
        "oelpr_latent_anchor_mode": anchor_mode,
        "oelpr_latent_anchor_confidence_gate": anchor_gate_key,
        "oelpr_latent_anchor_gate_threshold": float(latent_anchor_gate_threshold),
        "oelpr_latent_anchor_gate_tau": float(latent_anchor_gate_tau),
        "oelpr_latent_anchor_update_gate": float(latent_anchor_update_gate.detach().cpu().item()),
        "oelpr_latent_anchor_gate_applied_to_path": bool(latent_anchor_apply_update_gate),
        "oelpr_latent_anchor_constrained": bool(anchor_mode == "constrain"),
        "oelpr_latent_anchor_answer": normalize_binary_label(latent_anchor_answer),
        "oelpr_latent_anchor_counter_answer": normalize_binary_label(latent_anchor_counter_answer),
        "oelpr_latent_anchor_margin": anchor_margin_value,
        "oelpr_latent_anchor_confidence": (
            float(anchor_confidence.detach().cpu().item())
            if anchor_confidence is not None
            else None
        ),
        "oelpr_latent_anchor_source_effect_mean": (
            float(source_anchor_scores.mean().detach().cpu().item())
            if source_anchor_scores is not None
            else None
        ),
        "oelpr_latent_anchor_source_harm_weight_mean": (
            float(source_anchor_harm_weight.mean().detach().cpu().item())
            if source_anchor_harm_weight is not None
            else None
        ),
        "oelpr_latent_anchor_source_constraint_scale_mean": float(
            source_anchor_constraint_scale.mean().detach().cpu().item()
        ),
        "oelpr_latent_anchor_source_constraint_scale_min": float(
            source_anchor_constraint_scale.min().detach().cpu().item()
        ),
        "oelpr_latent_anchor_evidence_effect_mean": (
            float(evidence_anchor_scores.mean().detach().cpu().item())
            if evidence_anchor_scores is not None
            else None
        ),
        "oelpr_latent_anchor_evidence_harm_weight_mean": (
            float(evidence_anchor_harm_weight.mean().detach().cpu().item())
            if evidence_anchor_harm_weight is not None
            else None
        ),
        "oelpr_latent_anchor_evidence_constraint_scale_mean": float(
            evidence_anchor_constraint_scale.mean().detach().cpu().item()
        ),
        "oelpr_latent_anchor_evidence_constraint_scale_min": float(
            evidence_anchor_constraint_scale.min().detach().cpu().item()
        ),
        "oelpr_latent_anchor_available": bool(
            source_anchor_scores is not None or evidence_anchor_scores is not None
        ),
        "oelpr_full_context_answer": normalize_binary_label(full_context_answer),
        "oelpr_full_context_counter_answer": normalize_binary_label(full_context_counter_answer),
        "oelpr_full_context_margin": full_context_margin_value,
        "oelpr_full_context_confidence": (
            float(full_context_confidence.detach().cpu().item())
            if full_context_confidence is not None
            else None
        ),
        "oelpr_full_context_source_effect_mean": (
            float(source_full_context_scores.mean().detach().cpu().item())
            if source_full_context_scores is not None
            else None
        ),
        "oelpr_full_context_source_preserve_weight_mean": (
            float(source_full_context_preserve_weight.mean().detach().cpu().item())
            if source_full_context_preserve_weight is not None
            else None
        ),
        "oelpr_full_context_source_scale_mean": float(
            source_full_context_scale.mean().detach().cpu().item()
        ),
        "oelpr_full_context_source_scale_min": float(
            source_full_context_scale.min().detach().cpu().item()
        ),
        "oelpr_full_context_evidence_effect_mean": (
            float(evidence_full_context_scores.mean().detach().cpu().item())
            if evidence_full_context_scores is not None
            else None
        ),
        "oelpr_full_context_evidence_support_weight_mean": (
            float(evidence_full_context_support_weight.mean().detach().cpu().item())
            if evidence_full_context_support_weight is not None
            else None
        ),
        "oelpr_full_context_evidence_harm_weight_mean": (
            float(evidence_full_context_harm_weight.mean().detach().cpu().item())
            if evidence_full_context_harm_weight is not None
            else None
        ),
        "oelpr_full_context_evidence_scale_mean": float(
            evidence_full_context_scale.mean().detach().cpu().item()
        ),
        "oelpr_full_context_evidence_scale_min": float(
            evidence_full_context_scale.min().detach().cpu().item()
        ),
        "oelpr_full_context_evidence_reinforcement_mean": float(
            evidence_full_context_reinforcement.mean().detach().cpu().item()
        ),
        "oelpr_full_context_available": bool(
            source_full_context_scores is not None or evidence_full_context_scores is not None
        ),
        "oelpr_candidate_view_support": (
            float(candidate_view_support_value) if candidate_view_support_value is not None else None
        ),
        "oelpr_current_view_support": (
            float(current_view_support_value) if current_view_support_value is not None else None
        ),
        "oelpr_view_constraint_mode": view_constraint_key,
        "oelpr_view_candidate_deficit": float(view_candidate_deficit.detach().cpu().item()),
        "oelpr_view_current_advantage": float(view_current_advantage.detach().cpu().item()),
        "oelpr_view_candidate_advantage": float(view_candidate_advantage.detach().cpu().item()),
        "oelpr_view_source_scale_mean": float(view_source_scale.mean().detach().cpu().item()),
        "oelpr_view_evidence_scale_mean": float(view_evidence_scale.mean().detach().cpu().item()),
        "oelpr_attention_causal_mode": attention_causal_key,
        "oelpr_attention_causal_available": bool(
            source_attention_causal_scores is not None or evidence_attention_causal_scores is not None
        ),
        "oelpr_source_attention_causal_effect_mean": (
            float(source_attention_causal_scores.mean().detach().cpu().item())
            if source_attention_causal_scores is not None
            else None
        ),
        "oelpr_source_attention_causal_effect_min": (
            float(source_attention_causal_scores.min().detach().cpu().item())
            if source_attention_causal_scores is not None
            else None
        ),
        "oelpr_source_attention_causal_effect_max": (
            float(source_attention_causal_scores.max().detach().cpu().item())
            if source_attention_causal_scores is not None
            else None
        ),
        "oelpr_source_attention_causal_scale_mean": float(
            source_attention_causal_scale.mean().detach().cpu().item()
        ),
        "oelpr_source_attention_causal_scale_min": float(
            source_attention_causal_scale.min().detach().cpu().item()
        ),
        "oelpr_source_attention_causal_scale_max": float(
            source_attention_causal_scale.max().detach().cpu().item()
        ),
        "oelpr_evidence_attention_causal_effect_mean": (
            float(evidence_attention_causal_scores.mean().detach().cpu().item())
            if evidence_attention_causal_scores is not None
            else None
        ),
        "oelpr_evidence_attention_causal_effect_min": (
            float(evidence_attention_causal_scores.min().detach().cpu().item())
            if evidence_attention_causal_scores is not None
            else None
        ),
        "oelpr_evidence_attention_causal_effect_max": (
            float(evidence_attention_causal_scores.max().detach().cpu().item())
            if evidence_attention_causal_scores is not None
            else None
        ),
        "oelpr_evidence_attention_causal_scale_mean": float(
            evidence_attention_causal_scale.mean().detach().cpu().item()
        ),
        "oelpr_evidence_attention_causal_scale_min": float(
            evidence_attention_causal_scale.min().detach().cpu().item()
        ),
        "oelpr_evidence_attention_causal_scale_max": float(
            evidence_attention_causal_scale.max().detach().cpu().item()
        ),
        "oelpr_source_current_preservation_mean": mean_value(source_current_preservation),
        "oelpr_source_current_preservation_min": min_value(source_current_preservation),
        "oelpr_source_current_preservation_max": max_value(source_current_preservation),
        "oelpr_source_suppression_scale_mean": mean_value(source_suppression_scale),
        "oelpr_source_suppression_scale_min": min_value(source_suppression_scale),
        "oelpr_source_suppression_scale_max": max_value(source_suppression_scale),
        "oelpr_evidence_reinforcement_scale_mean": mean_value(evidence_reinforcement_scale),
        "oelpr_evidence_reinforcement_scale_min": min_value(evidence_reinforcement_scale),
        "oelpr_evidence_reinforcement_scale_max": max_value(evidence_reinforcement_scale),
        "oelpr_source_path_weight_mean": mean_value(source_path_weight),
        "oelpr_source_path_weight_min": min_value(source_path_weight),
        "oelpr_source_path_weight_max": max_value(source_path_weight),
        "oelpr_evidence_path_weight_mean": mean_value(evidence_path_weight),
        "oelpr_evidence_path_weight_min": min_value(evidence_path_weight),
        "oelpr_evidence_path_weight_max": max_value(evidence_path_weight),
        "oelpr_prior_dominant_head_count": int(prior_heads.numel()),
        "oelpr_evidence_dominant_head_count": int(evidence_heads.numel()),
        "oelpr_prior_dominant_heads": [int(x) for x in prior_heads.tolist()],
        "oelpr_evidence_dominant_heads": [int(x) for x in evidence_heads.tolist()],
        "oelpr_source_current_over_candidate_mean": (
            float(source_answer_scores.mean().detach().cpu().item())
            if source_answer_scores is not None
            else None
        ),
        "oelpr_evidence_candidate_over_current_mean": (
            float(evidence_answer_scores.mean().detach().cpu().item())
            if evidence_answer_scores is not None
            else None
        ),
        "oelpr_source_component_l2": float(source.norm().detach().cpu().item()),
        "oelpr_evidence_component_l2": float(evidence.norm().detach().cpu().item()),
        "head_transport_delta_l2": float(delta.norm().detach().cpu().item()),
        "head_transport_prior_delta_l2": float(prior_delta.norm().detach().cpu().item()),
        "head_transport_transport_delta_l2": float(evidence_delta.norm().detach().cpu().item()),
        "head_transport_compensation_delta_l2": 0.0,
        "head_transport_alpha_ratio": float(alpha_value),
        "head_transport_u_p_abs_cos": float(cos.mean().detach().cpu().item()),
        "head_transport_valid_prior_ratio": float(valid_source.float().mean().detach().cpu().item()),
        "head_transport_valid_evidence_ratio": float(valid_evidence.float().mean().detach().cpu().item()),
    }


def _carrier_constrained_path_refinement_output(
    *,
    original_head_output: torch.Tensor,
    source_contribution: torch.Tensor,
    evidence_contribution: torch.Tensor,
    source_mass: torch.Tensor,
    evidence_mass: torch.Tensor,
    source_prior_alignment: torch.Tensor,
    evidence_carrier_alignment: torch.Tensor,
    beta_for_layer: float,
    alpha_for_layer: float,
    alpha_mode: str,
    source_current_over_candidate: torch.Tensor | None = None,
    evidence_candidate_over_current: torch.Tensor | None = None,
) -> dict[str, Any]:
    """Path refinement constrained by hidden-space prior/evidence carriers.

    The hidden U/P carriers define which token/head paths are semantically
    relevant, while the update itself remains local to attention value paths.
    """
    head_output = original_head_output.float()
    source = source_contribution.float().to(device=head_output.device)
    evidence = evidence_contribution.float().to(device=head_output.device)
    num_heads = int(head_output.shape[1])
    if int(source.shape[1]) != num_heads or int(evidence.shape[1]) != num_heads:
        raise ValueError(
            "carrier-constrained path refinement expects source/evidence contributions "
            f"for all heads, got source={tuple(source.shape)} evidence={tuple(evidence.shape)} "
            f"head_output={tuple(head_output.shape)}"
        )
    src_mass = source_mass.detach().float().to(device=head_output.device)
    evi_mass = evidence_mass.detach().float().to(device=head_output.device)
    prior_align = source_prior_alignment.detach().float().to(device=head_output.device).clamp(0.0, 1.0)
    evidence_align = evidence_carrier_alignment.detach().float().to(device=head_output.device).clamp(0.0, 1.0)
    for name, scores in {
        "source_mass": src_mass,
        "evidence_mass": evi_mass,
        "source_prior_alignment": prior_align,
        "evidence_carrier_alignment": evidence_align,
    }.items():
        if int(scores.numel()) != num_heads:
            raise ValueError(f"{name} must have one score per head ({int(scores.numel())} != {num_heads})")

    beta_value = max(0.0, float(beta_for_layer))
    alpha_value = max(0.0, float(alpha_for_layer)) if safe_text(alpha_mode) == "evidence_value_boost" else 0.0
    answer_temperature = 0.001
    source_answer_weight = torch.ones(num_heads, device=head_output.device, dtype=torch.float32)
    evidence_answer_weight = torch.ones(num_heads, device=head_output.device, dtype=torch.float32)
    source_answer_scores = None
    evidence_answer_scores = None
    if source_current_over_candidate is not None:
        source_answer_scores = source_current_over_candidate.detach().float().to(device=head_output.device)
        if int(source_answer_scores.numel()) != num_heads:
            raise ValueError(
                "source_current_over_candidate must have one score per head "
                f"({int(source_answer_scores.numel())} != {num_heads})"
            )
        source_answer_weight = torch.sigmoid(source_answer_scores / answer_temperature)
    if evidence_candidate_over_current is not None:
        evidence_answer_scores = evidence_candidate_over_current.detach().float().to(device=head_output.device)
        if int(evidence_answer_scores.numel()) != num_heads:
            raise ValueError(
                "evidence_candidate_over_current must have one score per head "
                f"({int(evidence_answer_scores.numel())} != {num_heads})"
            )
        evidence_answer_weight = torch.sigmoid(evidence_answer_scores / answer_temperature)

    prior_score = src_mass * prior_align * source_answer_weight
    evidence_score = evi_mass * evidence_align * evidence_answer_weight
    score_sum = prior_score + evidence_score
    active = score_sum > 1.0e-12
    prior_weight = torch.where(active, prior_score / score_sum.clamp_min(1.0e-12), torch.zeros_like(prior_score))
    evidence_weight = torch.where(
        active,
        evidence_score / score_sum.clamp_min(1.0e-12),
        torch.zeros_like(evidence_score),
    )
    prior_delta = -beta_value * prior_weight.view(1, num_heads, 1, 1) * source
    evidence_delta = alpha_value * evidence_weight.view(1, num_heads, 1, 1) * evidence
    delta = prior_delta + evidence_delta
    patched = head_output + delta

    with torch.no_grad():
        source_norm = source.norm(dim=-1, keepdim=True)
        evidence_norm = evidence.norm(dim=-1, keepdim=True)
        cos = torch.abs(
            (source * evidence).sum(dim=-1, keepdim=True)
            / (source_norm * evidence_norm).clamp_min(1.0e-12)
        )
        valid_source = source_norm > 1.0e-12
        valid_evidence = evidence_norm > 1.0e-12
        prior_heads = torch.nonzero((prior_weight > evidence_weight).detach().cpu(), as_tuple=False).flatten()
        evidence_heads = torch.nonzero((evidence_weight >= prior_weight).detach().cpu(), as_tuple=False).flatten()

    return {
        "patched_head_output": patched,
        "delta": delta,
        "carrier_constrained_answer_temperature": float(answer_temperature),
        "carrier_constrained_active_head_count": int(active.detach().cpu().sum().item()),
        "carrier_constrained_prior_score_mean": float(prior_score.mean().detach().cpu().item()),
        "carrier_constrained_prior_score_min": float(prior_score.min().detach().cpu().item()),
        "carrier_constrained_prior_score_max": float(prior_score.max().detach().cpu().item()),
        "carrier_constrained_evidence_score_mean": float(evidence_score.mean().detach().cpu().item()),
        "carrier_constrained_evidence_score_min": float(evidence_score.min().detach().cpu().item()),
        "carrier_constrained_evidence_score_max": float(evidence_score.max().detach().cpu().item()),
        "carrier_constrained_prior_weight_mean": float(prior_weight.mean().detach().cpu().item()),
        "carrier_constrained_prior_weight_min": float(prior_weight.min().detach().cpu().item()),
        "carrier_constrained_prior_weight_max": float(prior_weight.max().detach().cpu().item()),
        "carrier_constrained_evidence_weight_mean": float(evidence_weight.mean().detach().cpu().item()),
        "carrier_constrained_evidence_weight_min": float(evidence_weight.min().detach().cpu().item()),
        "carrier_constrained_evidence_weight_max": float(evidence_weight.max().detach().cpu().item()),
        "carrier_constrained_source_prior_alignment_mean": float(prior_align.mean().detach().cpu().item()),
        "carrier_constrained_source_prior_alignment_min": float(prior_align.min().detach().cpu().item()),
        "carrier_constrained_source_prior_alignment_max": float(prior_align.max().detach().cpu().item()),
        "carrier_constrained_evidence_alignment_mean": float(evidence_align.mean().detach().cpu().item()),
        "carrier_constrained_evidence_alignment_min": float(evidence_align.min().detach().cpu().item()),
        "carrier_constrained_evidence_alignment_max": float(evidence_align.max().detach().cpu().item()),
        "carrier_constrained_prior_dominant_head_count": int(prior_heads.numel()),
        "carrier_constrained_evidence_dominant_head_count": int(evidence_heads.numel()),
        "carrier_constrained_prior_dominant_heads": [int(x) for x in prior_heads.tolist()],
        "carrier_constrained_evidence_dominant_heads": [int(x) for x in evidence_heads.tolist()],
        "carrier_constrained_answer_consistency": bool(
            source_answer_scores is not None or evidence_answer_scores is not None
        ),
        "carrier_constrained_source_answer_weight_mean": float(
            source_answer_weight.mean().detach().cpu().item()
        ),
        "carrier_constrained_source_answer_weight_min": float(source_answer_weight.min().detach().cpu().item()),
        "carrier_constrained_source_answer_weight_max": float(source_answer_weight.max().detach().cpu().item()),
        "carrier_constrained_evidence_answer_weight_mean": float(
            evidence_answer_weight.mean().detach().cpu().item()
        ),
        "carrier_constrained_evidence_answer_weight_min": float(evidence_answer_weight.min().detach().cpu().item()),
        "carrier_constrained_evidence_answer_weight_max": float(evidence_answer_weight.max().detach().cpu().item()),
        "carrier_constrained_source_current_over_candidate_mean": (
            float(source_answer_scores.mean().detach().cpu().item())
            if source_answer_scores is not None
            else None
        ),
        "carrier_constrained_evidence_candidate_over_current_mean": (
            float(evidence_answer_scores.mean().detach().cpu().item())
            if evidence_answer_scores is not None
            else None
        ),
        "carrier_constrained_source_component_l2": float(source.norm().detach().cpu().item()),
        "carrier_constrained_evidence_component_l2": float(evidence.norm().detach().cpu().item()),
        "head_transport_delta_l2": float(delta.norm().detach().cpu().item()),
        "head_transport_prior_delta_l2": float(prior_delta.norm().detach().cpu().item()),
        "head_transport_transport_delta_l2": float(evidence_delta.norm().detach().cpu().item()),
        "head_transport_compensation_delta_l2": 0.0,
        "head_transport_alpha_ratio": float(alpha_value),
        "head_transport_u_p_abs_cos": float(cos.mean().detach().cpu().item()),
        "head_transport_valid_prior_ratio": float(valid_source.float().mean().detach().cpu().item()),
        "head_transport_valid_evidence_ratio": float(valid_evidence.float().mean().detach().cpu().item()),
    }


def _residual_guided_path_solver_output(
    *,
    module: torch.nn.Module,
    hidden_state_base: torch.Tensor,
    original_head_output: torch.Tensor,
    source_contribution: torch.Tensor,
    evidence_contribution: torch.Tensor,
    source_mass: torch.Tensor,
    evidence_mass: torch.Tensor,
    prior_direction: torch.Tensor,
    evidence_direction: torch.Tensor,
    evidence_transfer_vector: torch.Tensor,
    beta_for_layer: float,
    alpha_for_layer: float,
    alpha_mode: str,
    source_current_over_candidate: torch.Tensor | None = None,
    evidence_candidate_over_current: torch.Tensor | None = None,
) -> dict[str, Any]:
    """Fit token/head value-path edits to the structured hidden residual target.

    The hidden U/P carrier is only used to define the per-layer residual target.
    The applied update remains a final-query attention value-path update, with
    continuous non-negative weights over all heads.
    """
    h = original_head_output.float()
    source = source_contribution.float().to(device=h.device)
    evidence = evidence_contribution.float().to(device=h.device)
    num_heads = int(h.shape[1])
    if int(source.shape[1]) != num_heads or int(evidence.shape[1]) != num_heads:
        raise ValueError(
            "residual-guided path solver expects source/evidence contributions "
            f"for all heads, got source={tuple(source.shape)} evidence={tuple(evidence.shape)} "
            f"head_output={tuple(h.shape)}"
        )

    src_mass = source_mass.detach().float().to(device=h.device)
    evi_mass = evidence_mass.detach().float().to(device=h.device)
    if int(src_mass.numel()) != num_heads or int(evi_mass.numel()) != num_heads:
        raise ValueError(
            "residual-guided path solver expects one mass score per head "
            f"({int(src_mass.numel())}, {int(evi_mass.numel())}) != {num_heads}"
        )

    eps = 1.0e-12
    beta_value = max(0.0, float(beta_for_layer))
    alpha_value = max(0.0, float(alpha_for_layer)) if safe_text(alpha_mode) == "evidence_value_boost" else 0.0
    answer_temperature = 0.001
    max_weight = 2.5

    def unit_vec(vec: torch.Tensor) -> torch.Tensor:
        norm = vec.norm().clamp_min(eps)
        return torch.where(norm > eps, vec / norm, torch.zeros_like(vec))

    base_tensor = hidden_state_base.detach().float().to(device=h.device)
    if base_tensor.ndim == 3:
        base = base_tensor[0, -1, :]
    elif base_tensor.ndim == 2:
        base = base_tensor[-1, :]
    else:
        raise ValueError(f"unexpected hidden_state_base shape: {tuple(base_tensor.shape)}")

    source_hidden = _project_head_contribution_to_hidden(
        module=module,
        contribution=source,
    ).to(device=h.device, dtype=torch.float32)
    evidence_hidden = _project_head_contribution_to_hidden(
        module=module,
        contribution=evidence,
    ).to(device=h.device, dtype=torch.float32)
    if int(source_hidden.shape[-1]) != int(base.numel()) or int(evidence_hidden.shape[-1]) != int(base.numel()):
        raise ValueError(
            "projected token/head paths must match hidden size "
            f"({tuple(source_hidden.shape)}, {tuple(evidence_hidden.shape)}, base={tuple(base.shape)})"
        )

    p_dir = unit_vec(prior_direction.detach().float().to(device=h.device))
    e_dir = unit_vec(evidence_direction.detach().float().to(device=h.device))
    transfer = evidence_transfer_vector.detach().float().to(device=h.device)
    transfer_dir = unit_vec(transfer) if float(transfer.norm().detach().cpu().item()) > eps else e_dir
    prior_scalar = torch.dot(base, p_dir)
    prior_fallback_dir = -torch.sign(prior_scalar).clamp(min=-1.0, max=1.0) * p_dir
    if float(prior_fallback_dir.norm().detach().cpu().item()) <= eps:
        prior_fallback_dir = -p_dir
    prior_target_raw = -prior_scalar * p_dir
    evidence_target_raw = transfer if float(transfer.norm().detach().cpu().item()) > eps else e_dir

    source_delta_basis = -source_hidden.mean(dim=0)
    evidence_delta_basis = evidence_hidden.mean(dim=0)

    def scaled_target(target_raw: torch.Tensor, fallback_dir: torch.Tensor, basis: torch.Tensor) -> torch.Tensor:
        basis_scale = basis.norm(dim=-1).mean().clamp_min(eps)
        direction = target_raw
        if float(direction.norm().detach().cpu().item()) <= eps:
            direction = fallback_dir
        return unit_vec(direction) * basis_scale

    prior_target = scaled_target(prior_target_raw, prior_fallback_dir, source_delta_basis)
    evidence_target = scaled_target(evidence_target_raw, transfer_dir, evidence_delta_basis)

    def ridge_path_coefficients(basis: torch.Tensor, target: torch.Tensor) -> tuple[torch.Tensor, bool, int]:
        coeff = torch.ones(num_heads, device=h.device, dtype=torch.float32)
        path_norm = basis.norm(dim=-1)
        active = path_norm > eps
        active_count = int(active.detach().cpu().sum().item())
        if active_count <= 0 or float(target.norm().detach().cpu().item()) <= eps:
            return coeff, False, active_count
        active_basis = basis[active]
        gram = active_basis @ active_basis.t()
        diag = torch.diag(gram)
        ridge = 0.05 * diag.mean().clamp_min(eps)
        eye = torch.eye(active_count, device=h.device, dtype=torch.float32)
        prior = torch.ones(active_count, device=h.device, dtype=torch.float32)
        rhs = active_basis @ target + ridge * prior
        solved = True
        try:
            raw = torch.linalg.solve(gram + ridge * eye, rhs)
        except RuntimeError:
            solved = False
            raw = torch.linalg.pinv(gram + ridge * eye) @ rhs
        if not bool(torch.isfinite(raw).all().detach().cpu().item()):
            return coeff, False, active_count
        coeff[active] = raw.clamp(0.0, max_weight)
        return coeff, solved, active_count

    def target_alignment(basis: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
        target_unit = unit_vec(target)
        path_norm = basis.norm(dim=-1).clamp_min(eps)
        return ((basis @ target_unit) / path_norm).clamp_min(0.0)

    def normalize_factor(values: torch.Tensor, *, floor: float = 0.0) -> torch.Tensor:
        clean = torch.nan_to_num(values.detach().float().to(device=h.device), nan=0.0, posinf=max_weight, neginf=0.0)
        clean = clean.clamp_min(float(floor))
        mean = clean.mean().clamp_min(eps)
        if not bool(torch.isfinite(mean).detach().cpu().item()) or float(mean.detach().cpu().item()) <= eps:
            return torch.ones(num_heads, device=h.device, dtype=torch.float32)
        return (clean / mean).clamp(0.0, max_weight)

    def answer_factor(scores: torch.Tensor | None) -> tuple[torch.Tensor, torch.Tensor | None]:
        if scores is None:
            return torch.ones(num_heads, device=h.device, dtype=torch.float32), None
        score = scores.detach().float().to(device=h.device)
        if int(score.numel()) != num_heads:
            raise ValueError(
                "answer-path scores must have one value per head "
                f"({int(score.numel())} != {num_heads})"
            )
        raw = 0.25 + 0.75 * torch.sigmoid(score / answer_temperature)
        return normalize_factor(raw), score

    source_solver_coeff, source_solver_ok, source_active_count = ridge_path_coefficients(
        source_delta_basis,
        prior_target,
    )
    evidence_solver_coeff, evidence_solver_ok, evidence_active_count = ridge_path_coefficients(
        evidence_delta_basis,
        evidence_target,
    )
    source_answer_weight, source_answer_scores = answer_factor(source_current_over_candidate)
    evidence_answer_weight, evidence_answer_scores = answer_factor(evidence_candidate_over_current)

    source_align_weight = normalize_factor(0.10 + 0.90 * target_alignment(source_delta_basis, prior_target))
    evidence_align_weight = normalize_factor(0.10 + 0.90 * target_alignment(evidence_delta_basis, evidence_target))
    source_mass_weight = normalize_factor(torch.sqrt(src_mass.clamp_min(0.0) + eps))
    evidence_mass_weight = normalize_factor(torch.sqrt(evi_mass.clamp_min(0.0) + eps))
    source_solver_weight = normalize_factor(0.10 + source_solver_coeff.clamp_min(0.0))
    evidence_solver_weight = normalize_factor(0.10 + evidence_solver_coeff.clamp_min(0.0))

    source_path_weight = normalize_factor(
        source_solver_weight * source_align_weight * source_answer_weight * source_mass_weight
    )
    evidence_path_weight = normalize_factor(
        evidence_solver_weight * evidence_align_weight * evidence_answer_weight * evidence_mass_weight
    )

    def global_trust_scale(
        *,
        target_raw: torch.Tensor,
        projected_delta: torch.Tensor,
        strength: float,
    ) -> float:
        if float(strength) <= eps:
            return 1.0
        target_l2 = float((float(strength) * target_raw).norm().detach().cpu().item())
        projected_l2 = float(projected_delta.norm().detach().cpu().item())
        if target_l2 <= eps or projected_l2 <= eps:
            return 1.0
        return max(0.25, min(4.0, target_l2 / projected_l2))

    pre_projected_prior_delta = (
        -beta_value * source_path_weight.view(1, num_heads, 1) * source_hidden
    ).sum(dim=1).mean(dim=0)
    pre_projected_evidence_delta = (
        alpha_value * evidence_path_weight.view(1, num_heads, 1) * evidence_hidden
    ).sum(dim=1).mean(dim=0)
    source_global_scale = global_trust_scale(
        target_raw=prior_target_raw,
        projected_delta=pre_projected_prior_delta,
        strength=beta_value,
    )
    evidence_global_scale = global_trust_scale(
        target_raw=evidence_target_raw,
        projected_delta=pre_projected_evidence_delta,
        strength=alpha_value,
    )
    source_path_weight = source_path_weight * float(source_global_scale)
    evidence_path_weight = evidence_path_weight * float(evidence_global_scale)

    prior_delta = -beta_value * source_path_weight.view(1, num_heads, 1, 1) * source
    evidence_delta = alpha_value * evidence_path_weight.view(1, num_heads, 1, 1) * evidence
    delta = prior_delta + evidence_delta
    patched = h + delta

    with torch.no_grad():
        projected_prior_delta = (
            -beta_value * source_path_weight.view(1, num_heads, 1) * source_hidden
        ).sum(dim=1).mean(dim=0)
        projected_evidence_delta = (
            alpha_value * evidence_path_weight.view(1, num_heads, 1) * evidence_hidden
        ).sum(dim=1).mean(dim=0)
        projected_total_delta = projected_prior_delta + projected_evidence_delta

        def cos_to(delta_vec: torch.Tensor, target: torch.Tensor) -> float | None:
            denom = delta_vec.norm() * target.norm()
            if float(denom.detach().cpu().item()) <= eps:
                return None
            return float((torch.dot(delta_vec, target) / denom.clamp_min(eps)).detach().cpu().item())

        source_norm = source.norm(dim=-1, keepdim=True)
        evidence_norm = evidence.norm(dim=-1, keepdim=True)
        valid_source = source_norm > eps
        valid_evidence = evidence_norm > eps
        prior_heads = torch.nonzero((source_path_weight >= evidence_path_weight).detach().cpu(), as_tuple=False).flatten()
        evidence_heads = torch.nonzero((evidence_path_weight > source_path_weight).detach().cpu(), as_tuple=False).flatten()

    def mean_value(values: torch.Tensor) -> float:
        return float(values.detach().float().mean().cpu().item())

    def min_value(values: torch.Tensor) -> float:
        return float(values.detach().float().min().cpu().item())

    def max_value(values: torch.Tensor) -> float:
        return float(values.detach().float().max().cpu().item())

    return {
        "patched_head_output": patched,
        "delta": delta,
        "residual_guided_path_answer_temperature": float(answer_temperature),
        "residual_guided_path_source_active_head_count": int(source_active_count),
        "residual_guided_path_evidence_active_head_count": int(evidence_active_count),
        "residual_guided_path_source_solver_ok": bool(source_solver_ok),
        "residual_guided_path_evidence_solver_ok": bool(evidence_solver_ok),
        "residual_guided_path_prior_target_l2": float(prior_target.norm().detach().cpu().item()),
        "residual_guided_path_evidence_target_l2": float(evidence_target.norm().detach().cpu().item()),
        "residual_guided_path_actual_prior_target_l2": float((beta_value * prior_target_raw).norm().detach().cpu().item()),
        "residual_guided_path_actual_evidence_target_l2": float(
            (alpha_value * evidence_target_raw).norm().detach().cpu().item()
        ),
        "residual_guided_path_prior_scalar": float(prior_scalar.detach().cpu().item()),
        "residual_guided_path_source_global_scale": float(source_global_scale),
        "residual_guided_path_evidence_global_scale": float(evidence_global_scale),
        "residual_guided_path_source_fit_cos": cos_to(projected_prior_delta, prior_target),
        "residual_guided_path_evidence_fit_cos": cos_to(projected_evidence_delta, evidence_target),
        "residual_guided_path_total_fit_cos": cos_to(projected_total_delta, prior_target + evidence_target),
        "residual_guided_path_source_solver_weight_mean": mean_value(source_solver_weight),
        "residual_guided_path_evidence_solver_weight_mean": mean_value(evidence_solver_weight),
        "residual_guided_path_source_align_weight_mean": mean_value(source_align_weight),
        "residual_guided_path_evidence_align_weight_mean": mean_value(evidence_align_weight),
        "residual_guided_path_source_mass_weight_mean": mean_value(source_mass_weight),
        "residual_guided_path_evidence_mass_weight_mean": mean_value(evidence_mass_weight),
        "residual_guided_path_source_answer_weight_mean": mean_value(source_answer_weight),
        "residual_guided_path_evidence_answer_weight_mean": mean_value(evidence_answer_weight),
        "residual_guided_path_source_path_weight_mean": mean_value(source_path_weight),
        "residual_guided_path_source_path_weight_min": min_value(source_path_weight),
        "residual_guided_path_source_path_weight_max": max_value(source_path_weight),
        "residual_guided_path_evidence_path_weight_mean": mean_value(evidence_path_weight),
        "residual_guided_path_evidence_path_weight_min": min_value(evidence_path_weight),
        "residual_guided_path_evidence_path_weight_max": max_value(evidence_path_weight),
        "residual_guided_path_prior_dominant_head_count": int(prior_heads.numel()),
        "residual_guided_path_evidence_dominant_head_count": int(evidence_heads.numel()),
        "residual_guided_path_prior_dominant_heads": [int(x) for x in prior_heads.tolist()],
        "residual_guided_path_evidence_dominant_heads": [int(x) for x in evidence_heads.tolist()],
        "residual_guided_path_source_current_over_candidate_mean": (
            float(source_answer_scores.mean().detach().cpu().item())
            if source_answer_scores is not None
            else None
        ),
        "residual_guided_path_evidence_candidate_over_current_mean": (
            float(evidence_answer_scores.mean().detach().cpu().item())
            if evidence_answer_scores is not None
            else None
        ),
        "residual_guided_path_source_component_l2": float(source.norm().detach().cpu().item()),
        "residual_guided_path_evidence_component_l2": float(evidence.norm().detach().cpu().item()),
        "residual_guided_path_projected_prior_delta_l2": float(projected_prior_delta.norm().detach().cpu().item()),
        "residual_guided_path_projected_evidence_delta_l2": float(projected_evidence_delta.norm().detach().cpu().item()),
        "residual_guided_path_projected_total_delta_l2": float(projected_total_delta.norm().detach().cpu().item()),
        "head_transport_delta_l2": float(delta.norm().detach().cpu().item()),
        "head_transport_prior_delta_l2": float(prior_delta.norm().detach().cpu().item()),
        "head_transport_transport_delta_l2": float(evidence_delta.norm().detach().cpu().item()),
        "head_transport_compensation_delta_l2": 0.0,
        "head_transport_alpha_ratio": float(alpha_value),
        "head_transport_u_p_abs_cos": abs(float(torch.dot(e_dir, p_dir).detach().cpu().item())),
        "head_transport_valid_prior_ratio": float(valid_source.float().mean().detach().cpu().item()),
        "head_transport_valid_evidence_ratio": float(valid_evidence.float().mean().detach().cpu().item()),
    }


def _carrier_trust_region_path_edit_output(
    *,
    original_head_output: torch.Tensor,
    source_contribution: torch.Tensor,
    evidence_contribution: torch.Tensor,
    source_mass: torch.Tensor,
    evidence_mass: torch.Tensor,
    source_prior_alignment: torch.Tensor,
    evidence_carrier_alignment: torch.Tensor,
    beta_for_layer: float,
    alpha_for_layer: float,
    alpha_mode: str,
    source_current_over_candidate: torch.Tensor | None = None,
    evidence_candidate_over_current: torch.Tensor | None = None,
    kappa: float = 0.6,
    lambda_prior: float = 0.3,
    lambda_n_max: float = 4.0,
    lambda_p_max: float = 4.0,
    vcr_floor: float = 0.05,
    pcr_ceiling: float = 0.95,
    pcr_threshold: float = 0.02,
    blend_tau: float = 0.7,
    norm_preserve: bool = True,
    norm_beta: float = 0.5,
) -> dict[str, Any]:
    """Closed-form token/head path editing under evidence/prior carriers.

    This is the token-head analogue of HulluEdit's U/P/R edit: each head path is
    decomposed into evidence-aligned, prior-aligned, and residual components.
    AllPath/SPIN-style path scores decide how much trust-region contraction is
    applied per head; evidence-aligned components are preserved rather than
    removed by a hard orthogonal projection.
    """
    h = original_head_output.float()
    source = source_contribution.float().to(device=h.device)
    evidence = evidence_contribution.float().to(device=h.device)
    num_heads = int(h.shape[1])
    if int(source.shape[1]) != num_heads or int(evidence.shape[1]) != num_heads:
        raise ValueError(
            "carrier trust-region path edit expects source/evidence contributions "
            f"for all heads, got source={tuple(source.shape)} evidence={tuple(evidence.shape)} "
            f"head_output={tuple(h.shape)}"
        )

    src_mass = source_mass.detach().float().to(device=h.device)
    evi_mass = evidence_mass.detach().float().to(device=h.device)
    prior_align = source_prior_alignment.detach().float().to(device=h.device).clamp(0.0, 1.0)
    evidence_align = evidence_carrier_alignment.detach().float().to(device=h.device).clamp(0.0, 1.0)
    for name, scores in {
        "source_mass": src_mass,
        "evidence_mass": evi_mass,
        "source_prior_alignment": prior_align,
        "evidence_carrier_alignment": evidence_align,
    }.items():
        if int(scores.numel()) != num_heads:
            raise ValueError(f"{name} must have one score per head ({int(scores.numel())} != {num_heads})")

    beta_value = max(0.0, float(beta_for_layer))
    alpha_value = max(0.0, float(alpha_for_layer)) if safe_text(alpha_mode) == "evidence_value_boost" else 0.0
    answer_temperature = 0.001
    source_answer_weight = torch.ones(num_heads, device=h.device, dtype=torch.float32)
    evidence_answer_weight = torch.ones(num_heads, device=h.device, dtype=torch.float32)
    source_answer_scores = None
    evidence_answer_scores = None
    if source_current_over_candidate is not None:
        source_answer_scores = source_current_over_candidate.detach().float().to(device=h.device)
        if int(source_answer_scores.numel()) != num_heads:
            raise ValueError(
                "source_current_over_candidate must have one score per head "
                f"({int(source_answer_scores.numel())} != {num_heads})"
            )
        source_answer_weight = torch.sigmoid(source_answer_scores / answer_temperature)
    if evidence_candidate_over_current is not None:
        evidence_answer_scores = evidence_candidate_over_current.detach().float().to(device=h.device)
        if int(evidence_answer_scores.numel()) != num_heads:
            raise ValueError(
                "evidence_candidate_over_current must have one score per head "
                f"({int(evidence_answer_scores.numel())} != {num_heads})"
            )
        evidence_answer_weight = torch.sigmoid(evidence_answer_scores / answer_temperature)

    prior_score = src_mass * prior_align * source_answer_weight
    evidence_score = evi_mass * evidence_align * evidence_answer_weight
    score_sum = prior_score + evidence_score
    active = score_sum > 1.0e-12
    prior_weight = torch.where(active, prior_score / score_sum.clamp_min(1.0e-12), torch.zeros_like(prior_score))
    evidence_weight = torch.where(
        active,
        evidence_score / score_sum.clamp_min(1.0e-12),
        torch.zeros_like(evidence_score),
    )

    eps = 1.0e-12

    def dot(a: torch.Tensor, b: torch.Tensor) -> torch.Tensor:
        return torch.sum(a * b, dim=-1, keepdim=True)

    evidence_norm = evidence.norm(dim=-1, keepdim=True)
    source_norm = source.norm(dim=-1, keepdim=True)
    u_dir = torch.where(evidence_norm > eps, evidence / evidence_norm.clamp_min(eps), torch.zeros_like(evidence))
    p_raw = source
    p_orth = p_raw - dot(p_raw, u_dir) * u_dir
    p_orth_norm = p_orth.norm(dim=-1, keepdim=True)
    p_raw_dir = torch.where(source_norm > eps, p_raw / source_norm.clamp_min(eps), torch.zeros_like(p_raw))
    p_dir = torch.where(p_orth_norm > eps, p_orth / p_orth_norm.clamp_min(eps), p_raw_dir)

    h_u = dot(h, u_dir) * u_dir
    h_p = dot(h, p_dir) * p_dir
    h_r = h - h_u - h_p
    h_norm_sq = (h * h).sum(dim=-1, keepdim=True).clamp_min(eps)
    vcr_raw = ((h_u * h_u).sum(dim=-1, keepdim=True) / h_norm_sq).clamp(0.0, 1.0)
    pcr_raw = ((h_p * h_p).sum(dim=-1, keepdim=True) / h_norm_sq).clamp(0.0, 1.0)
    vcr = vcr_raw.clamp(min=max(0.0, float(vcr_floor)), max=1.0)
    pcr = pcr_raw.clamp(min=0.0, max=max(0.0, min(1.0, float(pcr_ceiling))))

    prior_conf = prior_weight.view(1, num_heads, 1, 1)
    evidence_conf = evidence_weight.view(1, num_heads, 1, 1)
    lambda_n = max(0.0, float(kappa)) * beta_value * prior_conf * (1.0 - vcr) / vcr.clamp_min(eps)
    lambda_p = beta_value * (1.0 + max(0.0, float(lambda_prior))) * prior_conf * pcr / (1.0 - pcr).clamp_min(eps)
    lambda_p = torch.where(pcr >= max(0.0, float(pcr_threshold)), lambda_p, torch.zeros_like(lambda_p))
    lambda_n = lambda_n.clamp(min=0.0, max=max(0.0, float(lambda_n_max)))
    lambda_p = lambda_p.clamp(min=0.0, max=max(0.0, float(lambda_p_max)))

    u_gain = alpha_value * evidence_conf * (1.0 - vcr_raw).clamp(0.0, 1.0)
    prior_shrink_delta = h_p / (1.0 + lambda_n + lambda_p) - h_p
    residual_shrink_delta = h_r / (1.0 + lambda_n) - h_r
    evidence_lift_delta = u_gain * h_u
    edited = h + prior_shrink_delta + residual_shrink_delta + evidence_lift_delta
    pre_norm_edited = edited
    if bool(norm_preserve):
        edited_norm = torch.sqrt((edited * edited).sum(dim=-1, keepdim=True).clamp_min(eps))
        h_norm = torch.sqrt((h * h).sum(dim=-1, keepdim=True).clamp_min(eps))
        edited = edited * (h_norm / edited_norm).pow(max(0.0, float(norm_beta)))
    norm_restore_delta = edited - pre_norm_edited

    tau = max(0.0, min(1.0, float(blend_tau)))
    patched = (1.0 - tau) * h + tau * edited
    delta = patched - h

    with torch.no_grad():
        prior_before = dot(h, p_dir)
        prior_after = dot(patched, p_dir)
        evidence_before = dot(h, u_dir)
        evidence_after = dot(patched, u_dir)
        u_p_abs_cos = torch.abs(dot(u_dir, p_dir))
        valid_prior = source_norm > eps
        valid_evidence = evidence_norm > eps
        prior_heads = torch.nonzero((prior_weight > evidence_weight).detach().cpu(), as_tuple=False).flatten()
        evidence_heads = torch.nonzero((evidence_weight >= prior_weight).detach().cpu(), as_tuple=False).flatten()

    return {
        "patched_head_output": patched,
        "delta": delta,
        "carrier_trust_region_answer_temperature": float(answer_temperature),
        "carrier_trust_region_active_head_count": int(active.detach().cpu().sum().item()),
        "carrier_trust_region_prior_score_mean": float(prior_score.mean().detach().cpu().item()),
        "carrier_trust_region_prior_score_min": float(prior_score.min().detach().cpu().item()),
        "carrier_trust_region_prior_score_max": float(prior_score.max().detach().cpu().item()),
        "carrier_trust_region_evidence_score_mean": float(evidence_score.mean().detach().cpu().item()),
        "carrier_trust_region_evidence_score_min": float(evidence_score.min().detach().cpu().item()),
        "carrier_trust_region_evidence_score_max": float(evidence_score.max().detach().cpu().item()),
        "carrier_trust_region_prior_weight_mean": float(prior_weight.mean().detach().cpu().item()),
        "carrier_trust_region_prior_weight_min": float(prior_weight.min().detach().cpu().item()),
        "carrier_trust_region_prior_weight_max": float(prior_weight.max().detach().cpu().item()),
        "carrier_trust_region_evidence_weight_mean": float(evidence_weight.mean().detach().cpu().item()),
        "carrier_trust_region_evidence_weight_min": float(evidence_weight.min().detach().cpu().item()),
        "carrier_trust_region_evidence_weight_max": float(evidence_weight.max().detach().cpu().item()),
        "carrier_trust_region_source_prior_alignment_mean": float(prior_align.mean().detach().cpu().item()),
        "carrier_trust_region_evidence_alignment_mean": float(evidence_align.mean().detach().cpu().item()),
        "carrier_trust_region_prior_dominant_head_count": int(prior_heads.numel()),
        "carrier_trust_region_evidence_dominant_head_count": int(evidence_heads.numel()),
        "carrier_trust_region_prior_dominant_heads": [int(x) for x in prior_heads.tolist()],
        "carrier_trust_region_evidence_dominant_heads": [int(x) for x in evidence_heads.tolist()],
        "carrier_trust_region_vcr_mean": float(vcr.mean().detach().cpu().item()),
        "carrier_trust_region_pcr_mean": float(pcr.mean().detach().cpu().item()),
        "carrier_trust_region_lambda_n_mean": float(lambda_n.mean().detach().cpu().item()),
        "carrier_trust_region_lambda_p_mean": float(lambda_p.mean().detach().cpu().item()),
        "carrier_trust_region_u_gain_mean": float(u_gain.mean().detach().cpu().item()),
        "carrier_trust_region_blend_tau": float(tau),
        "carrier_trust_region_norm_preserve": bool(norm_preserve),
        "carrier_trust_region_norm_beta": float(norm_beta),
        "carrier_trust_region_source_current_over_candidate_mean": (
            float(source_answer_scores.mean().detach().cpu().item())
            if source_answer_scores is not None
            else None
        ),
        "carrier_trust_region_evidence_candidate_over_current_mean": (
            float(evidence_answer_scores.mean().detach().cpu().item())
            if evidence_answer_scores is not None
            else None
        ),
        "carrier_trust_region_source_component_l2": float(source.norm().detach().cpu().item()),
        "carrier_trust_region_evidence_component_l2": float(evidence.norm().detach().cpu().item()),
        "head_transport_prior_abs_before": float(torch.abs(prior_before).mean().detach().cpu().item()),
        "head_transport_prior_abs_after": float(torch.abs(prior_after).mean().detach().cpu().item()),
        "head_transport_prior_reduction_abs": float(
            (torch.abs(prior_before) - torch.abs(prior_after)).mean().detach().cpu().item()
        ),
        "head_transport_evidence_before": float(evidence_before.mean().detach().cpu().item()),
        "head_transport_evidence_after": float(evidence_after.mean().detach().cpu().item()),
        "head_transport_evidence_gain": float((evidence_after - evidence_before).mean().detach().cpu().item()),
        "head_transport_prior_delta_l2": float((tau * prior_shrink_delta).norm().detach().cpu().item()),
        "head_transport_residual_delta_l2": float((tau * residual_shrink_delta).norm().detach().cpu().item()),
        "head_transport_transport_delta_l2": float((tau * evidence_lift_delta).norm().detach().cpu().item()),
        "head_transport_compensation_delta_l2": float((tau * norm_restore_delta).norm().detach().cpu().item()),
        "head_transport_delta_l2": float(delta.norm().detach().cpu().item()),
        "head_transport_alpha_ratio": float(alpha_value),
        "head_transport_u_p_abs_cos": float(u_p_abs_cos.mean().detach().cpu().item()),
        "head_transport_valid_prior_ratio": float(valid_prior.float().mean().detach().cpu().item()),
        "head_transport_valid_evidence_ratio": float(valid_evidence.float().mean().detach().cpu().item()),
    }


def _orthogonalize_head_contribution(source: torch.Tensor, evidence: torch.Tensor) -> torch.Tensor:
    # source/evidence: [B, H, 1, D]
    denom = torch.sum(evidence.float() * evidence.float(), dim=-1, keepdim=True).clamp_min(1.0e-12)
    coeff = torch.sum(source.float() * evidence.float(), dim=-1, keepdim=True) / denom
    projection = coeff * evidence.float()
    tiny = torch.sum(evidence.float() * evidence.float(), dim=-1, keepdim=True) <= 1.0e-12
    return torch.where(tiny, source.float(), source.float() - projection)


def _head_subspace_transport_delta(
    *,
    head_output: torch.Tensor,
    source_contribution: torch.Tensor,
    evidence_contribution: torch.Tensor,
    beta_for_layer: float,
    transport_alpha_ratio: float,
) -> dict[str, Any]:
    """Head-local U/P transport instead of plain orthogonal subtraction.

    Source and evidence value paths define a local prior carrier P and evidence
    carrier U. The update shrinks the head output along P, transports a bounded
    amount of removed prior mass to U, and compensates any U-projection drop.
    """
    h = head_output.float()
    source = source_contribution.float()
    evidence = evidence_contribution.float()

    def dot(a: torch.Tensor, b: torch.Tensor) -> torch.Tensor:
        return torch.sum(a * b, dim=-1, keepdim=True)

    eps = 1.0e-12
    e_norm = evidence.norm(dim=-1, keepdim=True)
    e_dir = torch.where(e_norm > eps, evidence / e_norm.clamp_min(eps), torch.zeros_like(evidence))
    p_raw = source
    p_orth = p_raw - dot(p_raw, e_dir) * e_dir
    p_orth_norm = p_orth.norm(dim=-1, keepdim=True)
    p_raw_norm = p_raw.norm(dim=-1, keepdim=True)
    p_raw_dir = torch.where(p_raw_norm > eps, p_raw / p_raw_norm.clamp_min(eps), torch.zeros_like(p_raw))
    p_dir = torch.where(p_orth_norm > eps, p_orth / p_orth_norm.clamp_min(eps), p_raw_dir)

    beta_value = max(0.0, float(beta_for_layer))
    alpha_value = min(1.0, max(0.0, float(transport_alpha_ratio)))
    prior_before = dot(h, p_dir)
    evidence_before = dot(h, e_dir)
    prior_delta = -beta_value * prior_before * p_dir
    removed_prior_mass = torch.abs(beta_value * prior_before)
    transport_delta = alpha_value * removed_prior_mass * e_dir
    raw_delta = prior_delta + transport_delta
    evidence_change = dot(raw_delta, e_dir)
    compensation_delta = torch.clamp(-evidence_change, min=0.0) * e_dir
    delta = raw_delta + compensation_delta
    updated = h + delta
    prior_after = dot(updated, p_dir)
    evidence_after = dot(updated, e_dir)
    u_p_abs_cos = torch.abs(dot(e_dir, p_dir))
    return {
        "delta": delta,
        "head_transport_prior_abs_before": float(torch.abs(prior_before).mean().detach().cpu().item()),
        "head_transport_prior_abs_after": float(torch.abs(prior_after).mean().detach().cpu().item()),
        "head_transport_prior_reduction_abs": float(
            (torch.abs(prior_before) - torch.abs(prior_after)).mean().detach().cpu().item()
        ),
        "head_transport_evidence_before": float(evidence_before.mean().detach().cpu().item()),
        "head_transport_evidence_after": float(evidence_after.mean().detach().cpu().item()),
        "head_transport_evidence_gain": float((evidence_after - evidence_before).mean().detach().cpu().item()),
        "head_transport_prior_delta_l2": float(prior_delta.norm().detach().cpu().item()),
        "head_transport_transport_delta_l2": float(transport_delta.norm().detach().cpu().item()),
        "head_transport_compensation_delta_l2": float(compensation_delta.norm().detach().cpu().item()),
        "head_transport_delta_l2": float(delta.norm().detach().cpu().item()),
        "head_transport_alpha_ratio": float(alpha_value),
        "head_transport_u_p_abs_cos": float(u_p_abs_cos.mean().detach().cpu().item()),
        "head_transport_valid_prior_ratio": float((p_raw_norm > eps).float().mean().detach().cpu().item()),
        "head_transport_valid_evidence_ratio": float((e_norm > eps).float().mean().detach().cpu().item()),
    }


def _token_head_alpha_weights_for_policy(
    *,
    policy: str,
    operator: str,
    layers: Sequence[int],
    layer_weights: Mapping[int, float],
    evidence_layer_weights: Mapping[int, float],
    prior_layer_weights: Mapping[int, float],
) -> dict[int, float]:
    resolved = safe_text(policy)
    if resolved == "auto":
        resolved = "match_layer_group" if safe_text(operator) == "head_subspace_transport" else "match_evidence"
    if resolved == "match_prior":
        source = prior_layer_weights
    elif resolved == "match_evidence":
        source = evidence_layer_weights
    elif resolved == "match_layer_group":
        source = layer_weights
    elif resolved == "uniform":
        return {int(layer): 1.0 / float(len(layers)) for layer in layers}
    else:
        raise ValueError(f"unknown token_head_alpha_layer_policy: {policy}")
    total = sum(float(source.get(int(layer), 0.0)) for layer in layers)
    if total <= 0.0:
        raise ValueError(f"token-head alpha policy {policy} has no positive layer weights in group {list(layers)}")
    return {int(layer): float(source.get(int(layer), 0.0)) / total for layer in layers}


def _masked_value_contribution(
    row: torch.Tensor,
    values: torch.Tensor,
    positions: torch.Tensor,
) -> torch.Tensor:
    if positions.numel() <= 0:
        return torch.zeros(
            row.shape[0],
            row.shape[1],
            1,
            values.shape[-1],
            device=row.device,
            dtype=torch.float32,
        )
    pos = positions.to(device=row.device)
    weights = row[:, :, pos].unsqueeze(2).float()
    vals = values[:, :, pos, :].float()
    return torch.matmul(weights, vals)


def _attention_token_selection_mask(
    row: torch.Tensor,
    positions: torch.Tensor,
    *,
    mode: str,
    top_k: int,
    min_attn: float,
) -> tuple[torch.Tensor, dict[str, Any]]:
    # row: [B, H, S]. The returned mask has the same [B, H, S] shape so
    # attention_topk_per_head can keep different source tokens for each head.
    batch, heads, seq_len = int(row.shape[0]), int(row.shape[1]), int(row.shape[2])
    mask = torch.zeros((batch, heads, seq_len), device=row.device, dtype=torch.bool)
    if positions.numel() <= 0:
        return mask, {
            "token_selection_mode": safe_text(mode),
            "token_top_k": int(top_k),
            "token_min_attn": float(min_attn),
            "token_count_original": 0,
            "token_count_selected_unique": 0,
            "token_count_selected_mean_per_head": 0.0,
        }
    pos = positions.to(device=row.device, dtype=torch.long)
    key = safe_text(mode).lower()
    k = int(top_k)
    threshold = max(0.0, float(min_attn))
    if key == "all" or k <= 0 or k >= int(pos.numel()):
        mask[:, :, pos] = True
    elif key == "attention_topk_global":
        scores = row[:, :, pos].float().mean(dim=(0, 1))
        eligible_scores = scores.masked_fill(scores < threshold, float("-inf"))
        take = min(k, int(pos.numel()))
        values, indices = torch.topk(eligible_scores, k=take, dim=-1)
        valid = torch.isfinite(values)
        if valid.any():
            selected_pos = pos[indices[valid]]
            mask[:, :, selected_pos] = True
    elif key == "attention_topk_per_head":
        scores = row[:, :, pos].float()
        eligible_scores = scores.masked_fill(scores < threshold, float("-inf"))
        take = min(k, int(pos.numel()))
        values, indices = torch.topk(eligible_scores, k=take, dim=-1)
        valid = torch.isfinite(values)
        selected = torch.zeros_like(scores, dtype=torch.bool)
        selected.scatter_(-1, indices, valid)
        expanded_pos = pos.view(1, 1, -1).expand(batch, heads, -1)
        mask.scatter_(-1, expanded_pos, selected)
    else:
        raise ValueError(f"unsupported token selection mode: {mode}")

    selected_counts = mask.float().sum(dim=-1)
    unique_count = int(mask.any(dim=(0, 1)).sum().detach().cpu().item())
    return mask, {
        "token_selection_mode": key,
        "token_top_k": int(k),
        "token_min_attn": float(threshold),
        "token_count_original": int(pos.numel()),
        "token_count_selected_unique": unique_count,
        "token_count_selected_mean_per_head": float(selected_counts.mean().detach().cpu().item()),
        "token_count_selected_min_per_head": float(selected_counts.min().detach().cpu().item()),
        "token_count_selected_max_per_head": float(selected_counts.max().detach().cpu().item()),
    }


def _answer_effect_token_selection_mask(
    row: torch.Tensor,
    values: torch.Tensor,
    positions: torch.Tensor,
    *,
    module: torch.nn.Module,
    lm_head: torch.nn.Module,
    yes_id: int,
    no_id: int,
    positive_answer: str | None,
    negative_answer: str | None,
    mode: str,
    top_k: int,
    min_attn: float,
) -> tuple[torch.Tensor, torch.Tensor, dict[str, Any]]:
    # Select token-head paths by direct logit effect instead of attention mass.
    batch, heads, seq_len = int(row.shape[0]), int(row.shape[1]), int(row.shape[2])
    mask = torch.zeros((batch, heads, seq_len), device=row.device, dtype=torch.bool)
    gate = torch.zeros((batch, heads, seq_len), device=row.device, dtype=torch.float32)
    pos = positions.detach().long()
    pos = pos[(pos >= 0) & (pos < seq_len)].unique(sorted=True)
    key = safe_text(mode).lower()
    raw_key = key
    if key == "unsupported_answer_effect_soft_topk_per_head":
        key = "answer_effect_soft_topk_per_head"
    elif key == "unsupported_answer_effect_soft_positive":
        key = "answer_effect_soft_positive"
    if pos.numel() <= 0:
        return mask, gate, {
            "token_selection_mode": raw_key,
            "token_selection_base_mode": key,
            "token_selection_family": "answer_effect",
            "token_top_k": int(top_k),
            "token_min_attn": float(min_attn),
            "token_count_original": 0,
            "token_count_selected_unique": 0,
            "token_count_selected_mean_per_head": 0.0,
            "answer_effect_available": False,
            "answer_effect_fallback_reason": "empty_positions",
        }
    axis = _head_binary_axis_vectors(
        module=module,
        lm_head=lm_head,
        yes_id=yes_id,
        no_id=no_id,
        positive_answer=positive_answer,
        negative_answer=negative_answer,
        num_heads=heads,
    )
    if axis is None:
        return mask, gate, {
            "token_selection_mode": raw_key,
            "token_selection_base_mode": key,
            "token_selection_family": "answer_effect",
            "token_top_k": int(top_k),
            "token_min_attn": float(min_attn),
            "token_count_original": int(pos.numel()),
            "token_count_selected_unique": 0,
            "token_count_selected_mean_per_head": 0.0,
            "answer_effect_available": False,
            "answer_effect_fallback_reason": "missing_answer_axis",
        }
    pos_dev = pos.to(device=row.device)
    axis = axis.to(device=row.device, dtype=torch.float32)
    weights = row[:, :, pos_dev].float()
    token_values = values[:, :, pos_dev, :].float()
    token_effect = (weights.unsqueeze(-1) * token_values * axis).sum(dim=-1)
    effect_score = token_effect.mean(dim=0).detach().float()  # [H, T]
    attn_score = weights.mean(dim=0).detach().float()
    eligible = (effect_score > 0.0) & (attn_score >= max(0.0, float(min_attn)))
    k = int(top_k)
    topk_modes = {"answer_effect_topk_per_head", "answer_effect_soft_topk_per_head"}
    positive_modes = {"answer_effect_topk_per_head", "answer_effect_positive"}
    soft_modes = {"answer_effect_soft_topk_per_head", "answer_effect_soft_positive"}
    if key in topk_modes and k > 0 and k < int(pos.numel()):
        masked_score = effect_score.masked_fill(~eligible, float("-inf"))
        values_topk, indices = torch.topk(masked_score, k=min(k, int(pos.numel())), dim=-1)
        valid = torch.isfinite(values_topk)
        selected = torch.zeros_like(eligible)
        selected.scatter_(-1, indices, valid)
    elif key in positive_modes or key in soft_modes:
        selected = eligible
    else:
        raise ValueError(f"unsupported answer-effect token selection mode: {mode}")
    selected_float = selected.float()
    if key in soft_modes:
        positive_score = effect_score.clamp_min(0.0) * selected_float
        normalizer = positive_score.max(dim=-1, keepdim=True).values.clamp_min(1.0e-12)
        local_gate = (positive_score / normalizer).clamp(0.0, 1.0)
    else:
        local_gate = selected_float
    if selected.any():
        expanded_pos = pos_dev.view(1, 1, -1).expand(batch, heads, -1)
        selected_batch = selected.view(1, heads, -1).expand(batch, heads, -1)
        mask.scatter_(-1, expanded_pos, selected_batch)
        gate_batch = local_gate.view(1, heads, -1).expand(batch, heads, -1)
        gate.scatter_(-1, expanded_pos, gate_batch)

    selected_counts = mask.float().sum(dim=-1)
    gate_sum = gate.float().sum(dim=-1)
    selected_effect = effect_score.masked_select(selected)
    positive_effect = effect_score.masked_select(eligible)
    selected_gate = local_gate.masked_select(selected)
    unique_count = int(mask.any(dim=(0, 1)).sum().detach().cpu().item())
    return mask, gate, {
        "token_selection_mode": raw_key,
        "token_selection_base_mode": key,
        "token_selection_family": "answer_effect",
        "token_top_k": int(k),
        "token_min_attn": float(max(0.0, float(min_attn))),
        "token_count_original": int(pos.numel()),
        "token_count_selected_unique": unique_count,
        "token_count_selected_mean_per_head": float(selected_counts.mean().detach().cpu().item()),
        "token_count_selected_min_per_head": float(selected_counts.min().detach().cpu().item()),
        "token_count_selected_max_per_head": float(selected_counts.max().detach().cpu().item()),
        "token_gate_sum_mean_per_head": float(gate_sum.mean().detach().cpu().item()),
        "token_gate_sum_min_per_head": float(gate_sum.min().detach().cpu().item()),
        "token_gate_sum_max_per_head": float(gate_sum.max().detach().cpu().item()),
        "answer_effect_available": True,
        "answer_effect_positive_token_count": int(eligible.sum().detach().cpu().item()),
        "answer_effect_selected_token_count": int(selected.sum().detach().cpu().item()),
        "answer_effect_soft_gate": bool(key in soft_modes),
        "answer_effect_gate_mean_selected": (
            float(selected_gate.mean().detach().cpu().item()) if selected_gate.numel() > 0 else None
        ),
        "answer_effect_gate_min_selected": (
            float(selected_gate.min().detach().cpu().item()) if selected_gate.numel() > 0 else None
        ),
        "answer_effect_gate_max_selected": (
            float(selected_gate.max().detach().cpu().item()) if selected_gate.numel() > 0 else None
        ),
        "answer_effect_mean_all": float(effect_score.mean().detach().cpu().item()),
        "answer_effect_max_all": float(effect_score.max().detach().cpu().item()),
        "answer_effect_mean_positive": (
            float(positive_effect.mean().detach().cpu().item()) if positive_effect.numel() > 0 else None
        ),
        "answer_effect_mean_selected": (
            float(selected_effect.mean().detach().cpu().item()) if selected_effect.numel() > 0 else None
        ),
        "answer_effect_axis_positive_answer": normalize_binary_label(positive_answer),
        "answer_effect_axis_negative_answer": normalize_binary_label(negative_answer),
        "answer_effect_fallback_reason": None,
    }


def _token_selection_mask_for_answer_path(
    row: torch.Tensor,
    values: torch.Tensor,
    positions: torch.Tensor,
    *,
    module: torch.nn.Module,
    lm_head: torch.nn.Module,
    yes_id: int,
    no_id: int,
    positive_answer: str | None,
    negative_answer: str | None,
    mode: str,
    top_k: int,
    min_attn: float,
) -> tuple[torch.Tensor, torch.Tensor, dict[str, Any]]:
    key = safe_text(mode).lower()
    if key in {
        "answer_effect_topk_per_head",
        "answer_effect_positive",
        "answer_effect_soft_topk_per_head",
        "answer_effect_soft_positive",
        "unsupported_answer_effect_soft_topk_per_head",
        "unsupported_answer_effect_soft_positive",
    }:
        return _answer_effect_token_selection_mask(
            row,
            values,
            positions,
            module=module,
            lm_head=lm_head,
            yes_id=yes_id,
            no_id=no_id,
            positive_answer=positive_answer,
            negative_answer=negative_answer,
            mode=key,
            top_k=top_k,
            min_attn=min_attn,
        )
    mask, debug = _attention_token_selection_mask(
        row,
        positions,
        mode=mode,
        top_k=top_k,
        min_attn=min_attn,
    )
    return mask, mask.float(), debug


def _hidden_token_patch_plan_from_gate(
    gate: torch.Tensor,
    selected_heads: torch.Tensor,
    *,
    seq_len: int,
    max_positions: int,
    exclude_final: bool = True,
) -> dict[str, Any]:
    if gate.numel() <= 0 or int(seq_len) <= 0 or selected_heads.numel() <= 0:
        return {
            "positions": [],
            "weights": [],
            "count": 0,
            "weight_mean": None,
            "weight_max": None,
            "weight_sum": 0.0,
        }
    heads = selected_heads.detach().to(device=gate.device, dtype=torch.long)
    heads = heads[(heads >= 0) & (heads < int(gate.shape[1]))]
    if heads.numel() <= 0:
        return {
            "positions": [],
            "weights": [],
            "count": 0,
            "weight_mean": None,
            "weight_max": None,
            "weight_sum": 0.0,
        }
    token_scores = gate[:, heads, :].detach().float().mean(dim=(0, 1))
    if exclude_final and int(token_scores.numel()) > 0:
        token_scores[-1] = 0.0
    active = torch.nonzero(token_scores > 0.0, as_tuple=False).flatten()
    if active.numel() <= 0:
        return {
            "positions": [],
            "weights": [],
            "count": 0,
            "weight_mean": None,
            "weight_max": None,
            "weight_sum": 0.0,
        }
    if int(max_positions) > 0 and int(active.numel()) > int(max_positions):
        active_scores = token_scores[active]
        _values, order = torch.topk(active_scores, k=int(max_positions), largest=True)
        active = active[order].sort().values
    weights = token_scores[active].clamp_min(0.0)
    max_weight = weights.max().clamp_min(1.0e-12)
    weights = (weights / max_weight).clamp(0.0, 1.0)
    weights_cpu = weights.detach().cpu()
    return {
        "positions": [int(x) for x in active.detach().cpu().tolist()],
        "weights": [float(x) for x in weights_cpu.tolist()],
        "count": int(active.numel()),
        "weight_mean": float(weights_cpu.mean().item()) if weights_cpu.numel() > 0 else None,
        "weight_max": float(weights_cpu.max().item()) if weights_cpu.numel() > 0 else None,
        "weight_sum": float(weights_cpu.sum().item()) if weights_cpu.numel() > 0 else 0.0,
    }


def _attenuate_source_gate_by_evidence_answer_support(
    row: torch.Tensor,
    values: torch.Tensor,
    support_positions: torch.Tensor,
    source_mask: torch.Tensor,
    source_gate: torch.Tensor,
    *,
    module: torch.nn.Module,
    lm_head: torch.nn.Module,
    yes_id: int,
    no_id: int,
    current_answer: str | None,
    candidate_answer: str | None,
    support_mode: str,
    top_k: int,
    min_attn: float,
) -> tuple[torch.Tensor, torch.Tensor, dict[str, Any]]:
    """Suppress only current-support paths that lack support from the support token set.

    The unsupported factor is continuous:
        candidate_support / (current_support + candidate_support).
    If neither side has support, the factor is zero, so no source path is removed
    without a competing path.
    """
    current_mask, current_gate, current_debug = _answer_effect_token_selection_mask(
        row,
        values,
        support_positions,
        module=module,
        lm_head=lm_head,
        yes_id=yes_id,
        no_id=no_id,
        positive_answer=current_answer,
        negative_answer=candidate_answer,
        mode=support_mode,
        top_k=top_k,
        min_attn=min_attn,
    )
    candidate_mask, candidate_gate, candidate_debug = _answer_effect_token_selection_mask(
        row,
        values,
        support_positions,
        module=module,
        lm_head=lm_head,
        yes_id=yes_id,
        no_id=no_id,
        positive_answer=candidate_answer,
        negative_answer=current_answer,
        mode=support_mode,
        top_k=top_k,
        min_attn=min_attn,
    )
    current_support = (row.float() * current_gate.float()).sum(dim=-1)
    candidate_support = (row.float() * candidate_gate.float()).sum(dim=-1)
    total_support = current_support + candidate_support
    eps = torch.tensor(1.0e-12, device=row.device, dtype=torch.float32)
    unsupported = torch.where(
        total_support > eps,
        candidate_support / total_support.clamp_min(float(eps.item())),
        torch.zeros_like(total_support),
    ).clamp(0.0, 1.0)
    attenuated_gate = source_gate.float() * unsupported.unsqueeze(-1)
    attenuated_mask = source_mask.bool() & (attenuated_gate > 1.0e-8)
    debug = {
        "unsupported_answer_effect_enabled": True,
        "unsupported_answer_effect_support_mode": safe_text(support_mode),
        "unsupported_answer_effect_current_support_mean": float(
            current_support.detach().float().mean().cpu().item()
        ),
        "unsupported_answer_effect_candidate_support_mean": float(
            candidate_support.detach().float().mean().cpu().item()
        ),
        "unsupported_answer_effect_factor_mean": float(
            unsupported.detach().float().mean().cpu().item()
        ),
        "unsupported_answer_effect_factor_min": float(
            unsupported.detach().float().min().cpu().item()
        ),
        "unsupported_answer_effect_factor_max": float(
            unsupported.detach().float().max().cpu().item()
        ),
        "unsupported_answer_effect_current_support_selected_token_count": int(
            current_mask.detach().bool().sum().cpu().item()
        ),
        "unsupported_answer_effect_candidate_support_selected_token_count": int(
            candidate_mask.detach().bool().sum().cpu().item()
        ),
        "unsupported_answer_effect_current_support_available": bool(
            current_debug.get("answer_effect_available")
        ),
        "unsupported_answer_effect_candidate_support_available": bool(
            candidate_debug.get("answer_effect_available")
        ),
        "unsupported_answer_effect_current_support_fallback_reason": current_debug.get(
            "answer_effect_fallback_reason"
        ),
        "unsupported_answer_effect_candidate_support_fallback_reason": candidate_debug.get(
            "answer_effect_fallback_reason"
        ),
        "unsupported_answer_effect_source_gate_sum_before_mean_per_head": float(
            source_gate.float().sum(dim=-1).detach().mean().cpu().item()
        ),
        "unsupported_answer_effect_source_gate_sum_after_mean_per_head": float(
            attenuated_gate.float().sum(dim=-1).detach().mean().cpu().item()
        ),
    }
    return attenuated_mask, attenuated_gate, debug


def _masked_value_contribution_from_mask(
    row: torch.Tensor,
    values: torch.Tensor,
    mask: torch.Tensor,
) -> torch.Tensor:
    if mask.numel() <= 0 or not bool(mask.any().detach().cpu().item()):
        return torch.zeros(
            row.shape[0],
            row.shape[1],
            1,
            values.shape[-1],
            device=row.device,
            dtype=torch.float32,
        )
    weights = (row.float() * mask.to(device=row.device).float()).unsqueeze(2)
    return torch.matmul(weights, values.float())


def _value_contribution_from_token_weights(
    weights: torch.Tensor,
    values: torch.Tensor,
) -> torch.Tensor:
    if weights.numel() <= 0 or not bool((weights.detach().float().sum() > 0.0).cpu().item()):
        return torch.zeros(
            weights.shape[0],
            weights.shape[1],
            1,
            values.shape[-1],
            device=weights.device,
            dtype=torch.float32,
        )
    return torch.matmul(weights.float().unsqueeze(2), values.float())


def _uniform_counterfactual_value_contribution_from_mask(
    row: torch.Tensor,
    values: torch.Tensor,
    mask: torch.Tensor,
) -> torch.Tensor:
    """Same-mass uniform attention counterfactual for a selected token group."""
    if mask.numel() <= 0 or not bool(mask.any().detach().cpu().item()):
        return torch.zeros(
            row.shape[0],
            row.shape[1],
            1,
            values.shape[-1],
            device=row.device,
            dtype=torch.float32,
        )
    group_mask = mask.to(device=row.device).float()
    original_mass = (row.float() * group_mask).sum(dim=-1, keepdim=True)
    group_count = group_mask.sum(dim=-1, keepdim=True).clamp_min(1.0)
    uniform_weights = group_mask * (original_mass / group_count)
    return torch.matmul(uniform_weights.unsqueeze(2), values.float())


def _compute_intragroup_reception_scores(
    module: torch.nn.Module,
    *,
    hidden_states: torch.Tensor,
    attention_mask: torch.Tensor | None,
    position_embeddings: Any,
    positions: torch.Tensor,
) -> torch.Tensor:
    """DALI/VisFlow-style intra-modal reception R(j) for selected token positions.

    R(j) is computed from attention rows whose query token is in the same group,
    while each row is still normalized over all keys. This avoids the incorrect
    shortcut of re-normalizing only inside the group.
    """
    pos = positions.detach().long().to(device=hidden_states.device)
    seq_len = int(hidden_states.shape[1])
    pos = pos[(pos >= 0) & (pos < seq_len)].unique(sorted=True)
    if int(pos.numel()) <= 1:
        return torch.zeros(int(pos.numel()), dtype=torch.float32)

    bsz, q_len, _ = hidden_states.size()
    query_states = module.q_proj(hidden_states)
    key_states = module.k_proj(hidden_states)

    query_states = query_states.view(bsz, q_len, -1, module.head_dim).transpose(1, 2)
    key_states = key_states.view(bsz, q_len, -1, module.head_dim).transpose(1, 2)

    cos, sin = position_embeddings
    query_states, key_states = apply_multimodal_rotary_pos_emb(
        query_states,
        key_states,
        cos,
        sin,
        module.rope_scaling["mrope_section"],
    )
    query_states = query_states.to(torch.float32)
    key_states = key_states.to(torch.float32)
    key_states = repeat_kv(key_states, module.num_key_value_groups)

    group_count = int(pos.numel())
    reception_sum = torch.zeros(group_count, device=hidden_states.device, dtype=torch.float32)
    chunk_size = 64
    key_t = key_states.transpose(2, 3)
    for start in range(0, group_count, chunk_size):
        end = min(group_count, start + chunk_size)
        query_pos = pos[start:end]
        query_group = query_states.index_select(2, query_pos)
        logits = torch.matmul(query_group, key_t) * float(module.scaling)
        if attention_mask is not None:
            logits = logits + attention_mask[:, :, query_pos, : key_states.shape[-2]]
        attn = torch.nn.functional.softmax(logits, dim=-1, dtype=torch.float32)
        group_attn = attn.index_select(-1, pos)
        same_token = query_pos.view(-1, 1) == pos.view(1, -1)
        group_attn = group_attn.masked_fill(same_token.view(1, 1, end - start, group_count), 0.0)
        reception_sum = reception_sum + group_attn.sum(dim=(0, 1, 2))
        del logits, attn, group_attn, query_group
    denom = float(max(1, int(query_states.shape[0]) * int(query_states.shape[1]) * (group_count - 1)))
    reception = reception_sum / denom
    return reception.detach().float().cpu()


def _oelpr_reception_path_decomposition(
    *,
    module: torch.nn.Module,
    lm_head: torch.nn.Module,
    yes_id: int,
    no_id: int,
    current_answer: str | None,
    candidate_answer: str | None,
    hidden_states: torch.Tensor,
    attention_mask: torch.Tensor | None,
    position_embeddings: Any,
    row: torch.Tensor,
    values: torch.Tensor,
    source_mask: torch.Tensor,
    evidence_mask: torch.Tensor,
    source_positions: torch.Tensor,
    evidence_positions: torch.Tensor,
    mode: str,
    head_indices: torch.Tensor | None = None,
) -> dict[str, Any]:
    """Split O-ELPR value paths with DALI/VisFlow token reception.

    Non-target source tokens are not treated uniformly as prior. Source tokens
    with high intra-modal reception but below the sink threshold are migrated to
    the evidence path; sink and residual source tokens remain suppressible prior.
    Target evidence tokens are redistributed with the same salient/sink
    thresholds and mass-preserving normalization.
    """
    device = row.device
    eps = 1.0e-12
    salient_tau = 1.0 / 20.0
    sink_tau = 1.0 / 2.0
    salient_scale = 10.0
    sink_scale = 0.4

    def token_sets(positions: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
        pos_cpu = positions.detach().cpu().long().unique(sorted=True)
        reception = _compute_intragroup_reception_scores(
            module,
            hidden_states=hidden_states,
            attention_mask=attention_mask,
            position_embeddings=position_embeddings,
            positions=pos_cpu,
        )
        salient = torch.empty(0, dtype=torch.long)
        sink = torch.empty(0, dtype=torch.long)
        if int(pos_cpu.numel()) > 0 and int(reception.numel()) == int(pos_cpu.numel()):
            max_reception = float(reception.max().item()) if int(reception.numel()) > 0 else 0.0
            if max_reception > eps:
                salient = pos_cpu[reception > float(salient_tau * max_reception)]
                sink = pos_cpu[reception > float(sink_tau * max_reception)]
        support = torch.tensor(
            sorted(set(int(x) for x in salient.tolist()) - set(int(x) for x in sink.tolist())),
            dtype=torch.long,
        )
        return pos_cpu, salient, sink, support

    mode_key = safe_text(mode) or "reception_path_decompose"
    if mode_key not in {"reception_evidence_reweight", "reception_path_decompose"}:
        raise ValueError(f"unknown O-ELPR reception path mode: {mode}")
    source_pos, source_salient, source_sink, source_support = token_sets(source_positions)
    evidence_pos, evidence_salient, evidence_sink, evidence_support = token_sets(evidence_positions)
    seq_len = int(row.shape[-1])

    def position_mask(positions: torch.Tensor) -> torch.Tensor:
        mask = torch.zeros(seq_len, device=device, dtype=torch.bool)
        if int(positions.numel()) > 0:
            valid = positions.to(device=device).long()
            valid = valid[(valid >= 0) & (valid < seq_len)]
            if int(valid.numel()) > 0:
                mask[valid] = True
        return mask

    if mode_key == "reception_path_decompose":
        source_support_token = position_mask(source_support)
    else:
        source_support = torch.empty(0, dtype=torch.long)
        source_support_token = torch.zeros(seq_len, device=device, dtype=torch.bool)
    source_prior_mask = source_mask.to(device=device).bool() & ~source_support_token.view(1, 1, -1)
    source_weights = row.float() * source_prior_mask.float()

    evidence_scale = torch.ones(seq_len, device=device, dtype=torch.float32)
    evidence_sink_token = position_mask(evidence_sink)
    evidence_support_token = position_mask(evidence_support)
    evidence_scale = torch.where(
        evidence_sink_token,
        torch.full_like(evidence_scale, float(sink_scale)),
        evidence_scale,
    )
    evidence_scale = torch.where(
        evidence_support_token,
        torch.full_like(evidence_scale, float(salient_scale)),
        evidence_scale,
    )
    evidence_base = row.float() * evidence_mask.to(device=device).float()
    evidence_scaled = evidence_base * evidence_scale.view(1, 1, -1)
    evidence_base_mass = evidence_base.sum(dim=-1, keepdim=True)
    evidence_scaled_mass = evidence_scaled.sum(dim=-1, keepdim=True)
    evidence_weights = torch.where(
        evidence_scaled_mass > eps,
        evidence_scaled * (evidence_base_mass / evidence_scaled_mass.clamp_min(eps)),
        evidence_base,
    )

    source_support_mask = source_mask.to(device=device).bool() & source_support_token.view(1, 1, -1)
    source_support_weights = row.float() * source_support_mask.float() * float(salient_scale)
    source_support_base_mass = (row.float() * source_support_mask.float()).sum(dim=-1, keepdim=True)
    source_support_mass = source_support_weights.sum(dim=-1, keepdim=True)
    source_support_weights = torch.where(
        source_support_mass > eps,
        source_support_weights * (source_support_base_mass / source_support_mass.clamp_min(eps)),
        source_support_weights,
    )
    source_support_contribution = _value_contribution_from_token_weights(source_support_weights, values)
    source_support_axis = _head_answer_contribution_scores(
        module=module,
        contribution=source_support_contribution,
        lm_head=lm_head,
        yes_id=yes_id,
        no_id=no_id,
        current_answer=current_answer,
        candidate_answer=candidate_answer,
        head_indices=head_indices,
    )
    if bool((source_support_weights.detach().float().sum() > eps).cpu().item()) and bool(
        source_support_axis.get("available")
    ):
        support_scores = source_support_axis["candidate_minus_current"].to(device=device, dtype=torch.float32)
        support_migration = torch.sigmoid(support_scores / 0.001).view(1, -1, 1)
    else:
        support_scores = torch.zeros(row.shape[1], device=device, dtype=torch.float32)
        support_migration = torch.zeros(1, row.shape[1], 1, device=device, dtype=torch.float32)
    migrated_support_weights = source_support_weights * support_migration
    evidence_weights = evidence_weights + migrated_support_weights

    source_contribution = _value_contribution_from_token_weights(source_weights, values)
    evidence_contribution = _value_contribution_from_token_weights(evidence_weights, values)
    source_mass = source_weights.sum(dim=-1).mean(dim=0).detach().float().cpu()
    evidence_mass = evidence_weights.sum(dim=-1).mean(dim=0).detach().float().cpu()

    return {
        "source_contribution": source_contribution,
        "evidence_contribution": evidence_contribution,
        "source_mass": source_mass,
        "evidence_mass": evidence_mass,
        "debug": {
            "oelpr_token_flow_mode": mode_key,
            "oelpr_token_flow_salient_tau": float(salient_tau),
            "oelpr_token_flow_sink_tau": float(sink_tau),
            "oelpr_token_flow_salient_scale": float(salient_scale),
            "oelpr_token_flow_sink_scale": float(sink_scale),
            "oelpr_token_flow_source_token_count": int(source_pos.numel()),
            "oelpr_token_flow_source_salient_count": int(source_salient.numel()),
            "oelpr_token_flow_source_sink_count": int(source_sink.numel()),
            "oelpr_token_flow_source_support_count": int(source_support.numel()),
            "oelpr_token_flow_evidence_token_count": int(evidence_pos.numel()),
            "oelpr_token_flow_evidence_salient_count": int(evidence_salient.numel()),
            "oelpr_token_flow_evidence_sink_count": int(evidence_sink.numel()),
            "oelpr_token_flow_evidence_support_count": int(evidence_support.numel()),
            "oelpr_token_flow_source_mass_mean": float(source_mass.mean().item()),
            "oelpr_token_flow_evidence_mass_mean": float(evidence_mass.mean().item()),
            "oelpr_token_flow_cross_support_mass_mean": float(
                migrated_support_weights.sum(dim=-1).mean(dim=0).detach().float().mean().cpu().item()
            ),
            "oelpr_token_flow_cross_support_candidate_weight_mean": float(
                support_migration.detach().float().mean().cpu().item()
            ),
            "oelpr_token_flow_cross_support_candidate_effect_mean": float(
                support_scores.detach().float().mean().cpu().item()
            ),
        },
    }



def _project_head_contribution_to_hidden(
    *,
    module: torch.nn.Module,
    contribution: torch.Tensor,
    head_indices: torch.Tensor | None = None,
) -> torch.Tensor:
    """Project per-head value contributions through that head's o_proj slice."""
    contrib = contribution.detach().float()
    if contrib.ndim != 4 or int(contrib.shape[2]) != 1:
        raise ValueError(f"unexpected head contribution shape: {tuple(contrib.shape)}")
    num_paths = int(contrib.shape[1])
    head_vectors = contrib[:, :, 0, :]
    out_proj = getattr(module, "o_proj", None)
    if out_proj is None or not hasattr(out_proj, "weight"):
        raise ValueError("attention module is missing o_proj.weight")
    weight = out_proj.weight.detach().to(device=head_vectors.device, dtype=torch.float32)
    hidden_size = int(weight.shape[0])
    head_dim = int(head_vectors.shape[-1])
    if hidden_size != int(weight.shape[1]):
        raise ValueError(f"expected square o_proj, got {tuple(weight.shape)}")
    total_heads = hidden_size // head_dim
    if hidden_size != total_heads * head_dim:
        raise ValueError(
            f"o_proj hidden size does not match an integer number of heads: {hidden_size} != n*{head_dim}"
        )
    # Linear layer convention: y = x @ weight.T. A single head occupies a
    # contiguous slice of the merged MHA dimension before o_proj.
    o_slices = weight.t().reshape(total_heads, head_dim, hidden_size)
    if head_indices is not None:
        head_idx = head_indices.detach().long().to(device=head_vectors.device)
        if int(head_idx.numel()) != num_paths:
            raise ValueError(
                f"head_indices must match contribution paths: {int(head_idx.numel())} != {num_paths}"
            )
        if head_idx.numel() > 0 and (
            int(head_idx.min().detach().cpu().item()) < 0
            or int(head_idx.max().detach().cpu().item()) >= total_heads
        ):
            raise ValueError(f"head_indices out of range for {total_heads} heads")
        o_slices = o_slices[head_idx]
    elif total_heads != num_paths:
        raise ValueError(
            f"o_proj hidden size does not match heads*head_dim: {hidden_size} != {num_paths}*{head_dim}"
        )
    return torch.einsum("bhd,hdk->bhk", head_vectors, o_slices)


def _head_carrier_alignment_scores(
    *,
    module: torch.nn.Module,
    contribution: torch.Tensor,
    carrier_direction: torch.Tensor,
    head_indices: torch.Tensor | None = None,
) -> torch.Tensor:
    """Cosine alignment between each head path and a hidden-space carrier."""
    num_heads = int(contribution.shape[1]) if contribution.ndim >= 2 else 0
    if num_heads <= 0:
        return torch.zeros(0, dtype=torch.float32)
    projected = _project_head_contribution_to_hidden(
        module=module,
        contribution=contribution,
        head_indices=head_indices,
    )
    carrier = carrier_direction.detach().float().to(device=projected.device)
    if carrier.ndim != 1 or int(carrier.numel()) != int(projected.shape[-1]):
        raise ValueError(
            "carrier direction must be a hidden vector matching projected head contributions "
            f"({tuple(carrier.shape)} vs {tuple(projected.shape)})"
        )
    carrier = carrier / carrier.norm().clamp_min(1.0e-12)
    projected_norm = projected.norm(dim=-1).clamp_min(1.0e-12)
    # Carrier orientation can flip across construction paths; subspace membership is what matters here.
    alignment = torch.abs(torch.einsum("bhk,k->bh", projected, carrier) / projected_norm)
    return alignment.mean(dim=0).detach().float().cpu()


def _head_answer_contribution_scores(
    *,
    module: torch.nn.Module,
    contribution: torch.Tensor,
    lm_head: torch.nn.Module,
    yes_id: int,
    no_id: int,
    current_answer: str | None,
    candidate_answer: str | None,
    head_indices: torch.Tensor | None = None,
) -> dict[str, Any]:
    """AllPath-style per-head logit contribution for the candidate/current pair."""
    current = normalize_binary_label(current_answer)
    candidate = normalize_binary_label(candidate_answer)
    num_heads = int(contribution.shape[1]) if contribution.ndim >= 2 else 0
    empty = torch.zeros(num_heads, dtype=torch.float32)
    if current is None or candidate is None or current == candidate or num_heads <= 0:
        return {
            "candidate_minus_current": empty,
            "current_minus_candidate": empty,
            "candidate_token_id": None,
            "current_token_id": None,
            "available": False,
            "fallback_reason": "missing_or_degenerate_candidate_current",
        }
    candidate_id = int(yes_id if candidate == "Yes" else no_id)
    current_id = int(yes_id if current == "Yes" else no_id)
    projected = _project_head_contribution_to_hidden(
        module=module,
        contribution=contribution,
        head_indices=head_indices,
    )
    lm_weight = lm_head.weight.detach()
    answer_axis = (
        lm_weight[candidate_id].to(device=projected.device, dtype=torch.float32)
        - lm_weight[current_id].to(device=projected.device, dtype=torch.float32)
    )
    cand_minus_current = torch.einsum("bhk,k->h", projected, answer_axis).detach().float().cpu()
    cur_minus_candidate = -cand_minus_current
    return {
        "candidate_minus_current": cand_minus_current,
        "current_minus_candidate": cur_minus_candidate,
        "candidate_token_id": candidate_id,
        "current_token_id": current_id,
        "available": True,
        "fallback_reason": None,
    }


def _hulluedit_weighted_svd_basis(paths: torch.Tensor, weights: torch.Tensor, rank: int) -> torch.Tensor:
    """Use HulluEdit's weighted SVD implementation for path-carrier subspaces."""
    if HullueditSteerer is None:
        raise ImportError(
            f"HulluEdit repo is not importable from {HULLUEDIT_ROOT}. "
            "signed_path_subspace requires hulluedit.steer.HullueditSteerer._weighted_svd."
        )
    clean_paths = torch.as_tensor(paths).detach().float()
    clean_weights = torch.as_tensor(weights).detach().float().reshape(-1)
    if clean_paths.ndim != 2:
        raise ValueError(f"weighted SVD expects path matrix [N,D], got {tuple(clean_paths.shape)}")
    if int(clean_weights.numel()) != int(clean_paths.shape[0]):
        raise ValueError(
            "weighted SVD expects one weight per path "
            f"({int(clean_weights.numel())} != {int(clean_paths.shape[0])})"
        )
    clean_weights = torch.nan_to_num(clean_weights, nan=0.0, posinf=0.0, neginf=0.0).clamp_min(0.0)
    active = clean_weights > 1.0e-12
    if int(active.detach().cpu().sum().item()) <= 0 or int(rank) <= 0:
        return clean_paths.new_zeros((int(clean_paths.shape[-1]), 0))
    active_paths = clean_paths[active]
    active_weights = clean_weights[active]
    return HullueditSteerer._weighted_svd(active_paths, active_weights, int(rank)).detach().float()


def _project_token_head_atoms_to_hidden(
    *,
    module: torch.nn.Module,
    values: torch.Tensor,
    positions: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    """Project unweighted token-head value atoms through each head's o_proj slice."""
    if values.ndim != 4:
        raise ValueError(f"expected value states [B,H,S,Dh], got {tuple(values.shape)}")
    seq_len = int(values.shape[2])
    pos = positions.detach().long()
    pos = pos[(pos >= 0) & (pos < seq_len)].unique(sorted=True)
    if int(pos.numel()) <= 0:
        hidden_size = int(getattr(module, "hidden_size", 0) or 0)
        return (
            values.new_zeros((0, hidden_size), dtype=torch.float32),
            torch.zeros(0, dtype=torch.long),
            torch.zeros(0, dtype=torch.long),
        )
    token_values = values[:, :, pos.to(device=values.device), :].detach().float().mean(dim=0)
    # token_values: [H,T,Dh]
    num_heads = int(token_values.shape[0])
    head_dim = int(token_values.shape[-1])
    out_proj = getattr(module, "o_proj", None)
    if out_proj is None or not hasattr(out_proj, "weight"):
        raise ValueError("attention module is missing o_proj.weight")
    weight = out_proj.weight.detach().to(device=token_values.device, dtype=torch.float32)
    hidden_size = int(weight.shape[0])
    if hidden_size != int(weight.shape[1]):
        raise ValueError(f"expected square o_proj, got {tuple(weight.shape)}")
    total_heads = hidden_size // head_dim
    if total_heads != num_heads or hidden_size != total_heads * head_dim:
        raise ValueError(
            "o_proj hidden size does not match value heads "
            f"({hidden_size}, {num_heads}, {head_dim})"
        )
    o_slices = weight.t().reshape(total_heads, head_dim, hidden_size)
    atoms = torch.einsum("htd,hdk->htk", token_values, o_slices).reshape(-1, hidden_size)
    head_ids = torch.arange(num_heads, device=values.device).view(num_heads, 1).expand(num_heads, int(pos.numel()))
    token_ids = pos.to(device=values.device).view(1, int(pos.numel())).expand(num_heads, int(pos.numel()))
    return atoms.float(), head_ids.reshape(-1).detach().cpu(), token_ids.reshape(-1).detach().cpu()


def _signed_path_subspace_carriers_from_token_heads(
    *,
    module: torch.nn.Module,
    row: torch.Tensor,
    values: torch.Tensor,
    carrier_positions: torch.Tensor,
    carrier_gate: torch.Tensor | None = None,
    branch_prior_direction: torch.Tensor | None = None,
    branch_evidence_direction: torch.Tensor | None = None,
    lm_head: torch.nn.Module,
    yes_id: int,
    no_id: int,
    current_answer: str | None,
    candidate_answer: str | None,
    rank_evidence: int,
    rank_prior: int,
) -> dict[str, Any]:
    """Build U/P subspaces from signed token-head causal paths.

    The atom is an unweighted token-head value path projected through o_proj.
    Its sign is determined by the AllPath-style candidate-vs-current answer
    axis, while its causal weight is the actual final-query attention effect
    calibrated by a CausalMM-style uniform-attention counterfactual.
    """
    current = normalize_binary_label(current_answer)
    candidate = normalize_binary_label(candidate_answer)
    eps = 1.0e-12
    empty_debug = {
        "signed_path_available": False,
        "signed_path_fallback_reason": None,
        "signed_path_rank_evidence_requested": int(rank_evidence),
        "signed_path_rank_prior_requested": int(rank_prior),
        "signed_path_rank_evidence_actual": 0,
        "signed_path_rank_prior_actual": 0,
    }
    if current is None or candidate is None or current == candidate:
        empty_debug["signed_path_fallback_reason"] = "missing_or_degenerate_candidate_current"
        return {
            "prior_direction": torch.zeros(0),
            "evidence_direction": torch.zeros(0),
            "prior_basis": torch.zeros(0, 0),
            "evidence_basis": torch.zeros(0, 0),
            "prior_paths": torch.zeros(0, 0),
            "evidence_paths": torch.zeros(0, 0),
            "prior_scores": torch.zeros(0),
            "evidence_scores": torch.zeros(0),
            "prior_available": False,
            "evidence_available": False,
            "debug": empty_debug,
        }
    pos = carrier_positions.detach().long()
    seq_len = int(row.shape[-1])
    pos = pos[(pos >= 0) & (pos < seq_len)].unique(sorted=True)
    if int(pos.numel()) <= 0:
        empty_debug["signed_path_fallback_reason"] = "empty_carrier_positions"
        return {
            "prior_direction": torch.zeros(0),
            "evidence_direction": torch.zeros(0),
            "prior_basis": torch.zeros(0, 0),
            "evidence_basis": torch.zeros(0, 0),
            "prior_paths": torch.zeros(0, 0),
            "evidence_paths": torch.zeros(0, 0),
            "prior_scores": torch.zeros(0),
            "evidence_scores": torch.zeros(0),
            "prior_available": False,
            "evidence_available": False,
            "debug": empty_debug,
        }

    atoms, head_ids, token_ids = _project_token_head_atoms_to_hidden(
        module=module,
        values=values,
        positions=pos,
    )
    if int(atoms.shape[0]) <= 0:
        empty_debug["signed_path_fallback_reason"] = "empty_projected_path_atoms"
        return {
            "prior_direction": torch.zeros(0),
            "evidence_direction": torch.zeros(0),
            "prior_basis": torch.zeros(0, 0),
            "evidence_basis": torch.zeros(0, 0),
            "prior_paths": torch.zeros(0, 0),
            "evidence_paths": torch.zeros(0, 0),
            "prior_scores": torch.zeros(0),
            "evidence_scores": torch.zeros(0),
            "prior_available": False,
            "evidence_available": False,
            "debug": empty_debug,
        }

    candidate_id = int(yes_id if candidate == "Yes" else no_id)
    current_id = int(yes_id if current == "Yes" else no_id)
    answer_axis = (
        lm_head.weight.detach()[candidate_id].to(device=atoms.device, dtype=torch.float32)
        - lm_head.weight.detach()[current_id].to(device=atoms.device, dtype=torch.float32)
    )
    num_heads = int(row.shape[1])
    num_tokens = int(pos.numel())
    mass_rows = row[:, :, pos.to(device=row.device)].detach().float()
    if carrier_gate is not None:
        gate = carrier_gate.to(device=row.device, dtype=torch.float32)
        if gate.shape != row.shape:
            raise ValueError(f"carrier_gate shape must match row shape ({tuple(gate.shape)} != {tuple(row.shape)})")
        mass_rows = mass_rows * gate[:, :, pos.to(device=row.device)].detach().float()
    mass = mass_rows.mean(dim=0)
    if tuple(mass.shape) != (num_heads, num_tokens):
        raise ValueError(f"unexpected carrier mass shape: {tuple(mass.shape)} != {(num_heads, num_tokens)}")
    atom_answer = torch.matmul(atoms.to(device=answer_axis.device), answer_axis).reshape(num_heads, num_tokens)
    actual_effect = (mass.to(device=atom_answer.device) * atom_answer).reshape(-1)
    uniform_mass = mass.sum(dim=-1, keepdim=True) / float(max(1, num_tokens))
    uniform_effect = (uniform_mass.to(device=atom_answer.device) * atom_answer).reshape(-1)
    sensitivity = torch.abs(actual_effect - uniform_effect)
    sensitivity_max = sensitivity.max().clamp_min(eps)
    sensitivity_weight = (sensitivity / sensitivity_max).clamp(0.0, 1.0)

    def branch_alignment_weight(vectors: torch.Tensor, reference: torch.Tensor | None) -> tuple[torch.Tensor, bool]:
        if reference is None:
            return torch.ones(vectors.shape[0], device=vectors.device, dtype=torch.float32), False
        ref = torch.as_tensor(reference).detach().float().to(device=vectors.device).reshape(-1)
        if int(ref.numel()) != int(vectors.shape[-1]) or float(ref.norm().detach().cpu().item()) <= eps:
            return torch.ones(vectors.shape[0], device=vectors.device, dtype=torch.float32), False
        ref_dir = ref / ref.norm().clamp_min(eps)
        denom = vectors.detach().float().norm(dim=-1).clamp_min(eps)
        return torch.abs(torch.matmul(vectors.detach().float(), ref_dir) / denom).clamp(0.0, 1.0), True

    evidence_alignment, evidence_alignment_used = branch_alignment_weight(atoms, branch_evidence_direction)
    evidence_scores_raw = actual_effect.clamp_min(0.0) * sensitivity_weight
    evidence_scores = evidence_scores_raw * evidence_alignment
    evidence_alignment_degenerate = False
    evidence_sensitivity_degenerate = False
    if float(evidence_scores.sum().detach().cpu().item()) <= eps:
        evidence_scores = evidence_scores_raw
        evidence_alignment_degenerate = bool(evidence_alignment_used)
    if float(evidence_scores.sum().detach().cpu().item()) <= eps:
        evidence_scores = actual_effect.clamp_min(0.0)
        evidence_sensitivity_degenerate = True

    evidence_basis = _hulluedit_weighted_svd_basis(atoms, evidence_scores, int(rank_evidence))
    if evidence_basis.numel() > 0:
        basis_dev = evidence_basis.to(device=atoms.device, dtype=torch.float32)
        prior_atoms = atoms - (atoms @ basis_dev) @ basis_dev.T
    else:
        prior_atoms = atoms
    prior_alignment, prior_alignment_used = branch_alignment_weight(prior_atoms, branch_prior_direction)
    prior_scores_raw = (-actual_effect).clamp_min(0.0) * sensitivity_weight
    prior_scores = prior_scores_raw * prior_alignment
    prior_alignment_degenerate = False
    prior_sensitivity_degenerate = False
    if float(prior_scores.sum().detach().cpu().item()) <= eps:
        prior_scores = prior_scores_raw
        prior_alignment_degenerate = bool(prior_alignment_used)
    if float(prior_scores.sum().detach().cpu().item()) <= eps:
        prior_scores = (-actual_effect).clamp_min(0.0)
        prior_sensitivity_degenerate = True
    prior_basis = _hulluedit_weighted_svd_basis(prior_atoms, prior_scores, int(rank_prior))

    def weighted_direction(vectors: torch.Tensor, scores: torch.Tensor) -> torch.Tensor:
        clean_scores = torch.nan_to_num(scores.detach().float(), nan=0.0, posinf=0.0, neginf=0.0).clamp_min(0.0)
        if float(clean_scores.sum().detach().cpu().item()) <= eps:
            return vectors.new_zeros(int(vectors.shape[-1]))
        vec = torch.einsum("n,nd->d", clean_scores.to(device=vectors.device), vectors.detach().float())
        norm = vec.norm()
        if float(norm.detach().cpu().item()) <= eps:
            return vectors.new_zeros(int(vectors.shape[-1]))
        return vec / norm.clamp_min(eps)

    evidence_direction = weighted_direction(atoms, evidence_scores).detach().float().cpu()
    prior_direction = weighted_direction(prior_atoms, prior_scores).detach().float().cpu()
    evidence_available = int(evidence_basis.shape[1]) > 0 and float(evidence_scores.sum().detach().cpu().item()) > 1.0e-12
    prior_available = int(prior_basis.shape[1]) > 0 and float(prior_scores.sum().detach().cpu().item()) > 1.0e-12
    evidence_active = int((evidence_scores > 1.0e-12).detach().cpu().sum().item())
    prior_active = int((prior_scores > 1.0e-12).detach().cpu().sum().item())
    return {
        "prior_direction": prior_direction,
        "evidence_direction": evidence_direction,
        "prior_basis": prior_basis.detach().float().cpu(),
        "evidence_basis": evidence_basis.detach().float().cpu(),
        "prior_paths": prior_atoms.detach().float().cpu(),
        "evidence_paths": atoms.detach().float().cpu(),
        "prior_scores": prior_scores.detach().float().cpu(),
        "evidence_scores": evidence_scores.detach().float().cpu(),
        "prior_available": bool(prior_available),
        "evidence_available": bool(evidence_available),
        "debug": {
            **empty_debug,
            "signed_path_available": bool(prior_available or evidence_available),
            "signed_path_fallback_reason": None,
            "signed_path_token_count": int(num_tokens),
            "signed_path_head_count": int(num_heads),
            "signed_path_atom_count": int(atoms.shape[0]),
            "signed_path_gate_used": carrier_gate is not None,
            "signed_path_gate_mass_mean": float(mass.detach().float().mean().cpu().item()),
            "signed_path_gate_mass_max": float(mass.detach().float().max().cpu().item()),
            "signed_path_rank_evidence_actual": int(evidence_basis.shape[1]),
            "signed_path_rank_prior_actual": int(prior_basis.shape[1]),
            "signed_path_evidence_available": bool(evidence_available),
            "signed_path_prior_available": bool(prior_available),
            "signed_path_evidence_active_count": int(evidence_active),
            "signed_path_prior_active_count": int(prior_active),
            "signed_path_evidence_score_mean": float(evidence_scores.detach().float().mean().cpu().item()),
            "signed_path_evidence_score_max": float(evidence_scores.detach().float().max().cpu().item()),
            "signed_path_prior_score_mean": float(prior_scores.detach().float().mean().cpu().item()),
            "signed_path_prior_score_max": float(prior_scores.detach().float().max().cpu().item()),
            "signed_path_evidence_branch_alignment_used": bool(evidence_alignment_used),
            "signed_path_prior_branch_alignment_used": bool(prior_alignment_used),
            "signed_path_evidence_branch_alignment_degenerate": bool(evidence_alignment_degenerate),
            "signed_path_prior_branch_alignment_degenerate": bool(prior_alignment_degenerate),
            "signed_path_evidence_branch_alignment_mean": float(
                evidence_alignment.detach().float().mean().cpu().item()
            ),
            "signed_path_evidence_branch_alignment_max": float(
                evidence_alignment.detach().float().max().cpu().item()
            ),
            "signed_path_prior_branch_alignment_mean": float(
                prior_alignment.detach().float().mean().cpu().item()
            ),
            "signed_path_prior_branch_alignment_max": float(
                prior_alignment.detach().float().max().cpu().item()
            ),
            "signed_path_actual_effect_mean": float(actual_effect.detach().float().mean().cpu().item()),
            "signed_path_actual_effect_max": float(actual_effect.detach().float().max().cpu().item()),
            "signed_path_actual_effect_min": float(actual_effect.detach().float().min().cpu().item()),
            "signed_path_counterfactual_sensitivity_mean": float(
                sensitivity.detach().float().mean().cpu().item()
            ),
            "signed_path_counterfactual_sensitivity_max": float(
                sensitivity.detach().float().max().cpu().item()
            ),
            "signed_path_evidence_sensitivity_degenerate": bool(evidence_sensitivity_degenerate),
            "signed_path_prior_sensitivity_degenerate": bool(prior_sensitivity_degenerate),
            "signed_path_candidate_token_id": int(candidate_id),
            "signed_path_current_token_id": int(current_id),
            "signed_path_head_ids": [int(x) for x in head_ids.tolist()],
            "signed_path_token_ids": [int(x) for x in token_ids.tolist()],
        },
    }


def _path_soft_hidden_carriers_from_token_heads(
    *,
    module: torch.nn.Module,
    source_contribution: torch.Tensor,
    evidence_contribution: torch.Tensor,
    source_mass: torch.Tensor,
    evidence_mass: torch.Tensor,
    prior_direction: torch.Tensor,
    evidence_direction: torch.Tensor,
    source_current_over_candidate: torch.Tensor | None,
    evidence_candidate_over_current: torch.Tensor | None,
) -> dict[str, Any]:
    """Build hidden-space P/U carriers from token-head answer paths.

    Each head path is weighted by three continuous factors:
      attention mass, binary-answer logit effect, and carrier alignment.
    The resulting carriers let the hidden update act on localized paths rather
    than a whole-hidden orthogonal projection.
    """

    def max_normalize(scores: torch.Tensor) -> torch.Tensor:
        values = scores.detach().float().clamp_min(0.0)
        max_value = values.max().clamp_min(1.0e-12)
        return (values / max_value).clamp(0.0, 1.0)

    def orient_to_reference(vectors: torch.Tensor, reference: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
        dots = torch.einsum("hd,d->h", vectors, reference)
        signs = torch.where(dots >= 0.0, torch.ones_like(dots), -torch.ones_like(dots))
        return vectors * signs.unsqueeze(-1), dots

    def cosine_value(a: torch.Tensor, b: torch.Tensor) -> float | None:
        a_vec = a.detach().float().reshape(-1)
        b_vec = b.detach().float().to(device=a_vec.device).reshape(-1)
        denom = a_vec.norm() * b_vec.norm()
        if float(denom.detach().cpu().item()) <= 1.0e-12:
            return None
        return float((torch.dot(a_vec, b_vec) / denom.clamp_min(1.0e-12)).detach().cpu().item())

    source_hidden = _project_head_contribution_to_hidden(
        module=module,
        contribution=source_contribution,
    ).float()
    evidence_hidden = _project_head_contribution_to_hidden(
        module=module,
        contribution=evidence_contribution,
    ).float()
    if source_hidden.ndim != 3 or evidence_hidden.ndim != 3:
        raise ValueError(
            "path carrier construction expects projected source/evidence paths with shape [B,H,D]"
        )
    source_paths = source_hidden.mean(dim=0)
    evidence_paths = evidence_hidden.mean(dim=0)
    num_heads = int(source_paths.shape[0])
    if int(evidence_paths.shape[0]) != num_heads:
        raise ValueError(
            f"source/evidence path head count mismatch: {int(source_paths.shape[0])} != {int(evidence_paths.shape[0])}"
        )

    device = source_paths.device
    p_ref = unit(prior_direction).to(device=device, dtype=torch.float32)
    u_ref = unit(evidence_direction).to(device=device, dtype=torch.float32)
    src_mass = source_mass.detach().float().to(device=device).reshape(-1)
    evi_mass = evidence_mass.detach().float().to(device=device).reshape(-1)
    if int(src_mass.numel()) != num_heads or int(evi_mass.numel()) != num_heads:
        raise ValueError(
            "path carrier construction expects one source/evidence mass per head "
            f"({int(src_mass.numel())}, {int(evi_mass.numel())}) != {num_heads}"
        )

    source_answer_available = source_current_over_candidate is not None and int(source_current_over_candidate.numel()) == num_heads
    evidence_answer_available = (
        evidence_candidate_over_current is not None and int(evidence_candidate_over_current.numel()) == num_heads
    )
    if source_answer_available:
        source_answer = source_current_over_candidate.detach().float().to(device=device)
        source_answer_weight = max_normalize(source_answer)
    else:
        source_answer = torch.zeros(num_heads, device=device, dtype=torch.float32)
        source_answer_weight = torch.zeros(num_heads, device=device, dtype=torch.float32)
    if evidence_answer_available:
        evidence_answer = evidence_candidate_over_current.detach().float().to(device=device)
        evidence_answer_weight = max_normalize(evidence_answer)
    else:
        evidence_answer = torch.zeros(num_heads, device=device, dtype=torch.float32)
        evidence_answer_weight = torch.zeros(num_heads, device=device, dtype=torch.float32)

    source_norm = source_paths.norm(dim=-1).clamp_min(1.0e-12)
    evidence_norm = evidence_paths.norm(dim=-1).clamp_min(1.0e-12)
    source_oriented, source_ref_dot = orient_to_reference(source_paths, p_ref)
    evidence_oriented, evidence_ref_dot = orient_to_reference(evidence_paths, u_ref)
    source_align = torch.abs(source_ref_dot / source_norm).clamp(0.0, 1.0)
    evidence_align = torch.abs(evidence_ref_dot / evidence_norm).clamp(0.0, 1.0)

    source_mass_weight = max_normalize(src_mass)
    evidence_mass_weight = max_normalize(evi_mass)
    source_score = source_mass_weight * source_answer_weight * source_align
    evidence_score = evidence_mass_weight * evidence_answer_weight * evidence_align
    source_fallback = False
    evidence_fallback = False
    if float(source_score.sum().detach().cpu().item()) <= 1.0e-12:
        source_score = source_mass_weight * source_align
        source_fallback = True
    if float(evidence_score.sum().detach().cpu().item()) <= 1.0e-12:
        evidence_score = evidence_mass_weight * evidence_align
        evidence_fallback = True

    prior_vec = torch.einsum("h,hd->d", source_score, source_oriented)
    evidence_vec = torch.einsum("h,hd->d", evidence_score, evidence_oriented)
    prior_norm = float(prior_vec.norm().detach().cpu().item())
    evidence_norm_value = float(evidence_vec.norm().detach().cpu().item())
    prior_available = prior_norm > 1.0e-12
    evidence_available = evidence_norm_value > 1.0e-12
    if prior_available:
        prior_dir = (prior_vec / prior_vec.norm().clamp_min(1.0e-12)).detach().float().cpu()
    else:
        prior_dir = torch.zeros_like(prior_vec).detach().float().cpu()
    if evidence_available:
        evidence_dir = (evidence_vec / evidence_vec.norm().clamp_min(1.0e-12)).detach().float().cpu()
    else:
        evidence_dir = torch.zeros_like(evidence_vec).detach().float().cpu()

    prior_dominant = torch.nonzero((source_score > evidence_score).detach().cpu(), as_tuple=False).flatten()
    evidence_dominant = torch.nonzero((evidence_score >= source_score).detach().cpu(), as_tuple=False).flatten()
    return {
        "prior_direction": prior_dir,
        "evidence_direction": evidence_dir,
        "prior_paths": source_oriented.detach().float().cpu(),
        "evidence_paths": evidence_oriented.detach().float().cpu(),
        "prior_scores": source_score.detach().float().cpu(),
        "evidence_scores": evidence_score.detach().float().cpu(),
        "prior_available": bool(prior_available),
        "evidence_available": bool(evidence_available),
        "debug": {
            "path_soft_prior_available": bool(prior_available),
            "path_soft_evidence_available": bool(evidence_available),
            "path_soft_source_answer_available": bool(source_answer_available),
            "path_soft_evidence_answer_available": bool(evidence_answer_available),
            "path_soft_source_fallback_to_mass_alignment": bool(source_fallback),
            "path_soft_evidence_fallback_to_mass_alignment": bool(evidence_fallback),
            "path_soft_prior_norm": prior_norm,
            "path_soft_evidence_norm": evidence_norm_value,
            "path_soft_prior_score_mean": float(source_score.mean().detach().cpu().item()),
            "path_soft_prior_score_max": float(source_score.max().detach().cpu().item()),
            "path_soft_evidence_score_mean": float(evidence_score.mean().detach().cpu().item()),
            "path_soft_evidence_score_max": float(evidence_score.max().detach().cpu().item()),
            "path_soft_source_mass_weight_mean": float(source_mass_weight.mean().detach().cpu().item()),
            "path_soft_evidence_mass_weight_mean": float(evidence_mass_weight.mean().detach().cpu().item()),
            "path_soft_source_answer_weight_mean": float(source_answer_weight.mean().detach().cpu().item()),
            "path_soft_evidence_answer_weight_mean": float(evidence_answer_weight.mean().detach().cpu().item()),
            "path_soft_source_alignment_mean": float(source_align.mean().detach().cpu().item()),
            "path_soft_evidence_alignment_mean": float(evidence_align.mean().detach().cpu().item()),
            "path_soft_source_current_over_candidate_mean": float(source_answer.mean().detach().cpu().item()),
            "path_soft_evidence_candidate_over_current_mean": float(evidence_answer.mean().detach().cpu().item()),
            "path_soft_prior_cos_original_prior": cosine_value(prior_dir, p_ref.detach().cpu()) if prior_available else None,
            "path_soft_evidence_cos_original_evidence": (
                cosine_value(evidence_dir, u_ref.detach().cpu()) if evidence_available else None
            ),
            "path_soft_prior_dominant_head_count": int(prior_dominant.numel()),
            "path_soft_evidence_dominant_head_count": int(evidence_dominant.numel()),
            "path_soft_prior_dominant_heads": [int(x) for x in prior_dominant.tolist()],
            "path_soft_evidence_dominant_heads": [int(x) for x in evidence_dominant.tolist()],
        },
    }


def _path_constrained_hidden_delta_from_paths(
    *,
    target_delta: torch.Tensor,
    path_vectors: Any,
    path_scores: Any,
    prefix: str,
    residual_penalty: float | None = None,
) -> dict[str, Any]:
    """Project a hidden update onto token/head value-path bases.

    The basis vectors are oriented toward the target update, normalized into
    path directions, and solved as a non-negative ridge projection. This keeps
    the late update inside the causal paths identified by token/head attribution
    instead of applying an unconstrained whole-hidden projection.
    """
    target = target_delta.detach().float().reshape(-1)
    device = target.device
    eps = 1.0e-12
    empty = {
        "delta": torch.zeros_like(target),
        "available": False,
        "solved": False,
        "fallback_reason": "empty_path_basis",
        f"{prefix}_path_projected_available": False,
        f"{prefix}_path_projected_solved": False,
        f"{prefix}_path_projected_fallback_reason": "empty_path_basis",
        f"{prefix}_path_projected_active_count": 0,
        f"{prefix}_path_projected_target_l2": float(target.norm().detach().cpu().item()),
        f"{prefix}_path_projected_delta_l2": 0.0,
        f"{prefix}_path_projected_residual_l2": float(target.norm().detach().cpu().item()),
        f"{prefix}_path_projected_fit_cos": None,
        f"{prefix}_path_projected_fit_ratio": 0.0,
        f"{prefix}_path_projected_coeff_mean": None,
        f"{prefix}_path_projected_coeff_min": None,
        f"{prefix}_path_projected_coeff_max": None,
        f"{prefix}_path_projected_score_mean": None,
        f"{prefix}_path_projected_score_max": None,
        f"{prefix}_path_projected_residual_atom_gain": None,
        f"{prefix}_path_projected_residual_atom_penalty": None,
        f"{prefix}_path_projected_path_explained_ratio": None,
        f"{prefix}_path_projected_residual_atom_l2": 0.0,
    }
    target_norm = target.norm()
    if float(target_norm.detach().cpu().item()) <= eps:
        empty["fallback_reason"] = "zero_target_delta"
        empty[f"{prefix}_path_projected_fallback_reason"] = "zero_target_delta"
        return empty
    if path_vectors is None or path_scores is None:
        empty["fallback_reason"] = "missing_path_payload"
        empty[f"{prefix}_path_projected_fallback_reason"] = "missing_path_payload"
        return empty

    paths = torch.as_tensor(path_vectors, dtype=torch.float32).to(device=device)
    scores = torch.as_tensor(path_scores, dtype=torch.float32).to(device=device).reshape(-1)
    if paths.ndim != 2 or int(paths.shape[-1]) != int(target.numel()):
        raise ValueError(
            "path-projected hidden update expects path basis [H,D] matching target "
            f"({tuple(paths.shape)} vs {tuple(target.shape)})"
        )
    if int(scores.numel()) != int(paths.shape[0]):
        raise ValueError(
            "path-projected hidden update expects one score per path "
            f"({int(scores.numel())} != {int(paths.shape[0])})"
        )
    path_norm = paths.norm(dim=-1)
    clean_scores = torch.nan_to_num(scores, nan=0.0, posinf=0.0, neginf=0.0).clamp_min(0.0)
    active = (path_norm > eps) & (clean_scores > eps)
    active_count = int(active.detach().cpu().sum().item())
    if active_count <= 0:
        empty["fallback_reason"] = "no_positive_scored_path"
        empty[f"{prefix}_path_projected_fallback_reason"] = "no_positive_scored_path"
        return empty

    target_unit = target / target_norm.clamp_min(eps)
    active_paths = paths[active]
    active_scores = clean_scores[active]
    orientation = torch.einsum("hd,d->h", active_paths, target_unit)
    signs = torch.where(orientation >= 0.0, torch.ones_like(orientation), -torch.ones_like(orientation))
    oriented_paths = active_paths * signs.unsqueeze(-1)
    basis = oriented_paths / oriented_paths.norm(dim=-1, keepdim=True).clamp_min(eps)
    score_scale = active_scores / active_scores.mean().clamp_min(eps)
    score_scale = score_scale.clamp_min(eps)

    gram = basis @ basis.t()
    diag = torch.diag(gram).clamp_min(eps)
    ridge = 0.01 * diag.mean().clamp_min(eps)
    score_penalty = ridge / score_scale.clamp_min(0.05)
    rhs = basis @ target
    solved = True
    try:
        lipschitz = torch.linalg.eigvalsh(gram).max().clamp_min(eps) + score_penalty.max()
    except RuntimeError:
        solved = False
        lipschitz = diag.sum().clamp_min(eps) + score_penalty.max()
    coeff = (rhs / (diag + score_penalty).clamp_min(eps)).clamp_min(0.0)
    step = 1.0 / lipschitz
    for _ in range(80):
        grad = gram @ coeff - rhs + score_penalty * coeff
        coeff = (coeff - step * grad).clamp_min(0.0)
    if not bool(torch.isfinite(coeff).all().detach().cpu().item()):
        empty["fallback_reason"] = "nonfinite_solution"
        empty[f"{prefix}_path_projected_fallback_reason"] = "nonfinite_solution"
        return empty
    path_delta = torch.einsum("h,hd->d", coeff, basis)
    residual_atom_gain = None
    residual_atom_penalty = None
    path_explained_ratio = None
    residual_atom = torch.zeros_like(path_delta)
    delta = path_delta
    if residual_penalty is not None:
        raw_explained = torch.dot(path_delta, target) / target_norm.square().clamp_min(eps)
        path_explained_ratio = float(raw_explained.clamp(0.0, 1.0).detach().cpu().item())
        penalty = max(0.05, max(0.0, float(residual_penalty)) * path_explained_ratio)
        residual_atom_penalty = float(penalty)
        residual_before_atom = target - path_delta
        residual_norm_before_atom = residual_before_atom.norm()
        if float(residual_norm_before_atom.detach().cpu().item()) > eps:
            residual_atom_gain = 1.0 / (1.0 + penalty)
            residual_atom = float(residual_atom_gain) * residual_before_atom
            delta = path_delta + residual_atom
    delta_norm = delta.norm()
    residual = target - delta
    denom = delta_norm * target_norm
    fit_cos = (
        float((torch.dot(delta, target) / denom.clamp_min(eps)).detach().cpu().item())
        if float(denom.detach().cpu().item()) > eps
        else None
    )
    return {
        "delta": delta,
        "available": True,
        "solved": bool(solved),
        "fallback_reason": None,
        f"{prefix}_path_projected_available": True,
        f"{prefix}_path_projected_solved": bool(solved),
        f"{prefix}_path_projected_fallback_reason": None,
        f"{prefix}_path_projected_active_count": active_count,
        f"{prefix}_path_projected_target_l2": float(target_norm.detach().cpu().item()),
        f"{prefix}_path_projected_delta_l2": float(delta_norm.detach().cpu().item()),
        f"{prefix}_path_projected_residual_l2": float(residual.norm().detach().cpu().item()),
        f"{prefix}_path_projected_fit_cos": fit_cos,
        f"{prefix}_path_projected_fit_ratio": float((delta_norm / target_norm.clamp_min(eps)).detach().cpu().item()),
        f"{prefix}_path_projected_coeff_mean": float(coeff.mean().detach().cpu().item()),
        f"{prefix}_path_projected_coeff_min": float(coeff.min().detach().cpu().item()),
        f"{prefix}_path_projected_coeff_max": float(coeff.max().detach().cpu().item()),
        f"{prefix}_path_projected_score_mean": float(active_scores.mean().detach().cpu().item()),
        f"{prefix}_path_projected_score_max": float(active_scores.max().detach().cpu().item()),
        f"{prefix}_path_projected_residual_atom_gain": residual_atom_gain,
        f"{prefix}_path_projected_residual_atom_penalty": residual_atom_penalty,
        f"{prefix}_path_projected_path_explained_ratio": path_explained_ratio,
        f"{prefix}_path_projected_residual_atom_l2": float(residual_atom.norm().detach().cpu().item()),
    }


def _path_answer_margin_evidence_delta(
    *,
    base: torch.Tensor,
    path_vectors: Any,
    path_scores: Any,
    lm_head: torch.nn.Module,
    yes_id: int,
    no_id: int,
    current_answer: str | None,
    candidate_answer: str | None,
    alpha_for_layer: float,
    solution_mode: str = "weighted_path_mean",
) -> dict[str, Any]:
    """Build an evidence boost target from answer-positive evidence paths.

    This keeps the method within the existing token/head/path -> hidden framework:
    token/head attribution supplies the evidence path atoms, and this function
    only turns paths that increase candidate-over-current margin into the hidden
    target subsequently constrained by `_path_constrained_hidden_delta_from_paths`.
    """
    h = base.detach().float().reshape(-1)
    device = h.device
    eps = 1.0e-12
    alpha_value = max(0.0, float(alpha_for_layer))

    def empty(reason: str) -> dict[str, Any]:
        return {
            "delta": torch.zeros_like(h),
            "path_answer_margin_available": False,
            "path_answer_margin_reason": reason,
            "path_answer_margin_active_count": 0,
            "path_answer_margin_alpha": float(alpha_value),
            "path_answer_margin_solution_mode": str(solution_mode),
            "path_answer_margin_target_l2": 0.0,
            "path_answer_margin_delta_l2": 0.0,
            "path_answer_margin_budget_l2": 0.0,
            "path_answer_margin_axis_projection_l2": 0.0,
            "path_answer_margin_answer_gain": 0.0,
            "path_answer_margin_before_margin": None,
            "path_answer_margin_unit_margin_mean": None,
            "path_answer_margin_unit_margin_max": None,
            "path_answer_margin_weighted_path_norm": None,
            "path_answer_margin_score_mean": None,
        }

    if alpha_value <= eps:
        return empty("zero_alpha")
    current = normalize_binary_label(current_answer)
    candidate = normalize_binary_label(candidate_answer)
    if current is None or candidate is None or current == candidate:
        return empty("missing_or_degenerate_candidate_current")
    if path_vectors is None or path_scores is None:
        return empty("missing_path_payload")

    current_id = int(yes_id if current == "Yes" else no_id)
    candidate_id = int(yes_id if candidate == "Yes" else no_id)
    lm_weight = lm_head.weight.detach().to(device=device, dtype=torch.float32)
    if current_id >= int(lm_weight.shape[0]) or candidate_id >= int(lm_weight.shape[0]):
        return empty("answer_token_out_of_range")
    axis = lm_weight[candidate_id] - lm_weight[current_id]
    axis_norm = axis.norm()
    if float(axis_norm.detach().cpu().item()) <= eps:
        return empty("degenerate_answer_axis")
    axis_unit = axis / axis_norm.clamp_min(eps)

    paths = torch.as_tensor(path_vectors, dtype=torch.float32).to(device=device)
    scores = torch.as_tensor(path_scores, dtype=torch.float32).to(device=device).reshape(-1)
    if paths.ndim != 2 or int(paths.shape[-1]) != int(h.numel()):
        raise ValueError(
            "path-answer evidence target expects path basis [N,D] matching hidden state "
            f"({tuple(paths.shape)} vs {tuple(h.shape)})"
        )
    if int(scores.numel()) != int(paths.shape[0]):
        raise ValueError(
            "path-answer evidence target expects one score per path "
            f"({int(scores.numel())} != {int(paths.shape[0])})"
        )
    path_norm = paths.norm(dim=-1)
    clean_scores = torch.nan_to_num(scores.detach().float(), nan=0.0, posinf=0.0, neginf=0.0).clamp_min(0.0)
    unit_margin = (paths @ axis_unit) / path_norm.clamp_min(eps)
    active = (path_norm > eps) & (clean_scores > eps) & (unit_margin > 0.0)
    active_count = int(active.detach().cpu().sum().item())
    if active_count <= 0:
        return empty("no_answer_positive_evidence_path")

    active_scores = clean_scores[active]
    active_margins = unit_margin[active].clamp_min(0.0)
    raw_weights = active_scores * active_margins
    if float(raw_weights.sum().detach().cpu().item()) <= eps:
        return empty("zero_answer_path_weight")
    weights = raw_weights / raw_weights.sum().clamp_min(eps)
    active_paths = paths[active]
    weighted_target = torch.einsum("n,nd->d", weights, active_paths)
    weighted_target_norm = weighted_target.norm()
    solution_key = str(solution_mode)
    axis_projection_l2 = 0.0
    if solution_key == "weighted_path_mean":
        target = weighted_target
    elif solution_key == "least_norm_answer_axis":
        budget_l2 = alpha_value * float(weighted_target_norm.detach().cpu().item())
        if budget_l2 <= eps:
            return empty("zero_answer_path_budget")
        active_norm = path_norm[active].clamp_min(eps)
        basis = active_paths / active_norm.unsqueeze(-1)
        score_scale = raw_weights / raw_weights.mean().clamp_min(eps)
        score_scale = score_scale.clamp_min(eps)
        gram = basis @ basis.t()
        diag = torch.diag(gram).clamp_min(eps)
        ridge = 0.01 * diag.mean().clamp_min(eps)
        score_penalty = ridge / score_scale.clamp_min(0.05)
        rhs = basis @ axis_unit
        try:
            lipschitz = torch.linalg.eigvalsh(gram).max().clamp_min(eps) + score_penalty.max()
        except RuntimeError:
            lipschitz = diag.sum().clamp_min(eps) + score_penalty.max()
        coeff = (rhs / (diag + score_penalty).clamp_min(eps)).clamp_min(0.0)
        step = 1.0 / lipschitz
        for _ in range(80):
            grad = gram @ coeff - rhs + score_penalty * coeff
            coeff = (coeff - step * grad).clamp_min(0.0)
        if not bool(torch.isfinite(coeff).all().detach().cpu().item()):
            return empty("nonfinite_answer_axis_solution")
        answer_axis_path = torch.einsum("n,nd->d", coeff, basis)
        answer_axis_path_norm = answer_axis_path.norm()
        axis_projection_l2 = float(answer_axis_path_norm.detach().cpu().item())
        if axis_projection_l2 <= eps:
            return empty("zero_answer_axis_projection")
        target = float(weighted_target_norm.detach().cpu().item()) * (
            answer_axis_path / answer_axis_path_norm.clamp_min(eps)
        )
    else:
        raise ValueError(f"unknown path_answer_margin solution_mode: {solution_mode}")
    delta = alpha_value * target
    return {
        "delta": delta,
        "path_answer_margin_available": True,
        "path_answer_margin_reason": "ok",
        "path_answer_margin_active_count": active_count,
        "path_answer_margin_alpha": float(alpha_value),
        "path_answer_margin_solution_mode": solution_key,
        "path_answer_margin_target_l2": float(target.norm().detach().cpu().item()),
        "path_answer_margin_delta_l2": float(delta.norm().detach().cpu().item()),
        "path_answer_margin_budget_l2": float(delta.norm().detach().cpu().item()),
        "path_answer_margin_axis_projection_l2": float(axis_projection_l2),
        "path_answer_margin_answer_gain": float(torch.dot(delta, axis_unit).detach().cpu().item()),
        "path_answer_margin_before_margin": float(torch.dot(h, axis_unit).detach().cpu().item()),
        "path_answer_margin_unit_margin_mean": float(active_margins.mean().detach().cpu().item()),
        "path_answer_margin_unit_margin_max": float(active_margins.max().detach().cpu().item()),
        "path_answer_margin_weighted_path_norm": float(
            torch.einsum("n,n->", weights, path_norm[active]).detach().cpu().item()
        ),
        "path_answer_margin_score_mean": float(active_scores.mean().detach().cpu().item()),
    }


def _head_binary_axis_contribution_scores(
    *,
    module: torch.nn.Module,
    contribution: torch.Tensor,
    lm_head: torch.nn.Module,
    yes_id: int,
    no_id: int,
    positive_answer: str | None,
    negative_answer: str | None,
    head_indices: torch.Tensor | None = None,
) -> dict[str, Any]:
    """Per-head logit contribution on an arbitrary binary answer axis."""
    positive = normalize_binary_label(positive_answer)
    negative = normalize_binary_label(negative_answer)
    num_heads = int(contribution.shape[1]) if contribution.ndim >= 2 else 0
    empty = torch.zeros(num_heads, dtype=torch.float32)
    if positive is None or negative is None or positive == negative or num_heads <= 0:
        return {
            "positive_minus_negative": empty,
            "negative_minus_positive": empty,
            "positive_token_id": None,
            "negative_token_id": None,
            "available": False,
            "fallback_reason": "missing_or_degenerate_positive_negative",
        }
    positive_id = int(yes_id if positive == "Yes" else no_id)
    negative_id = int(yes_id if negative == "Yes" else no_id)
    projected = _project_head_contribution_to_hidden(
        module=module,
        contribution=contribution,
        head_indices=head_indices,
    )
    lm_weight = lm_head.weight.detach()
    answer_axis = (
        lm_weight[positive_id].to(device=projected.device, dtype=torch.float32)
        - lm_weight[negative_id].to(device=projected.device, dtype=torch.float32)
    )
    pos_minus_neg = torch.einsum("bhk,k->h", projected, answer_axis).detach().float().cpu()
    neg_minus_pos = -pos_minus_neg
    return {
        "positive_minus_negative": pos_minus_neg,
        "negative_minus_positive": neg_minus_pos,
        "positive_token_id": positive_id,
        "negative_token_id": negative_id,
        "available": True,
        "fallback_reason": None,
    }


def _head_binary_axis_vectors(
    *,
    module: torch.nn.Module,
    lm_head: torch.nn.Module,
    yes_id: int,
    no_id: int,
    positive_answer: str | None,
    negative_answer: str | None,
    num_heads: int,
) -> torch.Tensor | None:
    """Per-head value-space axis whose dot product equals a binary logit shift."""
    positive = normalize_binary_label(positive_answer)
    negative = normalize_binary_label(negative_answer)
    if positive is None or negative is None or positive == negative or int(num_heads) <= 0:
        return None
    positive_id = int(yes_id if positive == "Yes" else no_id)
    negative_id = int(yes_id if negative == "Yes" else no_id)
    out_proj = getattr(module, "o_proj", None)
    if out_proj is None or not hasattr(out_proj, "weight"):
        return None
    weight = out_proj.weight.detach().float()
    lm_weight = lm_head.weight.detach().float().to(device=weight.device)
    if positive_id >= int(lm_weight.shape[0]) or negative_id >= int(lm_weight.shape[0]):
        return None
    hidden_size = int(weight.shape[0])
    if hidden_size != int(weight.shape[1]) or hidden_size != int(lm_weight.shape[1]):
        return None
    head_dim = hidden_size // int(num_heads)
    if hidden_size != int(num_heads) * head_dim:
        return None
    answer_axis = lm_weight[positive_id] - lm_weight[negative_id]
    # Linear layer convention: y = x @ weight.T. Each pre-o_proj head slice maps
    # to hidden space through a contiguous block of weight.T.
    o_slices = weight.t().reshape(int(num_heads), head_dim, hidden_size)
    axis = torch.einsum("hdk,k->hd", o_slices, answer_axis)
    return axis.view(1, int(num_heads), 1, head_dim).detach().float()


def _self_logit_yes_minus_no_margin(
    *,
    lm_head: torch.nn.Module,
    hidden_state: torch.Tensor,
    yes_id: int,
    no_id: int,
    final_norm: torch.nn.Module | None = None,
) -> float:
    """VISTA-style self-logit margin from an intermediate hidden state."""
    hidden = hidden_state.detach()
    if final_norm is not None:
        norm_param = next(final_norm.parameters(), None)
        norm_device = norm_param.device if norm_param is not None else hidden.device
        norm_dtype = norm_param.dtype if norm_param is not None else hidden.dtype
        norm_input = hidden.reshape(1, 1, -1).to(
            device=norm_device,
            dtype=norm_dtype,
        )
        normed = final_norm(norm_input)
        hidden = normed.reshape(-1)
    vec = hidden.float().reshape(-1)
    lm_weight = lm_head.weight.detach().to(device=vec.device, dtype=torch.float32)
    axis = lm_weight[int(yes_id)] - lm_weight[int(no_id)]
    return float(torch.dot(vec, axis).detach().cpu().item())


def _finite_float_or_none(value: Any) -> float | None:
    if value is None:
        return None
    try:
        out = float(value)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(out):
        return None
    return out


def _clamp01(value: float | None) -> float | None:
    if value is None or not math.isfinite(float(value)):
        return None
    return max(0.0, min(1.0, float(value)))


def _positive_answer_axis_score(value: float | None, tau: float = 0.10) -> float | None:
    """Map signed answer-path effect to [0, 1] without rewarding opposite evidence."""
    if value is None or not math.isfinite(float(value)):
        return None
    return max(0.0, min(1.0, 2.0 * _safe_sigmoid_float(float(value) / max(1.0e-6, float(tau))) - 1.0))


def _carrier_trace_activity_from_token_payload(
    token_payload: Mapping[str, Any],
    *,
    max_patched_heads_per_layer: int,
) -> dict[str, Any]:
    """Continuous prior/evidence activity from the token/head carrier tracer.

    The activity is intentionally label-free: source-current paths define prior
    activity, while evidence-candidate paths define evidence activity. Attention
    mass localizes the carrier; answer-axis contribution decides whether the
    carrier actually supports the current/candidate answer.
    """
    selected_head_count = int(token_payload.get("selected_head_count") or 0)
    evidence_carrier_head_count = int(token_payload.get("evidence_carrier_head_count") or 0)
    head_denominator = max(1, int(max_patched_heads_per_layer))
    head_coverage = _clamp01(float(selected_head_count) / float(head_denominator)) or 0.0
    evidence_head_coverage = _clamp01(float(evidence_carrier_head_count) / float(head_denominator)) or 0.0

    source_mass = _clamp01(
        _finite_float_or_none(token_payload.get("source_mass_mean_selected_heads"))
        or _finite_float_or_none(token_payload.get("source_mass_mean_all_heads"))
    )
    evidence_mass = _clamp01(
        _finite_float_or_none(token_payload.get("evidence_carrier_mass_mean"))
        or _finite_float_or_none(token_payload.get("evidence_mass_mean_selected_heads"))
        or _finite_float_or_none(token_payload.get("evidence_mass_mean_all_heads"))
    )
    source_answer = _positive_answer_axis_score(
        _finite_float_or_none(token_payload.get("answer_current_over_candidate_mean_selected_heads"))
    )
    evidence_answer = _positive_answer_axis_score(
        _finite_float_or_none(token_payload.get("evidence_carrier_candidate_over_current_mean"))
        or _finite_float_or_none(token_payload.get("answer_candidate_over_current_mean_selected_heads"))
    )
    evidence_sensitivity = _clamp01(
        _finite_float_or_none(token_payload.get("evidence_carrier_sensitivity_mean"))
    )

    def combine(mass: float | None, answer: float | None) -> tuple[float, str]:
        if mass is None and answer is None:
            return 0.0, "no_trace"
        if mass is None:
            return float(answer) * head_coverage, "answer_only"
        if answer is None:
            return float(mass) * head_coverage, "mass_only"
        return math.sqrt(max(0.0, float(mass)) * max(0.0, float(answer))) * head_coverage, "mass_answer"

    prior_activity, prior_activity_source = combine(source_mass, source_answer)
    direct_evidence_activity = _finite_float_or_none(token_payload.get("evidence_carrier_activity"))
    if direct_evidence_activity is not None:
        evidence_activity = float(direct_evidence_activity)
        evidence_activity_source = "independent_evidence_carrier"
    else:
        evidence_activity, evidence_activity_source = combine(evidence_mass, evidence_answer)
    return {
        "carrier_trace_selected_head_count": selected_head_count,
        "carrier_trace_evidence_carrier_head_count": evidence_carrier_head_count,
        "carrier_trace_head_coverage": float(head_coverage),
        "carrier_trace_evidence_head_coverage": float(evidence_head_coverage),
        "carrier_trace_source_mass": source_mass,
        "carrier_trace_evidence_mass": evidence_mass,
        "carrier_trace_source_answer_score": source_answer,
        "carrier_trace_evidence_answer_score": evidence_answer,
        "carrier_trace_evidence_sensitivity": evidence_sensitivity,
        "carrier_trace_prior_activity": float(max(0.0, min(1.0, prior_activity))),
        "carrier_trace_evidence_activity": float(max(0.0, min(1.0, evidence_activity))),
        "carrier_trace_prior_activity_source": prior_activity_source,
        "carrier_trace_evidence_activity_source": evidence_activity_source,
        "carrier_trace_activity_available": bool(
            (selected_head_count > 0 and source_mass is not None)
            or (evidence_carrier_head_count > 0 and evidence_mass is not None)
        ),
    }


def _mean_binary_margin(values: Iterable[Any]) -> float | None:
    margins = [item for item in (_finite_float_or_none(value) for value in values) if item is not None]
    if not margins:
        return None
    return float(sum(margins) / float(len(margins)))


def _max_view_answer_support(
    *,
    margins: Iterable[Any],
    answer: str | None,
    tau: float = 0.10,
) -> float | None:
    """Max continuous branch support for an answer on the Yes/No margin axis."""
    label = normalize_binary_label(answer)
    if label is None:
        return None
    scores: list[float] = []
    for margin in margins:
        value = _finite_float_or_none(margin)
        if value is None:
            continue
        signed = signed_margin_for_answer(float(value), label)
        if signed is None:
            continue
        scores.append(_safe_sigmoid_float(float(signed) / max(1.0e-6, float(tau))))
    if not scores:
        return None
    return float(max(scores))


def _hidden_answer_trust_region_update(
    *,
    base: torch.Tensor,
    update_delta: torch.Tensor,
    lm_head: torch.nn.Module,
    yes_id: int,
    no_id: int,
    current_answer: str | None,
    candidate_answer: str | None,
    mode: str,
    current_protection_weight: float,
    carrier_consensus_margin: float | None,
    text_plausibility_margin: float | None = None,
    text_plausibility_threshold: float = 1.5,
    text_plausibility_tau: float = 0.5,
    floor: float = 0.0,
    tau: float = 0.10,
) -> dict[str, Any]:
    """Minimum-norm hidden update correction that preserves a supported answer axis.

    The correction is continuous and local to the hidden update. It is active only
    when the current answer is already locally supported by the hidden state and
    the proposed update would move it outside the requested half-space.
    """
    mode_key = safe_text(mode) or "none"
    if mode_key == "none":
        return {
            "update": update_delta,
            "available": False,
            "active": False,
            "mode": mode_key,
            "reason": "disabled",
            "strength": 0.0,
            "correction_l2": 0.0,
            "text_plausibility_margin": _finite_float_or_none(text_plausibility_margin),
            "text_plausibility_threshold": float(text_plausibility_threshold),
            "text_plausibility_deficit": None,
            "text_plausibility_update_scale": 1.0,
            "text_plausibility_scaling_l2": 0.0,
        }
    current = normalize_binary_label(current_answer)
    candidate = normalize_binary_label(candidate_answer)
    if current is None or candidate is None or current == candidate:
        return {
            "update": update_delta,
            "available": False,
            "active": False,
            "mode": mode_key,
            "reason": "missing_or_degenerate_candidate_current",
            "strength": 0.0,
            "correction_l2": 0.0,
            "text_plausibility_margin": _finite_float_or_none(text_plausibility_margin),
            "text_plausibility_threshold": float(text_plausibility_threshold),
            "text_plausibility_deficit": None,
            "text_plausibility_update_scale": 1.0,
            "text_plausibility_scaling_l2": 0.0,
        }
    current_id = int(yes_id if current == "Yes" else no_id)
    candidate_id = int(yes_id if candidate == "Yes" else no_id)
    lm_weight = lm_head.weight.detach().to(device=base.device, dtype=torch.float32)
    if current_id >= int(lm_weight.shape[0]) or candidate_id >= int(lm_weight.shape[0]):
        return {
            "update": update_delta,
            "available": False,
            "active": False,
            "mode": mode_key,
            "reason": "answer_token_out_of_range",
            "strength": 0.0,
            "correction_l2": 0.0,
            "text_plausibility_margin": _finite_float_or_none(text_plausibility_margin),
            "text_plausibility_threshold": float(text_plausibility_threshold),
            "text_plausibility_deficit": None,
            "text_plausibility_update_scale": 1.0,
            "text_plausibility_scaling_l2": 0.0,
        }
    axis = lm_weight[current_id] - lm_weight[candidate_id]
    axis_norm_sq = torch.dot(axis, axis).clamp_min(1.0e-12)
    base_margin = torch.dot(base.float(), axis)
    raw_shift = torch.dot(update_delta.float(), axis)
    raw_after = base_margin + raw_shift
    floor_value = float(floor)
    if float(base_margin.detach().cpu().item()) < floor_value:
        return {
            "update": update_delta,
            "available": True,
            "active": False,
            "mode": mode_key,
            "reason": "base_not_current_supporting",
            "strength": 0.0,
            "base_margin": float(base_margin.detach().cpu().item()),
            "raw_shift": float(raw_shift.detach().cpu().item()),
            "raw_after_margin": float(raw_after.detach().cpu().item()),
            "corrected_after_margin": float(raw_after.detach().cpu().item()),
            "floor": floor_value,
            "correction_l2": 0.0,
            "text_plausibility_margin": _finite_float_or_none(text_plausibility_margin),
            "text_plausibility_threshold": float(text_plausibility_threshold),
            "text_plausibility_deficit": None,
            "text_plausibility_update_scale": 1.0,
            "text_plausibility_scaling_l2": 0.0,
        }
    text_update_scale = 1.0
    text_scaling_l2 = 0.0
    if mode_key == "current_protection":
        strength = max(0.0, min(1.0, float(current_protection_weight)))
    elif mode_key == "carrier_consensus":
        signed_consensus = None
        consensus_value = _finite_float_or_none(carrier_consensus_margin)
        if consensus_value is not None:
            signed_consensus = signed_margin_for_answer(float(consensus_value), current)
        if signed_consensus is None or float(signed_consensus) <= 0.0:
            strength = 0.0
        else:
            # Zero at the decision boundary, then smoothly approaches one.
            strength = max(
                0.0,
                min(
                    1.0,
                    2.0 * _safe_sigmoid_float(float(signed_consensus) / max(1.0e-6, float(tau))) - 1.0,
                ),
            )
    elif mode_key == "text_plausibility":
        plausibility_margin = _finite_float_or_none(text_plausibility_margin)
        plausibility_threshold = float(text_plausibility_threshold)
        plausibility_tau = max(1.0e-6, float(text_plausibility_tau))
        if plausibility_margin is None:
            # If the certificate is unavailable, keep the hidden update conservative.
            plausibility_deficit = plausibility_tau
        else:
            plausibility_deficit = plausibility_threshold - float(plausibility_margin)
        strength = max(0.0, min(1.0, float(plausibility_deficit) / plausibility_tau))
        text_update_scale = 1.0 - float(strength)
    else:
        raise ValueError(f"unknown hidden_answer_trust_region_mode: {mode}")
    text_margin_value = _finite_float_or_none(text_plausibility_margin)
    text_threshold_value = float(text_plausibility_threshold)
    text_deficit_value = (
        None if text_margin_value is None else float(text_threshold_value - float(text_margin_value))
    )
    if mode_key == "text_plausibility" and text_update_scale < 1.0 - 1.0e-12:
        original_update = update_delta.float()
        scaled_update = original_update * float(text_update_scale)
        text_scaling_l2 = float((original_update - scaled_update).norm().detach().cpu().item())
        update_delta = scaled_update.to(device=update_delta.device, dtype=update_delta.dtype)
        raw_shift = torch.dot(update_delta.float(), axis)
        raw_after = base_margin + raw_shift
    violation = torch.tensor(floor_value, device=base.device, dtype=torch.float32) - raw_after
    if strength <= 1.0e-12 or float(violation.detach().cpu().item()) <= 0.0:
        scaled_active = bool(text_scaling_l2 > 1.0e-12)
        return {
            "update": update_delta,
            "available": True,
            "active": scaled_active,
            "mode": mode_key,
            "reason": "scaled_by_text_plausibility" if scaled_active else "no_violation_or_zero_strength",
            "strength": float(strength),
            "base_margin": float(base_margin.detach().cpu().item()),
            "raw_shift": float(raw_shift.detach().cpu().item()),
            "raw_after_margin": float(raw_after.detach().cpu().item()),
            "corrected_after_margin": float(raw_after.detach().cpu().item()),
            "floor": floor_value,
            "violation": max(0.0, float(violation.detach().cpu().item())),
            "correction_l2": 0.0,
            "text_plausibility_margin": text_margin_value,
            "text_plausibility_threshold": text_threshold_value,
            "text_plausibility_deficit": text_deficit_value,
            "text_plausibility_update_scale": float(text_update_scale),
            "text_plausibility_scaling_l2": float(text_scaling_l2),
        }
    correction = float(strength) * violation * axis / axis_norm_sq
    corrected_update = update_delta.float() + correction
    corrected_after = base_margin + torch.dot(corrected_update, axis)
    return {
        "update": corrected_update.to(device=update_delta.device, dtype=update_delta.dtype),
        "available": True,
        "active": True,
        "mode": mode_key,
        "reason": "projected_to_answer_halfspace",
        "strength": float(strength),
        "base_margin": float(base_margin.detach().cpu().item()),
        "raw_shift": float(raw_shift.detach().cpu().item()),
        "raw_after_margin": float(raw_after.detach().cpu().item()),
        "corrected_after_margin": float(corrected_after.detach().cpu().item()),
        "floor": floor_value,
        "violation": max(0.0, float(violation.detach().cpu().item())),
        "correction_l2": float(correction.norm().detach().cpu().item()),
        "text_plausibility_margin": text_margin_value,
        "text_plausibility_threshold": text_threshold_value,
        "text_plausibility_deficit": text_deficit_value,
        "text_plausibility_update_scale": float(text_update_scale),
        "text_plausibility_scaling_l2": float(text_scaling_l2),
    }


def _output_answer_trust_region_logits(
    logits: torch.Tensor,
    *,
    current_answer: str | None,
    candidate_answer: str | None,
    mode: str,
    current_protection_weight: float,
    carrier_consensus_margin: float | None,
    floor: float = 0.0,
    tau: float = 0.10,
) -> tuple[torch.Tensor, dict[str, Any]]:
    """Minimum yes/no-logit correction that keeps supported current answer stable."""
    mode_key = safe_text(mode) or "none"
    if mode_key == "none":
        return logits, {
            "output_answer_trust_region_mode": mode_key,
            "output_answer_trust_region_available": False,
            "output_answer_trust_region_active": False,
            "output_answer_trust_region_reason": "disabled",
            "output_answer_trust_region_strength": 0.0,
        }
    current = normalize_binary_label(current_answer)
    candidate = normalize_binary_label(candidate_answer)
    if current is None or candidate is None or current == candidate or logits.numel() < 2:
        return logits, {
            "output_answer_trust_region_mode": mode_key,
            "output_answer_trust_region_available": False,
            "output_answer_trust_region_active": False,
            "output_answer_trust_region_reason": "missing_or_degenerate_candidate_current",
            "output_answer_trust_region_strength": 0.0,
        }

    if mode_key == "current_protection":
        strength = max(0.0, min(1.0, float(current_protection_weight)))
    elif mode_key == "carrier_consensus":
        signed_consensus = None
        consensus_value = _finite_float_or_none(carrier_consensus_margin)
        if consensus_value is not None:
            signed_consensus = signed_margin_for_answer(float(consensus_value), current)
        if signed_consensus is None or float(signed_consensus) <= 0.0:
            strength = 0.0
        else:
            strength = max(
                0.0,
                min(
                    1.0,
                    2.0 * _safe_sigmoid_float(float(signed_consensus) / max(1.0e-6, float(tau))) - 1.0,
                ),
            )
    else:
        raise ValueError(f"unknown output_answer_trust_region_mode: {mode}")

    corrected = logits.clone()
    margin_yes_minus_no = (corrected[:, 0] - corrected[:, 1]).float()
    current_margin = margin_yes_minus_no if current == "Yes" else -margin_yes_minus_no
    floor_value = float(floor)
    violation = torch.tensor(floor_value, device=corrected.device, dtype=torch.float32) - current_margin
    max_violation = float(torch.clamp(violation, min=0.0).max().detach().cpu().item())
    before_margin = float(current_margin.detach().float().mean().cpu().item())
    if strength > 1.0e-12 and max_violation > 0.0:
        correction = float(strength) * torch.clamp(violation, min=0.0)
        if current == "Yes":
            corrected[:, 0] = corrected[:, 0] + 0.5 * correction.to(dtype=corrected.dtype)
            corrected[:, 1] = corrected[:, 1] - 0.5 * correction.to(dtype=corrected.dtype)
        else:
            corrected[:, 0] = corrected[:, 0] - 0.5 * correction.to(dtype=corrected.dtype)
            corrected[:, 1] = corrected[:, 1] + 0.5 * correction.to(dtype=corrected.dtype)
    after_margin_tensor = (corrected[:, 0] - corrected[:, 1]).float()
    after_current_margin = after_margin_tensor if current == "Yes" else -after_margin_tensor
    return corrected, {
        "output_answer_trust_region_mode": mode_key,
        "output_answer_trust_region_available": True,
        "output_answer_trust_region_active": bool(strength > 1.0e-12 and max_violation > 0.0),
        "output_answer_trust_region_reason": (
            "projected_to_answer_halfspace"
            if strength > 1.0e-12 and max_violation > 0.0
            else "no_violation_or_zero_strength"
        ),
        "output_answer_trust_region_strength": float(strength),
        "output_answer_trust_region_floor": floor_value,
        "output_answer_trust_region_before_current_margin": before_margin,
        "output_answer_trust_region_after_current_margin": float(
            after_current_margin.detach().float().mean().cpu().item()
        ),
        "output_answer_trust_region_violation": max_violation,
        "output_answer_trust_region_consensus_margin": _finite_float_or_none(carrier_consensus_margin),
    }


def _carrier_consensus_calibrated_anchor(
    *,
    early_anchor_margin: float,
    carrier_consensus_margin: float | None,
    soft_disagreement: bool = False,
) -> tuple[float, float | None]:
    """Continuously align a local early anchor with multi-carrier evidence.

    If the early self-logit and carrier consensus agree, tanh(m*c) keeps the
    local anchor direction. If they disagree, the default safe variant disables
    the anchor instead of flipping it into another shortcut. The explicit soft
    ablation uses 1/(1+|m*c|) under disagreement.
    """
    if carrier_consensus_margin is None:
        return float(early_anchor_margin), None
    product = float(early_anchor_margin) * float(carrier_consensus_margin)
    if product >= 0.0:
        alignment = math.tanh(product)
    elif not soft_disagreement:
        alignment = 0.0
    else:
        alignment = 1.0 / (1.0 + abs(product))
    return float(early_anchor_margin) * float(alignment), float(alignment)


def _redistribute_attention_row_with_masks(
    row: torch.Tensor,
    *,
    selected_heads: torch.Tensor,
    source_mask: torch.Tensor,
    evidence_mask: torch.Tensor,
    beta_for_layer: float,
    alpha_for_layer: float,
    alpha_mode: str,
) -> tuple[torch.Tensor, dict[str, float]]:
    edited = row.clone()
    if selected_heads.numel() <= 0 or not bool(source_mask.any().detach().cpu().item()):
        return edited, {"removed_source_mass": 0.0, "transferred_evidence_mass": 0.0}
    heads = selected_heads.to(device=row.device)
    edited_heads = edited[:, heads, :].clone()
    src_mask = source_mask[:, heads, :].to(device=row.device).bool()
    evi_mask = evidence_mask[:, heads, :].to(device=row.device).bool()
    source_values = torch.where(src_mask, edited_heads, torch.zeros_like(edited_heads))
    scaled_source_values = source_values * max(0.0, 1.0 - float(beta_for_layer))
    removed = source_values - scaled_source_values
    edited_heads = torch.where(src_mask, scaled_source_values, edited_heads)
    transferred_mass = torch.zeros(
        edited_heads.shape[0],
        edited_heads.shape[1],
        1,
        device=edited_heads.device,
        dtype=edited_heads.dtype,
    )
    if safe_text(alpha_mode) == "attention_transfer" and bool(evi_mask.any().detach().cpu().item()):
        transfer = removed.sum(dim=-1, keepdim=True) * max(0.0, float(alpha_for_layer))
        evidence_values = torch.where(evi_mask, edited_heads, torch.zeros_like(edited_heads))
        evidence_mass = evidence_values.sum(dim=-1, keepdim=True)
        evi_count = evi_mask.float().sum(dim=-1, keepdim=True).clamp_min(1.0)
        uniform = evi_mask.float() / evi_count
        proportional = evidence_values / evidence_mass.clamp_min(1.0e-8)
        addition_weights = torch.where(evidence_mass > 1.0e-8, proportional, uniform)
        edited_heads = edited_heads + addition_weights.to(dtype=edited_heads.dtype) * transfer
        transferred_mass = transfer
    edited[:, heads, :] = edited_heads / edited_heads.sum(dim=-1, keepdim=True).clamp_min(1.0e-8)
    return edited, {
        "removed_source_mass": float(removed.sum().detach().float().cpu().item()),
        "transferred_evidence_mass": float(transferred_mass.sum().detach().float().cpu().item()),
    }


def _oelpr_attention_transport_row_with_masks(
    row: torch.Tensor,
    *,
    source_mask: torch.Tensor,
    evidence_mask: torch.Tensor,
    source_gate: torch.Tensor | None = None,
    evidence_gate: torch.Tensor | None = None,
    source_mass: torch.Tensor,
    evidence_mass: torch.Tensor,
    beta_for_layer: float,
    alpha_for_layer: float,
    alpha_mode: str,
    source_current_over_candidate: torch.Tensor | None = None,
    evidence_candidate_over_current: torch.Tensor | None = None,
    current_protection_weight: float | None = None,
) -> tuple[torch.Tensor, dict[str, Any]]:
    """O-ELPR attention transport.

    This operator keeps the O-ELPR path weights but applies them to the
    final-query attention row: mass removed from shortcut/source tokens is
    transported to evidence tokens in the same head before recomputing the
    value-path output.
    """
    edited = row.float().clone()
    num_heads = int(edited.shape[1])
    src_mask = source_mask.to(device=edited.device).bool()
    evi_mask = evidence_mask.to(device=edited.device).bool()
    if int(src_mask.shape[1]) != num_heads or int(evi_mask.shape[1]) != num_heads:
        raise ValueError(
            "O-ELPR attention transport expects source/evidence masks for all heads, "
            f"got source={tuple(source_mask.shape)} evidence={tuple(evidence_mask.shape)} row={tuple(row.shape)}"
        )
    if source_gate is None:
        src_gate = src_mask.float()
    else:
        src_gate = source_gate.to(device=edited.device, dtype=torch.float32).clamp(0.0, 1.0)
        src_gate = torch.where(src_mask, src_gate, torch.zeros_like(src_gate))
    if evidence_gate is None:
        evi_gate = evi_mask.float()
    else:
        evi_gate = evidence_gate.to(device=edited.device, dtype=torch.float32).clamp(0.0, 1.0)
        evi_gate = torch.where(evi_mask, evi_gate, torch.zeros_like(evi_gate))
    src_mass = source_mass.detach().float().to(device=edited.device).clamp_min(0.0)
    evi_mass = evidence_mass.detach().float().to(device=edited.device).clamp_min(0.0)
    if int(src_mass.numel()) != num_heads or int(evi_mass.numel()) != num_heads:
        raise ValueError(
            "O-ELPR attention transport expects one mass score per head "
            f"({int(src_mass.numel())}, {int(evi_mass.numel())}) != {num_heads}"
        )

    mass_temperature = 0.02
    answer_temperature = 0.001
    beta_value = max(0.0, float(beta_for_layer))
    alpha_value = max(0.0, float(alpha_for_layer))
    protection_value = max(0.0, min(1.0, float(current_protection_weight or 0.0)))

    source_answer_scores = None
    evidence_answer_scores = None
    if source_current_over_candidate is None:
        source_answer_weight = torch.ones(num_heads, device=edited.device, dtype=torch.float32)
    else:
        source_answer_scores = source_current_over_candidate.detach().float().to(device=edited.device)
        if int(source_answer_scores.numel()) != num_heads:
            raise ValueError(
                "source_current_over_candidate must have one score per head "
                f"({int(source_answer_scores.numel())} != {num_heads})"
            )
        source_answer_weight = torch.sigmoid(source_answer_scores / answer_temperature)
    if evidence_candidate_over_current is None:
        evidence_answer_weight = torch.ones(num_heads, device=edited.device, dtype=torch.float32)
    else:
        evidence_answer_scores = evidence_candidate_over_current.detach().float().to(device=edited.device)
        if int(evidence_answer_scores.numel()) != num_heads:
            raise ValueError(
                "evidence_candidate_over_current must have one score per head "
                f"({int(evidence_answer_scores.numel())} != {num_heads})"
            )
        evidence_answer_weight = torch.sigmoid(evidence_answer_scores / answer_temperature)

    carrier_score = (src_mass - evi_mass) / mass_temperature
    source_carrier_weight = torch.sigmoid(carrier_score)
    evidence_carrier_weight = 1.0 - source_carrier_weight
    source_current_preservation = (protection_value * source_answer_weight).clamp(0.0, 1.0)
    source_suppression_scale = (1.0 - source_current_preservation).clamp(0.10, 1.0)
    evidence_reinforcement_scale = (
        1.0 + protection_value * evidence_answer_weight * (1.0 - source_answer_weight)
    ).clamp(1.0, 1.50)
    source_path_weight = source_carrier_weight * source_answer_weight * source_suppression_scale
    evidence_path_weight = evidence_carrier_weight * evidence_answer_weight * evidence_reinforcement_scale

    transport_strength = (beta_value * source_path_weight).clamp(0.0, 0.95).view(1, num_heads, 1)
    if safe_text(alpha_mode) in {"evidence_value_boost", "attention_transfer"}:
        evidence_acceptance = (evidence_path_weight * (1.0 + alpha_value)).clamp(0.0, 1.0)
    else:
        evidence_acceptance = torch.zeros_like(evidence_path_weight)
    evidence_acceptance = evidence_acceptance.view(1, num_heads, 1)

    source_values = edited * src_gate.to(dtype=edited.dtype)
    removed = source_values * transport_strength
    edited_heads = edited - removed

    transferred_mass = torch.zeros(
        edited_heads.shape[0],
        edited_heads.shape[1],
        1,
        device=edited_heads.device,
        dtype=edited_heads.dtype,
    )
    if bool((evi_gate > 0.0).any().detach().cpu().item()):
        transfer = removed.sum(dim=-1, keepdim=True) * evidence_acceptance
        evidence_values = edited_heads * evi_gate.to(dtype=edited_heads.dtype)
        evidence_sum = evidence_values.sum(dim=-1, keepdim=True)
        evi_gate_sum = evi_gate.sum(dim=-1, keepdim=True).clamp_min(1.0e-8)
        uniform = evi_gate / evi_gate_sum
        proportional = evidence_values / evidence_sum.clamp_min(1.0e-8)
        addition_weights = torch.where(evidence_sum > 1.0e-8, proportional, uniform)
        edited_heads = edited_heads + addition_weights.to(dtype=edited_heads.dtype) * transfer
        transferred_mass = transfer

    edited = edited_heads / edited_heads.sum(dim=-1, keepdim=True).clamp_min(1.0e-8)

    prior_heads = torch.nonzero((source_path_weight > 0.5).detach().cpu(), as_tuple=False).flatten()
    evidence_heads = torch.nonzero(
        (evidence_path_weight >= source_path_weight).detach().cpu(),
        as_tuple=False,
    ).flatten()

    def mean_value(values: torch.Tensor) -> float:
        return float(values.detach().float().mean().cpu().item())

    def min_value(values: torch.Tensor) -> float:
        return float(values.detach().float().min().cpu().item())

    def max_value(values: torch.Tensor) -> float:
        return float(values.detach().float().max().cpu().item())

    removed_mass_value = float(removed.sum().detach().float().cpu().item())
    transferred_mass_value = float(transferred_mass.sum().detach().float().cpu().item())
    source_gate_sum = src_gate.sum(dim=-1)
    evidence_gate_sum = evi_gate.sum(dim=-1)
    return edited.to(dtype=row.dtype), {
        "oelpr_mass_temperature": float(mass_temperature),
        "oelpr_answer_temperature": float(answer_temperature),
        "oelpr_current_protection_weight": float(protection_value),
        "oelpr_carrier_score_mean": mean_value(carrier_score),
        "oelpr_carrier_score_min": min_value(carrier_score),
        "oelpr_carrier_score_max": max_value(carrier_score),
        "oelpr_source_carrier_weight_mean": mean_value(source_carrier_weight),
        "oelpr_source_carrier_weight_min": min_value(source_carrier_weight),
        "oelpr_source_carrier_weight_max": max_value(source_carrier_weight),
        "oelpr_evidence_carrier_weight_mean": mean_value(evidence_carrier_weight),
        "oelpr_evidence_carrier_weight_min": min_value(evidence_carrier_weight),
        "oelpr_evidence_carrier_weight_max": max_value(evidence_carrier_weight),
        "oelpr_source_answer_weight_mean": mean_value(source_answer_weight),
        "oelpr_source_answer_weight_min": min_value(source_answer_weight),
        "oelpr_source_answer_weight_max": max_value(source_answer_weight),
        "oelpr_evidence_answer_weight_mean": mean_value(evidence_answer_weight),
        "oelpr_evidence_answer_weight_min": min_value(evidence_answer_weight),
        "oelpr_evidence_answer_weight_max": max_value(evidence_answer_weight),
        "oelpr_source_current_preservation_mean": mean_value(source_current_preservation),
        "oelpr_source_current_preservation_min": min_value(source_current_preservation),
        "oelpr_source_current_preservation_max": max_value(source_current_preservation),
        "oelpr_source_suppression_scale_mean": mean_value(source_suppression_scale),
        "oelpr_source_suppression_scale_min": min_value(source_suppression_scale),
        "oelpr_source_suppression_scale_max": max_value(source_suppression_scale),
        "oelpr_evidence_reinforcement_scale_mean": mean_value(evidence_reinforcement_scale),
        "oelpr_evidence_reinforcement_scale_min": min_value(evidence_reinforcement_scale),
        "oelpr_evidence_reinforcement_scale_max": max_value(evidence_reinforcement_scale),
        "oelpr_source_path_weight_mean": mean_value(source_path_weight),
        "oelpr_source_path_weight_min": min_value(source_path_weight),
        "oelpr_source_path_weight_max": max_value(source_path_weight),
        "oelpr_evidence_path_weight_mean": mean_value(evidence_path_weight),
        "oelpr_evidence_path_weight_min": min_value(evidence_path_weight),
        "oelpr_evidence_path_weight_max": max_value(evidence_path_weight),
        "oelpr_prior_dominant_head_count": int(prior_heads.numel()),
        "oelpr_evidence_dominant_head_count": int(evidence_heads.numel()),
        "oelpr_prior_dominant_heads": [int(x) for x in prior_heads.tolist()],
        "oelpr_evidence_dominant_heads": [int(x) for x in evidence_heads.tolist()],
        "oelpr_source_current_over_candidate_mean": (
            float(source_answer_scores.mean().detach().cpu().item())
            if source_answer_scores is not None
            else None
        ),
        "oelpr_evidence_candidate_over_current_mean": (
            float(evidence_answer_scores.mean().detach().cpu().item())
            if evidence_answer_scores is not None
            else None
        ),
        "attention_transport_removed_source_mass": removed_mass_value,
        "attention_transport_transferred_evidence_mass": transferred_mass_value,
        "attention_transport_transfer_ratio": (
            transferred_mass_value / removed_mass_value if removed_mass_value > 1.0e-12 else 0.0
        ),
        "attention_transport_strength_mean": mean_value(transport_strength),
        "attention_transport_strength_max": max_value(transport_strength),
        "attention_transport_evidence_acceptance_mean": mean_value(evidence_acceptance),
        "attention_transport_evidence_acceptance_max": max_value(evidence_acceptance),
        "attention_transport_source_gate_sum_mean": mean_value(source_gate_sum),
        "attention_transport_source_gate_sum_max": max_value(source_gate_sum),
        "attention_transport_evidence_gate_sum_mean": mean_value(evidence_gate_sum),
        "attention_transport_evidence_gate_sum_max": max_value(evidence_gate_sum),
        "head_transport_delta_l2": 0.0,
        "head_transport_prior_delta_l2": 0.0,
        "head_transport_transport_delta_l2": 0.0,
        "head_transport_compensation_delta_l2": 0.0,
        "head_transport_alpha_ratio": float(alpha_value),
        "head_transport_u_p_abs_cos": None,
        "head_transport_valid_prior_ratio": None,
        "head_transport_valid_evidence_ratio": None,
    }


def _redistribute_attention_row(
    row: torch.Tensor,
    *,
    selected_heads: torch.Tensor,
    source_positions: torch.Tensor,
    evidence_positions: torch.Tensor,
    beta_for_layer: float,
    alpha_for_layer: float,
    alpha_mode: str,
) -> tuple[torch.Tensor, dict[str, float]]:
    edited = row.clone()
    if selected_heads.numel() <= 0 or source_positions.numel() <= 0:
        return edited, {"removed_source_mass": 0.0, "transferred_evidence_mass": 0.0}
    heads = selected_heads.to(device=row.device)
    src = source_positions.to(device=row.device)
    evi = evidence_positions.to(device=row.device)
    before_source = edited[:, heads, :][:, :, src].sum(dim=-1, keepdim=True)
    source_slice = edited[:, heads, :][:, :, src]
    scaled_source = source_slice * max(0.0, 1.0 - float(beta_for_layer))
    removed = source_slice - scaled_source
    edited_heads = edited[:, heads, :].clone()
    edited_heads[:, :, src] = scaled_source
    transferred_mass = torch.zeros_like(before_source)
    if safe_text(alpha_mode) == "attention_transfer" and evi.numel() > 0:
        transfer = removed.sum(dim=-1, keepdim=True) * max(0.0, float(alpha_for_layer))
        evidence_slice = edited_heads[:, :, evi]
        evidence_mass = evidence_slice.sum(dim=-1, keepdim=True)
        if bool(torch.all(evidence_mass <= 1.0e-8)):
            addition = transfer / float(evi.numel())
        else:
            addition = evidence_slice / evidence_mass.clamp_min(1.0e-8) * transfer
        edited_heads[:, :, evi] = evidence_slice + addition
        transferred_mass = transfer
    edited[:, heads, :] = edited_heads / edited_heads.sum(dim=-1, keepdim=True).clamp_min(1.0e-8)
    return edited, {
        "removed_source_mass": float(removed.sum().detach().float().cpu().item()),
        "transferred_evidence_mass": float(transferred_mass.sum().detach().float().cpu().item()),
    }


def patched_token_head_value_suppression_logits(
    adapter: QwenOmniAdapter,
    *,
    row: Mapping[str, Any],
    layer_group: Sequence[int],
    layer_weights: Mapping[int, float] | None,
    evidence_layer_weights: Mapping[int, float] | None,
    prior_layer_weights: Mapping[int, float] | None,
    beta: float,
    alpha: float,
    yes_id: int,
    no_id: int,
    current_answer: str | None,
    candidate_answer: str | None,
    runtime_full_answer: str | None = None,
    runtime_target_answer: str | None = None,
    runtime_non_target_answer: str | None = None,
    runtime_text_answer: str | None = None,
    budget: Mapping[str, float],
    source_prior_token_group: str,
    evidence_token_group: str,
    head_selection_mode: str,
    max_patched_heads_per_layer: int,
    head_source_margin_min: float,
    head_source_mass_min: float,
    head_answer_contribution_min: float,
    source_token_selection_mode: str,
    source_token_top_k: int,
    source_token_min_attn: float,
    evidence_token_selection_mode: str,
    evidence_token_top_k: int,
    evidence_token_min_attn: float,
    operator: str,
    alpha_mode: str,
    token_head_alpha_layer_policy: str,
    seed: int,
) -> dict[str, Any]:
    inputs = prepare_branch_inputs(adapter, row=dict(row), branch="full", budget=dict(budget))
    thinker = adapter._model.thinker
    lm_head = thinker.lm_head
    layers = [int(layer) for layer in layer_group]
    if not layers:
        raise ValueError("layer_group must not be empty")
    if layer_weights is None:
        weights = {layer: 1.0 / float(len(layers)) for layer in layers}
    else:
        total = sum(float(layer_weights.get(layer, 0.0)) for layer in layers)
        if total <= 0.0:
            raise ValueError(f"layer weights must sum to a positive value for group {layers}")
        weights = {layer: float(layer_weights.get(layer, 0.0)) / total for layer in layers}
    alpha_weights = _token_head_alpha_weights_for_policy(
        policy=str(token_head_alpha_layer_policy),
        operator=str(operator),
        layers=layers,
        layer_weights=weights,
        evidence_layer_weights=evidence_layer_weights if evidence_layer_weights is not None else weights,
        prior_layer_weights=prior_layer_weights if prior_layer_weights is not None else weights,
    )
    if safe_text(operator) == "head_subspace_transport":
        beta_weights = dict(alpha_weights)
    elif prior_layer_weights is None:
        beta_weights = dict(weights)
    else:
        total = sum(float(prior_layer_weights.get(layer, 0.0)) for layer in layers)
        if total <= 0.0:
            raise ValueError(f"prior layer weights have no overlap with layer group {layers}")
        beta_weights = {layer: float(prior_layer_weights.get(layer, 0.0)) / total for layer in layers}

    attention_mask = inputs.get("attention_mask")
    if attention_mask is None:
        attention_mask = torch.ones_like(inputs["input_ids"])
    special_ids = tokenizer_ids(adapter)
    label_masks = resolve_avcd_label_masks(
        input_ids=inputs["input_ids"].detach().cpu(),
        attention_mask=attention_mask.detach().cpu(),
        special_ids=special_ids,
    )
    causallens_system_positions = _resolve_causallens_system_positions(
        input_ids=inputs["input_ids"],
        attention_mask=attention_mask,
        special_ids=special_ids,
    )
    source_positions = _resolve_token_group_positions(
        label_masks=label_masks,
        group=source_prior_token_group,
        target_modality=safe_text(row.get("target_modality")),
    )
    evidence_positions = _resolve_token_group_positions(
        label_masks=label_masks,
        group=evidence_token_group,
        target_modality=safe_text(row.get("target_modality")),
    )
    if source_positions.numel() <= 0:
        raise ValueError(
            f"empty source-prior token group={source_prior_token_group} sample={safe_text(row.get('sample_id'))}"
        )
    if evidence_positions.numel() <= 0:
        raise ValueError(
            f"empty evidence token group={evidence_token_group} sample={safe_text(row.get('sample_id'))}"
        )

    selected_layer_set = set(layers)
    debug_by_layer: dict[str, dict[str, Any]] = {}
    patched_outputs: dict[int, torch.Tensor] = {}
    hooks = []

    def make_pre_hook(layer_id: int):
        beta_for_layer = float(beta) * float(beta_weights.get(int(layer_id), 0.0))
        alpha_for_layer = float(alpha) * float(alpha_weights.get(int(layer_id), 0.0))

        def hook_fn(module, args, kwargs):
            hidden_states = args[0] if args else kwargs.get("hidden_states")
            position_embeddings = kwargs.get("position_embeddings")
            if hidden_states is None or position_embeddings is None or int(layer_id) not in selected_layer_set:
                return None
            if hidden_states.shape[1] <= 1:
                return None
            operator_key = safe_text(operator)
            selection_key = safe_text(head_selection_mode)
            alpha_active = safe_text(alpha_mode) in {"evidence_value_boost", "attention_transfer"}
            if abs(float(beta_for_layer)) <= 1.0e-12 and (
                not alpha_active or abs(float(alpha_for_layer)) <= 1.0e-12
            ):
                debug_by_layer[str(layer_id)] = {
                    "selected_head_count": 0,
                    "selected_heads": [],
                    "beta_for_layer": beta_for_layer,
                    "alpha_for_layer": alpha_for_layer,
                    "operator": operator_key,
                    "alpha_mode": safe_text(alpha_mode),
                    "alpha_layer_policy": safe_text(token_head_alpha_layer_policy),
                    "skip_reason": "zero_token_head_intervention_weight",
                }
                return None
            attn_mask = kwargs.get("attention_mask")
            attn_row, value_states = _compute_last_query_attn_row_and_values(
                module,
                hidden_states=hidden_states,
                attention_mask=attn_mask,
                position_embeddings=position_embeddings,
            )
            row_before = attn_row[:, :, 0, :].float()
            src = source_positions.to(device=row_before.device)
            evi = evidence_positions.to(device=row_before.device)
            source_token_mask, source_token_gate, source_token_debug = _token_selection_mask_for_answer_path(
                row_before,
                value_states,
                source_positions,
                module=module,
                lm_head=lm_head,
                yes_id=yes_id,
                no_id=no_id,
                positive_answer=current_answer,
                negative_answer=candidate_answer,
                mode=source_token_selection_mode,
                top_k=source_token_top_k,
                min_attn=source_token_min_attn,
            )
            evidence_token_mask, evidence_token_gate, evidence_token_debug = _token_selection_mask_for_answer_path(
                row_before,
                value_states,
                evidence_positions,
                module=module,
                lm_head=lm_head,
                yes_id=yes_id,
                no_id=no_id,
                positive_answer=candidate_answer,
                negative_answer=current_answer,
                mode=evidence_token_selection_mode,
                top_k=evidence_token_top_k,
                min_attn=evidence_token_min_attn,
            )
            source_selection_key = safe_text(source_token_selection_mode).lower()
            if source_selection_key in {
                "unsupported_answer_effect_soft_topk_per_head",
                "unsupported_answer_effect_soft_positive",
            }:
                support_mode = (
                    "answer_effect_soft_topk_per_head"
                    if source_selection_key == "unsupported_answer_effect_soft_topk_per_head"
                    else "answer_effect_soft_positive"
                )
                source_token_mask, source_token_gate, unsupported_debug = (
                    _attenuate_source_gate_by_evidence_answer_support(
                        row_before,
                        value_states,
                        evidence_positions,
                        source_token_mask,
                        source_token_gate,
                        module=module,
                        lm_head=lm_head,
                        yes_id=yes_id,
                        no_id=no_id,
                        current_answer=current_answer,
                        candidate_answer=candidate_answer,
                        support_mode=support_mode,
                        top_k=evidence_token_top_k,
                        min_attn=evidence_token_min_attn,
                    )
                )
                source_token_debug.update(unsupported_debug)
            source_mass = (row_before * source_token_gate.float()).sum(dim=-1).mean(dim=0).detach().cpu()
            evidence_mass = (row_before * evidence_token_gate.float()).sum(dim=-1).mean(dim=0).detach().cpu()
            source_mass_all_heads = source_mass.detach().clone()
            evidence_mass_all_heads = evidence_mass.detach().clone()
            causallens_selection_sensitivity: torch.Tensor | None = None
            causallens_selection_sensitivity_hat: torch.Tensor | None = None
            if operator_key == "causallens_acg_omni":
                (
                    causallens_selection_sensitivity,
                    causallens_selection_sensitivity_hat,
                ) = _causallens_raw_evidence_sensitivity(row_before, evidence_token_gate)
            answer_contribution: dict[str, Any] | None = None
            answer_current_over_candidate: torch.Tensor | None = None
            answer_candidate_over_current: torch.Tensor | None = None
            if operator_key in {
                "continuous_carrier_refinement",
                "carrier_constrained_path_refinement",
                "carrier_trust_region_path_edit",
                "residual_guided_path_solver",
                "oelpr_constrained_path_refinement",
                "oelpr_attention_transport",
            } or selection_key in {
                "answer_contribution",
                "source_answer_contribution",
            }:
                all_source_contrib = _masked_value_contribution_from_mask(
                    row_before,
                    value_states,
                    source_token_gate,
                )
                answer_contribution = _head_answer_contribution_scores(
                    module=module,
                    contribution=all_source_contrib,
                    lm_head=lm_head,
                    yes_id=yes_id,
                    no_id=no_id,
                    current_answer=current_answer,
                    candidate_answer=candidate_answer,
                )
                answer_current_over_candidate = answer_contribution["current_minus_candidate"]
                answer_candidate_over_current = answer_contribution["candidate_minus_current"]
            if operator_key in {
                "continuous_carrier_refinement",
                "carrier_constrained_path_refinement",
                "carrier_trust_region_path_edit",
                "residual_guided_path_solver",
                "oelpr_constrained_path_refinement",
                "oelpr_attention_transport",
            }:
                selected_heads = torch.arange(int(row_before.shape[1]), dtype=torch.long)
            else:
                selected_heads = _select_patch_heads(
                    source_mass=source_mass,
                    evidence_mass=evidence_mass,
                    mode=head_selection_mode,
                    max_heads=max_patched_heads_per_layer,
                    min_source_margin=head_source_margin_min,
                    min_source_mass=head_source_mass_min,
                    seed=_stable_int_seed(seed, safe_text(row.get("sample_id")), layer_id, "token_head_value"),
                    answer_current_over_candidate=answer_current_over_candidate,
                    min_answer_contribution=head_answer_contribution_min,
                )
            if selected_heads.numel() <= 0:
                debug_by_layer[str(layer_id)] = {
                    "selected_head_count": 0,
                    "selected_heads": [],
                    "source_mass_mean_all_heads": float(source_mass.mean().item()),
                    "evidence_mass_mean_all_heads": float(evidence_mass.mean().item()),
                    "source_over_evidence_margin_mean_all_heads": float((source_mass - evidence_mass).mean().item()),
                    "beta_for_layer": beta_for_layer,
                    "alpha_for_layer": alpha_for_layer,
                    "operator": operator_key,
                    "skip_reason": "empty_selected_heads",
                    "alpha_layer_policy": safe_text(token_head_alpha_layer_policy),
                    "source_token_selection": source_token_debug,
                    "evidence_token_selection": evidence_token_debug,
                    "answer_contribution_available": bool(
                        answer_contribution.get("available") if answer_contribution else False
                    ),
                    "answer_contribution_fallback_reason": (
                        answer_contribution.get("fallback_reason") if answer_contribution else None
                    ),
                    "answer_contribution_min": float(head_answer_contribution_min),
                    "answer_current_over_candidate_mean_all_heads": (
                        finite_mean(answer_current_over_candidate.tolist())
                        if answer_current_over_candidate is not None
                        else None
                    ),
                    "answer_candidate_over_current_mean_all_heads": (
                        finite_mean(answer_candidate_over_current.tolist())
                        if answer_candidate_over_current is not None
                        else None
                    ),
                }
                return None

            original_head_output = torch.matmul(attn_row.float(), value_states.float())
            patched_head_output = original_head_output.clone()
            heads = selected_heads.to(device=row_before.device)
            heads_cpu = selected_heads.detach().cpu().long()
            debug_payload: dict[str, Any] = {}
            if operator_key == "attention_redistribution":
                edited_row, redistribution = _redistribute_attention_row_with_masks(
                    row_before,
                    selected_heads=selected_heads,
                    source_mask=source_token_mask,
                    evidence_mask=evidence_token_mask,
                    beta_for_layer=beta_for_layer,
                    alpha_for_layer=alpha_for_layer,
                    alpha_mode=alpha_mode,
                )
                patched_head_output = torch.matmul(edited_row.unsqueeze(2).float(), value_states.float())
                debug_payload.update(redistribution)
                source_contrib = _masked_value_contribution_from_mask(
                    row_before[:, heads, :],
                    value_states[:, heads, :, :],
                    source_token_gate[:, heads, :],
                )
                evidence_contrib = _masked_value_contribution_from_mask(
                    row_before[:, heads, :],
                    value_states[:, heads, :, :],
                    evidence_token_gate[:, heads, :],
                )
                delta = patched_head_output[:, heads, :, :] - original_head_output[:, heads, :, :]
            else:
                source_contrib = _masked_value_contribution_from_mask(
                    row_before[:, heads, :],
                    value_states[:, heads, :, :],
                    source_token_gate[:, heads, :],
                )
                evidence_contrib = _masked_value_contribution_from_mask(
                    row_before[:, heads, :],
                    value_states[:, heads, :, :],
                    evidence_token_gate[:, heads, :],
                )
                if operator_key == "orthogonal_value_suppression":
                    suppressible = _orthogonalize_head_contribution(source_contrib, evidence_contrib)
                elif operator_key == "head_subspace_transport":
                    transport_alpha_ratio = (
                        float(alpha) if safe_text(alpha_mode) == "evidence_value_boost" else 0.0
                    )
                    transport = _head_subspace_transport_delta(
                        head_output=original_head_output[:, heads, :, :],
                        source_contribution=source_contrib,
                        evidence_contribution=evidence_contrib,
                        beta_for_layer=beta_for_layer,
                        transport_alpha_ratio=transport_alpha_ratio,
                    )
                    delta = torch.as_tensor(transport["delta"]).to(
                        device=patched_head_output.device,
                        dtype=torch.float32,
                    )
                    debug_payload.update({k: v for k, v in transport.items() if k != "delta"})
                    patched_head_output[:, heads, :, :] = patched_head_output[:, heads, :, :] + delta
                    suppressible = None
                elif operator_key == "allpath_head_scaling":
                    good_heads = _select_evidence_support_heads(
                        source_mass=source_mass,
                        evidence_mass=evidence_mass,
                        max_heads=max_patched_heads_per_layer,
                        exclude_heads=selected_heads,
                        answer_candidate_over_current=answer_candidate_over_current,
                        min_answer_contribution=head_answer_contribution_min,
                    )
                    scaled = _allpath_head_scaled_output(
                        original_head_output=original_head_output,
                        hallu_heads=selected_heads,
                        good_heads=good_heads,
                        beta_for_layer=beta_for_layer,
                        alpha_for_layer=alpha_for_layer,
                        alpha_mode=alpha_mode,
                    )
                    patched_head_output = scaled["patched_head_output"].to(
                        device=patched_head_output.device,
                        dtype=torch.float32,
                    )
                    delta = torch.as_tensor(scaled["delta"]).to(
                        device=patched_head_output.device,
                        dtype=torch.float32,
                    )
                    debug_payload.update(
                        {k: v for k, v in scaled.items() if k not in {"patched_head_output", "delta"}}
                    )
                    suppressible = None
                elif operator_key == "allpath_token_scaling":
                    good_heads = _select_evidence_support_heads(
                        source_mass=source_mass,
                        evidence_mass=evidence_mass,
                        max_heads=max_patched_heads_per_layer,
                        exclude_heads=selected_heads,
                        answer_candidate_over_current=answer_candidate_over_current,
                        min_answer_contribution=head_answer_contribution_min,
                    )
                    if good_heads.numel() > 0:
                        good_dev = good_heads.to(device=row_before.device)
                        evidence_contrib_good = _masked_value_contribution_from_mask(
                            row_before[:, good_dev, :],
                            value_states[:, good_dev, :, :],
                            evidence_token_gate[:, good_dev, :],
                        )
                    else:
                        evidence_contrib_good = torch.zeros(
                            row_before.shape[0],
                            0,
                            1,
                            value_states.shape[-1],
                            device=row_before.device,
                            dtype=torch.float32,
                        )
                    scaled = _allpath_token_scaled_output(
                        original_head_output=original_head_output,
                        hallu_heads=selected_heads,
                        good_heads=good_heads,
                        source_contribution=source_contrib,
                        evidence_contribution_good=evidence_contrib_good,
                        beta_for_layer=beta_for_layer,
                        alpha_for_layer=alpha_for_layer,
                        alpha_mode=alpha_mode,
                    )
                    patched_head_output = scaled["patched_head_output"].to(
                        device=patched_head_output.device,
                        dtype=torch.float32,
                    )
                    delta = torch.as_tensor(scaled["delta"]).to(
                        device=patched_head_output.device,
                        dtype=torch.float32,
                    )
                    debug_payload.update(
                        {k: v for k, v in scaled.items() if k not in {"patched_head_output", "delta"}}
                    )
                    suppressible = None
                elif operator_key == "continuous_carrier_refinement":
                    evidence_answer_contribution = _head_answer_contribution_scores(
                        module=module,
                        contribution=evidence_contrib,
                        lm_head=lm_head,
                        yes_id=yes_id,
                        no_id=no_id,
                        current_answer=current_answer,
                        candidate_answer=candidate_answer,
                    )
                    refined = _continuous_carrier_refinement_output(
                        original_head_output=original_head_output,
                        source_contribution=source_contrib,
                        evidence_contribution=evidence_contrib,
                        source_mass=source_mass,
                        evidence_mass=evidence_mass,
                        beta_for_layer=beta_for_layer,
                        alpha_for_layer=alpha_for_layer,
                        alpha_mode=alpha_mode,
                        source_current_over_candidate=(
                            answer_current_over_candidate
                            if answer_contribution and bool(answer_contribution.get("available"))
                            else None
                        ),
                        evidence_candidate_over_current=(
                            evidence_answer_contribution["candidate_minus_current"]
                            if bool(evidence_answer_contribution.get("available"))
                            else None
                        ),
                    )
                    patched_head_output = refined["patched_head_output"].to(
                        device=patched_head_output.device,
                        dtype=torch.float32,
                    )
                    delta = torch.as_tensor(refined["delta"]).to(
                        device=patched_head_output.device,
                        dtype=torch.float32,
                    )
                    debug_payload.update(
                        {k: v for k, v in refined.items() if k not in {"patched_head_output", "delta"}}
                    )
                    suppressible = None
                elif operator_key == "carrier_constrained_path_refinement":
                    raise ValueError(
                        "carrier_constrained_path_refinement requires --executor-mode=structured_subspace "
                        "because it uses the structured hidden U/P carriers."
                    )
                elif operator_key == "carrier_trust_region_path_edit":
                    raise ValueError(
                        "carrier_trust_region_path_edit requires --executor-mode=structured_subspace "
                        "because it uses the structured hidden U/P carriers."
                    )
                elif operator_key == "residual_guided_path_solver":
                    raise ValueError(
                        "residual_guided_path_solver requires --executor-mode=structured_subspace "
                        "because it uses the structured hidden U/P residual target."
                    )
                elif operator_key == "oelpr_constrained_path_refinement":
                    raise ValueError(
                        "oelpr_constrained_path_refinement requires --executor-mode=structured_subspace "
                        "because it uses branch-counterfactual current-preservation carriers."
                    )
                elif operator_key == "oelpr_attention_transport":
                    raise ValueError(
                        "oelpr_attention_transport requires --executor-mode=structured_subspace "
                        "because it uses branch-counterfactual current-preservation carriers."
                    )
                elif operator_key in {
                    "carrier_weighted_allpath_token_scaling",
                    "current_protected_carrier_weighted_allpath_token_scaling",
                }:
                    raise ValueError(
                        f"{operator_key} requires --executor-mode=structured_subspace "
                        "because it uses the structured hidden U/P carriers."
                    )
                elif operator_key == "raw_value_suppression":
                    suppressible = source_contrib.float()
                else:
                    raise ValueError(f"unknown token_head_value operator: {operator}")
                if suppressible is not None:
                    delta = -float(beta_for_layer) * suppressible
                    if safe_text(alpha_mode) == "evidence_value_boost":
                        delta = delta + float(alpha_for_layer) * evidence_contrib.float()
                    patched_head_output[:, heads, :, :] = patched_head_output[:, heads, :, :] + delta

            attn_output = patched_head_output.transpose(1, 2).contiguous()
            attn_output = attn_output.reshape(attn_output.shape[0], attn_output.shape[1], -1)
            attn_output = attn_output.to(dtype=hidden_states.dtype)
            patched_outputs[id(module)] = module.o_proj(attn_output)

            source_norm = float(source_contrib.detach().float().norm().cpu().item())
            evidence_norm = float(evidence_contrib.detach().float().norm().cpu().item())
            delta_norm = float(delta.detach().float().norm().cpu().item())
            if int(source_mass.numel()) == int(selected_heads.numel()):
                selected_source_mass = source_mass.float()
            else:
                selected_source_mass = source_mass[heads_cpu].float()
            if int(evidence_mass.numel()) == int(selected_heads.numel()):
                selected_evidence_mass = evidence_mass.float()
            else:
                selected_evidence_mass = evidence_mass[heads_cpu].float()
            selected_answer_current_over_candidate = (
                answer_current_over_candidate[heads_cpu].float()
                if answer_current_over_candidate is not None
                else torch.empty(0, dtype=torch.float32)
            )
            selected_answer_candidate_over_current = (
                answer_candidate_over_current[heads_cpu].float()
                if answer_candidate_over_current is not None
                else torch.empty(0, dtype=torch.float32)
            )
            debug_by_layer[str(layer_id)] = {
                "selected_head_count": int(selected_heads.numel()),
                "selected_heads": [int(x) for x in selected_heads.tolist()],
                "source_token_count": int(source_positions.numel()),
                "evidence_token_count": int(evidence_positions.numel()),
                "source_mass_mean_all_heads": float(source_mass_all_heads.mean().item()),
                "evidence_mass_mean_all_heads": float(evidence_mass_all_heads.mean().item()),
                "source_over_evidence_margin_mean_all_heads": float(
                    (source_mass_all_heads - evidence_mass_all_heads).mean().item()
                ),
                "source_mass_mean_selected_heads": float(selected_source_mass.mean().item()),
                "evidence_mass_mean_selected_heads": float(selected_evidence_mass.mean().item()),
                "source_over_evidence_margin_mean_selected_heads": float(
                    (selected_source_mass - selected_evidence_mass).mean().item()
                ),
                "answer_contribution_available": bool(
                    answer_contribution.get("available") if answer_contribution else False
                ),
                "answer_contribution_fallback_reason": (
                    answer_contribution.get("fallback_reason") if answer_contribution else None
                ),
                "answer_candidate_token_id": (
                    answer_contribution.get("candidate_token_id") if answer_contribution else None
                ),
                "answer_current_token_id": (
                    answer_contribution.get("current_token_id") if answer_contribution else None
                ),
                "answer_contribution_min": float(head_answer_contribution_min),
                "answer_current_over_candidate_mean_all_heads": (
                    finite_mean(answer_current_over_candidate.tolist())
                    if answer_current_over_candidate is not None
                    else None
                ),
                "answer_current_over_candidate_mean_selected_heads": (
                    finite_mean(selected_answer_current_over_candidate.tolist())
                    if selected_answer_current_over_candidate.numel() > 0
                    else None
                ),
                "answer_candidate_over_current_mean_all_heads": (
                    finite_mean(answer_candidate_over_current.tolist())
                    if answer_candidate_over_current is not None
                    else None
                ),
                "answer_candidate_over_current_mean_selected_heads": (
                    finite_mean(selected_answer_candidate_over_current.tolist())
                    if selected_answer_candidate_over_current.numel() > 0
                    else None
                ),
                "answer_support_head_count_all": (
                    int((answer_candidate_over_current > 0).sum().item())
                    if answer_candidate_over_current is not None
                    else None
                ),
                "answer_interference_head_count_all": (
                    int((answer_current_over_candidate > 0).sum().item())
                    if answer_current_over_candidate is not None
                    else None
                ),
                "source_value_contribution_l2": source_norm,
                "evidence_value_contribution_l2": evidence_norm,
                "delta_l2": delta_norm,
                "source_token_selection": source_token_debug,
                "evidence_token_selection": evidence_token_debug,
                "source_token_count_selected_mean_per_head": source_token_debug.get(
                    "token_count_selected_mean_per_head"
                ),
                "source_token_count_selected_unique": source_token_debug.get("token_count_selected_unique"),
                "evidence_token_count_selected_mean_per_head": evidence_token_debug.get(
                    "token_count_selected_mean_per_head"
                ),
                "evidence_token_count_selected_unique": evidence_token_debug.get("token_count_selected_unique"),
                "beta_for_layer": beta_for_layer,
                "alpha_for_layer": alpha_for_layer,
                "operator": operator_key,
                "alpha_mode": safe_text(alpha_mode),
                "alpha_layer_policy": safe_text(token_head_alpha_layer_policy),
                **debug_payload,
            }
            return None

        return hook_fn

    def make_forward_hook():
        def hook_fn(module, _args, output):
            patched = patched_outputs.pop(id(module), None)
            if patched is None:
                return None
            if isinstance(output, tuple):
                if not output:
                    return output
                attn_output = output[0].clone()
                attn_output[:, -1:, :].copy_(patched[:, -1:, :].to(dtype=attn_output.dtype))
                return (attn_output, *output[1:])
            if isinstance(output, list):
                if not output:
                    return output
                cloned = list(output)
                attn_output = cloned[0].clone()
                attn_output[:, -1:, :].copy_(patched[:, -1:, :].to(dtype=attn_output.dtype))
                cloned[0] = attn_output
                return cloned
            patched_output = output.clone()
            patched_output[:, -1:, :].copy_(patched[:, -1:, :].to(dtype=patched_output.dtype))
            return patched_output

        return hook_fn

    for layer_id, layer_module in enumerate(thinker.model.layers):
        if int(layer_id) not in selected_layer_set:
            continue
        hooks.append(
            layer_module.self_attn.register_forward_pre_hook(
                make_pre_hook(int(layer_id)),
                with_kwargs=True,
            )
        )
        hooks.append(layer_module.self_attn.register_forward_hook(make_forward_hook()))

    outputs = None
    try:
        thinker.rope_deltas = None
        with adapter.temporary_release_cuda_reserve("token_head_value_suppression"):
            with torch.inference_mode():
                outputs = thinker(
                    **inputs,
                    use_cache=False,
                    output_attentions=False,
                    output_hidden_states=False,
                    return_dict=True,
                )
        logits = outputs.logits[:, -1, [yes_id, no_id]]
    finally:
        for hook in hooks:
            hook.remove()
        thinker.rope_deltas = None

    result = yes_no_payload(logits)
    debug_rows = list(debug_by_layer.values())
    selected_counts = [int(item.get("selected_head_count") or 0) for item in debug_rows]
    result.update(
        {
            "debug_executor_mode": "token_head_value",
            "debug_layer_group": layers,
            "debug_num_layers_patched": sum(1 for count in selected_counts if count > 0),
            "debug_layer_weights": {str(layer): float(weights[int(layer)]) for layer in layers},
            "debug_evidence_layer_weights": {str(layer): float(alpha_weights[int(layer)]) for layer in layers},
            "debug_prior_layer_weights": {str(layer): float(beta_weights[int(layer)]) for layer in layers},
            "debug_beta_by_layer": {
                str(layer): float(beta) * float(beta_weights[int(layer)]) for layer in layers
            },
            "debug_alpha_by_layer": {
                str(layer): float(alpha) * float(alpha_weights[int(layer)]) for layer in layers
            },
            "debug_by_layer": debug_by_layer,
            "debug_source_prior_token_group": safe_text(source_prior_token_group),
            "debug_evidence_token_group": safe_text(evidence_token_group),
            "debug_source_prior_token_count": int(source_positions.numel()),
            "debug_evidence_token_count": int(evidence_positions.numel()),
            "debug_source_token_selection_mode": safe_text(source_token_selection_mode),
            "debug_source_token_top_k": int(source_token_top_k),
            "debug_source_token_min_attn": float(source_token_min_attn),
            "debug_evidence_token_selection_mode": safe_text(evidence_token_selection_mode),
            "debug_evidence_token_top_k": int(evidence_token_top_k),
            "debug_evidence_token_min_attn": float(evidence_token_min_attn),
            "debug_source_token_count_selected_mean_per_head": finite_mean(
                item.get("source_token_count_selected_mean_per_head") for item in debug_rows
            ),
            "debug_source_token_count_selected_unique_mean": finite_mean(
                item.get("source_token_count_selected_unique") for item in debug_rows
            ),
            "debug_source_answer_effect_selected_token_count": finite_mean(
                (item.get("source_token_selection") or {}).get("answer_effect_selected_token_count")
                for item in debug_rows
            ),
            "debug_source_answer_effect_mean_selected": finite_mean(
                (item.get("source_token_selection") or {}).get("answer_effect_mean_selected")
                for item in debug_rows
            ),
            "debug_source_token_gate_sum_mean_per_head": finite_mean(
                (item.get("source_token_selection") or {}).get("token_gate_sum_mean_per_head")
                for item in debug_rows
            ),
            "debug_source_answer_effect_gate_mean_selected": finite_mean(
                (item.get("source_token_selection") or {}).get("answer_effect_gate_mean_selected")
                for item in debug_rows
            ),
            "debug_evidence_token_count_selected_mean_per_head": finite_mean(
                item.get("evidence_token_count_selected_mean_per_head") for item in debug_rows
            ),
            "debug_evidence_token_count_selected_unique_mean": finite_mean(
                item.get("evidence_token_count_selected_unique") for item in debug_rows
            ),
            "debug_evidence_answer_effect_selected_token_count": finite_mean(
                (item.get("evidence_token_selection") or {}).get("answer_effect_selected_token_count")
                for item in debug_rows
            ),
            "debug_evidence_answer_effect_mean_selected": finite_mean(
                (item.get("evidence_token_selection") or {}).get("answer_effect_mean_selected")
                for item in debug_rows
            ),
            "debug_evidence_token_gate_sum_mean_per_head": finite_mean(
                (item.get("evidence_token_selection") or {}).get("token_gate_sum_mean_per_head")
                for item in debug_rows
            ),
            "debug_evidence_answer_effect_gate_mean_selected": finite_mean(
                (item.get("evidence_token_selection") or {}).get("answer_effect_gate_mean_selected")
                for item in debug_rows
            ),
            "debug_head_selection_mode": safe_text(head_selection_mode),
            "debug_max_patched_heads_per_layer": int(max_patched_heads_per_layer),
            "debug_head_answer_contribution_min": float(head_answer_contribution_min),
            "debug_selected_head_count_total": int(sum(selected_counts)),
            "debug_selected_head_count_mean": finite_mean(selected_counts),
            "debug_source_mass_selected": finite_mean(
                item.get("source_mass_mean_selected_heads") for item in debug_rows
            ),
            "debug_evidence_mass_selected": finite_mean(
                item.get("evidence_mass_mean_selected_heads") for item in debug_rows
            ),
            "debug_source_over_evidence_margin_selected": finite_mean(
                item.get("source_over_evidence_margin_mean_selected_heads") for item in debug_rows
            ),
            "debug_answer_current_over_candidate_selected": finite_mean(
                item.get("answer_current_over_candidate_mean_selected_heads") for item in debug_rows
            ),
            "debug_answer_candidate_over_current_selected": finite_mean(
                item.get("answer_candidate_over_current_mean_selected_heads") for item in debug_rows
            ),
            "debug_answer_current_over_candidate_all": finite_mean(
                item.get("answer_current_over_candidate_mean_all_heads") for item in debug_rows
            ),
            "debug_answer_candidate_over_current_all": finite_mean(
                item.get("answer_candidate_over_current_mean_all_heads") for item in debug_rows
            ),
            "debug_answer_support_head_count_all": finite_mean(
                item.get("answer_support_head_count_all") for item in debug_rows
            ),
            "debug_answer_interference_head_count_all": finite_mean(
                item.get("answer_interference_head_count_all") for item in debug_rows
            ),
            "debug_source_value_contribution_l2": sum(
                float(item.get("source_value_contribution_l2") or 0.0) for item in debug_rows
            ),
            "debug_evidence_value_contribution_l2": sum(
                float(item.get("evidence_value_contribution_l2") or 0.0) for item in debug_rows
            ),
            "debug_delta_l2": sum(float(item.get("delta_l2") or 0.0) for item in debug_rows),
            "debug_token_head_value_operator": safe_text(operator),
            "debug_token_head_alpha_mode": safe_text(alpha_mode),
            "debug_token_head_alpha_layer_policy": safe_text(token_head_alpha_layer_policy),
            "debug_head_transport_prior_abs_before": finite_mean(
                item.get("head_transport_prior_abs_before") for item in debug_rows
            ),
            "debug_head_transport_prior_abs_after": finite_mean(
                item.get("head_transport_prior_abs_after") for item in debug_rows
            ),
            "debug_head_transport_prior_reduction_abs": finite_mean(
                item.get("head_transport_prior_reduction_abs") for item in debug_rows
            ),
            "debug_head_transport_evidence_gain": finite_mean(
                item.get("head_transport_evidence_gain") for item in debug_rows
            ),
            "debug_head_transport_prior_delta_l2": sum(
                float(item.get("head_transport_prior_delta_l2") or 0.0) for item in debug_rows
            ),
            "debug_head_transport_transport_delta_l2": sum(
                float(item.get("head_transport_transport_delta_l2") or 0.0) for item in debug_rows
            ),
            "debug_head_transport_compensation_delta_l2": sum(
                float(item.get("head_transport_compensation_delta_l2") or 0.0) for item in debug_rows
            ),
            "debug_head_transport_delta_l2": sum(
                float(item.get("head_transport_delta_l2") or 0.0) for item in debug_rows
            ),
            "debug_head_transport_alpha_ratio": finite_mean(
                item.get("head_transport_alpha_ratio") for item in debug_rows
            ),
            "debug_head_transport_u_p_abs_cos": finite_mean(
                item.get("head_transport_u_p_abs_cos") for item in debug_rows
            ),
            "debug_head_transport_valid_prior_ratio": finite_mean(
                item.get("head_transport_valid_prior_ratio") for item in debug_rows
            ),
            "debug_head_transport_valid_evidence_ratio": finite_mean(
                item.get("head_transport_valid_evidence_ratio") for item in debug_rows
            ),
        }
    )

    del inputs, outputs
    gc.collect()
    if torch.cuda.is_available():
        torch.cuda.empty_cache()
    return result


def _hulluedit_config(
    *,
    rank_evidence: int,
    rank_prior: int,
    kappa: float,
    lambda_prior: float,
    lambda_n_max: float,
    lambda_p_max: float,
    vcr_floor: float,
    pcr_ceiling: float,
    pcr_threshold: float,
    blend_tau: float,
    norm_preserve: bool,
    norm_beta: float,
    weight_temp: float,
    uniform_svd: bool,
    no_complement: bool,
    no_gating: bool,
    use_fixed_strengths: bool,
    fixed_lambda_n: float,
    fixed_lambda_p: float,
    only_residual: bool,
    only_anti_prior: bool,
):
    if HullueditConfig is None:
        raise ImportError(
            f"HulluEdit repo is not importable from {HULLUEDIT_ROOT}. "
            "Expected bundled third_party/HulluEdit/hulluedit/steer.py."
        )
    return HullueditConfig(
        rank_evidence=max(0, int(rank_evidence)),
        rank_prior=max(0, int(rank_prior)),
        kappa=max(0.0, float(kappa)),
        lambda_prior=max(0.0, float(lambda_prior)),
        lambda_n_max=max(0.0, float(lambda_n_max)),
        lambda_p_max=max(0.0, float(lambda_p_max)),
        vcr_floor=max(0.0, float(vcr_floor)),
        pcr_ceiling=max(0.0, min(1.0, float(pcr_ceiling))),
        pcr_threshold=max(0.0, float(pcr_threshold)),
        blend_tau=max(0.0, min(1.0, float(blend_tau))),
        norm_preserve=bool(norm_preserve),
        norm_beta=max(0.0, float(norm_beta)),
        weight_temp=float(weight_temp),
        uniform_svd=bool(uniform_svd),
        no_complement=bool(no_complement),
        no_gating=bool(no_gating),
        use_fixed_strengths=bool(use_fixed_strengths),
        fixed_lambda_n=max(0.0, float(fixed_lambda_n)),
        fixed_lambda_p=max(0.0, float(fixed_lambda_p)),
        only_residual=bool(only_residual),
        only_anti_prior=bool(only_anti_prior),
    )


def _subspace_projection_l2(vec: torch.Tensor, basis: torch.Tensor) -> float:
    if not isinstance(basis, torch.Tensor) or basis.numel() <= 0:
        return 0.0
    base = vec.float()
    b = basis.to(device=base.device, dtype=torch.float32)
    projection = b @ (b.T @ base)
    return float(projection.norm().detach().cpu().item())


@torch.no_grad()
def patched_hulluedit_subspace_logits(
    adapter: QwenOmniAdapter,
    *,
    row: Mapping[str, Any],
    layer_group: Sequence[int],
    layer_weights: Mapping[int, float] | None,
    evidence_layer_weights: Mapping[int, float] | None,
    prior_layer_weights: Mapping[int, float] | None,
    beta: float,
    alpha: float,
    yes_id: int,
    no_id: int,
    budget: Mapping[str, float],
    source_prior_token_group: str,
    evidence_token_group: str,
    rank_evidence: int,
    rank_prior: int,
    kappa: float,
    lambda_prior: float,
    use_beta_grid: bool,
    lambda_n_max: float,
    lambda_p_max: float,
    vcr_floor: float,
    pcr_ceiling: float,
    pcr_threshold: float,
    blend_tau: float,
    norm_preserve: bool,
    norm_beta: float,
    weight_temp: float,
    uniform_svd: bool,
    no_complement: bool,
    no_gating: bool,
    use_fixed_strengths: bool,
    fixed_lambda_n: float,
    fixed_lambda_p: float,
    only_residual: bool,
    only_anti_prior: bool,
    common_trace_baseline_states: Mapping[int, torch.Tensor] | None = None,
    common_trace_evidence_directions: Mapping[int, torch.Tensor] | None = None,
    common_trace_prior_directions: Mapping[int, torch.Tensor] | None = None,
) -> dict[str, Any]:
    if HullueditSteerer is None:
        raise ImportError(
            f"HulluEdit repo is not importable from {HULLUEDIT_ROOT}. "
            "Expected bundled third_party/HulluEdit/hulluedit/steer.py."
    )
    inputs = prepare_branch_inputs(adapter, row=dict(row), branch="full", budget=dict(budget))
    thinker = adapter._model.thinker
    layers = [int(layer) for layer in layer_group]
    if not layers:
        raise ValueError("layer_group must not be empty")
    if layer_weights is None:
        weights = {layer: 1.0 / float(len(layers)) for layer in layers}
    else:
        total = sum(float(layer_weights.get(layer, 0.0)) for layer in layers)
        if total <= 0.0:
            raise ValueError(f"layer weights must sum to a positive value for group {layers}")
        weights = {layer: float(layer_weights.get(layer, 0.0)) / total for layer in layers}
    if evidence_layer_weights is None:
        alpha_weights = dict(weights)
    else:
        total = sum(float(evidence_layer_weights.get(layer, 0.0)) for layer in layers)
        if total <= 0.0:
            raise ValueError(f"evidence layer weights have no overlap with layer group {layers}")
        alpha_weights = {layer: float(evidence_layer_weights.get(layer, 0.0)) / total for layer in layers}
    if prior_layer_weights is None:
        beta_weights = dict(weights)
    else:
        total = sum(float(prior_layer_weights.get(layer, 0.0)) for layer in layers)
        if total <= 0.0:
            raise ValueError(f"prior layer weights have no overlap with layer group {layers}")
        beta_weights = {layer: float(prior_layer_weights.get(layer, 0.0)) / total for layer in layers}

    attention_mask = inputs.get("attention_mask")
    if attention_mask is None:
        attention_mask = torch.ones_like(inputs["input_ids"])
    special_ids = tokenizer_ids(adapter)
    label_masks = resolve_avcd_label_masks(
        input_ids=inputs["input_ids"].detach().cpu(),
        attention_mask=attention_mask.detach().cpu(),
        special_ids=special_ids,
    )
    causallens_system_positions = _resolve_causallens_system_positions(
        input_ids=inputs["input_ids"],
        attention_mask=attention_mask,
        special_ids=special_ids,
    )
    source_positions = _resolve_token_group_positions(
        label_masks=label_masks,
        group=source_prior_token_group,
        target_modality=safe_text(row.get("target_modality")),
    )
    evidence_positions = _resolve_token_group_positions(
        label_masks=label_masks,
        group=evidence_token_group,
        target_modality=safe_text(row.get("target_modality")),
    )
    if source_positions.numel() <= 0:
        raise ValueError(
            f"empty source-prior token group={source_prior_token_group} sample={safe_text(row.get('sample_id'))}"
        )
    if evidence_positions.numel() <= 0:
        raise ValueError(
            f"empty evidence token group={evidence_token_group} sample={safe_text(row.get('sample_id'))}"
        )
    valid_positions = torch.nonzero(attention_mask[0].detach().cpu().bool(), as_tuple=False).flatten().long()
    edit_token_position = int(valid_positions[-1].item()) if valid_positions.numel() > 0 else int(inputs["input_ids"].shape[1] - 1)
    source_positions = source_positions[source_positions != edit_token_position]
    evidence_positions = evidence_positions[evidence_positions != edit_token_position]
    if source_positions.numel() <= 0:
        raise ValueError(
            f"empty source-prior token group after edit-token exclusion group={source_prior_token_group} "
            f"sample={safe_text(row.get('sample_id'))}"
        )
    if evidence_positions.numel() <= 0:
        raise ValueError(
            f"empty evidence token group after edit-token exclusion group={evidence_token_group} "
            f"sample={safe_text(row.get('sample_id'))}"
        )

    debug_by_layer: dict[str, dict[str, Any]] = {}
    common_trace_by_layer: dict[str, dict[str, Any]] = {}
    hooks = []

    common_baseline = dict(common_trace_baseline_states or {})
    common_evidence = dict(common_trace_evidence_directions or {})
    common_prior = dict(common_trace_prior_directions or {})
    common_trace_layers = sorted(set(common_baseline) & set(common_evidence) & set(common_prior))

    def common_coordinates(
        state: torch.Tensor,
        *,
        layer_id: int,
        prefix: str,
    ) -> dict[str, float]:
        vector = state.detach().float()
        evidence = common_evidence[int(layer_id)].to(device=vector.device, dtype=torch.float32)
        prior = common_prior[int(layer_id)].to(device=vector.device, dtype=torch.float32)
        evidence = evidence / evidence.norm().clamp_min(1.0e-12)
        prior = prior / prior.norm().clamp_min(1.0e-12)
        state_norm = vector.norm().clamp_min(1.0e-12)
        evidence_projection = torch.dot(vector, evidence)
        prior_projection = torch.dot(vector, prior)
        balance = 100.0 * (evidence_projection - prior_projection) / state_norm
        return {
            f"{prefix}_norm": float(state_norm.cpu().item()),
            f"{prefix}_evidence_projection": float(evidence_projection.cpu().item()),
            f"{prefix}_prior_projection": float(prior_projection.cpu().item()),
            f"{prefix}_balance": float(balance.cpu().item()),
        }

    for trace_layer in common_trace_layers:
        common_trace_by_layer[str(trace_layer)] = common_coordinates(
            common_baseline[trace_layer],
            layer_id=trace_layer,
            prefix="baseline",
        )

    def record_common_post(layer_id: int, state: torch.Tensor) -> None:
        if int(layer_id) not in common_trace_layers:
            return
        payload = common_trace_by_layer[str(layer_id)]
        payload.update(common_coordinates(state, layer_id=layer_id, prefix="post"))
        payload["balance_shift"] = float(payload["post_balance"] - payload["baseline_balance"])

    def make_patch_hook(layer_id: int):
        beta_for_layer = float(beta) * float(beta_weights.get(int(layer_id), 0.0))
        alpha_for_layer = float(alpha) * float(alpha_weights.get(int(layer_id), 0.0))
        lambda_prior_for_layer = float(lambda_prior)
        if bool(use_beta_grid):
            lambda_prior_for_layer *= max(0.0, float(beta_for_layer))

        def patch_hook(_module, _inp, output):
            hidden_states = output[0] if isinstance(output, (tuple, list)) else output
            if not isinstance(hidden_states, torch.Tensor):
                return None
            patched = hidden_states.clone()
            base = patched[0, -1, :].float()
            evi_pos = evidence_positions.to(device=patched.device, dtype=torch.long)
            src_pos = source_positions.to(device=patched.device, dtype=torch.long)
            evidence_states = patched[0, evi_pos, :].detach().float()
            source_states = patched[0, src_pos, :].detach().float()
            cfg = _hulluedit_config(
                rank_evidence=rank_evidence,
                rank_prior=rank_prior,
                kappa=kappa,
                lambda_prior=lambda_prior_for_layer,
                lambda_n_max=lambda_n_max,
                lambda_p_max=lambda_p_max,
                vcr_floor=vcr_floor,
                pcr_ceiling=pcr_ceiling,
                pcr_threshold=pcr_threshold,
                blend_tau=blend_tau,
                norm_preserve=norm_preserve,
                norm_beta=norm_beta,
                weight_temp=weight_temp,
                uniform_svd=uniform_svd,
                no_complement=no_complement,
                no_gating=no_gating,
                use_fixed_strengths=use_fixed_strengths,
                fixed_lambda_n=fixed_lambda_n,
                fixed_lambda_p=fixed_lambda_p,
                only_residual=only_residual,
                only_anti_prior=only_anti_prior,
            )
            steerer = HullueditSteerer(cfg)
            U = steerer.compute_evidence_subspace(evidence_states, base)
            P = steerer.compute_anti_prior_subspace(source_states, U)
            edited = steerer.edit_text_hidden(base, U, P)
            updated = edited.h_edited.to(device=base.device, dtype=torch.float32)
            patched[0, -1, :] = updated.to(dtype=patched.dtype)
            record_common_post(layer_id, updated)
            delta = updated - base
            debug_by_layer[str(layer_id)] = {
                "layer_weight": float(weights[int(layer_id)]),
                "evidence_layer_weight": float(alpha_weights.get(int(layer_id), 0.0)),
                "prior_layer_weight": float(beta_weights.get(int(layer_id), 0.0)),
                "beta_for_layer": float(beta_for_layer),
                "alpha_for_layer": float(alpha_for_layer),
                "lambda_prior_for_layer": float(lambda_prior_for_layer),
                "kappa": float(cfg.kappa),
                "rank_evidence_requested": int(cfg.rank_evidence),
                "rank_prior_requested": int(cfg.rank_prior),
                "rank_evidence_actual": int(U.shape[1]) if isinstance(U, torch.Tensor) and U.dim() == 2 else 0,
                "rank_prior_actual": int(P.shape[1]) if isinstance(P, torch.Tensor) and P.dim() == 2 else 0,
                "source_token_count": int(source_positions.numel()),
                "evidence_token_count": int(evidence_positions.numel()),
                "edit_token_position": int(edit_token_position),
                "vcr": float(edited.vcr.detach().float().cpu().item()),
                "pcr": float(edited.pcr.detach().float().cpu().item()),
                "gate": float(edited.gate.detach().float().cpu().item()),
                "base_norm": float(base.norm().detach().cpu().item()),
                "updated_norm": float(updated.norm().detach().cpu().item()),
                "delta_l2": float(delta.norm().detach().cpu().item()),
                "delta_evidence_subspace_l2": _subspace_projection_l2(delta, U),
                "delta_prior_subspace_l2": _subspace_projection_l2(delta, P),
                "base_evidence_subspace_l2": _subspace_projection_l2(base, U),
                "base_prior_subspace_l2": _subspace_projection_l2(base, P),
                "uniform_svd": bool(cfg.uniform_svd),
                "no_complement": bool(cfg.no_complement),
                "no_gating": bool(cfg.no_gating),
                "use_fixed_strengths": bool(cfg.use_fixed_strengths),
                "only_residual": bool(cfg.only_residual),
                "only_anti_prior": bool(cfg.only_anti_prior),
                "norm_preserve": bool(cfg.norm_preserve),
                "blend_tau": float(cfg.blend_tau),
                "norm_beta": float(cfg.norm_beta),
                "weight_temp": float(cfg.weight_temp),
            }
            if isinstance(output, tuple):
                return (patched,) + tuple(output[1:])
            if isinstance(output, list):
                return [patched] + list(output[1:])
            return patched

        return patch_hook

    for layer in layers:
        hooks.append(thinker.model.layers[int(layer)].register_forward_hook(make_patch_hook(int(layer))))
    for trace_layer in common_trace_layers:
        if int(trace_layer) in layers:
            continue

        def common_trace_hook(_module, _inp, output, *, layer_id=int(trace_layer)):
            hidden_states = output[0] if isinstance(output, (tuple, list)) else output
            if isinstance(hidden_states, torch.Tensor):
                record_common_post(layer_id, hidden_states[0, -1, :].float())
            return None

        hooks.append(
            thinker.model.layers[int(trace_layer)].register_forward_hook(common_trace_hook)
        )
    outputs = None
    try:
        with adapter.temporary_release_cuda_reserve("hulluedit_subspace"):
            with torch.inference_mode():
                outputs = thinker(
                    **inputs,
                    use_cache=False,
                    output_attentions=False,
                    output_hidden_states=False,
                    return_dict=True,
                )
        logits = outputs.logits[:, -1, [yes_id, no_id]]
    finally:
        for hook in hooks:
            hook.remove()
        thinker.rope_deltas = None

    result = yes_no_payload(logits)
    debug_rows = list(debug_by_layer.values())
    result.update(
        {
            "debug_executor_mode": "hulluedit_subspace",
            "debug_layer_group": layers,
            "debug_num_layers_patched": len(debug_rows),
            "debug_layer_weights": {str(layer): float(weights[int(layer)]) for layer in layers},
            "debug_evidence_layer_weights": {str(layer): float(alpha_weights[int(layer)]) for layer in layers},
            "debug_prior_layer_weights": {str(layer): float(beta_weights[int(layer)]) for layer in layers},
            "debug_beta_by_layer": {
                str(layer): float(beta) * float(beta_weights[int(layer)]) for layer in layers
            },
            "debug_alpha_by_layer": {
                str(layer): float(alpha) * float(alpha_weights[int(layer)]) for layer in layers
            },
            "debug_by_layer": debug_by_layer,
            "debug_common_balance_trace_by_layer": common_trace_by_layer,
            "debug_source_prior_token_group": safe_text(source_prior_token_group),
            "debug_evidence_token_group": safe_text(evidence_token_group),
            "debug_source_prior_token_count": int(source_positions.numel()),
            "debug_evidence_token_count": int(evidence_positions.numel()),
            "debug_hulluedit_edit_token_position": int(edit_token_position),
            "debug_hulluedit_rank_evidence": int(rank_evidence),
            "debug_hulluedit_rank_prior": int(rank_prior),
            "debug_hulluedit_kappa": float(kappa),
            "debug_hulluedit_lambda_prior": float(lambda_prior),
            "debug_hulluedit_use_beta_grid": bool(use_beta_grid),
            "debug_hulluedit_lambda_prior_per_layer": finite_mean(
                item.get("lambda_prior_for_layer") for item in debug_rows
            ),
            "debug_hulluedit_vcr": finite_mean(item.get("vcr") for item in debug_rows),
            "debug_hulluedit_pcr": finite_mean(item.get("pcr") for item in debug_rows),
            "debug_hulluedit_gate": finite_mean(item.get("gate") for item in debug_rows),
            "debug_delta_l2": sum(float(item.get("delta_l2") or 0.0) for item in debug_rows),
            "debug_hulluedit_delta_evidence_subspace_l2": sum(
                float(item.get("delta_evidence_subspace_l2") or 0.0) for item in debug_rows
            ),
            "debug_hulluedit_delta_prior_subspace_l2": sum(
                float(item.get("delta_prior_subspace_l2") or 0.0) for item in debug_rows
            ),
            "debug_hulluedit_actual_rank_evidence": finite_mean(
                item.get("rank_evidence_actual") for item in debug_rows
            ),
            "debug_hulluedit_actual_rank_prior": finite_mean(
                item.get("rank_prior_actual") for item in debug_rows
            ),
        }
    )

    del inputs, outputs
    gc.collect()
    if torch.cuda.is_available():
        torch.cuda.empty_cache()
    return result


@torch.no_grad()
def patched_structured_subspace_logits(
    adapter: QwenOmniAdapter,
    *,
    row: Mapping[str, Any],
    layer_group: Sequence[int],
    layer_weights: Mapping[int, float] | None,
    evidence_layer_weights: Mapping[int, float] | None,
    prior_layer_weights: Mapping[int, float] | None,
    evidence_directions: Mapping[int, torch.Tensor],
    evidence_transfer_vectors: Mapping[int, torch.Tensor],
    prior_directions: Mapping[int, torch.Tensor],
    contamination_directions: Mapping[int, torch.Tensor] | None,
    beta: float,
    alpha: float,
    gamma: float,
    evidence_gaps: Mapping[int, float],
    evidence_transfer_mode: str,
    evidence_constraint_mode: str,
    evidence_constraint_strength: float,
    prior_suppression_operator: str,
    soft_suppression_evidence_lambda: float,
    intervention_constraint_mode: str,
    feasible_evidence_damage_tolerance: float,
    feasible_prior_reduction_floor_ratio: float,
    feasible_prior_reduction_floor_abs: float,
    yes_id: int,
    no_id: int,
    current_answer: str | None,
    candidate_answer: str | None,
    budget: Mapping[str, float],
    source_prior_token_group: str,
    evidence_token_group: str,
    head_selection_mode: str,
    max_patched_heads_per_layer: int,
    head_source_margin_min: float,
    head_source_mass_min: float,
    head_answer_contribution_min: float,
    source_token_selection_mode: str,
    source_token_top_k: int,
    source_token_min_attn: float,
    evidence_token_selection_mode: str,
    evidence_token_top_k: int,
    evidence_token_min_attn: float,
    token_head_operator: str,
    token_head_alpha_mode: str,
    token_head_alpha_layer_policy: str,
    oelpr_counterfactual_path_mode: str,
    oelpr_latent_anchor_mode: str,
    oelpr_latent_anchor_source: str,
    oelpr_latent_anchor_confidence_gate: str,
    oelpr_latent_anchor_gate_threshold: float,
    oelpr_latent_anchor_gate_tau: float,
    oelpr_reference_blend_mode: str,
    oelpr_reference_blend_strength: float,
    oelpr_attention_causal_mode: str,
    oelpr_path_score_mode: str,
    oelpr_token_flow_mode: str,
    oelpr_path_update_geometry: str,
    oelpr_conflict_budget: float,
    oelpr_hidden_budget_coupling: str,
    oelpr_target_trust_gate_mode: str,
    oelpr_target_trust_gate_floor: float,
    oelpr_target_trust_gate_tau: float,
    oelpr_target_trust_candidate_reliability: float | None,
    oelpr_target_trust_target_prob: float | None,
    causallens_lambda: float,
    acg_gamma: float,
    structured_hidden_strength: float,
    structured_hidden_update_mode: str,
    structured_hidden_carrier_source: str,
    structured_hidden_edit_site: str,
    structured_hidden_token_update_scale: float,
    structured_hidden_token_max_positions: int,
    structured_token_head_strength: float,
    structured_token_head_update_mode: str,
    structured_token_head_alpha_strength: float,
    hidden_beta_budget_scale: float,
    hidden_alpha_budget_scale: float,
    token_beta_budget_scale: float,
    token_alpha_budget_scale: float,
    oelpr_suppression_budget: float | None,
    oelpr_evidence_budget: float | None,
    hidden_current_protection_weight: float,
    token_head_current_protection_weight: float,
    hidden_answer_trust_region_mode: str,
    hidden_answer_trust_region_floor: float,
    hidden_answer_trust_region_text_plausibility_margin: float | None,
    hidden_answer_trust_region_text_plausibility_threshold: float,
    hidden_answer_trust_region_text_plausibility_tau: float,
    output_answer_trust_region_mode: str,
    output_answer_trust_region_floor: float,
    seed: int,
    adaptive_granularity_mode: str = "none",
    adaptive_granularity_tau: float = -0.5625,
    adaptive_granularity_temperature: float = 0.25,
    adaptive_granularity_hidden_floor: float = 0.0,
    adaptive_granularity_token_floor: float = 0.0,
    runtime_full_answer: str | None = None,
    runtime_target_answer: str | None = None,
    runtime_non_target_answer: str | None = None,
    runtime_text_answer: str | None = None,
    runtime_full_margin: float | None = None,
    runtime_target_margin: float | None = None,
    runtime_non_target_margin: float | None = None,
    runtime_text_margin: float | None = None,
    hulluedit_rank_evidence: int = 6,
    hulluedit_rank_prior: int = 4,
    hulluedit_kappa: float = 0.6,
    hulluedit_lambda_prior: float = 0.3,
    hulluedit_lambda_n_max: float = 4.0,
    hulluedit_lambda_p_max: float = 4.0,
    hulluedit_vcr_floor: float = 0.05,
    hulluedit_pcr_ceiling: float = 0.95,
    hulluedit_pcr_threshold: float = 0.02,
    hulluedit_blend_tau: float = 0.7,
    signed_path_subspace_blend_mode: str = "alignment",
    hulluedit_norm_preserve: bool = True,
    hulluedit_norm_beta: float = 0.5,
    explicit_residual_carrier: str = "none",
    explicit_residual_direction: torch.Tensor | None = None,
    matched_residual_norm_budgets: Mapping[int, float] | None = None,
    matched_residual_expected_gate: float | None = None,
    matched_residual_gate_atol: float = 1.0e-9,
    explicit_residual_debug: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Composite executor: branch-counterfactual carriers plus token/head/path correction.

    The hidden-state part can either apply the validated U/P/R update or only
    diagnose the branch-level carrier geometry. The token/head correction then
    realizes the intervention on final-query value paths.
    """
    raw_hidden_strength = max(0.0, float(structured_hidden_strength))
    raw_token_strength = max(0.0, float(structured_token_head_strength))
    adaptive_granularity_key = safe_text(adaptive_granularity_mode) or "none"
    if adaptive_granularity_key not in {
        "none",
        "sigmoid_margin",
        "reverse_sigmoid_margin",
        "confidence_margin",
        "random_control",
    }:
        raise ValueError(f"unknown adaptive_granularity_mode: {adaptive_granularity_mode}")
    runtime_full_label_for_adaptive = normalize_binary_label(runtime_full_answer)
    runtime_target_label_for_adaptive = normalize_binary_label(runtime_target_answer)
    runtime_non_target_label_for_adaptive = normalize_binary_label(runtime_non_target_answer)
    runtime_text_label_for_adaptive = normalize_binary_label(runtime_text_answer)
    candidate_label_for_adaptive = normalize_binary_label(candidate_answer)
    current_label_for_adaptive = normalize_binary_label(current_answer)

    def _signed_adaptive_margin(margin: Any, answer: str | None) -> float | None:
        value = _finite_float_or_none(margin)
        label = normalize_binary_label(answer)
        if value is None or label is None:
            return None
        signed = signed_margin_for_answer(float(value), label)
        return _finite_float_or_none(signed)

    def _positive_or_zero(value: float | None) -> float:
        return max(0.0, float(value)) if value is not None else 0.0

    def _positive_max(values: Iterable[float | None]) -> float | None:
        positives = [_positive_or_zero(value) for value in values if value is not None]
        if not positives:
            return None
        return float(max(positives))

    full_candidate_margin = _signed_adaptive_margin(runtime_full_margin, candidate_label_for_adaptive)
    target_candidate_margin = _signed_adaptive_margin(runtime_target_margin, candidate_label_for_adaptive)
    text_candidate_margin = _signed_adaptive_margin(runtime_text_margin, candidate_label_for_adaptive)
    full_current_margin = _signed_adaptive_margin(runtime_full_margin, current_label_for_adaptive)
    non_target_current_margin = _signed_adaptive_margin(
        runtime_non_target_margin,
        current_label_for_adaptive,
    )
    candidate_full_conflict = (
        max(0.0, -float(full_candidate_margin)) if full_candidate_margin is not None else None
    )
    candidate_branch_support = _positive_max((target_candidate_margin, text_candidate_margin))
    if candidate_full_conflict is not None and candidate_branch_support is not None:
        candidate_aligned_raw_conflict = min(
            float(candidate_full_conflict),
            float(candidate_branch_support),
        )
    else:
        candidate_aligned_raw_conflict = candidate_full_conflict
    if full_current_margin is not None and non_target_current_margin is not None:
        current_agreement_protection = min(
            _positive_or_zero(full_current_margin),
            _positive_or_zero(non_target_current_margin),
        )
    else:
        current_agreement_protection = 0.0
    adaptive_signal = (
        max(0.0, float(candidate_aligned_raw_conflict) - float(current_agreement_protection))
        if candidate_aligned_raw_conflict is not None
        else None
    )
    adaptive_conflict_signal = adaptive_signal
    confidence_signal_values = [
        abs(float(value))
        for value in (
            _finite_float_or_none(runtime_full_margin),
            _finite_float_or_none(runtime_target_margin),
            _finite_float_or_none(runtime_non_target_margin),
            _finite_float_or_none(runtime_text_margin),
        )
        if value is not None
    ]
    adaptive_confidence_signal = (
        float(max(confidence_signal_values)) if confidence_signal_values else None
    )
    adaptive_tau_value = float(adaptive_granularity_tau)
    adaptive_temperature_value = max(1.0e-6, float(adaptive_granularity_temperature))
    adaptive_hidden_floor_value = max(0.0, min(1.0, float(adaptive_granularity_hidden_floor)))
    adaptive_token_floor_value = max(0.0, min(1.0, float(adaptive_granularity_token_floor)))
    adaptive_gate = 0.0
    adaptive_random_gate: float | None = None
    adaptive_reason = "disabled"
    if adaptive_granularity_key == "confidence_margin":
        adaptive_signal = adaptive_confidence_signal
        if adaptive_signal is None:
            adaptive_reason = "missing_branch_confidence_margin"
        else:
            z = (float(adaptive_signal) - adaptive_tau_value) / adaptive_temperature_value
            if z >= 60.0:
                adaptive_gate = 0.0
            elif z <= -60.0:
                adaptive_gate = 1.0
            else:
                adaptive_gate = 1.0 / (1.0 + math.exp(z))
            adaptive_gate = max(0.0, min(1.0, float(adaptive_gate)))
            adaptive_reason = "branch_answer_confidence_margin_control"
    elif adaptive_granularity_key == "random_control":
        sample_key = safe_text(row.get("sample_id")) or safe_text(row.get("id")) or "unknown"
        digest = hashlib.sha256(
            f"{sample_key}|{int(seed)}|adaptive_granularity_random_control".encode("utf-8")
        ).digest()
        adaptive_random_gate = int.from_bytes(digest[:8], byteorder="big", signed=False) / float(2**64)
        adaptive_gate = max(0.0, min(1.0, float(adaptive_random_gate)))
        adaptive_signal = adaptive_random_gate
        adaptive_reason = "deterministic_random_gate_control"
    elif adaptive_granularity_key in {"sigmoid_margin", "reverse_sigmoid_margin"}:
        if adaptive_signal is None:
            adaptive_reason = "missing_candidate_aligned_conflict_strength"
        else:
            z = (float(adaptive_signal) - adaptive_tau_value) / adaptive_temperature_value
            if z >= 60.0:
                adaptive_gate = 0.0
            elif z <= -60.0:
                adaptive_gate = 1.0
            else:
                adaptive_gate = 1.0 / (1.0 + math.exp(z))
            adaptive_gate = max(0.0, min(1.0, float(adaptive_gate)))
            adaptive_reason = "candidate_aligned_runtime_full_margin_conflict_strength"
    if adaptive_granularity_key == "none":
        hidden_gate = 1.0
        token_gate = 1.0
    else:
        hidden_gate = 1.0 - adaptive_gate
        token_gate = adaptive_gate
    if adaptive_granularity_key == "reverse_sigmoid_margin":
        hidden_gate = adaptive_gate
        token_gate = 1.0 - adaptive_gate
    hidden_strength = raw_hidden_strength * (
        adaptive_hidden_floor_value + (1.0 - adaptive_hidden_floor_value) * hidden_gate
    )
    token_strength = raw_token_strength * (
        adaptive_token_floor_value + (1.0 - adaptive_token_floor_value) * token_gate
    )
    explicit_residual_carrier_key = safe_text(explicit_residual_carrier) or "none"
    if explicit_residual_carrier_key not in {"none", "literal_answer_axis"}:
        raise ValueError(f"unknown explicit_residual_carrier: {explicit_residual_carrier}")
    if explicit_residual_carrier_key == "literal_answer_axis":
        if explicit_residual_direction is None:
            raise ValueError("literal_answer_axis requires an explicit residual direction")
        axis = torch.as_tensor(explicit_residual_direction).detach().float().cpu()
        if axis.ndim != 1 or float(axis.norm().item()) <= 1.0e-12:
            raise ValueError(
                f"invalid literal answer axis shape/norm: shape={tuple(axis.shape)}, "
                f"norm={float(axis.norm().item())}"
            )
        if matched_residual_norm_budgets is None:
            raise ValueError("literal_answer_axis requires matched per-layer residual norm budgets")
        missing_budget_layers = [
            int(layer) for layer in layer_group if int(layer) not in matched_residual_norm_budgets
        ]
        if missing_budget_layers:
            raise ValueError(
                f"literal_answer_axis sidecar is missing layer budgets: {missing_budget_layers}"
            )
        if matched_residual_expected_gate is None:
            raise ValueError("literal_answer_axis requires the matched G2 adaptive gate")
        gate_error = abs(float(adaptive_gate) - float(matched_residual_expected_gate))
        if gate_error > max(0.0, float(matched_residual_gate_atol)):
            raise ValueError(
                "literal_answer_axis adaptive gate mismatch: "
                f"runtime={adaptive_gate:.17g}, sidecar={float(matched_residual_expected_gate):.17g}, "
                f"abs_error={gate_error:.3g}, atol={float(matched_residual_gate_atol):.3g}"
            )
    hidden_update_mode = safe_text(structured_hidden_update_mode) or "apply"
    if hidden_update_mode not in {"apply", "diagnose_only"}:
        raise ValueError(f"unknown structured_hidden_update_mode: {structured_hidden_update_mode}")
    hidden_carrier_source_key = safe_text(structured_hidden_carrier_source) or "branch"
    signed_path_blend_key = safe_text(signed_path_subspace_blend_mode) or "alignment"
    if signed_path_blend_key not in {"alignment", "coverage", "path_only"}:
        raise ValueError(f"unsupported signed_path_subspace_blend_mode: {signed_path_subspace_blend_mode}")
    if hidden_carrier_source_key not in {"branch", "trace_conditioned", "signed_path_subspace"}:
        raise ValueError(f"unknown structured_hidden_carrier_source: {structured_hidden_carrier_source}")
    hidden_edit_site_key = safe_text(structured_hidden_edit_site) or "final_token"
    if hidden_edit_site_key not in {
        "final_token",
        "selected_token_states",
        "selected_token_states_plus_final_gated",
        "selected_token_states_pre_attn",
        "selected_token_states_pre_attn_plus_final_gated",
    }:
        raise ValueError(f"unknown structured_hidden_edit_site: {structured_hidden_edit_site}")
    hidden_pre_attn_edit_enabled = hidden_edit_site_key in {
        "selected_token_states_pre_attn",
        "selected_token_states_pre_attn_plus_final_gated",
    }
    hidden_final_gated_edit_enabled = hidden_edit_site_key in {
        "selected_token_states_plus_final_gated",
        "selected_token_states_pre_attn_plus_final_gated",
    }
    hidden_token_update_scale_value = max(0.0, float(structured_hidden_token_update_scale))
    hidden_token_max_positions_value = max(0, int(structured_hidden_token_max_positions))
    if hidden_carrier_source_key == "signed_path_subspace" and HullueditSteerer is None:
        raise ImportError(
            f"HulluEdit repo is not importable from {HULLUEDIT_ROOT}. "
            "structured_hidden_carrier_source=signed_path_subspace requires HulluEdit weighted SVD."
        )
    if (
        safe_text(prior_suppression_operator) in {"signed_path_closed_form", "signed_path_coverage_closed_form"}
        and hidden_carrier_source_key != "signed_path_subspace"
    ):
        raise ValueError(f"prior_suppression_operator={prior_suppression_operator} requires signed_path_subspace carriers")
    path_carrier_required = (
        hidden_carrier_source_key in {"trace_conditioned", "signed_path_subspace"}
        or safe_text(prior_suppression_operator)
        in {
            "path_soft_minimal",
            "path_projected_minimal",
            "path_residual_minimal",
            "signed_path_closed_form",
            "signed_path_coverage_closed_form",
        }
        or safe_text(evidence_transfer_mode) in {"path_answer_margin", "path_answer_margin_minimal"}
    )
    token_update_mode = safe_text(structured_token_head_update_mode) or "apply"
    if token_update_mode not in {"apply", "trace_only"}:
        raise ValueError(f"unknown structured_token_head_update_mode: {structured_token_head_update_mode}")
    hidden_beta_budget_scale_value = max(0.0, min(1.0, float(hidden_beta_budget_scale)))
    hidden_alpha_budget_scale_value = max(0.0, min(1.0, float(hidden_alpha_budget_scale)))
    token_beta_budget_scale_value = max(0.0, min(1.0, float(token_beta_budget_scale)))
    token_alpha_budget_scale_value = max(0.0, min(1.0, float(token_alpha_budget_scale)))
    causallens_lambda_base_value = max(0.0, float(causallens_lambda)) * token_strength
    acg_gamma_base_value = max(0.0, float(acg_gamma)) * token_strength
    if token_strength <= 1.0e-12 and hidden_update_mode == "diagnose_only":
        raise ValueError("structured_hidden_update_mode=diagnose_only requires structured_token_head_strength > 0")
    hidden_current_protection = max(0.0, min(1.0, float(hidden_current_protection_weight)))
    hidden_answer_trust_region_key = safe_text(hidden_answer_trust_region_mode) or "none"
    if hidden_answer_trust_region_key not in {"none", "current_protection", "carrier_consensus", "text_plausibility"}:
        raise ValueError(f"unknown hidden_answer_trust_region_mode: {hidden_answer_trust_region_mode}")
    hidden_answer_trust_region_floor = float(hidden_answer_trust_region_floor)
    hidden_text_plausibility_margin = _finite_float_or_none(
        hidden_answer_trust_region_text_plausibility_margin
    )
    hidden_text_plausibility_threshold = float(hidden_answer_trust_region_text_plausibility_threshold)
    hidden_text_plausibility_tau = max(1.0e-6, float(hidden_answer_trust_region_text_plausibility_tau))
    output_answer_trust_region_key = safe_text(output_answer_trust_region_mode) or "none"
    if output_answer_trust_region_key not in {"none", "current_protection", "carrier_consensus"}:
        raise ValueError(f"unknown output_answer_trust_region_mode: {output_answer_trust_region_mode}")
    output_answer_trust_region_floor = float(output_answer_trust_region_floor)
    oelpr_cf_mode = safe_text(oelpr_counterfactual_path_mode) or "none"
    if oelpr_cf_mode not in {"none", "diagnose", "apply"}:
        raise ValueError(f"unknown oelpr_counterfactual_path_mode: {oelpr_counterfactual_path_mode}")
    oelpr_anchor_mode = safe_text(oelpr_latent_anchor_mode) or "none"
    if oelpr_anchor_mode not in {"none", "diagnose", "constrain"}:
        raise ValueError(f"unknown oelpr_latent_anchor_mode: {oelpr_latent_anchor_mode}")
    oelpr_attention_causal_key = safe_text(oelpr_attention_causal_mode) or "none"
    if oelpr_attention_causal_key not in {"none", "uniform_path_contrast", "uniform_path_boost"}:
        raise ValueError(f"unknown oelpr_attention_causal_mode: {oelpr_attention_causal_mode}")
    oelpr_path_score_key = safe_text(oelpr_path_score_mode) or "factorized"
    if oelpr_path_score_key not in {
        "factorized",
        "unified_sensitivity",
        "unified_sensitivity_posterior",
        "evidence_flow_calibrated",
    }:
        raise ValueError(f"unknown oelpr_path_score_mode: {oelpr_path_score_mode}")
    oelpr_token_flow_key = safe_text(oelpr_token_flow_mode) or "none"
    if oelpr_token_flow_key not in {"none", "reception_evidence_reweight", "reception_path_decompose"}:
        raise ValueError(f"unknown oelpr_token_flow_mode: {oelpr_token_flow_mode}")
    oelpr_path_update_geometry_key = safe_text(oelpr_path_update_geometry) or "additive"
    if oelpr_path_update_geometry_key not in {"additive", "angular", "anchor_nullspace"}:
        raise ValueError(f"unknown oelpr_path_update_geometry: {oelpr_path_update_geometry}")
    oelpr_budget_value = max(0.0, min(1.0, float(oelpr_conflict_budget)))
    oelpr_suppression_budget_value = max(
        0.0,
        min(
            1.0,
            float(oelpr_suppression_budget)
            if oelpr_suppression_budget is not None
            else float(oelpr_budget_value),
        ),
    )
    oelpr_evidence_budget_value = max(
        0.0,
        min(
            1.0,
            float(oelpr_evidence_budget)
            if oelpr_evidence_budget is not None
            else float(oelpr_budget_value),
        ),
    )
    causallens_lambda_value = causallens_lambda_base_value * float(token_alpha_budget_scale_value)
    acg_gamma_value = acg_gamma_base_value * float(token_beta_budget_scale_value)
    oelpr_hidden_budget_coupling_key = safe_text(oelpr_hidden_budget_coupling) or "none"
    if oelpr_hidden_budget_coupling_key not in {"none", "token_path_activity", "carrier_trace_activity"}:
        raise ValueError(f"unknown oelpr_hidden_budget_coupling: {oelpr_hidden_budget_coupling}")
    oelpr_target_trust_gate_key = safe_text(oelpr_target_trust_gate_mode) or "none"
    if oelpr_target_trust_gate_key not in {
        "none",
        "path_balance",
        "candidate_reliability",
        "target_prob",
        "target_prob_path_balance",
        "candidate_reliability_path_balance",
    }:
        raise ValueError(f"unknown oelpr_target_trust_gate_mode: {oelpr_target_trust_gate_mode}")
    oelpr_target_trust_gate_floor_value = max(0.0, min(1.0, float(oelpr_target_trust_gate_floor)))
    oelpr_target_trust_gate_tau_value = max(1.0e-6, float(oelpr_target_trust_gate_tau))
    oelpr_target_trust_candidate_reliability_value = _finite_float_or_none(
        oelpr_target_trust_candidate_reliability
    )
    oelpr_target_trust_target_prob_value = _finite_float_or_none(oelpr_target_trust_target_prob)
    oelpr_anchor_source = safe_text(oelpr_latent_anchor_source) or "early_self_logit"
    if oelpr_anchor_source not in {
        "early_self_logit",
        "full_context",
        "full_context_view_trust",
        "full_context_view_competition",
        "carrier_consensus",
        "carrier_consensus_soft",
    }:
        raise ValueError(f"unknown oelpr_latent_anchor_source: {oelpr_latent_anchor_source}")
    oelpr_anchor_gate_key = safe_text(oelpr_latent_anchor_confidence_gate) or "none"
    if oelpr_anchor_gate_key not in {"none", "soft_margin", "hard_margin"}:
        raise ValueError(
            f"unknown oelpr_latent_anchor_confidence_gate: {oelpr_latent_anchor_confidence_gate}"
        )
    oelpr_reference_blend_key = safe_text(oelpr_reference_blend_mode) or "none"
    if oelpr_reference_blend_key not in {"none", "head_subspace_transport"}:
        raise ValueError(f"unknown oelpr_reference_blend_mode: {oelpr_reference_blend_mode}")
    full_context_anchor_sources = {
        "full_context",
        "full_context_view_trust",
        "full_context_view_competition",
    }
    runtime_full_label = normalize_binary_label(runtime_full_answer)
    runtime_target_label = normalize_binary_label(runtime_target_answer)
    runtime_non_target_label = normalize_binary_label(runtime_non_target_answer)
    runtime_text_label = normalize_binary_label(runtime_text_answer)
    runtime_target_counter_label = opposite_binary_label(runtime_target_label)
    latent_anchor_carrier_consensus_margin = _mean_binary_margin(
        (
            runtime_full_margin,
            runtime_target_margin,
            runtime_non_target_margin,
            runtime_text_margin,
        )
    )
    latent_anchor_full_context_margin = _finite_float_or_none(runtime_full_margin)
    runtime_view_margins = (
        runtime_full_margin,
        runtime_target_margin,
        runtime_non_target_margin,
        runtime_text_margin,
    )
    oelpr_candidate_view_support = _max_view_answer_support(
        margins=runtime_view_margins,
        answer=candidate_answer,
    )
    oelpr_current_view_support = _max_view_answer_support(
        margins=runtime_view_margins,
        answer=current_answer,
    )
    if token_strength <= 1.0e-12 and hidden_answer_trust_region_key == "none" and not path_carrier_required:
        hidden = patched_prior_suppression_logits(
            adapter,
            row=row,
            layer_group=layer_group,
            layer_weights=layer_weights,
            evidence_layer_weights=evidence_layer_weights,
            prior_layer_weights=prior_layer_weights,
            evidence_directions=evidence_directions,
            evidence_transfer_vectors=evidence_transfer_vectors,
            prior_directions=prior_directions,
            contamination_directions=contamination_directions,
            beta=(
                float(beta)
                * hidden_strength
                * hidden_beta_budget_scale_value
                * (1.0 - hidden_current_protection)
            ),
            alpha=float(alpha) * hidden_strength * hidden_alpha_budget_scale_value,
            gamma=float(gamma) * hidden_strength * hidden_beta_budget_scale_value,
            evidence_gaps=evidence_gaps,
            evidence_transfer_mode=evidence_transfer_mode,
            evidence_constraint_mode=evidence_constraint_mode,
            evidence_constraint_strength=evidence_constraint_strength,
            prior_suppression_operator=prior_suppression_operator,
            soft_suppression_evidence_lambda=soft_suppression_evidence_lambda,
            intervention_constraint_mode=intervention_constraint_mode,
            feasible_evidence_damage_tolerance=feasible_evidence_damage_tolerance,
            feasible_prior_reduction_floor_ratio=feasible_prior_reduction_floor_ratio,
            feasible_prior_reduction_floor_abs=feasible_prior_reduction_floor_abs,
            yes_id=yes_id,
            no_id=no_id,
            budget=budget,
            explicit_residual_carrier=explicit_residual_carrier_key,
            explicit_residual_direction=explicit_residual_direction,
            matched_residual_norm_budgets=matched_residual_norm_budgets,
            explicit_residual_debug=explicit_residual_debug,
        )
        hidden.update(
            {
                "debug_executor_mode": "structured_subspace",
                "debug_structured_backbone_executor": "up_r_block_output",
                "debug_structured_hidden_update_mode": hidden_update_mode,
                "debug_structured_hidden_update_applied": hidden_update_mode == "apply",
                "debug_structured_hidden_carrier_source": hidden_carrier_source_key,
                "debug_explicit_residual_carrier": explicit_residual_carrier_key,
                "debug_matched_residual_expected_gate": matched_residual_expected_gate,
                "debug_matched_residual_gate_abs_error": (
                    abs(float(adaptive_gate) - float(matched_residual_expected_gate))
                    if matched_residual_expected_gate is not None
                    else None
                ),
                "debug_structured_token_head_enabled": False,
                "debug_structured_token_head_update_mode": token_update_mode,
                "debug_structured_token_head_update_applied": False,
                "debug_adaptive_granularity_mode": adaptive_granularity_key,
                "debug_adaptive_granularity_reason": adaptive_reason,
                "debug_adaptive_granularity_signal": adaptive_signal,
                "debug_adaptive_granularity_tau": adaptive_tau_value,
                "debug_adaptive_granularity_temperature": adaptive_temperature_value,
                "debug_adaptive_granularity_hidden_floor": adaptive_hidden_floor_value,
                "debug_adaptive_granularity_token_floor": adaptive_token_floor_value,
                "debug_adaptive_granularity_gate": adaptive_gate,
                "debug_adaptive_granularity_full_candidate_margin": full_candidate_margin,
                "debug_adaptive_granularity_target_candidate_margin": target_candidate_margin,
                "debug_adaptive_granularity_text_candidate_margin": text_candidate_margin,
                "debug_adaptive_granularity_full_current_margin": full_current_margin,
                "debug_adaptive_granularity_non_target_current_margin": non_target_current_margin,
                "debug_adaptive_granularity_candidate_full_conflict": candidate_full_conflict,
                "debug_adaptive_granularity_candidate_branch_support": candidate_branch_support,
                "debug_adaptive_granularity_current_agreement_protection": (
                    current_agreement_protection
                ),
                "debug_adaptive_granularity_raw_conflict": candidate_aligned_raw_conflict,
                "debug_adaptive_granularity_conflict_signal": adaptive_conflict_signal,
                "debug_adaptive_granularity_confidence_signal": adaptive_confidence_signal,
                "debug_adaptive_granularity_random_gate": adaptive_random_gate,
                "debug_adaptive_granularity_runtime_full_answer": runtime_full_label_for_adaptive,
                "debug_adaptive_granularity_runtime_target_answer": runtime_target_label_for_adaptive,
                "debug_adaptive_granularity_runtime_non_target_answer": (
                    runtime_non_target_label_for_adaptive
                ),
                "debug_adaptive_granularity_runtime_text_answer": runtime_text_label_for_adaptive,
                "debug_structured_hidden_strength_raw": raw_hidden_strength,
                "debug_structured_hidden_strength": hidden_strength,
                "debug_structured_hidden_current_protection_weight": hidden_current_protection,
                "debug_hidden_answer_trust_region_mode": hidden_answer_trust_region_key,
                "debug_hidden_answer_trust_region_floor": hidden_answer_trust_region_floor,
                "debug_structured_token_head_strength_raw": raw_token_strength,
                "debug_structured_token_head_strength": token_strength,
                "debug_structured_token_head_alpha_strength": float(structured_token_head_alpha_strength),
                "debug_oelpr_conflict_budget": oelpr_budget_value,
                "debug_oelpr_suppression_budget": oelpr_suppression_budget_value,
                "debug_oelpr_evidence_budget": oelpr_evidence_budget_value,
                "debug_hidden_beta_budget_scale": hidden_beta_budget_scale_value,
                "debug_hidden_alpha_budget_scale": hidden_alpha_budget_scale_value,
                "debug_token_beta_budget_scale": token_beta_budget_scale_value,
                "debug_token_alpha_budget_scale": token_alpha_budget_scale_value,
                "debug_oelpr_hidden_budget_coupling": oelpr_hidden_budget_coupling_key,
                "debug_oelpr_hidden_path_activity_scale": None,
                "debug_structured_hidden_prediction": hidden.get("prediction"),
                "debug_structured_hidden_margin": hidden.get("margin_yes_minus_no"),
                "debug_structured_token_prediction": None,
                "debug_structured_token_margin": None,
                "debug_structured_single_forward": False,
                "debug_structured_margin_shift_from_hidden": 0.0,
                "debug_token_head_alpha_layer_policy": safe_text(token_head_alpha_layer_policy),
            }
        )
        return hidden

    inputs = prepare_branch_inputs(adapter, row=dict(row), branch="full", budget=dict(budget))
    thinker = adapter._model.thinker
    lm_head = thinker.lm_head
    final_norm = getattr(getattr(thinker, "model", None), "norm", None)
    layers = [int(layer) for layer in layer_group]
    if not layers:
        raise ValueError("layer_group must not be empty")
    if layer_weights is None:
        weights = {layer: 1.0 / float(len(layers)) for layer in layers}
    else:
        total = sum(float(layer_weights.get(layer, 0.0)) for layer in layers)
        if total <= 0.0:
            raise ValueError(f"layer weights must sum to a positive value for group {layers}")
        weights = {layer: float(layer_weights.get(layer, 0.0)) / total for layer in layers}
    alpha_weights = _token_head_alpha_weights_for_policy(
        policy=str(token_head_alpha_layer_policy),
        operator=str(token_head_operator),
        layers=layers,
        layer_weights=weights,
        evidence_layer_weights=evidence_layer_weights if evidence_layer_weights is not None else weights,
        prior_layer_weights=prior_layer_weights if prior_layer_weights is not None else weights,
    )
    if prior_layer_weights is None:
        beta_weights = dict(weights)
    else:
        beta_total = sum(float(prior_layer_weights.get(layer, 0.0)) for layer in layers)
        if beta_total <= 0.0:
            raise ValueError(f"prior layer weights have no overlap with layer group {layers}")
        beta_weights = {
            layer: float(prior_layer_weights.get(layer, 0.0)) / beta_total for layer in layers
        }
    token_beta_weights = (
        dict(alpha_weights)
        if safe_text(token_head_operator) == "head_subspace_transport"
        else dict(beta_weights)
    )
    contamination_weights = dict(beta_weights)

    attention_mask = inputs.get("attention_mask")
    if attention_mask is None:
        attention_mask = torch.ones_like(inputs["input_ids"])
    special_ids = tokenizer_ids(adapter)
    label_masks = resolve_avcd_label_masks(
        input_ids=inputs["input_ids"].detach().cpu(),
        attention_mask=attention_mask.detach().cpu(),
        special_ids=special_ids,
    )
    causallens_system_positions = _resolve_causallens_system_positions(
        input_ids=inputs["input_ids"],
        attention_mask=attention_mask,
        special_ids=special_ids,
    )
    source_positions = _resolve_token_group_positions(
        label_masks=label_masks,
        group=source_prior_token_group,
        target_modality=safe_text(row.get("target_modality")),
    )
    evidence_positions = _resolve_token_group_positions(
        label_masks=label_masks,
        group=evidence_token_group,
        target_modality=safe_text(row.get("target_modality")),
    )
    if source_positions.numel() <= 0:
        raise ValueError(
            f"empty source-prior token group={source_prior_token_group} sample={safe_text(row.get('sample_id'))}"
        )
    if evidence_positions.numel() <= 0:
        raise ValueError(
            f"empty evidence token group={evidence_token_group} sample={safe_text(row.get('sample_id'))}"
        )

    selected_layer_set = set(layers)
    hidden_debug_by_layer: dict[str, dict[str, Any]] = {}
    token_debug_by_layer: dict[str, dict[str, Any]] = {}
    path_carriers_by_layer: dict[int, dict[str, Any]] = {}
    pre_attn_hidden_patch_debug_by_layer: dict[str, dict[str, Any]] = {}
    patched_attn_outputs: dict[int, torch.Tensor] = {}
    hooks = []
    latent_anchor_margin_by_layer: dict[int, float] = {}
    latent_anchor_source_layers = {
        int(layer)
        for layer in layers
        if float(alpha_weights.get(int(layer), 0.0)) > 1.0e-12
    }
    if not latent_anchor_source_layers:
        latent_anchor_source_layers = set(layers)

    def latent_anchor_margin_for_layer(layer_id: int, current_margin: float) -> float:
        if int(layer_id) in latent_anchor_source_layers:
            latent_anchor_margin_by_layer[int(layer_id)] = float(current_margin)
        values: list[tuple[float, float]] = []
        for anchor_layer in sorted(latent_anchor_margin_by_layer):
            if int(anchor_layer) in latent_anchor_source_layers:
                values.append(
                    (
                        float(latent_anchor_margin_by_layer[int(anchor_layer)]),
                        max(0.0, float(alpha_weights.get(int(anchor_layer), 0.0))),
                    )
                )
        if not values:
            return float(current_margin)
        weight_sum = sum(weight for _value, weight in values)
        if weight_sum <= 1.0e-12:
            return float(sum(value for value, _weight in values) / float(len(values)))
        return float(sum(value * weight for value, weight in values) / weight_sum)

    def make_token_pre_hook(layer_id: int):
        beta_for_layer = (
            float(beta)
            * token_strength
            * token_beta_budget_scale_value
            * float(token_beta_weights.get(int(layer_id), 0.0))
        )
        alpha_for_layer = (
            float(alpha)
            * token_strength
            * token_alpha_budget_scale_value
            * max(0.0, float(structured_token_head_alpha_strength))
            * float(alpha_weights.get(int(layer_id), 0.0))
        )

        def hook_fn(module, args, kwargs):
            hidden_states = args[0] if args else kwargs.get("hidden_states")
            position_embeddings = kwargs.get("position_embeddings")
            if hidden_states is None or position_embeddings is None or int(layer_id) not in selected_layer_set:
                return None
            if hidden_states.shape[1] <= 1:
                return None
            operator_key = safe_text(token_head_operator)
            selection_key = safe_text(head_selection_mode)
            alpha_active = safe_text(token_head_alpha_mode) in {"evidence_value_boost", "attention_transfer"}
            literature_operator_active = (
                operator_key == "causallens_acg_omni"
                and (
                    (
                        float(alpha_weights.get(int(layer_id), 0.0)) > 1.0e-12
                        and causallens_lambda_value > 1.0e-12
                    )
                    or (
                        float(beta_weights.get(int(layer_id), 0.0)) > 1.0e-12
                        and acg_gamma_value > 1.0e-12
                    )
                )
            )
            if (
                not literature_operator_active
                and not path_carrier_required
                and abs(float(beta_for_layer)) <= 1.0e-12
                and (not alpha_active or abs(float(alpha_for_layer)) <= 1.0e-12)
            ):
                token_debug_by_layer[str(layer_id)] = {
                    "selected_head_count": 0,
                    "selected_heads": [],
                    "beta_for_layer": beta_for_layer,
                    "alpha_for_layer": alpha_for_layer,
                    "token_beta_budget_scale": token_beta_budget_scale_value,
                    "token_alpha_budget_scale": token_alpha_budget_scale_value,
                    "oelpr_suppression_budget": oelpr_suppression_budget_value,
                    "oelpr_evidence_budget": oelpr_evidence_budget_value,
                    "operator": operator_key,
                    "alpha_mode": safe_text(token_head_alpha_mode),
                    "alpha_layer_policy": safe_text(token_head_alpha_layer_policy),
                    "token_head_update_mode": token_update_mode,
                    "token_head_update_applied": False,
                    "skip_reason": "zero_structured_token_head_weight",
                }
                return None
            attn_mask = kwargs.get("attention_mask")
            attn_row, value_states = _compute_last_query_attn_row_and_values(
                module,
                hidden_states=hidden_states,
                attention_mask=attn_mask,
                position_embeddings=position_embeddings,
            )
            row_before = attn_row[:, :, 0, :].float()
            self_logit_margin = _self_logit_yes_minus_no_margin(
                lm_head=lm_head,
                hidden_state=hidden_states[0, -1, :],
                yes_id=yes_id,
                no_id=no_id,
                final_norm=final_norm,
            )
            raw_latent_anchor_margin = latent_anchor_margin_for_layer(int(layer_id), self_logit_margin)
            latent_anchor_alignment = None
            latent_anchor_margin = raw_latent_anchor_margin
            if oelpr_anchor_source in full_context_anchor_sources:
                latent_anchor_margin, latent_anchor_alignment = _carrier_consensus_calibrated_anchor(
                    early_anchor_margin=raw_latent_anchor_margin,
                    carrier_consensus_margin=latent_anchor_full_context_margin,
                    soft_disagreement=False,
                )
            elif oelpr_anchor_source in {"carrier_consensus", "carrier_consensus_soft"}:
                latent_anchor_margin, latent_anchor_alignment = _carrier_consensus_calibrated_anchor(
                    early_anchor_margin=raw_latent_anchor_margin,
                    carrier_consensus_margin=latent_anchor_carrier_consensus_margin,
                    soft_disagreement=oelpr_anchor_source == "carrier_consensus_soft",
                )
            latent_anchor_answer = "Yes" if latent_anchor_margin >= 0.0 else "No"
            latent_anchor_counter_answer = opposite_binary_label(latent_anchor_answer)
            source_token_mask, source_token_gate, source_token_debug = _token_selection_mask_for_answer_path(
                row_before,
                value_states,
                source_positions,
                module=module,
                lm_head=lm_head,
                yes_id=yes_id,
                no_id=no_id,
                positive_answer=current_answer,
                negative_answer=candidate_answer,
                mode=source_token_selection_mode,
                top_k=source_token_top_k,
                min_attn=source_token_min_attn,
            )
            evidence_token_mask, evidence_token_gate, evidence_token_debug = _token_selection_mask_for_answer_path(
                row_before,
                value_states,
                evidence_positions,
                module=module,
                lm_head=lm_head,
                yes_id=yes_id,
                no_id=no_id,
                positive_answer=candidate_answer,
                negative_answer=current_answer,
                mode=evidence_token_selection_mode,
                top_k=evidence_token_top_k,
                min_attn=evidence_token_min_attn,
            )
            source_selection_key = safe_text(source_token_selection_mode).lower()
            if source_selection_key in {
                "unsupported_answer_effect_soft_topk_per_head",
                "unsupported_answer_effect_soft_positive",
            }:
                support_mode = (
                    "answer_effect_soft_topk_per_head"
                    if source_selection_key == "unsupported_answer_effect_soft_topk_per_head"
                    else "answer_effect_soft_positive"
                )
                source_token_mask, source_token_gate, unsupported_debug = (
                    _attenuate_source_gate_by_evidence_answer_support(
                        row_before,
                        value_states,
                        evidence_positions,
                        source_token_mask,
                        source_token_gate,
                        module=module,
                        lm_head=lm_head,
                        yes_id=yes_id,
                        no_id=no_id,
                        current_answer=current_answer,
                        candidate_answer=candidate_answer,
                        support_mode=support_mode,
                        top_k=evidence_token_top_k,
                        min_attn=evidence_token_min_attn,
                    )
                )
                source_token_debug.update(unsupported_debug)
            localized_evidence_token_mask = evidence_token_mask
            localized_evidence_token_gate = evidence_token_gate
            localized_evidence_token_debug = dict(evidence_token_debug)
            causallens_system_token_gate: torch.Tensor | None = None
            if operator_key == "causallens_acg_omni":
                seq_len = int(row_before.shape[-1])
                source_group_mask_1d = torch.zeros(seq_len, device=row_before.device, dtype=torch.bool)
                system_group_mask_1d = torch.zeros(seq_len, device=row_before.device, dtype=torch.bool)
                evidence_group_mask_1d = torch.zeros(seq_len, device=row_before.device, dtype=torch.bool)
                if int(source_positions.numel()) > 0:
                    src_pos = source_positions.to(device=row_before.device).long()
                    src_pos = src_pos[(src_pos >= 0) & (src_pos < seq_len)]
                    source_group_mask_1d[src_pos] = True
                if int(causallens_system_positions.numel()) > 0:
                    sys_pos = causallens_system_positions.to(device=row_before.device).long()
                    sys_pos = sys_pos[(sys_pos >= 0) & (sys_pos < seq_len)]
                    system_group_mask_1d[sys_pos] = True
                if int(evidence_positions.numel()) > 0:
                    evi_pos = evidence_positions.to(device=row_before.device).long()
                    evi_pos = evi_pos[(evi_pos >= 0) & (evi_pos < seq_len)]
                    evidence_group_mask_1d[evi_pos] = True
                textual_prior_mask_1d = source_group_mask_1d | system_group_mask_1d
                source_token_mask = textual_prior_mask_1d.view(1, 1, -1).expand_as(row_before)
                evidence_token_mask = localized_evidence_token_mask
                source_token_gate = source_token_mask.to(dtype=torch.float32)
                evidence_token_gate = localized_evidence_token_gate.to(dtype=torch.float32)
                causallens_system_token_gate = (
                    system_group_mask_1d.view(1, 1, -1).expand_as(row_before).to(dtype=torch.float32)
                )
                source_token_debug = {
                    "token_selection_overridden_by_operator": "causallens_acg_omni_textual_prior_group",
                    "token_count_selected_mean_per_head": float(textual_prior_mask_1d.float().sum().item()),
                    "token_count_selected_unique": int(textual_prior_mask_1d.detach().sum().cpu().item()),
                    "token_gate_sum_mean_per_head": float(textual_prior_mask_1d.float().sum().item()),
                    "causallens_text_token_count": int(source_group_mask_1d.detach().sum().cpu().item()),
                    "causallens_system_token_count": int(system_group_mask_1d.detach().sum().cpu().item()),
                }
                evidence_token_debug = dict(localized_evidence_token_debug)
                evidence_token_debug.update(
                    {
                        "token_selection_used_by_operator": "causallens_acg_omni_localized_evidence_carrier",
                        "causallens_full_evidence_group_token_count": int(
                            evidence_group_mask_1d.detach().sum().cpu().item()
                        ),
                    }
                )
            source_mass = (row_before * source_token_gate.float()).sum(dim=-1).mean(dim=0).detach().cpu()
            evidence_mass = (row_before * evidence_token_gate.float()).sum(dim=-1).mean(dim=0).detach().cpu()
            source_mass_all_heads = source_mass.detach().clone()
            evidence_mass_all_heads = evidence_mass.detach().clone()
            causallens_selection_sensitivity: torch.Tensor | None = None
            causallens_selection_sensitivity_hat: torch.Tensor | None = None
            if operator_key == "causallens_acg_omni":
                (
                    causallens_selection_sensitivity,
                    causallens_selection_sensitivity_hat,
                ) = _causallens_raw_evidence_sensitivity(row_before, evidence_token_gate)
            answer_contribution: dict[str, Any] | None = None
            answer_current_over_candidate: torch.Tensor | None = None
            answer_candidate_over_current: torch.Tensor | None = None
            if operator_key in {
                "continuous_carrier_refinement",
                "carrier_constrained_path_refinement",
                "carrier_trust_region_path_edit",
                "residual_guided_path_solver",
                "oelpr_constrained_path_refinement",
                "oelpr_attention_transport",
            } or selection_key in {
                "answer_contribution",
                "source_answer_contribution",
            }:
                all_source_contrib = _masked_value_contribution_from_mask(
                    row_before,
                    value_states,
                    source_token_gate,
                )
                answer_contribution = _head_answer_contribution_scores(
                    module=module,
                    contribution=all_source_contrib,
                    lm_head=lm_head,
                    yes_id=yes_id,
                    no_id=no_id,
                    current_answer=current_answer,
                    candidate_answer=candidate_answer,
                )
                answer_current_over_candidate = answer_contribution["current_minus_candidate"]
                answer_candidate_over_current = answer_contribution["candidate_minus_current"]
            if operator_key == "causallens_acg_omni" and selection_key == "causallens_sensitivity_topk":
                if causallens_selection_sensitivity is None:
                    selected_heads = torch.empty(0, dtype=torch.long)
                else:
                    scores = causallens_selection_sensitivity.detach().float().mean(dim=0).cpu()
                    head_count = int(scores.numel())
                    k = min(max(0, int(max_patched_heads_per_layer)), head_count)
                    if k <= 0:
                        selected_heads = torch.empty(0, dtype=torch.long)
                    else:
                        selected_heads = torch.argsort(scores, descending=True)[:k].sort().values
            elif operator_key in {
                "continuous_carrier_refinement",
                "carrier_constrained_path_refinement",
                "carrier_trust_region_path_edit",
                "residual_guided_path_solver",
            }:
                selected_heads = torch.arange(int(row_before.shape[1]), dtype=torch.long)
            elif operator_key in {
                "oelpr_constrained_path_refinement",
                "oelpr_attention_transport",
            }:
                # O-ELPR is stage-local: evidence layers select evidence-support heads,
                # while prior layers select source/prior heads. This avoids the previous
                # all-head edit and keeps the intervention at token/head/path granularity.
                prior_heads = torch.empty(0, dtype=torch.long)
                if abs(float(beta_for_layer)) > 1.0e-12:
                    prior_selection_mode = safe_text(head_selection_mode)
                    if prior_selection_mode.lower() == "source_answer_contribution":
                        # Source positions already localize the prior carrier here.
                        # Requiring source_mass > evidence_mass made late prior layers
                        # empty on conflict samples where evidence tokens also attract
                        # attention, so use the answer-axis effect as the prior criterion.
                        prior_selection_mode = "answer_contribution"
                    prior_heads = _select_patch_heads(
                        source_mass=source_mass,
                        evidence_mass=evidence_mass,
                        mode=prior_selection_mode,
                        max_heads=max_patched_heads_per_layer,
                        min_source_margin=head_source_margin_min,
                        min_source_mass=head_source_mass_min,
                        seed=_stable_int_seed(
                            seed,
                            safe_text(row.get("sample_id")),
                            layer_id,
                            "structured_token_head_prior",
                        ),
                        answer_current_over_candidate=answer_current_over_candidate,
                        min_answer_contribution=head_answer_contribution_min,
                    )
                evidence_heads = torch.empty(0, dtype=torch.long)
                if abs(float(alpha_for_layer)) > 1.0e-12:
                    evidence_candidate_over_current_for_selection = None
                    evidence_contrib_for_selection = _masked_value_contribution_from_mask(
                        row_before,
                        value_states,
                        evidence_token_gate,
                    )
                    evidence_answer_for_selection = _head_answer_contribution_scores(
                        module=module,
                        contribution=evidence_contrib_for_selection,
                        lm_head=lm_head,
                        yes_id=yes_id,
                        no_id=no_id,
                        current_answer=current_answer,
                        candidate_answer=candidate_answer,
                    )
                    if bool(evidence_answer_for_selection.get("available")):
                        evidence_candidate_over_current_for_selection = evidence_answer_for_selection[
                            "candidate_minus_current"
                        ]
                    evidence_heads = _select_evidence_support_heads(
                        source_mass=source_mass,
                        evidence_mass=evidence_mass,
                        max_heads=max_patched_heads_per_layer,
                        exclude_heads=prior_heads,
                        answer_candidate_over_current=evidence_candidate_over_current_for_selection,
                        min_answer_contribution=head_answer_contribution_min,
                    )
                if int(prior_heads.numel()) > 0 and int(evidence_heads.numel()) > 0:
                    selected_heads = torch.unique(torch.cat([prior_heads, evidence_heads])).sort().values
                elif int(prior_heads.numel()) > 0:
                    selected_heads = prior_heads.sort().values
                else:
                    selected_heads = evidence_heads.sort().values
            else:
                if hidden_carrier_source_key == "signed_path_subspace":
                    carrier_positions = torch.unique(
                        torch.cat(
                            [
                                source_positions.detach().long(),
                                evidence_positions.detach().long(),
                            ]
                        )
                    )
                    path_carriers_by_layer[int(layer_id)] = _signed_path_subspace_carriers_from_token_heads(
                        module=module,
                        row=row_before,
                        values=value_states,
                        carrier_positions=carrier_positions,
                        carrier_gate=torch.maximum(source_token_gate.float(), evidence_token_gate.float()),
                        branch_prior_direction=prior_directions[int(layer_id)],
                        branch_evidence_direction=evidence_directions[int(layer_id)],
                        lm_head=lm_head,
                        yes_id=yes_id,
                        no_id=no_id,
                        current_answer=latent_anchor_counter_answer,
                        candidate_answer=latent_anchor_answer,
                        rank_evidence=int(hulluedit_rank_evidence),
                        rank_prior=int(hulluedit_rank_prior),
                    )
                elif path_carrier_required:
                    path_source_contrib = _masked_value_contribution_from_mask(
                        row_before,
                        value_states,
                        source_token_gate,
                    )
                    path_evidence_contrib = _masked_value_contribution_from_mask(
                        row_before,
                        value_states,
                        evidence_token_gate,
                    )
                    path_source_current_over_candidate = (
                        answer_current_over_candidate
                        if answer_contribution and bool(answer_contribution.get("available"))
                        else None
                    )
                    if path_source_current_over_candidate is None:
                        path_source_answer_for_path = _head_answer_contribution_scores(
                            module=module,
                            contribution=path_source_contrib,
                            lm_head=lm_head,
                            yes_id=yes_id,
                            no_id=no_id,
                            current_answer=current_answer,
                            candidate_answer=candidate_answer,
                        )
                        if bool(path_source_answer_for_path.get("available")):
                            path_source_current_over_candidate = path_source_answer_for_path["current_minus_candidate"]
                    evidence_answer_for_path = _head_answer_contribution_scores(
                        module=module,
                        contribution=path_evidence_contrib,
                        lm_head=lm_head,
                        yes_id=yes_id,
                        no_id=no_id,
                        current_answer=current_answer,
                        candidate_answer=candidate_answer,
                    )
                    path_carriers_by_layer[int(layer_id)] = _path_soft_hidden_carriers_from_token_heads(
                        module=module,
                        source_contribution=path_source_contrib,
                        evidence_contribution=path_evidence_contrib,
                        source_mass=source_mass,
                        evidence_mass=evidence_mass,
                        prior_direction=prior_directions[int(layer_id)],
                        evidence_direction=evidence_directions[int(layer_id)],
                        source_current_over_candidate=path_source_current_over_candidate,
                        evidence_candidate_over_current=(
                            evidence_answer_for_path["candidate_minus_current"]
                            if bool(evidence_answer_for_path.get("available"))
                            else None
                        ),
                    )
                selected_heads = _select_patch_heads(
                    source_mass=source_mass,
                    evidence_mass=evidence_mass,
                    mode=head_selection_mode,
                    max_heads=max_patched_heads_per_layer,
                    min_source_margin=head_source_margin_min,
                    min_source_mass=head_source_mass_min,
                    seed=_stable_int_seed(seed, safe_text(row.get("sample_id")), layer_id, "structured_token_head"),
                    answer_current_over_candidate=answer_current_over_candidate,
                    min_answer_contribution=head_answer_contribution_min,
                )
            carrier_trace_token_debug: dict[str, Any] = {}
            if oelpr_hidden_budget_coupling_key == "carrier_trace_activity":
                evidence_trace_contrib = _masked_value_contribution_from_mask(
                    row_before,
                    value_states,
                    evidence_token_gate,
                )
                evidence_trace_answer = _head_answer_contribution_scores(
                    module=module,
                    contribution=evidence_trace_contrib,
                    lm_head=lm_head,
                    yes_id=yes_id,
                    no_id=no_id,
                    current_answer=current_answer,
                    candidate_answer=candidate_answer,
                )
                evidence_candidate_trace = (
                    evidence_trace_answer["candidate_minus_current"]
                    if bool(evidence_trace_answer.get("available"))
                    else None
                )
                if causallens_selection_sensitivity_hat is None:
                    _, carrier_trace_sensitivity_hat = _causallens_raw_evidence_sensitivity(
                        row_before,
                        evidence_token_gate,
                    )
                else:
                    carrier_trace_sensitivity_hat = causallens_selection_sensitivity_hat
                evidence_sensitivity_scores = carrier_trace_sensitivity_hat.detach().float().mean(dim=0).cpu()
                evidence_carrier_heads, evidence_carrier_score_debug = _select_carrier_trace_heads_by_score(
                    mass=evidence_mass,
                    max_heads=max_patched_heads_per_layer,
                    answer_scores=evidence_candidate_trace,
                    sensitivity_scores=evidence_sensitivity_scores,
                    min_answer_contribution=head_answer_contribution_min,
                )
                if int(evidence_carrier_heads.numel()) > 0:
                    e_heads_cpu = evidence_carrier_heads.detach().cpu().long()
                    evidence_carrier_mass = evidence_mass[e_heads_cpu].float()
                    evidence_carrier_sensitivity = evidence_sensitivity_scores[e_heads_cpu].float()
                    evidence_head_coverage = float(evidence_carrier_heads.numel()) / float(
                        max(1, int(max_patched_heads_per_layer))
                    )
                    evidence_activity = max(0.0, min(1.0, evidence_head_coverage)) * math.sqrt(
                        max(0.0, float(evidence_carrier_mass.mean().item()))
                        * max(1.0e-12, float(evidence_carrier_sensitivity.mean().item()))
                    )
                    evidence_carrier_candidate_mean = (
                        float(evidence_candidate_trace[e_heads_cpu].float().mean().item())
                        if evidence_candidate_trace is not None
                        else None
                    )
                    evidence_carrier_candidate_min = (
                        float(evidence_candidate_trace[e_heads_cpu].float().min().item())
                        if evidence_candidate_trace is not None
                        else None
                    )
                    evidence_carrier_candidate_max = (
                        float(evidence_candidate_trace[e_heads_cpu].float().max().item())
                        if evidence_candidate_trace is not None
                        else None
                    )
                else:
                    evidence_carrier_mass = torch.empty(0, dtype=torch.float32)
                    evidence_carrier_sensitivity = torch.empty(0, dtype=torch.float32)
                    evidence_activity = 0.0
                    evidence_carrier_candidate_mean = None
                    evidence_carrier_candidate_min = None
                    evidence_carrier_candidate_max = None
                carrier_trace_token_debug = {
                    "prior_carrier_heads": [int(x) for x in selected_heads.detach().cpu().long().tolist()],
                    "prior_carrier_head_count": int(selected_heads.numel()),
                    "evidence_carrier_heads": [
                        int(x) for x in evidence_carrier_heads.detach().cpu().long().tolist()
                    ],
                    "evidence_carrier_head_count": int(evidence_carrier_heads.numel()),
                    "evidence_carrier_activity": float(max(0.0, min(1.0, evidence_activity))),
                    "evidence_carrier_mass_mean": (
                        float(evidence_carrier_mass.mean().item())
                        if int(evidence_carrier_mass.numel()) > 0
                        else None
                    ),
                    "evidence_carrier_mass_min": (
                        float(evidence_carrier_mass.min().item())
                        if int(evidence_carrier_mass.numel()) > 0
                        else None
                    ),
                    "evidence_carrier_mass_max": (
                        float(evidence_carrier_mass.max().item())
                        if int(evidence_carrier_mass.numel()) > 0
                        else None
                    ),
                    "evidence_carrier_sensitivity_mean": (
                        float(evidence_carrier_sensitivity.mean().item())
                        if int(evidence_carrier_sensitivity.numel()) > 0
                        else None
                    ),
                    "evidence_carrier_candidate_over_current_mean": evidence_carrier_candidate_mean,
                    "evidence_carrier_candidate_over_current_min": evidence_carrier_candidate_min,
                    "evidence_carrier_candidate_over_current_max": evidence_carrier_candidate_max,
                    "evidence_carrier_answer_available": bool(evidence_trace_answer.get("available")),
                    "evidence_carrier_answer_fallback_reason": evidence_trace_answer.get("fallback_reason"),
                    **{
                        f"evidence_{key}": value
                        for key, value in evidence_carrier_score_debug.items()
                    },
                }
            if selected_heads.numel() <= 0:
                token_debug_by_layer[str(layer_id)] = {
                    "selected_head_count": 0,
                    "selected_heads": [],
                    "source_mass_mean_all_heads": float(source_mass.mean().item()),
                    "evidence_mass_mean_all_heads": float(evidence_mass.mean().item()),
                    "source_over_evidence_margin_mean_all_heads": float((source_mass - evidence_mass).mean().item()),
                    "beta_for_layer": beta_for_layer,
                    "alpha_for_layer": alpha_for_layer,
                    "operator": operator_key,
                    "alpha_layer_policy": safe_text(token_head_alpha_layer_policy),
                    "skip_reason": "empty_selected_heads",
                    "source_token_selection": source_token_debug,
                    "evidence_token_selection": evidence_token_debug,
                    "source_hidden_token_patch_positions": [],
                    "source_hidden_token_patch_weights": [],
                    "source_hidden_token_patch_count": 0,
                    "source_hidden_token_patch_weight_mean": None,
                    "evidence_hidden_token_patch_positions": [],
                    "evidence_hidden_token_patch_weights": [],
                    "evidence_hidden_token_patch_count": 0,
                    "evidence_hidden_token_patch_weight_mean": None,
                    "answer_contribution_available": bool(
                        answer_contribution.get("available") if answer_contribution else False
                    ),
                    "answer_contribution_fallback_reason": (
                        answer_contribution.get("fallback_reason") if answer_contribution else None
                    ),
                    "answer_contribution_min": float(head_answer_contribution_min),
                    "answer_current_over_candidate_mean_all_heads": (
                        finite_mean(answer_current_over_candidate.tolist())
                        if answer_current_over_candidate is not None
                        else None
                    ),
                    "answer_candidate_over_current_mean_all_heads": (
                        finite_mean(answer_candidate_over_current.tolist())
                        if answer_candidate_over_current is not None
                        else None
                    ),
                    **carrier_trace_token_debug,
                }
                return None

            original_head_output = torch.matmul(attn_row.float(), value_states.float())
            patched_head_output = original_head_output.clone()
            patched_projected_output: torch.Tensor | None = None
            heads = selected_heads.to(device=row_before.device)
            heads_cpu = selected_heads.detach().cpu().long()
            source_hidden_patch_plan = _hidden_token_patch_plan_from_gate(
                source_token_gate,
                selected_heads,
                seq_len=int(row_before.shape[-1]),
                max_positions=hidden_token_max_positions_value,
            )
            evidence_hidden_patch_plan = _hidden_token_patch_plan_from_gate(
                evidence_token_gate,
                selected_heads,
                seq_len=int(row_before.shape[-1]),
                max_positions=hidden_token_max_positions_value,
            )
            debug_payload: dict[str, Any] = {}
            if operator_key == "oelpr_attention_transport":
                source_contrib = _masked_value_contribution_from_mask(
                    row_before[:, heads, :],
                    value_states[:, heads, :, :],
                    source_token_gate[:, heads, :],
                )
                evidence_contrib = _masked_value_contribution_from_mask(
                    row_before[:, heads, :],
                    value_states[:, heads, :, :],
                    evidence_token_gate[:, heads, :],
                )
                evidence_answer_contribution = _head_answer_contribution_scores(
                    module=module,
                    contribution=evidence_contrib,
                    lm_head=lm_head,
                    yes_id=yes_id,
                    no_id=no_id,
                    current_answer=current_answer,
                    candidate_answer=candidate_answer,
                    head_indices=heads_cpu,
                )
                edited_row, transport_payload = _oelpr_attention_transport_row_with_masks(
                    row_before[:, heads, :],
                    source_mask=source_token_mask[:, heads, :],
                    evidence_mask=evidence_token_mask[:, heads, :],
                    source_gate=source_token_gate[:, heads, :],
                    evidence_gate=evidence_token_gate[:, heads, :],
                    source_mass=source_mass[heads_cpu],
                    evidence_mass=evidence_mass[heads_cpu],
                    beta_for_layer=beta_for_layer,
                    alpha_for_layer=alpha_for_layer,
                    alpha_mode=token_head_alpha_mode,
                    source_current_over_candidate=(
                        answer_current_over_candidate[heads_cpu]
                        if answer_contribution and bool(answer_contribution.get("available"))
                        else None
                    ),
                    evidence_candidate_over_current=(
                        evidence_answer_contribution["candidate_minus_current"]
                        if bool(evidence_answer_contribution.get("available"))
                        else None
                    ),
                    current_protection_weight=float(token_head_current_protection_weight),
                )
                full_edited_row = row_before.clone()
                full_edited_row[:, heads, :] = edited_row.to(device=row_before.device, dtype=row_before.dtype)
                patched_head_output = torch.matmul(full_edited_row.unsqueeze(2).float(), value_states.float())
                delta = patched_head_output[:, heads, :, :] - original_head_output[:, heads, :, :]
                debug_payload.update(transport_payload)
            elif operator_key == "attention_redistribution":
                edited_row, redistribution = _redistribute_attention_row_with_masks(
                    row_before,
                    selected_heads=selected_heads,
                    source_mask=source_token_mask,
                    evidence_mask=evidence_token_mask,
                    beta_for_layer=beta_for_layer,
                    alpha_for_layer=alpha_for_layer,
                    alpha_mode=token_head_alpha_mode,
                )
                patched_head_output = torch.matmul(edited_row.unsqueeze(2).float(), value_states.float())
                debug_payload.update(redistribution)
                source_contrib = _masked_value_contribution_from_mask(
                    row_before[:, heads, :],
                    value_states[:, heads, :, :],
                    source_token_gate[:, heads, :],
                )
                evidence_contrib = _masked_value_contribution_from_mask(
                    row_before[:, heads, :],
                    value_states[:, heads, :, :],
                    evidence_token_gate[:, heads, :],
                )
                delta = patched_head_output[:, heads, :, :] - original_head_output[:, heads, :, :]
            else:
                source_contrib = _masked_value_contribution_from_mask(
                    row_before[:, heads, :],
                    value_states[:, heads, :, :],
                    source_token_gate[:, heads, :],
                )
                evidence_contrib = _masked_value_contribution_from_mask(
                    row_before[:, heads, :],
                    value_states[:, heads, :, :],
                    evidence_token_gate[:, heads, :],
                )
                if operator_key == "orthogonal_value_suppression":
                    suppressible = _orthogonalize_head_contribution(source_contrib, evidence_contrib)
                elif operator_key == "head_subspace_transport":
                    transport_alpha_ratio = (
                        float(alpha) * max(0.0, float(structured_token_head_alpha_strength))
                        if safe_text(token_head_alpha_mode) == "evidence_value_boost"
                        else 0.0
                    )
                    transport = _head_subspace_transport_delta(
                        head_output=original_head_output[:, heads, :, :],
                        source_contribution=source_contrib,
                        evidence_contribution=evidence_contrib,
                        beta_for_layer=beta_for_layer,
                        transport_alpha_ratio=transport_alpha_ratio,
                    )
                    delta = torch.as_tensor(transport["delta"]).to(
                        device=patched_head_output.device,
                        dtype=torch.float32,
                    )
                    debug_payload.update({k: v for k, v in transport.items() if k != "delta"})
                    patched_head_output[:, heads, :, :] = patched_head_output[:, heads, :, :] + delta
                    suppressible = None
                elif operator_key == "allpath_head_scaling":
                    good_heads = _select_evidence_support_heads(
                        source_mass=source_mass,
                        evidence_mass=evidence_mass,
                        max_heads=max_patched_heads_per_layer,
                        exclude_heads=selected_heads,
                        answer_candidate_over_current=answer_candidate_over_current,
                        min_answer_contribution=head_answer_contribution_min,
                    )
                    scaled = _allpath_head_scaled_output(
                        original_head_output=original_head_output,
                        hallu_heads=selected_heads,
                        good_heads=good_heads,
                        beta_for_layer=beta_for_layer,
                        alpha_for_layer=alpha_for_layer,
                        alpha_mode=token_head_alpha_mode,
                    )
                    patched_head_output = scaled["patched_head_output"].to(
                        device=patched_head_output.device,
                        dtype=torch.float32,
                    )
                    delta = torch.as_tensor(scaled["delta"]).to(
                        device=patched_head_output.device,
                        dtype=torch.float32,
                    )
                    debug_payload.update(
                        {k: v for k, v in scaled.items() if k not in {"patched_head_output", "delta"}}
                    )
                    suppressible = None
                elif operator_key in {
                    "allpath_token_scaling",
                    "carrier_weighted_allpath_token_scaling",
                    "current_protected_carrier_weighted_allpath_token_scaling",
                }:
                    good_heads = _select_evidence_support_heads(
                        source_mass=source_mass,
                        evidence_mass=evidence_mass,
                        max_heads=max_patched_heads_per_layer,
                        exclude_heads=selected_heads,
                        answer_candidate_over_current=answer_candidate_over_current,
                        min_answer_contribution=head_answer_contribution_min,
                    )
                    if good_heads.numel() > 0:
                        good_dev = good_heads.to(device=row_before.device)
                        evidence_contrib_good = _masked_value_contribution_from_mask(
                            row_before[:, good_dev, :],
                            value_states[:, good_dev, :, :],
                            evidence_token_gate[:, good_dev, :],
                        )
                    else:
                        evidence_contrib_good = torch.zeros(
                            row_before.shape[0],
                            0,
                            1,
                            value_states.shape[-1],
                            device=row_before.device,
                            dtype=torch.float32,
                        )
                    if operator_key in {
                        "carrier_weighted_allpath_token_scaling",
                        "current_protected_carrier_weighted_allpath_token_scaling",
                    }:
                        source_prior_alignment = _head_carrier_alignment_scores(
                            module=module,
                            contribution=source_contrib,
                            carrier_direction=prior_directions[int(layer_id)],
                            head_indices=selected_heads,
                        )
                        evidence_carrier_alignment = _head_carrier_alignment_scores(
                            module=module,
                            contribution=evidence_contrib_good,
                            carrier_direction=evidence_directions[int(layer_id)],
                            head_indices=good_heads,
                        )
                        evidence_answer_contribution = _head_answer_contribution_scores(
                            module=module,
                            contribution=evidence_contrib_good,
                            lm_head=lm_head,
                            yes_id=yes_id,
                            no_id=no_id,
                            current_answer=current_answer,
                            candidate_answer=candidate_answer,
                            head_indices=good_heads,
                        )
                        selected_cpu = selected_heads.detach().cpu().long()
                        source_answer_selected = (
                            answer_current_over_candidate[selected_cpu]
                            if answer_current_over_candidate is not None
                            else None
                        )
                        scaled = _carrier_weighted_allpath_token_scaled_output(
                            original_head_output=original_head_output,
                            hallu_heads=selected_heads,
                            good_heads=good_heads,
                            source_contribution=source_contrib,
                            evidence_contribution_good=evidence_contrib_good,
                            evidence_contribution_selected=evidence_contrib,
                            source_prior_alignment=source_prior_alignment,
                            evidence_carrier_alignment=evidence_carrier_alignment,
                            beta_for_layer=beta_for_layer,
                            alpha_for_layer=alpha_for_layer,
                            alpha_mode=token_head_alpha_mode,
                            source_current_over_candidate=source_answer_selected,
                            evidence_candidate_over_current=(
                                evidence_answer_contribution["candidate_minus_current"]
                                if bool(evidence_answer_contribution.get("available"))
                                else None
                            ),
                            current_protection_weight=float(token_head_current_protection_weight),
                            protect_current=(
                                operator_key == "current_protected_carrier_weighted_allpath_token_scaling"
                            ),
                        )
                    else:
                        scaled = _allpath_token_scaled_output(
                            original_head_output=original_head_output,
                            hallu_heads=selected_heads,
                            good_heads=good_heads,
                            source_contribution=source_contrib,
                            evidence_contribution_good=evidence_contrib_good,
                            beta_for_layer=beta_for_layer,
                            alpha_for_layer=alpha_for_layer,
                            alpha_mode=token_head_alpha_mode,
                        )
                    patched_head_output = scaled["patched_head_output"].to(
                        device=patched_head_output.device,
                        dtype=torch.float32,
                    )
                    delta = torch.as_tensor(scaled["delta"]).to(
                        device=patched_head_output.device,
                        dtype=torch.float32,
                    )
                    debug_payload.update(
                        {k: v for k, v in scaled.items() if k not in {"patched_head_output", "delta"}}
                    )
                    suppressible = None
                elif operator_key == "continuous_carrier_refinement":
                    evidence_answer_contribution = _head_answer_contribution_scores(
                        module=module,
                        contribution=evidence_contrib,
                        lm_head=lm_head,
                        yes_id=yes_id,
                        no_id=no_id,
                        current_answer=current_answer,
                        candidate_answer=candidate_answer,
                    )
                    refined = _continuous_carrier_refinement_output(
                        original_head_output=original_head_output,
                        source_contribution=source_contrib,
                        evidence_contribution=evidence_contrib,
                        source_mass=source_mass,
                        evidence_mass=evidence_mass,
                        beta_for_layer=beta_for_layer,
                        alpha_for_layer=alpha_for_layer,
                        alpha_mode=token_head_alpha_mode,
                        source_current_over_candidate=(
                            answer_current_over_candidate
                            if answer_contribution and bool(answer_contribution.get("available"))
                            else None
                        ),
                        evidence_candidate_over_current=(
                            evidence_answer_contribution["candidate_minus_current"]
                            if bool(evidence_answer_contribution.get("available"))
                            else None
                        ),
                    )
                    patched_head_output = refined["patched_head_output"].to(
                        device=patched_head_output.device,
                        dtype=torch.float32,
                    )
                    delta = torch.as_tensor(refined["delta"]).to(
                        device=patched_head_output.device,
                        dtype=torch.float32,
                    )
                    debug_payload.update(
                        {k: v for k, v in refined.items() if k not in {"patched_head_output", "delta"}}
                    )
                    suppressible = None
                elif operator_key == "oelpr_constrained_path_refinement":
                    if oelpr_token_flow_key in {"reception_evidence_reweight", "reception_path_decompose"}:
                        flow = _oelpr_reception_path_decomposition(
                            module=module,
                            lm_head=lm_head,
                            yes_id=yes_id,
                            no_id=no_id,
                            current_answer=current_answer,
                            candidate_answer=candidate_answer,
                            hidden_states=hidden_states,
                            attention_mask=attn_mask,
                            position_embeddings=position_embeddings,
                            row=row_before[:, heads, :],
                            values=value_states[:, heads, :, :],
                            source_mask=source_token_mask[:, heads, :],
                            evidence_mask=evidence_token_mask[:, heads, :],
                            source_positions=source_positions,
                        evidence_positions=evidence_positions,
                        mode=oelpr_token_flow_key,
                        head_indices=heads_cpu,
                    )
                        source_contrib = flow["source_contribution"]
                        evidence_contrib = flow["evidence_contribution"]
                        source_mass = flow["source_mass"]
                        evidence_mass = flow["evidence_mass"]
                        debug_payload.update(flow["debug"])
                    evidence_answer_contribution = _head_answer_contribution_scores(
                        module=module,
                        contribution=evidence_contrib,
                        lm_head=lm_head,
                        yes_id=yes_id,
                        no_id=no_id,
                        current_answer=current_answer,
                        candidate_answer=candidate_answer,
                        head_indices=heads_cpu,
                    )
                    cf_source_target_shortcut_excess = None
                    cf_evidence_counter_support = None
                    cf_target_answer = runtime_target_label
                    cf_counter_answer = runtime_target_counter_label
                    latent_source_anchor_effect = None
                    latent_evidence_anchor_effect = None
                    full_context_path_margin = None
                    full_context_path_answer = None
                    full_context_path_counter_answer = None
                    source_full_context_path_effect = None
                    evidence_full_context_path_effect = None
                    source_attention_causal_effect = None
                    evidence_attention_causal_effect = None
                    anchor_nullspace_axis = None
                    if oelpr_anchor_source in full_context_anchor_sources:
                        full_context_path_margin = latent_anchor_full_context_margin
                        full_context_path_answer = runtime_full_label
                        if full_context_path_answer is None and full_context_path_margin is not None:
                            full_context_path_answer = (
                                "Yes" if float(full_context_path_margin) >= 0.0 else "No"
                            )
                        full_context_path_counter_answer = opposite_binary_label(
                            full_context_path_answer
                        )
                    if (
                        oelpr_cf_mode != "none"
                        and cf_target_answer is not None
                        and cf_counter_answer is not None
                    ):
                        source_target_effect = _head_binary_axis_contribution_scores(
                            module=module,
                            contribution=source_contrib,
                            lm_head=lm_head,
                            yes_id=yes_id,
                            no_id=no_id,
                            positive_answer=cf_target_answer,
                            negative_answer=cf_counter_answer,
                            head_indices=heads_cpu,
                        )
                        evidence_target_effect = _head_binary_axis_contribution_scores(
                            module=module,
                            contribution=evidence_contrib,
                            lm_head=lm_head,
                            yes_id=yes_id,
                            no_id=no_id,
                            positive_answer=cf_target_answer,
                            negative_answer=cf_counter_answer,
                            head_indices=heads_cpu,
                        )
                        if bool(source_target_effect.get("available")) and bool(
                            evidence_target_effect.get("available")
                        ):
                            source_target_minus_counter = source_target_effect[
                                "positive_minus_negative"
                            ]
                            evidence_target_minus_counter = evidence_target_effect[
                                "positive_minus_negative"
                            ]
                            cf_source_target_shortcut_excess = (
                                source_target_minus_counter - evidence_target_minus_counter
                            )
                            cf_evidence_counter_support = -evidence_target_minus_counter
                    if (
                        oelpr_anchor_mode != "none"
                        and latent_anchor_answer is not None
                        and latent_anchor_counter_answer is not None
                    ):
                        source_anchor_effect = _head_binary_axis_contribution_scores(
                            module=module,
                            contribution=source_contrib,
                            lm_head=lm_head,
                            yes_id=yes_id,
                            no_id=no_id,
                            positive_answer=latent_anchor_answer,
                            negative_answer=latent_anchor_counter_answer,
                            head_indices=heads_cpu,
                        )
                        evidence_anchor_effect = _head_binary_axis_contribution_scores(
                            module=module,
                            contribution=evidence_contrib,
                            lm_head=lm_head,
                            yes_id=yes_id,
                            no_id=no_id,
                            positive_answer=latent_anchor_answer,
                            negative_answer=latent_anchor_counter_answer,
                            head_indices=heads_cpu,
                        )
                        if bool(source_anchor_effect.get("available")) and bool(
                            evidence_anchor_effect.get("available")
                        ):
                            latent_source_anchor_effect = source_anchor_effect[
                                "positive_minus_negative"
                            ]
                            latent_evidence_anchor_effect = evidence_anchor_effect[
                                "positive_minus_negative"
                            ]
                    if (
                        oelpr_anchor_source in full_context_anchor_sources
                        and oelpr_anchor_mode != "none"
                        and full_context_path_answer is not None
                        and full_context_path_counter_answer is not None
                    ):
                        source_full_context_effect = _head_binary_axis_contribution_scores(
                            module=module,
                            contribution=source_contrib,
                            lm_head=lm_head,
                            yes_id=yes_id,
                            no_id=no_id,
                            positive_answer=full_context_path_answer,
                            negative_answer=full_context_path_counter_answer,
                            head_indices=heads_cpu,
                        )
                        evidence_full_context_effect = _head_binary_axis_contribution_scores(
                            module=module,
                            contribution=evidence_contrib,
                            lm_head=lm_head,
                            yes_id=yes_id,
                            no_id=no_id,
                            positive_answer=full_context_path_answer,
                            negative_answer=full_context_path_counter_answer,
                            head_indices=heads_cpu,
                        )
                        if bool(source_full_context_effect.get("available")) and bool(
                            evidence_full_context_effect.get("available")
                        ):
                            source_full_context_path_effect = source_full_context_effect[
                                "positive_minus_negative"
                            ]
                            evidence_full_context_path_effect = evidence_full_context_effect[
                                "positive_minus_negative"
                            ]
                    if (
                        oelpr_path_update_geometry_key == "anchor_nullspace"
                        and full_context_path_answer is not None
                        and full_context_path_counter_answer is not None
                    ):
                        anchor_nullspace_axis = _head_binary_axis_vectors(
                            module=module,
                            lm_head=lm_head,
                            yes_id=yes_id,
                            no_id=no_id,
                            positive_answer=full_context_path_answer,
                            negative_answer=full_context_path_counter_answer,
                            num_heads=int(heads.numel()),
                        )
                    if oelpr_attention_causal_key in {"uniform_path_contrast", "uniform_path_boost"}:
                        source_uniform_contrib = _uniform_counterfactual_value_contribution_from_mask(
                            row_before[:, heads, :],
                            value_states[:, heads, :, :],
                            source_token_gate[:, heads, :],
                        )
                        evidence_uniform_contrib = _uniform_counterfactual_value_contribution_from_mask(
                            row_before[:, heads, :],
                            value_states[:, heads, :, :],
                            evidence_token_gate[:, heads, :],
                        )
                        source_actual_axis = _head_answer_contribution_scores(
                            module=module,
                            contribution=source_contrib,
                            lm_head=lm_head,
                            yes_id=yes_id,
                            no_id=no_id,
                            current_answer=current_answer,
                            candidate_answer=candidate_answer,
                            head_indices=heads_cpu,
                        )
                        source_uniform_axis = _head_answer_contribution_scores(
                            module=module,
                            contribution=source_uniform_contrib,
                            lm_head=lm_head,
                            yes_id=yes_id,
                            no_id=no_id,
                            current_answer=current_answer,
                            candidate_answer=candidate_answer,
                            head_indices=heads_cpu,
                        )
                        evidence_uniform_axis = _head_answer_contribution_scores(
                            module=module,
                            contribution=evidence_uniform_contrib,
                            lm_head=lm_head,
                            yes_id=yes_id,
                            no_id=no_id,
                            current_answer=current_answer,
                            candidate_answer=candidate_answer,
                            head_indices=heads_cpu,
                        )
                        if bool(source_actual_axis.get("available")) and bool(
                            source_uniform_axis.get("available")
                        ):
                            source_attention_causal_effect = (
                                source_actual_axis["current_minus_candidate"]
                                - source_uniform_axis["current_minus_candidate"]
                            )
                        if bool(evidence_answer_contribution.get("available")) and bool(
                            evidence_uniform_axis.get("available")
                        ):
                            evidence_attention_causal_effect = (
                                evidence_answer_contribution["candidate_minus_current"]
                                - evidence_uniform_axis["candidate_minus_current"]
                            )
                    refined = _oelpr_constrained_path_refinement_output(
                        original_head_output=original_head_output[:, heads, :, :],
                        source_contribution=source_contrib,
                        evidence_contribution=evidence_contrib,
                        source_mass=source_mass,
                        evidence_mass=evidence_mass,
                        beta_for_layer=beta_for_layer,
                        alpha_for_layer=alpha_for_layer,
                        alpha_mode=token_head_alpha_mode,
                        source_current_over_candidate=(
                            answer_current_over_candidate[heads_cpu]
                            if answer_contribution and bool(answer_contribution.get("available"))
                            else None
                        ),
                        evidence_candidate_over_current=(
                            evidence_answer_contribution["candidate_minus_current"]
                            if bool(evidence_answer_contribution.get("available"))
                            else None
                        ),
                        current_protection_weight=float(token_head_current_protection_weight),
                        counterfactual_path_mode=oelpr_cf_mode,
                        source_target_shortcut_excess=cf_source_target_shortcut_excess,
                        evidence_counter_support=cf_evidence_counter_support,
                        counterfactual_target_answer=cf_target_answer,
                        counterfactual_counter_answer=cf_counter_answer,
                        latent_anchor_mode=oelpr_anchor_mode,
                        latent_anchor_margin=latent_anchor_margin,
                        source_latent_anchor_effect=latent_source_anchor_effect,
                        evidence_latent_anchor_effect=latent_evidence_anchor_effect,
                        latent_anchor_answer=latent_anchor_answer,
                        latent_anchor_counter_answer=latent_anchor_counter_answer,
                        latent_anchor_confidence_gate=oelpr_anchor_gate_key,
                        latent_anchor_gate_threshold=float(oelpr_latent_anchor_gate_threshold),
                        latent_anchor_gate_tau=float(oelpr_latent_anchor_gate_tau),
                        latent_anchor_apply_update_gate=(
                            oelpr_reference_blend_key == "none"
                        ),
                        full_context_margin=full_context_path_margin,
                        source_full_context_effect=source_full_context_path_effect,
                        evidence_full_context_effect=evidence_full_context_path_effect,
                        full_context_answer=full_context_path_answer,
                        full_context_counter_answer=full_context_path_counter_answer,
                        candidate_view_support=(
                            oelpr_candidate_view_support
                            if oelpr_anchor_source in {
                                "full_context_view_trust",
                                "full_context_view_competition",
                            }
                            else None
                        ),
                        current_view_support=(
                            oelpr_current_view_support
                            if oelpr_anchor_source in {
                                "full_context_view_trust",
                                "full_context_view_competition",
                            }
                            else None
                        ),
                        view_competition_mode=(
                            oelpr_anchor_source == "full_context_view_competition"
                        ),
                        path_update_geometry=oelpr_path_update_geometry_key,
                        anchor_nullspace_axis=anchor_nullspace_axis,
                        attention_causal_mode=oelpr_attention_causal_key,
                        path_score_mode=oelpr_path_score_key,
                        source_attention_causal_effect=source_attention_causal_effect,
                        evidence_attention_causal_effect=evidence_attention_causal_effect,
                    )
                    refined_patched = refined["patched_head_output"].to(
                        device=patched_head_output.device,
                        dtype=torch.float32,
                    )
                    refined_delta = torch.as_tensor(refined["delta"]).to(
                        device=patched_head_output.device,
                        dtype=torch.float32,
                    )
                    if oelpr_reference_blend_key == "head_subspace_transport":
                        reference_alpha_ratio = (
                            float(alpha) * max(0.0, float(structured_token_head_alpha_strength))
                            if safe_text(token_head_alpha_mode) == "evidence_value_boost"
                            else 0.0
                        )
                        reference = _head_subspace_transport_delta(
                            head_output=original_head_output[:, heads, :, :],
                            source_contribution=source_contrib,
                            evidence_contribution=evidence_contrib,
                            beta_for_layer=beta_for_layer,
                            transport_alpha_ratio=reference_alpha_ratio,
                        )
                        reference_delta = torch.as_tensor(reference["delta"]).to(
                            device=patched_head_output.device,
                            dtype=torch.float32,
                        )
                        reference_strength_ratio = max(
                            0.0,
                            float(oelpr_reference_blend_strength),
                        ) / max(1.0e-12, float(token_strength))
                        reference_delta = reference_delta * float(reference_strength_ratio)
                        residual_gate = float(refined.get("oelpr_latent_anchor_update_gate") or 1.0)
                        delta = reference_delta + residual_gate * (refined_delta - reference_delta)
                        patched_head_output[:, heads, :, :] = original_head_output[:, heads, :, :] + delta
                        debug_payload.update(
                            {
                                "oelpr_reference_blend_mode": oelpr_reference_blend_key,
                                "oelpr_reference_blend_gate": float(residual_gate),
                                "oelpr_reference_blend_strength": float(
                                    oelpr_reference_blend_strength
                                ),
                                "oelpr_reference_strength_ratio": float(
                                    reference_strength_ratio
                                ),
                                "oelpr_reference_delta_l2": float(
                                    reference_delta.norm().detach().cpu().item()
                                ),
                                "oelpr_raw_delta_l2": float(
                                    refined_delta.norm().detach().cpu().item()
                                ),
                                "oelpr_reference_residual_l2": float(
                                    (refined_delta - reference_delta).norm().detach().cpu().item()
                                ),
                            }
                        )
                        debug_payload.update(
                            {
                                f"oelpr_reference_{k}": v
                                for k, v in reference.items()
                                if k != "delta"
                            }
                        )
                    else:
                        delta = refined_delta
                        patched_head_output[:, heads, :, :] = refined_patched
                        debug_payload.update(
                            {
                                "oelpr_reference_blend_mode": oelpr_reference_blend_key,
                                "oelpr_reference_blend_gate": None,
                                "oelpr_reference_blend_strength": float(
                                    oelpr_reference_blend_strength
                                ),
                                "oelpr_reference_strength_ratio": None,
                                "oelpr_reference_delta_l2": None,
                                "oelpr_raw_delta_l2": float(
                                    refined_delta.norm().detach().cpu().item()
                                ),
                                "oelpr_reference_residual_l2": None,
                            }
                        )
                    debug_payload.update(
                        {k: v for k, v in refined.items() if k not in {"patched_head_output", "delta"}}
                    )
                    suppressible = None
                elif operator_key == "causallens_acg_omni":
                    eps = 1.0e-12
                    full_source_contrib = _masked_value_contribution_from_mask(
                        row_before,
                        value_states,
                        source_token_gate,
                    )
                    full_evidence_contrib = _masked_value_contribution_from_mask(
                        row_before,
                        value_states,
                        evidence_token_gate,
                    )
                    system_gate = (
                        causallens_system_token_gate
                        if causallens_system_token_gate is not None
                        else torch.zeros_like(source_token_gate)
                    )
                    system_prior_contrib = _masked_value_contribution_from_mask(
                        row_before,
                        value_states,
                        system_gate,
                    )
                    mid_hci_active = (
                        float(alpha_weights.get(int(layer_id), 0.0)) > 1.0e-12
                        and causallens_lambda_value > 1.0e-12
                    )
                    late_acg_active = (
                        float(beta_weights.get(int(layer_id), 0.0)) > 1.0e-12
                        and acg_gamma_value > 1.0e-12
                    )
                    source_norm2 = system_prior_contrib.float().square().sum(dim=-1).clamp_min(0.0)
                    evidence_norm2 = full_evidence_contrib.float().square().sum(dim=-1).clamp_min(0.0)
                    causal_gate = source_norm2 / (source_norm2 + evidence_norm2 + eps)
                    if (
                        causallens_selection_sensitivity is not None
                        and causallens_selection_sensitivity_hat is not None
                    ):
                        visual_sensitivity = causallens_selection_sensitivity
                        visual_sensitivity_hat = causallens_selection_sensitivity_hat
                    else:
                        visual_sensitivity, visual_sensitivity_hat = _causallens_raw_evidence_sensitivity(
                            row_before,
                            evidence_token_gate,
                            eps=eps,
                        )
                    projected_debug: dict[str, Any] = {}
                    if mid_hci_active:
                        contrast_direction = full_evidence_contrib.float() - full_source_contrib.float()
                        hci_target = full_source_contrib.float() + (
                            float(causallens_lambda_value)
                            * visual_sensitivity_hat.view(
                                visual_sensitivity_hat.shape[0],
                                visual_sensitivity_hat.shape[1],
                                1,
                                1,
                            )
                            * contrast_direction
                        )
                        hci_head_output = (
                            (1.0 - causal_gate.unsqueeze(-1)) * original_head_output.float()
                            + causal_gate.unsqueeze(-1) * hci_target
                        )
                        patched_head_output = original_head_output.float().clone()
                        patched_head_output[:, heads, :, :] = hci_head_output[:, heads, :, :]
                        hci_pre = patched_head_output.transpose(1, 2).contiguous()
                        hci_pre = hci_pre.reshape(hci_pre.shape[0], hci_pre.shape[1], -1)
                        selected_contrast_direction = torch.zeros_like(contrast_direction)
                        selected_contrast_direction[:, heads, :, :] = contrast_direction[:, heads, :, :]
                        prc_pre = selected_contrast_direction.transpose(1, 2).contiguous()
                        prc_pre = prc_pre.reshape(prc_pre.shape[0], prc_pre.shape[1], -1)
                        patched_projected_output = module.o_proj(hci_pre.to(dtype=hidden_states.dtype))
                        prc_projected = float(causallens_lambda_value) * module.o_proj(
                            prc_pre.to(dtype=hidden_states.dtype)
                        )
                        patched_projected_output = patched_projected_output + prc_projected
                        projected_debug.update(
                            {
                                "causallens_hci_active": True,
                                "causallens_prc_active": True,
                                "causallens_lambda": float(causallens_lambda_value),
                                "causallens_sensitivity_mean": float(
                                    visual_sensitivity.detach().float().mean().cpu().item()
                                ),
                                "causallens_sensitivity_hat_mean": float(
                                    visual_sensitivity_hat.detach().float().mean().cpu().item()
                                ),
                                "causallens_causal_gate_mean": float(
                                    causal_gate.detach().float().mean().cpu().item()
                                ),
                                "causallens_system_prior_l2": float(
                                    system_prior_contrib.detach().float().norm().cpu().item()
                                ),
                                "causallens_textual_prior_l2": float(
                                    full_source_contrib.detach().float().norm().cpu().item()
                                ),
                                "causallens_selected_sensitivity_mean": float(
                                    visual_sensitivity[:, heads].detach().float().mean().cpu().item()
                                ),
                                "causallens_selected_sensitivity_hat_mean": float(
                                    visual_sensitivity_hat[:, heads].detach().float().mean().cpu().item()
                                ),
                                "causallens_prc_l2": float(
                                    prc_projected.detach().float().norm().cpu().item()
                                ),
                                "causallens_hci_head_scope": "selected_heads",
                            }
                        )
                    else:
                        projected_debug.update(
                            {
                                "causallens_hci_active": False,
                                "causallens_prc_active": False,
                                "causallens_lambda": float(causallens_lambda_value),
                                "causallens_skip_reason": (
                                    "not_evidence_layer"
                                    if float(alpha_weights.get(int(layer_id), 0.0)) <= 1.0e-12
                                    else "zero_causallens_lambda"
                                ),
                            }
                        )
                    if late_acg_active:
                        non_evidence_gate = 1.0 - evidence_token_gate.float().clamp(0.0, 1.0)
                        uncond_row = row_before.float() * non_evidence_gate
                        uncond_denom = uncond_row.sum(dim=-1, keepdim=True)
                        uncond_row = torch.where(
                            uncond_denom > eps,
                            uncond_row / uncond_denom.clamp_min(eps),
                            row_before.float(),
                        )
                        uncond_head_output = torch.matmul(uncond_row.unsqueeze(2), value_states.float())
                        cond_pre = original_head_output.float().transpose(1, 2).contiguous()
                        cond_pre = cond_pre.reshape(cond_pre.shape[0], cond_pre.shape[1], -1)
                        uncond_pre = uncond_head_output.float().transpose(1, 2).contiguous()
                        uncond_pre = uncond_pre.reshape(uncond_pre.shape[0], uncond_pre.shape[1], -1)
                        guidance = cond_pre - uncond_pre
                        text_direction = uncond_pre / uncond_pre.norm(dim=-1, keepdim=True).clamp_min(eps)
                        guidance_parallel = (guidance * text_direction).sum(dim=-1, keepdim=True) * text_direction
                        guidance_orthogonal = guidance - guidance_parallel
                        final_pre = cond_pre + float(acg_gamma_value) * guidance_orthogonal
                        patched_projected_output = module.o_proj(final_pre.to(dtype=hidden_states.dtype))
                        patched_head_output = final_pre.reshape(
                            final_pre.shape[0],
                            final_pre.shape[1],
                            original_head_output.shape[1],
                            original_head_output.shape[-1],
                        ).transpose(1, 2).contiguous()
                        projected_debug.update(
                            {
                                "acg_active": True,
                                "acg_gamma": float(acg_gamma_value),
                                "acg_masked_unconditional_mass_mean": float(
                                    uncond_denom.detach().float().mean().cpu().item()
                                ),
                                "acg_guidance_l2": float(guidance.detach().float().norm().cpu().item()),
                                "acg_guidance_parallel_l2": float(
                                    guidance_parallel.detach().float().norm().cpu().item()
                                ),
                                "acg_guidance_orthogonal_l2": float(
                                    guidance_orthogonal.detach().float().norm().cpu().item()
                                ),
                            }
                        )
                    else:
                        projected_debug.update(
                            {
                                "acg_active": False,
                                "acg_gamma": float(acg_gamma_value),
                                "acg_skip_reason": (
                                    "not_prior_layer"
                                    if float(beta_weights.get(int(layer_id), 0.0)) <= 1.0e-12
                                    else "zero_acg_gamma"
                                ),
                            }
                        )
                    delta = patched_head_output.float() - original_head_output.float()
                    source_contrib = full_source_contrib[:, heads, :, :]
                    evidence_contrib = full_evidence_contrib[:, heads, :, :]
                    debug_payload.update(
                        {
                            "literature_operator": "causallens_acg_omni",
                            "literature_sources": [
                                "CausalLens_CVPR2026_HCI_PRC",
                                "ACG_CVPR2026F_attention_space_ortho",
                            ],
                            "causallens_acg_mid_hci_active": bool(mid_hci_active),
                            "causallens_acg_late_acg_active": bool(late_acg_active),
                            "causallens_acg_uses_textual_prior_group": True,
                            "causallens_acg_gate_uses_system_prior": True,
                            "causallens_acg_uses_localized_evidence_carrier": True,
                            "causallens_acg_source_path_l2": float(
                                full_source_contrib.detach().float().norm().cpu().item()
                            ),
                            "causallens_acg_system_path_l2": float(
                                system_prior_contrib.detach().float().norm().cpu().item()
                            ),
                            "causallens_acg_evidence_path_l2": float(
                                full_evidence_contrib.detach().float().norm().cpu().item()
                            ),
                            **projected_debug,
                        }
                    )
                    suppressible = None
                elif operator_key == "carrier_constrained_path_refinement":
                    evidence_answer_contribution = _head_answer_contribution_scores(
                        module=module,
                        contribution=evidence_contrib,
                        lm_head=lm_head,
                        yes_id=yes_id,
                        no_id=no_id,
                        current_answer=current_answer,
                        candidate_answer=candidate_answer,
                    )
                    source_prior_alignment = _head_carrier_alignment_scores(
                        module=module,
                        contribution=source_contrib,
                        carrier_direction=prior_directions[int(layer_id)],
                    )
                    evidence_carrier_alignment = _head_carrier_alignment_scores(
                        module=module,
                        contribution=evidence_contrib,
                        carrier_direction=evidence_directions[int(layer_id)],
                    )
                    refined = _carrier_constrained_path_refinement_output(
                        original_head_output=original_head_output,
                        source_contribution=source_contrib,
                        evidence_contribution=evidence_contrib,
                        source_mass=source_mass,
                        evidence_mass=evidence_mass,
                        source_prior_alignment=source_prior_alignment,
                        evidence_carrier_alignment=evidence_carrier_alignment,
                        beta_for_layer=beta_for_layer,
                        alpha_for_layer=alpha_for_layer,
                        alpha_mode=token_head_alpha_mode,
                        source_current_over_candidate=(
                            answer_current_over_candidate
                            if answer_contribution and bool(answer_contribution.get("available"))
                            else None
                        ),
                        evidence_candidate_over_current=(
                            evidence_answer_contribution["candidate_minus_current"]
                            if bool(evidence_answer_contribution.get("available"))
                            else None
                        ),
                    )
                    patched_head_output = refined["patched_head_output"].to(
                        device=patched_head_output.device,
                        dtype=torch.float32,
                    )
                    delta = torch.as_tensor(refined["delta"]).to(
                        device=patched_head_output.device,
                        dtype=torch.float32,
                    )
                    debug_payload.update(
                        {k: v for k, v in refined.items() if k not in {"patched_head_output", "delta"}}
                    )
                    suppressible = None
                elif operator_key == "carrier_trust_region_path_edit":
                    evidence_answer_contribution = _head_answer_contribution_scores(
                        module=module,
                        contribution=evidence_contrib,
                        lm_head=lm_head,
                        yes_id=yes_id,
                        no_id=no_id,
                        current_answer=current_answer,
                        candidate_answer=candidate_answer,
                    )
                    source_prior_alignment = _head_carrier_alignment_scores(
                        module=module,
                        contribution=source_contrib,
                        carrier_direction=prior_directions[int(layer_id)],
                    )
                    evidence_carrier_alignment = _head_carrier_alignment_scores(
                        module=module,
                        contribution=evidence_contrib,
                        carrier_direction=evidence_directions[int(layer_id)],
                    )
                    refined = _carrier_trust_region_path_edit_output(
                        original_head_output=original_head_output,
                        source_contribution=source_contrib,
                        evidence_contribution=evidence_contrib,
                        source_mass=source_mass,
                        evidence_mass=evidence_mass,
                        source_prior_alignment=source_prior_alignment,
                        evidence_carrier_alignment=evidence_carrier_alignment,
                        beta_for_layer=beta_for_layer,
                        alpha_for_layer=alpha_for_layer,
                        alpha_mode=token_head_alpha_mode,
                        source_current_over_candidate=(
                            answer_current_over_candidate
                            if answer_contribution and bool(answer_contribution.get("available"))
                            else None
                        ),
                        evidence_candidate_over_current=(
                            evidence_answer_contribution["candidate_minus_current"]
                            if bool(evidence_answer_contribution.get("available"))
                            else None
                        ),
                        kappa=hulluedit_kappa,
                        lambda_prior=hulluedit_lambda_prior,
                        lambda_n_max=hulluedit_lambda_n_max,
                        lambda_p_max=hulluedit_lambda_p_max,
                        vcr_floor=hulluedit_vcr_floor,
                        pcr_ceiling=hulluedit_pcr_ceiling,
                        pcr_threshold=hulluedit_pcr_threshold,
                        blend_tau=hulluedit_blend_tau,
                        norm_preserve=hulluedit_norm_preserve,
                        norm_beta=hulluedit_norm_beta,
                    )
                    patched_head_output = refined["patched_head_output"].to(
                        device=patched_head_output.device,
                        dtype=torch.float32,
                    )
                    delta = torch.as_tensor(refined["delta"]).to(
                        device=patched_head_output.device,
                        dtype=torch.float32,
                    )
                    debug_payload.update(
                        {k: v for k, v in refined.items() if k not in {"patched_head_output", "delta"}}
                    )
                    suppressible = None
                elif operator_key == "residual_guided_path_solver":
                    evidence_answer_contribution = _head_answer_contribution_scores(
                        module=module,
                        contribution=evidence_contrib,
                        lm_head=lm_head,
                        yes_id=yes_id,
                        no_id=no_id,
                        current_answer=current_answer,
                        candidate_answer=candidate_answer,
                    )
                    refined = _residual_guided_path_solver_output(
                        module=module,
                        hidden_state_base=hidden_states,
                        original_head_output=original_head_output,
                        source_contribution=source_contrib,
                        evidence_contribution=evidence_contrib,
                        source_mass=source_mass,
                        evidence_mass=evidence_mass,
                        prior_direction=prior_directions[int(layer_id)],
                        evidence_direction=evidence_directions[int(layer_id)],
                        evidence_transfer_vector=evidence_transfer_vectors[int(layer_id)],
                        beta_for_layer=beta_for_layer,
                        alpha_for_layer=alpha_for_layer,
                        alpha_mode=token_head_alpha_mode,
                        source_current_over_candidate=(
                            answer_current_over_candidate
                            if answer_contribution and bool(answer_contribution.get("available"))
                            else None
                        ),
                        evidence_candidate_over_current=(
                            evidence_answer_contribution["candidate_minus_current"]
                            if bool(evidence_answer_contribution.get("available"))
                            else None
                        ),
                    )
                    patched_head_output = refined["patched_head_output"].to(
                        device=patched_head_output.device,
                        dtype=torch.float32,
                    )
                    delta = torch.as_tensor(refined["delta"]).to(
                        device=patched_head_output.device,
                        dtype=torch.float32,
                    )
                    debug_payload.update(
                        {k: v for k, v in refined.items() if k not in {"patched_head_output", "delta"}}
                    )
                    suppressible = None
                elif operator_key == "raw_value_suppression":
                    suppressible = source_contrib.float()
                else:
                    raise ValueError(f"unknown token_head_value operator: {token_head_operator}")
                if suppressible is not None:
                    delta = -float(beta_for_layer) * suppressible
                    if safe_text(token_head_alpha_mode) == "evidence_value_boost":
                        delta = delta + float(alpha_for_layer) * evidence_contrib.float()
                    patched_head_output[:, heads, :, :] = patched_head_output[:, heads, :, :] + delta

            if token_update_mode == "apply":
                if patched_projected_output is not None:
                    patched_attn_outputs[id(module)] = patched_projected_output.to(dtype=hidden_states.dtype)
                else:
                    attn_output = patched_head_output.transpose(1, 2).contiguous()
                    attn_output = attn_output.reshape(attn_output.shape[0], attn_output.shape[1], -1)
                    attn_output = attn_output.to(dtype=hidden_states.dtype)
                    patched_attn_outputs[id(module)] = module.o_proj(attn_output)

            source_norm = float(source_contrib.detach().float().norm().cpu().item())
            evidence_norm = float(evidence_contrib.detach().float().norm().cpu().item())
            delta_norm = float(delta.detach().float().norm().cpu().item())
            if int(source_mass.numel()) == int(selected_heads.numel()):
                selected_source_mass = source_mass.float()
            else:
                selected_source_mass = source_mass[heads_cpu].float()
            if int(evidence_mass.numel()) == int(selected_heads.numel()):
                selected_evidence_mass = evidence_mass.float()
            else:
                selected_evidence_mass = evidence_mass[heads_cpu].float()
            selected_answer_current_over_candidate = (
                answer_current_over_candidate[heads_cpu].float()
                if answer_current_over_candidate is not None
                else torch.empty(0, dtype=torch.float32)
            )
            selected_answer_candidate_over_current = (
                answer_candidate_over_current[heads_cpu].float()
                if answer_candidate_over_current is not None
                else torch.empty(0, dtype=torch.float32)
            )
            token_debug_by_layer[str(layer_id)] = {
                "selected_head_count": int(selected_heads.numel()),
                "selected_heads": [int(x) for x in selected_heads.tolist()],
                "source_token_count": int(source_positions.numel()),
                "evidence_token_count": int(evidence_positions.numel()),
                "source_mass_mean_all_heads": float(source_mass_all_heads.mean().item()),
                "evidence_mass_mean_all_heads": float(evidence_mass_all_heads.mean().item()),
                "source_over_evidence_margin_mean_all_heads": float(
                    (source_mass_all_heads - evidence_mass_all_heads).mean().item()
                ),
                "source_mass_mean_selected_heads": float(selected_source_mass.mean().item()),
                "evidence_mass_mean_selected_heads": float(selected_evidence_mass.mean().item()),
                "source_over_evidence_margin_mean_selected_heads": float(
                    (selected_source_mass - selected_evidence_mass).mean().item()
                ),
                "answer_contribution_available": bool(
                    answer_contribution.get("available") if answer_contribution else False
                ),
                "answer_contribution_fallback_reason": (
                    answer_contribution.get("fallback_reason") if answer_contribution else None
                ),
                "answer_candidate_token_id": (
                    answer_contribution.get("candidate_token_id") if answer_contribution else None
                ),
                "answer_current_token_id": (
                    answer_contribution.get("current_token_id") if answer_contribution else None
                ),
                "answer_contribution_min": float(head_answer_contribution_min),
                "answer_current_over_candidate_mean_all_heads": (
                    finite_mean(answer_current_over_candidate.tolist())
                    if answer_current_over_candidate is not None
                    else None
                ),
                "answer_current_over_candidate_mean_selected_heads": (
                    finite_mean(selected_answer_current_over_candidate.tolist())
                    if selected_answer_current_over_candidate.numel() > 0
                    else None
                ),
                "answer_candidate_over_current_mean_all_heads": (
                    finite_mean(answer_candidate_over_current.tolist())
                    if answer_candidate_over_current is not None
                    else None
                ),
                "answer_candidate_over_current_mean_selected_heads": (
                    finite_mean(selected_answer_candidate_over_current.tolist())
                    if selected_answer_candidate_over_current.numel() > 0
                    else None
                ),
                "answer_support_head_count_all": (
                    int((answer_candidate_over_current > 0).sum().item())
                    if answer_candidate_over_current is not None
                    else None
                ),
                "answer_interference_head_count_all": (
                    int((answer_current_over_candidate > 0).sum().item())
                    if answer_current_over_candidate is not None
                    else None
                ),
                "self_logit_yes_minus_no_margin": float(self_logit_margin),
                "latent_anchor_source": oelpr_anchor_source,
                "latent_anchor_raw_margin": float(raw_latent_anchor_margin),
                "latent_anchor_full_context_margin": latent_anchor_full_context_margin,
                "latent_anchor_carrier_consensus_margin": latent_anchor_carrier_consensus_margin,
                "latent_anchor_carrier_alignment": latent_anchor_alignment,
                "latent_anchor_margin": float(latent_anchor_margin),
                "latent_anchor_answer": latent_anchor_answer,
                "latent_anchor_counter_answer": latent_anchor_counter_answer,
                "latent_anchor_source_layers": [int(x) for x in sorted(latent_anchor_source_layers)],
                "source_value_contribution_l2": source_norm,
                "evidence_value_contribution_l2": evidence_norm,
                "delta_l2": delta_norm,
                "source_token_selection": source_token_debug,
                "evidence_token_selection": evidence_token_debug,
                "source_hidden_token_patch_positions": source_hidden_patch_plan["positions"],
                "source_hidden_token_patch_weights": source_hidden_patch_plan["weights"],
                "source_hidden_token_patch_count": source_hidden_patch_plan["count"],
                "source_hidden_token_patch_weight_mean": source_hidden_patch_plan["weight_mean"],
                "source_hidden_token_patch_weight_max": source_hidden_patch_plan["weight_max"],
                "source_hidden_token_patch_weight_sum": source_hidden_patch_plan["weight_sum"],
                "evidence_hidden_token_patch_positions": evidence_hidden_patch_plan["positions"],
                "evidence_hidden_token_patch_weights": evidence_hidden_patch_plan["weights"],
                "evidence_hidden_token_patch_count": evidence_hidden_patch_plan["count"],
                "evidence_hidden_token_patch_weight_mean": evidence_hidden_patch_plan["weight_mean"],
                "evidence_hidden_token_patch_weight_max": evidence_hidden_patch_plan["weight_max"],
                "evidence_hidden_token_patch_weight_sum": evidence_hidden_patch_plan["weight_sum"],
                "source_token_count_selected_mean_per_head": source_token_debug.get(
                    "token_count_selected_mean_per_head"
                ),
                "source_token_count_selected_unique": source_token_debug.get("token_count_selected_unique"),
                "evidence_token_count_selected_mean_per_head": evidence_token_debug.get(
                    "token_count_selected_mean_per_head"
                ),
                "evidence_token_count_selected_unique": evidence_token_debug.get("token_count_selected_unique"),
                "beta_for_layer": beta_for_layer,
                "alpha_for_layer": alpha_for_layer,
                "token_beta_budget_scale": token_beta_budget_scale_value,
                "token_alpha_budget_scale": token_alpha_budget_scale_value,
                "oelpr_suppression_budget": oelpr_suppression_budget_value,
                "oelpr_evidence_budget": oelpr_evidence_budget_value,
                "token_head_update_mode": token_update_mode,
                "token_head_update_applied": token_update_mode == "apply",
                "operator": operator_key,
                "alpha_mode": safe_text(token_head_alpha_mode),
                "alpha_layer_policy": safe_text(token_head_alpha_layer_policy),
                **carrier_trace_token_debug,
                **debug_payload,
            }
            return None

        return hook_fn

    def make_pre_attn_hidden_patch_hook(layer_id: int):
        e_cpu = evidence_directions[int(layer_id)].detach().float().cpu()
        t_cpu = evidence_transfer_vectors[int(layer_id)].detach().float().cpu()
        p_cpu = prior_directions[int(layer_id)].detach().float().cpu()
        c_cpu = (
            contamination_directions[int(layer_id)].detach().float().cpu()
            if contamination_directions is not None and int(layer_id) in contamination_directions
            else torch.zeros_like(p_cpu)
        )
        evidence_gap = float(evidence_gaps[int(layer_id)])
        beta_for_layer_raw = (
            float(beta)
            * hidden_strength
            * hidden_beta_budget_scale_value
            * float(beta_weights.get(int(layer_id), 0.0))
        )
        beta_for_layer = beta_for_layer_raw * (1.0 - hidden_current_protection)
        alpha_for_layer = (
            float(alpha)
            * hidden_strength
            * hidden_alpha_budget_scale_value
            * float(alpha_weights.get(int(layer_id), 0.0))
        )
        gamma_for_layer = (
            float(gamma)
            * hidden_strength
            * hidden_beta_budget_scale_value
            * float(contamination_weights.get(int(layer_id), 0.0))
        )

        def hook_fn(_module, args, kwargs):
            if not hidden_pre_attn_edit_enabled or hidden_update_mode == "diagnose_only":
                return None
            hidden_states = args[0] if args else kwargs.get("hidden_states")
            if not isinstance(hidden_states, torch.Tensor) or int(layer_id) not in selected_layer_set:
                return None
            if hidden_states.shape[1] <= 1:
                return None
            if (
                abs(float(beta_for_layer)) <= 1.0e-12
                and abs(float(alpha_for_layer)) <= 1.0e-12
                and abs(float(gamma_for_layer)) <= 1.0e-12
            ):
                return None
            patched = hidden_states.clone()
            seq_len = int(patched.shape[1])
            final_index = seq_len - 1
            p_dir = unit(p_cpu).to(device=patched.device, dtype=torch.float32)
            e_dir = unit(e_cpu).to(device=patched.device, dtype=torch.float32)
            c_norm = float(c_cpu.norm().item())
            c_dir = (
                unit(c_cpu).to(device=patched.device, dtype=torch.float32)
                if c_norm > 1.0e-12
                else torch.zeros_like(p_dir)
            )
            transfer_vec = t_cpu.to(device=patched.device, dtype=torch.float32)

            def _positions_to_patch(positions: torch.Tensor) -> list[int]:
                pos = positions.detach().cpu().long()
                pos = pos[(pos >= 0) & (pos < seq_len) & (pos != final_index)]
                if pos.numel() <= 0:
                    return []
                pos = pos.unique(sorted=True)
                if hidden_token_max_positions_value > 0 and int(pos.numel()) > hidden_token_max_positions_value:
                    pos = pos[:hidden_token_max_positions_value]
                return [int(x) for x in pos.tolist()]

            source_patch_positions = _positions_to_patch(source_positions)
            evidence_patch_positions = _positions_to_patch(evidence_positions)
            selected_source_token_patch_count = 0
            selected_evidence_token_patch_count = 0
            selected_hidden_token_update_l2 = 0.0
            scale = float(hidden_token_update_scale_value)
            if scale > 1.0e-12:
                for pos_idx in source_patch_positions:
                    token_base = patched[0, pos_idx, :].float()
                    source_projection = torch.dot(token_base, p_dir) * p_dir
                    contamination_projection = (
                        torch.dot(token_base, c_dir) * c_dir
                        if c_norm > 1.0e-12
                        else torch.zeros_like(token_base)
                    )
                    token_delta = (
                        -float(beta_for_layer) * source_projection
                        -float(gamma_for_layer) * contamination_projection
                    ) * scale
                    patched[0, pos_idx, :] = (token_base + token_delta).to(dtype=patched.dtype)
                    selected_source_token_patch_count += 1
                    selected_hidden_token_update_l2 += float(token_delta.norm().detach().cpu().item())
                for pos_idx in evidence_patch_positions:
                    token_base = patched[0, pos_idx, :].float()
                    if evidence_transfer_mode == "legacy_projection_gap":
                        token_delta = float(alpha_for_layer) * max(0.0, evidence_gap) * e_dir
                    elif evidence_transfer_mode == "clean_target_full_gap":
                        token_delta = float(alpha_for_layer) * transfer_vec
                    elif evidence_transfer_mode in {"path_answer_margin", "path_answer_margin_minimal"}:
                        token_delta = float(alpha_for_layer) * max(0.0, evidence_gap) * e_dir
                    else:
                        raise ValueError(f"unknown evidence_transfer_mode: {evidence_transfer_mode}")
                    token_delta = token_delta * scale
                    patched[0, pos_idx, :] = (token_base + token_delta).to(dtype=patched.dtype)
                    selected_evidence_token_patch_count += 1
                    selected_hidden_token_update_l2 += float(token_delta.norm().detach().cpu().item())
            pre_attn_hidden_patch_debug_by_layer[str(layer_id)] = {
                "hidden_pre_attn_patch_applied": True,
                "hidden_pre_attn_source_token_patch_count": int(selected_source_token_patch_count),
                "hidden_pre_attn_evidence_token_patch_count": int(selected_evidence_token_patch_count),
                "hidden_pre_attn_token_patch_count": int(
                    selected_source_token_patch_count + selected_evidence_token_patch_count
                ),
                "hidden_pre_attn_token_update_l2": float(selected_hidden_token_update_l2),
                "hidden_pre_attn_token_update_scale": float(hidden_token_update_scale_value),
                "hidden_pre_attn_token_max_positions": int(hidden_token_max_positions_value),
            }
            if args:
                new_args = (patched,) + tuple(args[1:])
                return new_args, kwargs
            new_kwargs = dict(kwargs)
            new_kwargs["hidden_states"] = patched
            return args, new_kwargs

        return hook_fn

    def make_attn_forward_hook():
        def hook_fn(module, _args, output):
            patched = patched_attn_outputs.pop(id(module), None)
            if patched is None:
                return None
            if isinstance(output, tuple):
                if not output:
                    return output
                attn_output = output[0].clone()
                attn_output[:, -1:, :].copy_(patched[:, -1:, :].to(dtype=attn_output.dtype))
                return (attn_output, *output[1:])
            if isinstance(output, list):
                if not output:
                    return output
                cloned = list(output)
                attn_output = cloned[0].clone()
                attn_output[:, -1:, :].copy_(patched[:, -1:, :].to(dtype=attn_output.dtype))
                cloned[0] = attn_output
                return cloned
            patched_output = output.clone()
            patched_output[:, -1:, :].copy_(patched[:, -1:, :].to(dtype=patched_output.dtype))
            return patched_output

        return hook_fn

    def make_hidden_patch_hook(layer_id: int):
        e_cpu = evidence_directions[int(layer_id)].detach().float().cpu()
        t_cpu = evidence_transfer_vectors[int(layer_id)].detach().float().cpu()
        p_cpu = prior_directions[int(layer_id)].detach().float().cpu()
        c_cpu = (
            contamination_directions[int(layer_id)].detach().float().cpu()
            if contamination_directions is not None and int(layer_id) in contamination_directions
            else torch.zeros_like(p_cpu)
        )
        evidence_gap = float(evidence_gaps[int(layer_id)])
        layer_weight = float(weights[int(layer_id)])
        beta_layer_weight = float(beta_weights.get(int(layer_id), 0.0))
        alpha_layer_weight = float(alpha_weights.get(int(layer_id), 0.0))
        gamma_layer_weight = float(contamination_weights.get(int(layer_id), 0.0))
        beta_for_layer_raw = (
            float(beta)
            * hidden_strength
            * hidden_beta_budget_scale_value
            * beta_layer_weight
        )
        beta_for_layer = beta_for_layer_raw * (1.0 - hidden_current_protection)
        alpha_for_layer = (
            float(alpha)
            * hidden_strength
            * hidden_alpha_budget_scale_value
            * alpha_layer_weight
        )
        gamma_for_layer = (
            float(gamma)
            * hidden_strength
            * hidden_beta_budget_scale_value
            * gamma_layer_weight
        )

        def patch_hook(_module, _inp, output):
            hidden_states = output[0] if isinstance(output, (tuple, list)) else output
            if not isinstance(hidden_states, torch.Tensor):
                return None
            if abs(beta_for_layer) <= 1.0e-12 and abs(alpha_for_layer) <= 1.0e-12 and abs(gamma_for_layer) <= 1.0e-12:
                hidden_debug_by_layer[str(layer_id)] = {
                    "layer_weight": layer_weight,
                    "hidden_current_protection_weight": hidden_current_protection,
                    "oelpr_conflict_budget": oelpr_budget_value,
                    "oelpr_suppression_budget": oelpr_suppression_budget_value,
                    "oelpr_evidence_budget": oelpr_evidence_budget_value,
                    "hidden_beta_budget_scale": hidden_beta_budget_scale_value,
                    "hidden_alpha_budget_scale": hidden_alpha_budget_scale_value,
                    "token_beta_budget_scale": token_beta_budget_scale_value,
                    "token_alpha_budget_scale": token_alpha_budget_scale_value,
                    "hidden_budget_coupling": oelpr_hidden_budget_coupling_key,
                    "hidden_path_activity_scale": 0.0 if oelpr_hidden_budget_coupling_key == "token_path_activity" else 1.0,
                    "carrier_trace_prior_activity": 0.0 if oelpr_hidden_budget_coupling_key == "carrier_trace_activity" else 1.0,
                    "carrier_trace_evidence_activity": 0.0 if oelpr_hidden_budget_coupling_key == "carrier_trace_activity" else 1.0,
                    "beta_for_layer_raw": beta_for_layer_raw,
                    "beta_for_layer": beta_for_layer,
                    "alpha_for_layer": alpha_for_layer,
                    "gamma_for_layer": gamma_for_layer,
                    "hidden_carrier_source": hidden_carrier_source_key,
                    "trace_conditioned_carrier_requested": bool(
                        hidden_carrier_source_key == "trace_conditioned"
                    ),
                    "signed_path_subspace_carrier_requested": bool(
                        hidden_carrier_source_key == "signed_path_subspace"
                    ),
                    "prior_suppression_operator": str(prior_suppression_operator),
                    "skip_reason": "zero_structured_hidden_weight",
                }
                return None
            patched = hidden_states.clone()
            base = patched[0, -1, :].float()
            p_dir = unit(p_cpu).to(device=base.device, dtype=torch.float32)
            e_dir = unit(e_cpu).to(device=base.device, dtype=torch.float32)
            c_norm = float(c_cpu.norm().item())
            c_dir = unit(c_cpu).to(device=base.device, dtype=torch.float32) if c_norm > 1.0e-12 else torch.zeros_like(base)
            transfer_vec = t_cpu.to(device=base.device, dtype=torch.float32)
            original_p_dir = p_dir
            original_e_dir = e_dir
            carrier_trace_prior_activity = 1.0
            carrier_trace_evidence_activity = 1.0
            carrier_trace_debug: dict[str, Any] = {}
            if oelpr_hidden_budget_coupling_key == "carrier_trace_activity":
                carrier_trace_debug = _carrier_trace_activity_from_token_payload(
                    token_debug_by_layer.get(str(layer_id), {}),
                    max_patched_heads_per_layer=max_patched_heads_per_layer,
                )
                carrier_trace_prior_activity = float(carrier_trace_debug["carrier_trace_prior_activity"])
                carrier_trace_evidence_activity = float(carrier_trace_debug["carrier_trace_evidence_activity"])
            effective_beta_for_layer = float(beta_for_layer) * float(carrier_trace_prior_activity)
            effective_alpha_for_layer = float(alpha_for_layer) * float(carrier_trace_evidence_activity)
            path_payload = path_carriers_by_layer.get(int(layer_id), {})
            path_debug = dict(path_payload.get("debug") or {})
            signed_path_requested = hidden_carrier_source_key == "signed_path_subspace"
            signed_path_prior_used = False
            signed_path_evidence_used = False
            signed_path_vcr = None
            signed_path_pcr = None
            signed_path_evidence_component_l2 = None
            signed_path_prior_component_l2 = None
            signed_path_residual_component_l2 = None
            signed_path_prior_blend = 0.0
            signed_path_evidence_blend = 0.0
            signed_path_rank_evidence_actual = path_debug.get("signed_path_rank_evidence_actual")
            signed_path_rank_prior_actual = path_debug.get("signed_path_rank_prior_actual")
            if signed_path_requested:
                evidence_basis_payload = path_payload.get("evidence_basis")
                prior_basis_payload = path_payload.get("prior_basis")

                def _signed_path_blend_weight(alignment_abs: float, coverage: float | None) -> float:
                    if signed_path_blend_key == "path_only":
                        return 1.0
                    if signed_path_blend_key == "coverage" and coverage is not None:
                        return math.sqrt(max(0.0, min(1.0, float(coverage))))
                    return max(0.0, min(1.0, float(alignment_abs)))

                def _basis_component(basis_payload: Any) -> torch.Tensor:
                    if basis_payload is None:
                        return torch.zeros_like(base)
                    basis = torch.as_tensor(basis_payload).to(device=base.device, dtype=torch.float32)
                    if basis.ndim != 2 or int(basis.shape[0]) != int(base.numel()) or int(basis.shape[1]) <= 0:
                        return torch.zeros_like(base)
                    return basis @ (basis.T @ base)

                evidence_component = _basis_component(evidence_basis_payload)
                prior_component = _basis_component(prior_basis_payload)
                residual_component = base - evidence_component - prior_component
                base_norm_sq = float(torch.dot(base, base).detach().cpu().item()) + 1.0e-12
                evidence_component_norm = float(evidence_component.norm().detach().cpu().item())
                prior_component_norm = float(prior_component.norm().detach().cpu().item())
                residual_component_norm = float(residual_component.norm().detach().cpu().item())
                signed_path_evidence_component_l2 = evidence_component_norm
                signed_path_prior_component_l2 = prior_component_norm
                signed_path_residual_component_l2 = residual_component_norm
                signed_path_vcr = float(
                    torch.dot(evidence_component, evidence_component).detach().cpu().item() / base_norm_sq
                )
                signed_path_pcr = float(
                    torch.dot(prior_component, prior_component).detach().cpu().item() / base_norm_sq
                )
                if evidence_component_norm > 1.0e-12:
                    signed_e_dir = unit(evidence_component).to(device=base.device, dtype=torch.float32)
                    evidence_alignment = torch.dot(signed_e_dir, original_e_dir).clamp(-1.0, 1.0)
                    signed_path_evidence_blend = _signed_path_blend_weight(
                        abs(float(evidence_alignment.detach().cpu().item())),
                        signed_path_vcr,
                    )
                    oriented_signed_evidence = (
                        signed_e_dir if float(evidence_alignment.item()) >= 0.0 else -signed_e_dir
                    )
                    e_dir = unit(
                        (1.0 - signed_path_evidence_blend) * original_e_dir
                        + signed_path_evidence_blend * oriented_signed_evidence
                    ).to(device=base.device, dtype=torch.float32)
                    signed_path_evidence_used = True
                elif bool(path_payload.get("evidence_available")):
                    path_evidence_tensor = torch.as_tensor(path_payload.get("evidence_direction")).to(
                        device=base.device,
                        dtype=torch.float32,
                    )
                    if float(path_evidence_tensor.norm().detach().cpu().item()) > 1.0e-12:
                        e_dir = unit(path_evidence_tensor).to(device=base.device, dtype=torch.float32)
                        signed_path_evidence_used = True
                if prior_component_norm > 1.0e-12:
                    signed_p_dir = unit(prior_component).to(device=base.device, dtype=torch.float32)
                    prior_alignment = torch.dot(signed_p_dir, original_p_dir).clamp(-1.0, 1.0)
                    signed_path_prior_blend = _signed_path_blend_weight(
                        abs(float(prior_alignment.detach().cpu().item())),
                        signed_path_pcr,
                    )
                    oriented_signed_prior = (
                        signed_p_dir if float(prior_alignment.item()) >= 0.0 else -signed_p_dir
                    )
                    p_dir = unit(
                        (1.0 - signed_path_prior_blend) * original_p_dir
                        + signed_path_prior_blend * oriented_signed_prior
                    ).to(device=base.device, dtype=torch.float32)
                    signed_path_prior_used = True
                elif bool(path_payload.get("prior_available")):
                    path_prior_tensor = torch.as_tensor(path_payload.get("prior_direction")).to(
                        device=base.device,
                        dtype=torch.float32,
                    )
                    if float(path_prior_tensor.norm().detach().cpu().item()) > 1.0e-12:
                        p_dir = unit(path_prior_tensor).to(device=base.device, dtype=torch.float32)
                        signed_path_prior_used = True
            path_soft_requested = path_carrier_required
            path_soft_prior_used = False
            path_soft_evidence_used = False
            path_soft_prior_blend = 0.0
            path_soft_evidence_blend = 0.0
            if path_soft_requested:
                path_prior = path_payload.get("prior_direction")
                path_evidence = path_payload.get("evidence_direction")
                if bool(path_payload.get("prior_available")) and path_prior is not None:
                    path_prior_tensor = torch.as_tensor(path_prior).to(device=base.device, dtype=torch.float32)
                    if float(path_prior_tensor.norm().detach().cpu().item()) > 1.0e-12:
                        path_prior_dir = unit(path_prior_tensor).to(device=base.device, dtype=torch.float32)
                        prior_alignment = torch.dot(path_prior_dir, original_p_dir).clamp(-1.0, 1.0)
                        path_soft_prior_blend = abs(float(prior_alignment.detach().cpu().item()))
                        oriented_path_prior = path_prior_dir if float(prior_alignment.item()) >= 0.0 else -path_prior_dir
                        p_dir = unit(
                            (1.0 - path_soft_prior_blend) * original_p_dir
                            + path_soft_prior_blend * oriented_path_prior
                        ).to(device=base.device, dtype=torch.float32)
                        path_soft_prior_used = True
                if bool(path_payload.get("evidence_available")) and path_evidence is not None:
                    path_evidence_tensor = torch.as_tensor(path_evidence).to(device=base.device, dtype=torch.float32)
                    if float(path_evidence_tensor.norm().detach().cpu().item()) > 1.0e-12:
                        path_evidence_dir = unit(path_evidence_tensor).to(device=base.device, dtype=torch.float32)
                        evidence_alignment = torch.dot(path_evidence_dir, original_e_dir).clamp(-1.0, 1.0)
                        path_soft_evidence_blend = abs(float(evidence_alignment.detach().cpu().item()))
                        oriented_path_evidence = (
                            path_evidence_dir if float(evidence_alignment.item()) >= 0.0 else -path_evidence_dir
                        )
                        e_dir = unit(
                            (1.0 - path_soft_evidence_blend) * original_e_dir
                            + path_soft_evidence_blend * oriented_path_evidence
                        ).to(device=base.device, dtype=torch.float32)
                        path_soft_evidence_used = True
            projection = torch.dot(base, p_dir) * p_dir
            soft_payload: dict[str, Any] = {}
            up_r_payload: dict[str, Any] = {}
            signed_path_closed_payload: dict[str, Any] = {}
            if str(prior_suppression_operator) == "projection":
                prior_delta = -effective_beta_for_layer * projection
                soft_payload = {
                    "mu": None,
                    "lambda": float(soft_suppression_evidence_lambda),
                    "cos_prior_evidence": float(torch.dot(p_dir, e_dir).item()),
                    "raw_projection_delta_l2": float(prior_delta.norm().item()),
                    "soft_delta_l2": None,
                    "delta_evidence_projection": float(torch.dot(prior_delta, e_dir).item()),
                    "delta_prior_projection": float(torch.dot(prior_delta, p_dir).item()),
                    "solver_degenerate": False,
                }
                up_r_payload = up_r_projection_delta(
                    base=base,
                    prior_direction=p_dir,
                    evidence_direction=e_dir,
                    beta=effective_beta_for_layer,
                )
            elif str(prior_suppression_operator) == "up_r_projection":
                up_r_payload = up_r_projection_delta(
                    base=base,
                    prior_direction=p_dir,
                    evidence_direction=e_dir,
                    beta=effective_beta_for_layer,
                )
                prior_delta = torch.as_tensor(up_r_payload["delta"]).to(device=base.device, dtype=torch.float32)
                soft_payload = {
                    "mu": None,
                    "lambda": float(soft_suppression_evidence_lambda),
                    "cos_prior_evidence": float(torch.dot(p_dir, e_dir).item()),
                    "raw_projection_delta_l2": float(prior_delta.norm().item()),
                    "soft_delta_l2": None,
                    "delta_evidence_projection": float(torch.dot(prior_delta, e_dir).item()),
                    "delta_prior_projection": float(torch.dot(prior_delta, p_dir).item()),
                    "solver_degenerate": False,
                }
            elif str(prior_suppression_operator) in {"signed_path_closed_form", "signed_path_coverage_closed_form"}:
                signed_path_closed_payload = signed_path_closed_form_delta(
                    base=base,
                    evidence_basis=torch.as_tensor(path_payload.get("evidence_basis", torch.zeros(0, 0))),
                    prior_basis=torch.as_tensor(path_payload.get("prior_basis", torch.zeros(0, 0))),
                    beta_scale=effective_beta_for_layer,
                    kappa=float(hulluedit_kappa),
                    lambda_prior=float(hulluedit_lambda_prior),
                    lambda_n_max=float(hulluedit_lambda_n_max),
                    lambda_p_max=float(hulluedit_lambda_p_max),
                    vcr_floor=float(hulluedit_vcr_floor),
                    pcr_ceiling=float(hulluedit_pcr_ceiling),
                    pcr_threshold=float(hulluedit_pcr_threshold),
                    blend_tau=float(hulluedit_blend_tau),
                    norm_preserve=bool(hulluedit_norm_preserve),
                    norm_beta=float(hulluedit_norm_beta),
                    trust_mode=(
                        "coverage"
                        if str(prior_suppression_operator) == "signed_path_coverage_closed_form"
                        else "hulluedit"
                    ),
                )
                prior_delta = torch.as_tensor(signed_path_closed_payload["delta"]).to(
                    device=base.device,
                    dtype=torch.float32,
                )
                up_r_payload = up_r_projection_delta(
                    base=base,
                    prior_direction=p_dir,
                    evidence_direction=e_dir,
                    beta=effective_beta_for_layer,
                )
                soft_payload = {
                    "mu": None,
                    "lambda": float(soft_suppression_evidence_lambda),
                    "cos_prior_evidence": float(torch.dot(p_dir, e_dir).item()),
                    "raw_projection_delta_l2": float(prior_delta.norm().item()),
                    "soft_delta_l2": None,
                    "delta_evidence_projection": float(torch.dot(prior_delta, e_dir).item()),
                    "delta_prior_projection": float(torch.dot(prior_delta, p_dir).item()),
                    "solver_degenerate": False,
                }
            elif str(prior_suppression_operator) in {
                "soft_minimal",
                "path_soft_minimal",
                "path_projected_minimal",
                "path_residual_minimal",
            }:
                soft_payload = soft_minimal_suppression_delta(
                    base=base,
                    prior_direction=p_dir,
                    evidence_direction=e_dir,
                    beta=effective_beta_for_layer,
                    evidence_lambda=float(soft_suppression_evidence_lambda),
                )
                prior_delta = torch.as_tensor(soft_payload["delta"]).to(device=base.device, dtype=torch.float32)
                up_r_payload = up_r_projection_delta(
                    base=base,
                    prior_direction=p_dir,
                    evidence_direction=e_dir,
                    beta=effective_beta_for_layer,
                )
            else:
                raise ValueError(f"unknown prior_suppression_operator: {prior_suppression_operator}")
            path_projected_prior_payload: dict[str, Any] = {}
            path_projected_evidence_payload: dict[str, Any] = {}
            if str(prior_suppression_operator) in {"path_projected_minimal", "path_residual_minimal"}:
                path_projected_prior_payload = _path_constrained_hidden_delta_from_paths(
                    target_delta=prior_delta,
                    path_vectors=path_payload.get("prior_paths"),
                    path_scores=path_payload.get("prior_scores"),
                    prefix="prior",
                    residual_penalty=0.5 if str(prior_suppression_operator) == "path_residual_minimal" else None,
                )
                if bool(path_projected_prior_payload.get("available")):
                    prior_delta = torch.as_tensor(path_projected_prior_payload["delta"]).to(
                        device=base.device,
                        dtype=torch.float32,
                    )
            contamination_projection = torch.dot(base, c_dir) * c_dir if c_norm > 1.0e-12 else torch.zeros_like(base)
            contamination_delta = -gamma_for_layer * contamination_projection
            path_answer_margin_payload: dict[str, Any] = {}
            if evidence_transfer_mode == "legacy_projection_gap":
                evidence_delta = effective_alpha_for_layer * max(0.0, evidence_gap) * e_dir
            elif evidence_transfer_mode == "clean_target_full_gap":
                evidence_delta = effective_alpha_for_layer * transfer_vec
            elif evidence_transfer_mode in {"path_answer_margin", "path_answer_margin_minimal"}:
                path_answer_solution_mode = (
                    "least_norm_answer_axis"
                    if evidence_transfer_mode == "path_answer_margin_minimal"
                    else "weighted_path_mean"
                )
                path_answer_margin_payload = _path_answer_margin_evidence_delta(
                    base=base,
                    path_vectors=path_payload.get("evidence_paths"),
                    path_scores=path_payload.get("evidence_scores"),
                    lm_head=lm_head,
                    yes_id=yes_id,
                    no_id=no_id,
                    current_answer=current_answer,
                    candidate_answer=candidate_answer,
                    alpha_for_layer=effective_alpha_for_layer,
                    solution_mode=path_answer_solution_mode,
                )
                evidence_delta = torch.as_tensor(path_answer_margin_payload["delta"]).to(
                    device=base.device,
                    dtype=torch.float32,
                )
            else:
                raise ValueError(f"unknown evidence_transfer_mode: {evidence_transfer_mode}")
            if str(prior_suppression_operator) in {"path_projected_minimal", "path_residual_minimal"}:
                path_projected_evidence_payload = _path_constrained_hidden_delta_from_paths(
                    target_delta=evidence_delta,
                    path_vectors=path_payload.get("evidence_paths"),
                    path_scores=path_payload.get("evidence_scores"),
                    prefix="evidence",
                    residual_penalty=0.5 if str(prior_suppression_operator) == "path_residual_minimal" else None,
                )
                if bool(path_projected_evidence_payload.get("available")):
                    evidence_delta = torch.as_tensor(path_projected_evidence_payload["delta"]).to(
                        device=base.device,
                        dtype=torch.float32,
                    )
            evidence_projection_before = torch.dot(base, e_dir)
            evidence_projection_after_suppression = torch.dot(base + prior_delta, e_dir)
            evidence_constraint_damage = torch.clamp(
                evidence_projection_before - evidence_projection_after_suppression,
                min=0.0,
            )
            constraint_delta = torch.zeros_like(base)
            if evidence_constraint_mode == "nonnegative_projection":
                constraint_delta = max(0.0, float(evidence_constraint_strength)) * evidence_constraint_damage * e_dir
            elif evidence_constraint_mode == "orthogonal_residual_projection":
                e_res = e_dir - torch.dot(e_dir, p_dir) * p_dir
                e_res_norm = torch.norm(e_res)
                if float(e_res_norm.item()) > 1.0e-12:
                    e_res_dir = e_res / e_res_norm.clamp_min(1.0e-12)
                    evidence_gain_per_unit = torch.dot(e_res_dir, e_dir).clamp_min(1.0e-12)
                    scale = evidence_constraint_damage / evidence_gain_per_unit
                    constraint_delta = max(0.0, float(evidence_constraint_strength)) * scale * e_res_dir
            elif evidence_constraint_mode != "none":
                raise ValueError(f"unknown evidence_constraint_mode: {evidence_constraint_mode}")
            constraint_prior_projection = torch.dot(constraint_delta, p_dir)
            constraint_evidence_projection = torch.dot(constraint_delta, e_dir)
            source_component_delta = prior_delta + contamination_delta
            evidence_component_delta = evidence_delta + constraint_delta
            raw_update = prior_delta + evidence_delta + constraint_delta + contamination_delta
            feasible_payload: dict[str, Any] = {
                "changed": False,
                "feasible": True,
                "active_constraints": [],
                "projection_l2": 0.0,
                "prior_reduction_floor": 0.0,
                "prior_floor_relaxed": False,
                "current_prior_magnitude": abs(float(torch.dot(base, p_dir).item())),
                "nominal_prior_reduction": max(
                    0.0,
                    float(effective_beta_for_layer) * abs(float(torch.dot(base, p_dir).item())),
                ),
                "raw_update_evidence_projection": float(torch.dot(raw_update, e_dir).item()),
                "constrained_update_evidence_projection": float(torch.dot(raw_update, e_dir).item()),
                "raw_update_prior_reduction": float(
                    torch.dot(
                        -raw_update,
                        (1.0 if float(torch.dot(base, p_dir).item()) >= 0.0 else -1.0) * p_dir,
                    ).item()
                ),
                "constrained_update_prior_reduction": float(
                    torch.dot(
                        -raw_update,
                        (1.0 if float(torch.dot(base, p_dir).item()) >= 0.0 else -1.0) * p_dir,
                    ).item()
                ),
                "raw_update_l2": float(raw_update.norm().item()),
                "constrained_update_l2": float(raw_update.norm().item()),
            }
            if str(intervention_constraint_mode) == "feasible_update":
                feasible_payload = feasible_update_projection(
                    base=base,
                    raw_update=raw_update,
                    evidence_direction=e_dir,
                    prior_direction=p_dir,
                    beta_for_layer=effective_beta_for_layer,
                    evidence_damage_tolerance=float(feasible_evidence_damage_tolerance),
                    prior_reduction_floor_ratio=float(feasible_prior_reduction_floor_ratio),
                    prior_reduction_floor_abs=float(feasible_prior_reduction_floor_abs),
                )
                update_delta = torch.as_tensor(feasible_payload["update"]).to(device=base.device, dtype=torch.float32)
            elif str(intervention_constraint_mode) == "none":
                update_delta = raw_update
            else:
                raise ValueError(f"unknown intervention_constraint_mode: {intervention_constraint_mode}")
            component_update_scale = 1.0
            raw_update_norm_for_components = float(raw_update.norm().item())
            if raw_update_norm_for_components > 1.0e-12:
                component_update_scale = float(update_delta.norm().item()) / raw_update_norm_for_components
            source_token_update_delta = source_component_delta * float(component_update_scale)
            evidence_token_update_delta = evidence_component_delta * float(component_update_scale)
            pre_coupling_update_l2 = float(update_delta.norm().item())
            hidden_path_activity_scale = 1.0
            hidden_path_activity_debug: dict[str, Any] = {}
            if oelpr_hidden_budget_coupling_key == "token_path_activity":
                token_payload = token_debug_by_layer.get(str(layer_id), {})
                source_path = _finite_float_or_none(token_payload.get("oelpr_source_path_weight_mean"))
                evidence_path = _finite_float_or_none(token_payload.get("oelpr_evidence_path_weight_mean"))
                unified_activity = _finite_float_or_none(token_payload.get("oelpr_unified_activity_mean"))
                valid_activity = [
                    float(value)
                    for value in (source_path, evidence_path, unified_activity)
                    if value is not None and math.isfinite(float(value))
                ]
                hidden_path_activity_scale = (
                    max(0.0, min(1.0, max(valid_activity))) if valid_activity else 0.0
                )
                update_delta = update_delta * float(hidden_path_activity_scale)
                source_token_update_delta = source_token_update_delta * float(hidden_path_activity_scale)
                evidence_token_update_delta = evidence_token_update_delta * float(hidden_path_activity_scale)
                hidden_path_activity_debug = {
                    "token_oelpr_source_path_weight": source_path,
                    "token_oelpr_evidence_path_weight": evidence_path,
                    "token_oelpr_unified_activity": unified_activity,
                    "token_oelpr_activity_available": bool(valid_activity),
                }
            token_payload_for_target_trust = token_debug_by_layer.get(str(layer_id), {})
            target_trust_payload = _target_trust_gate_from_path_certificate(
                token_payload_for_target_trust,
                mode=oelpr_target_trust_gate_key,
                floor=oelpr_target_trust_gate_floor_value,
                tau=oelpr_target_trust_gate_tau_value,
                candidate_reliability=oelpr_target_trust_candidate_reliability_value,
                target_prob=oelpr_target_trust_target_prob_value,
            )
            target_trust_scale = float(target_trust_payload.get("scale") or 1.0)
            if oelpr_target_trust_gate_key != "none":
                update_delta = update_delta * target_trust_scale
                source_token_update_delta = source_token_update_delta * target_trust_scale
                evidence_token_update_delta = evidence_token_update_delta * target_trust_scale
            pre_trust_update_l2 = float(update_delta.norm().item())
            trust_region_payload = _hidden_answer_trust_region_update(
                base=base,
                update_delta=update_delta,
                lm_head=lm_head,
                yes_id=yes_id,
                no_id=no_id,
                current_answer=current_answer,
                candidate_answer=candidate_answer,
                mode=hidden_answer_trust_region_key,
                current_protection_weight=float(token_head_current_protection_weight),
                carrier_consensus_margin=latent_anchor_carrier_consensus_margin,
                text_plausibility_margin=hidden_text_plausibility_margin,
                text_plausibility_threshold=hidden_text_plausibility_threshold,
                text_plausibility_tau=hidden_text_plausibility_tau,
                floor=hidden_answer_trust_region_floor,
            )
            update_delta = torch.as_tensor(trust_region_payload["update"]).to(
                device=base.device,
                dtype=torch.float32,
            )
            trust_component_scale = 1.0
            if pre_trust_update_l2 > 1.0e-12:
                trust_component_scale = float(update_delta.norm().item()) / pre_trust_update_l2
            source_token_update_delta = source_token_update_delta * float(trust_component_scale)
            evidence_token_update_delta = evidence_token_update_delta * float(trust_component_scale)
            diagnostic_updated = base + update_delta
            selected_source_token_patch_count = 0
            selected_evidence_token_patch_count = 0
            selected_hidden_token_update_l2 = 0.0
            selected_hidden_token_update_weight_sum = 0.0
            selected_hidden_final_gate_scale = 0.0
            if hidden_update_mode == "diagnose_only":
                actual_update_delta = torch.zeros_like(update_delta)
                updated = base
            elif hidden_edit_site_key == "final_token":
                actual_update_delta = update_delta
                updated = diagnostic_updated
                patched[0, -1, :] = updated.to(dtype=patched.dtype)
            else:
                token_payload = token_debug_by_layer.get(str(layer_id), {})
                pre_attn_payload = pre_attn_hidden_patch_debug_by_layer.get(str(layer_id), {})
                source_plan_positions = list(token_payload.get("source_hidden_token_patch_positions") or [])
                source_plan_weights = list(token_payload.get("source_hidden_token_patch_weights") or [])
                evidence_plan_positions = list(token_payload.get("evidence_hidden_token_patch_positions") or [])
                evidence_plan_weights = list(token_payload.get("evidence_hidden_token_patch_weights") or [])
                seq_len = int(patched.shape[1])
                final_index = seq_len - 1
                if hidden_pre_attn_edit_enabled:
                    selected_source_token_patch_count = int(
                        pre_attn_payload.get("hidden_pre_attn_source_token_patch_count") or 0
                    )
                    selected_evidence_token_patch_count = int(
                        pre_attn_payload.get("hidden_pre_attn_evidence_token_patch_count") or 0
                    )
                    selected_hidden_token_update_l2 = float(
                        pre_attn_payload.get("hidden_pre_attn_token_update_l2") or 0.0
                    )
                    selected_hidden_token_update_weight_sum = float(
                        selected_source_token_patch_count + selected_evidence_token_patch_count
                    )
                elif hidden_token_update_scale_value > 1.0e-12:
                    for position, token_weight in zip(source_plan_positions, source_plan_weights):
                        pos_idx = int(position)
                        if pos_idx < 0 or pos_idx >= seq_len or pos_idx == final_index:
                            continue
                        weight_value = max(0.0, min(1.0, float(token_weight)))
                        if weight_value <= 1.0e-12:
                            continue
                        token_delta = (
                            source_token_update_delta
                            * float(hidden_token_update_scale_value)
                            * float(weight_value)
                        )
                        patched[0, pos_idx, :] = (
                            patched[0, pos_idx, :].float() + token_delta
                        ).to(dtype=patched.dtype)
                        selected_source_token_patch_count += 1
                        selected_hidden_token_update_l2 += float(token_delta.norm().item())
                        selected_hidden_token_update_weight_sum += float(weight_value)
                    for position, token_weight in zip(evidence_plan_positions, evidence_plan_weights):
                        pos_idx = int(position)
                        if pos_idx < 0 or pos_idx >= seq_len or pos_idx == final_index:
                            continue
                        weight_value = max(0.0, min(1.0, float(token_weight)))
                        if weight_value <= 1.0e-12:
                            continue
                        token_delta = (
                            evidence_token_update_delta
                            * float(hidden_token_update_scale_value)
                            * float(weight_value)
                        )
                        patched[0, pos_idx, :] = (
                            patched[0, pos_idx, :].float() + token_delta
                        ).to(dtype=patched.dtype)
                        selected_evidence_token_patch_count += 1
                        selected_hidden_token_update_l2 += float(token_delta.norm().item())
                        selected_hidden_token_update_weight_sum += float(weight_value)
                if hidden_final_gated_edit_enabled:
                    gate_candidates = [
                        _finite_float_or_none(token_payload.get("source_hidden_token_patch_weight_mean")),
                        _finite_float_or_none(token_payload.get("evidence_hidden_token_patch_weight_mean")),
                    ]
                    gate_values = [
                        float(value)
                        for value in gate_candidates
                        if value is not None and math.isfinite(float(value))
                    ]
                    selected_hidden_final_gate_scale = (
                        min(1.0, float(hidden_token_update_scale_value) * max(gate_values))
                        if gate_values
                        else 0.0
                    )
                    if selected_hidden_final_gate_scale > 1.0e-12:
                        final_delta = update_delta * float(selected_hidden_final_gate_scale)
                        patched[0, -1, :] = (base + final_delta).to(dtype=patched.dtype)
                updated = patched[0, -1, :].float()
                actual_update_delta = updated - base
